-- =============================================================================
-- 20261120001_schema.sql: the whole database schema in one file.
--
-- Made on 2026-11-16 by replaying the 82 migrations from 20260715001 to 20261119003 on an
-- empty database and dumping the result (supabase db dump). It replaces all of them: a
-- database built from this file and 20261120002 matches one built from the 82, checked
-- object by object. Tables, types, functions, triggers, row security, grants and realtime
-- are here; storage buckets, scheduled jobs, the sign-up trigger on auth.users and the role
-- defaults are in 20261120002.
--
-- New changes go in new migration files after these two, as before.
-- =============================================================================




SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

-- Tables and sequences get exactly the grants listed below. Without this, Supabase's default
-- grants (everything to anon and authenticated) would apply to each table as it is created,
-- giving more than the 83 migrations left. The defaults are set back at the end of the file.
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" REVOKE ALL ON TABLES FROM "anon", "authenticated", "service_role";
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" REVOKE ALL ON SEQUENCES FROM "anon", "authenticated", "service_role";


CREATE EXTENSION IF NOT EXISTS "pg_cron" WITH SCHEMA "pg_catalog";






CREATE EXTENSION IF NOT EXISTS "pg_net" WITH SCHEMA "extensions";






COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pg_trgm" WITH SCHEMA "public";






CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";






CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";






