CREATE OR REPLACE FUNCTION "public"."accept_alert"("p_notification_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_n public.notifications%ROWTYPE;
    v_by TEXT;
    v_me UUID := (SELECT u.id FROM public.users u WHERE u.auth_user_id = auth.uid());
BEGIN
    SELECT * INTO v_n FROM public.notifications WHERE id = p_notification_id AND deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND OR NOT (v_n.business_id = ANY(public.get_user_business_ids())) THEN
        RAISE EXCEPTION 'That alert was not found.';
    END IF;
    IF v_me IS NULL OR NOT public.fn_is_alert_recipient(v_n, v_me) THEN
        RAISE EXCEPTION 'That alert was not sent to you.' USING ERRCODE = '42501';
    END IF;

    IF v_n.accepted_at IS NULL THEN
        UPDATE public.notifications
        SET accepted_at = NOW(), accepted_by = v_me,
            read_at = COALESCE(read_at, NOW()), clicked_at = COALESCE(clicked_at, NOW())
        WHERE id = v_n.id;
        RETURN jsonb_build_object('accepted', TRUE, 'alreadyAcceptedBy', NULL,
                                  'actionTarget', v_n.action_target, 'businessId', v_n.business_id);
    END IF;

    SELECT name INTO v_by FROM public.users WHERE id = v_n.accepted_by;
    RETURN jsonb_build_object('accepted', FALSE,
                              'alreadyAcceptedBy', CASE WHEN v_n.accepted_by = v_me THEN 'you' ELSE COALESCE(v_by, 'someone') END,
                              'actionTarget', v_n.action_target, 'businessId', v_n.business_id);
END;
$$;


ALTER FUNCTION "public"."accept_alert"("p_notification_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_invitation_with_token"("p_token" "text", "p_auth_user_id" "uuid", "p_name" "text", "p_phone" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_invite      RECORD;
    v_login_email TEXT;
BEGIN
    IF NOT public.invite_guesses_left() THEN
        RAISE EXCEPTION 'Too many wrong codes. Please wait 15 minutes and try again.';
    END IF;

    SELECT * INTO v_invite
    FROM public.invitations
    WHERE invitation_token = p_token
      AND status = 'Pending'
      AND expires_at > NOW()
    FOR UPDATE;

    IF NOT FOUND THEN
        PERFORM public.check_rate_limit(public.invite_guess_key(), 1000000, 900);
        RETURN FALSE;
    END IF;

    -- A logged-in caller can only accept for their own account
    IF auth.uid() IS NOT NULL AND auth.uid() <> p_auth_user_id THEN
        RAISE EXCEPTION 'This invitation belongs to a different account.';
    END IF;

    -- The account must be the one the invitation was sent to
    SELECT email INTO v_login_email FROM auth.users WHERE id = p_auth_user_id;
    IF v_login_email IS NULL
       OR LOWER(TRIM(v_login_email)) <> LOWER(TRIM(v_invite.email)) THEN
        RAISE EXCEPTION 'This invitation belongs to a different account.';
    END IF;

    IF public.account_email_verified(p_auth_user_id) THEN
        PERFORM public.finish_invitation(v_invite.id, p_auth_user_id, p_name, p_phone);
    ELSE
        UPDATE public.invitations
        SET claimed_by    = p_auth_user_id,
            claimed_at    = NOW(),
            claimed_name  = p_name,
            claimed_phone = p_phone
        WHERE id = v_invite.id;
    END IF;

    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."accept_invitation_with_token"("p_token" "text", "p_auth_user_id" "uuid", "p_name" "text", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_schedule_occurrence"("p_schedule_id" "uuid", "p_date" "date", "p_time" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_me UUID := (SELECT u.id FROM public.users u WHERE u.auth_user_id = auth.uid());
    v_s public.schedules%ROWTYPE;
    v_n UUID;
    v_time TEXT := NULLIF(left(p_time, 5), '');
BEGIN
    SELECT * INTO v_s FROM public.schedules WHERE id = p_schedule_id;
    IF NOT FOUND OR v_me IS NULL OR public.fn_schedule_user(v_s.employee_id) IS DISTINCT FROM v_me
       OR NOT (v_s.business_id = ANY(public.get_user_business_ids())) THEN
        RAISE EXCEPTION 'That reminder was not found.' USING ERRCODE = '42501';
    END IF;

    SELECT n.id INTO v_n
    FROM public.notifications n
    WHERE n.type = 'Schedule Reminder'
      AND n.user_id = v_me
      AND n.payload->>'schedule_id' = p_schedule_id::TEXT
      AND n.payload->>'shift_date' = to_char(p_date, 'YYYY-MM-DD')
      AND (v_time IS NULL OR n.payload->>'start_time' = v_time)
      AND n.deleted_at IS NULL
    ORDER BY n.created_at DESC
    LIMIT 1;

    IF v_n IS NOT NULL THEN
        RETURN public.accept_alert(v_n) || jsonb_build_object('notificationId', v_n);
    END IF;

    -- No server row yet (the phone rang first, or was offline). Mark the day done so the server
    -- doesn't ring or escalate it, but only if the reminder still rings at this time.
    UPDATE public.schedules
    SET last_reminded_on = p_date, reminder_sent = TRUE
    WHERE id = p_schedule_id
      AND last_reminded_on IS DISTINCT FROM p_date
      AND (v_time IS NULL OR to_char(start_time, 'HH24:MI') = v_time);

    RETURN jsonb_build_object('accepted', TRUE, 'alreadyAcceptedBy', NULL,
                              'actionTarget', 'dashboard', 'businessId', v_s.business_id,
                              'notificationId', NULL);
END;
$$;


ALTER FUNCTION "public"."accept_schedule_occurrence"("p_schedule_id" "uuid", "p_date" "date", "p_time" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_transfer_request"("p_transfer_id" "uuid", "p_items" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_t    public.stock_transfers%ROWTYPE;
    v_item public.stock_transfer_items%ROWTYPE;
    v_src  public.products%ROWTYPE;
    v_el   JSONB;
    v_qty  NUMERIC;
BEGIN
    SELECT * INTO v_t FROM public.stock_transfers WHERE id = p_transfer_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Transfer not found.'; END IF;
    PERFORM public.assert_business_member(v_t.from_business_id);
    PERFORM public.assert_permission(v_t.from_business_id, 'inventory.transfer_stock');
    IF v_t.status <> 'requested' THEN
        RAISE EXCEPTION 'This request was already answered.';
    END IF;

    FOR v_item IN SELECT * FROM public.stock_transfer_items WHERE transfer_id = v_t.id ORDER BY id LOOP
        SELECT e INTO v_el FROM jsonb_array_elements(COALESCE(p_items, '[]'::JSONB)) e WHERE (e->>'item_id')::UUID = v_item.id LIMIT 1;
        v_qty := CASE WHEN v_el IS NULL OR NULLIF(v_el->>'quantity', '') IS NULL THEN v_item.quantity_sent
                      ELSE round((v_el->>'quantity')::NUMERIC, 3) END;
        IF v_qty <= 0 THEN
            DELETE FROM public.stock_transfer_items WHERE id = v_item.id;
            CONTINUE;
        END IF;
        v_src := NULL;
        IF NULLIF(btrim(COALESCE(v_item.sku, '')), '') IS NOT NULL THEN
            SELECT * INTO v_src FROM public.products
            WHERE business_id = v_t.from_business_id AND sku = v_item.sku AND deleted_at IS NULL LIMIT 1;
        END IF;
        IF v_src.id IS NULL THEN
            SELECT * INTO v_src FROM public.products
            WHERE business_id = v_t.from_business_id AND deleted_at IS NULL
              AND lower(btrim(name)) = lower(btrim(v_item.product_name))
            ORDER BY created_at LIMIT 1;
        END IF;
        IF v_src.id IS NULL THEN
            RAISE EXCEPTION '% isn''t a product here. Set its quantity to 0 to send the rest.', v_item.product_name;
        END IF;
        IF lower(btrim(v_src.unit)) <> lower(btrim(v_item.unit)) THEN
            RAISE EXCEPTION '% is counted in % here but in % there. Make the units match first.', v_item.product_name, v_src.unit, v_item.unit;
        END IF;
        UPDATE public.stock_transfer_items
        SET from_product_id = v_src.id, quantity_sent = v_qty, unit_cost = v_src.cost
        WHERE id = v_item.id;
    END LOOP;
    IF NOT EXISTS (SELECT 1 FROM public.stock_transfer_items WHERE transfer_id = v_t.id) THEN
        RAISE EXCEPTION 'Nothing left to send. Decline the request instead.';
    END IF;
    UPDATE public.stock_transfers
    SET status = 'draft', sent_by_name = public.fn_my_display_name(v_t.from_business_id), sent_by_user_id = public.fn_my_user_id()
    WHERE id = v_t.id;
    RETURN public.fn_transfer_go(v_t.id);
END;
$$;


ALTER FUNCTION "public"."accept_transfer_request"("p_transfer_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."account_email_verified"("p_auth_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM auth.users au
        JOIN public.users u ON u.auth_user_id = au.id
        WHERE au.id = p_auth_user_id
          AND u.verified_email IS NOT NULL
          AND LOWER(TRIM(u.verified_email)) = LOWER(TRIM(au.email))
    );
$$;


ALTER FUNCTION "public"."account_email_verified"("p_auth_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adjust_stock_bulk"("p_adjustments" "jsonb", "p_employee_id" "uuid", "p_staff_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_adj         JSONB;
    v_product_id  UUID;
    v_adj_type    public.inventory_adjustment_type;
    v_quantity    NUMERIC(14,3);
    v_reason      TEXT;
    v_old_stock   NUMERIC(14,3);
    v_new_stock   NUMERIC(14,3);
    v_biz_id      UUID;
    v_prod_name   TEXT;
BEGIN
    PERFORM public.assert_permission(pr.business_id, 'inventory.adjust_stock') FROM public.products pr WHERE pr.id IN (SELECT (e->>'product_id')::UUID FROM jsonb_array_elements(p_adjustments) e);
    PERFORM public.assert_business_member(pr.business_id) FROM public.products pr WHERE pr.id IN (SELECT (e->>'product_id')::UUID FROM jsonb_array_elements(p_adjustments) e);
    FOR v_adj IN SELECT * FROM jsonb_array_elements(p_adjustments)
    LOOP
        v_product_id := (v_adj->>'product_id')::UUID;
        v_adj_type   := (v_adj->>'type')::public.inventory_adjustment_type;
        v_quantity   := (v_adj->>'quantity')::NUMERIC;
        v_reason     := v_adj->>'reason';

        SELECT stock, business_id, name
        INTO v_old_stock, v_biz_id, v_prod_name
        FROM public.products
        WHERE id = v_product_id
        FOR UPDATE;

        IF FOUND THEN
            v_new_stock := CASE
                WHEN v_adj_type = 'Restock'        THEN v_old_stock + v_quantity
                WHEN v_adj_type = 'Damage'         THEN GREATEST(0, v_old_stock - v_quantity)
                WHEN v_adj_type = 'Reconciliation' THEN v_quantity
                ELSE v_old_stock
            END;

            UPDATE public.products
            SET stock = v_new_stock,
                updated_at = NOW()
            WHERE id = v_product_id;

            INSERT INTO public.inventory_adjustments
                (business_id, product_id, product_name, type, quantity_adjusted,
                 previous_stock, new_stock, reason, staff_name)
            VALUES (
                v_biz_id,
                v_product_id,
                v_prod_name,
                v_adj_type,
                CASE
                    WHEN v_adj_type = 'Restock'        THEN v_quantity
                    WHEN v_adj_type = 'Damage'         THEN -v_quantity
                    ELSE v_new_stock - v_old_stock
                END,
                v_old_stock,
                v_new_stock,
                v_reason,
                p_staff_name
            );
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."adjust_stock_bulk"("p_adjustments" "jsonb", "p_employee_id" "uuid", "p_staff_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adjust_stock_manually"("p_product_id" "uuid", "p_employee_id" "uuid", "p_staff_name" "text", "p_adj_type" "public"."inventory_adjustment_type", "p_quantity" numeric, "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_old_stock NUMERIC(14,3);
    v_new_stock NUMERIC(14,3);
    v_biz_id    UUID;
    v_prod_name TEXT;
BEGIN
    PERFORM public.assert_permission((SELECT business_id FROM public.products WHERE id = p_product_id), 'inventory.adjust_stock');
    PERFORM public.assert_business_member((SELECT business_id FROM public.products WHERE id = p_product_id));
    SELECT stock, business_id, name
    INTO v_old_stock, v_biz_id, v_prod_name
    FROM public.products
    WHERE id = p_product_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Product not found: %', p_product_id;
    END IF;

    v_new_stock := CASE
        WHEN p_adj_type = 'Restock'        THEN v_old_stock + p_quantity
        WHEN p_adj_type = 'Damage'         THEN GREATEST(0, v_old_stock - p_quantity)
        WHEN p_adj_type = 'Reconciliation' THEN p_quantity
        ELSE v_old_stock
    END;

    UPDATE public.products
    SET stock = v_new_stock,
        updated_at = NOW()
    WHERE id = p_product_id;

    INSERT INTO public.inventory_adjustments
        (business_id, product_id, product_name, type, quantity_adjusted,
         previous_stock, new_stock, reason, staff_name)
    VALUES (
        v_biz_id,
        p_product_id,
        v_prod_name,
        p_adj_type,
        CASE
            WHEN p_adj_type = 'Restock'        THEN p_quantity
            WHEN p_adj_type = 'Damage'         THEN -p_quantity
            ELSE v_new_stock - v_old_stock
        END,
        v_old_stock,
        v_new_stock,
        p_reason,
        p_staff_name
    );
END;
$$;


ALTER FUNCTION "public"."adjust_stock_manually"("p_product_id" "uuid", "p_employee_id" "uuid", "p_staff_name" "text", "p_adj_type" "public"."inventory_adjustment_type", "p_quantity" numeric, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_purchase"("p_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_p    public.purchases%ROWTYPE;
    v_me   TEXT;
    v_role TEXT;
BEGIN
    SELECT * INTO v_p FROM public.purchases WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That purchase was not found.'; END IF;
    PERFORM public.assert_business_member(v_p.business_id);
    IF v_p.status <> 'Awaiting approval' THEN
        RAISE EXCEPTION 'This purchase is not waiting for approval.';
    END IF;
    IF NOT public.fn_can_approve(v_p.business_id, v_p.total_amount) THEN
        RAISE EXCEPTION 'This amount is above what your role can approve. Ask the owner.';
    END IF;
    v_role := public.fn_my_role(v_p.business_id);
    IF v_p.requested_by_user_id = public.fn_my_user_id() AND COALESCE(v_role, '') NOT IN ('Owner', 'Admin', 'Administrator') THEN
        RAISE EXCEPTION 'Someone else has to approve your own purchase.';
    END IF;
    v_me := public.fn_my_display_name(v_p.business_id);
    PERFORM public.fn_buying_ctx();
    UPDATE public.purchases
    SET status = 'Ordered', approved_amount = total_amount, approved_by = v_me, approved_at = NOW(),
        ordered_at = NOW(), rejected_by = NULL, rejected_at = NULL, reject_reason = NULL,
        notes = CASE WHEN NULLIF(trim(COALESCE(p_note, '')), '') IS NULL THEN notes
                     ELSE trim(COALESCE(notes || E'\n', '') || 'Approved: ' || trim(p_note)) END,
        updated_at = NOW()
    WHERE id = p_id;
    IF v_p.requested_by_user_id IS NOT NULL THEN
        PERFORM public.fn_buying_notify(v_p.business_id, v_p.requested_by_user_id, 'Purchase Approval', 'Purchase approved',
            v_me || ' approved ' || public.fn_purchase_ref(v_p) || ' to ' || v_p.supplier_name || '. It is now ordered.',
            'suppliers', jsonb_build_object('purchaseId', v_p.id));
    END IF;
END;
$$;


ALTER FUNCTION "public"."approve_purchase"("p_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_stock_transfer"("p_transfer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_t    public.stock_transfers%ROWTYPE;
    v_role TEXT;
BEGIN
    SELECT * INTO v_t FROM public.stock_transfers WHERE id = p_transfer_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Transfer not found.'; END IF;
    PERFORM public.assert_business_member(v_t.from_business_id);
    IF v_t.status <> 'awaiting_approval' THEN
        RAISE EXCEPTION 'This transfer is not waiting for approval.';
    END IF;
    IF NOT public.fn_can_approve(v_t.from_business_id, public.fn_transfer_value(v_t.id)) THEN
        RAISE EXCEPTION 'This amount is above what your role can approve. Ask the owner.';
    END IF;
    v_role := public.fn_my_role(v_t.from_business_id);
    IF v_t.sent_by_user_id = public.fn_my_user_id() AND COALESCE(v_role, '') NOT IN ('Owner', 'Admin', 'Administrator') THEN
        RAISE EXCEPTION 'Someone else has to approve your own transfer.';
    END IF;
    UPDATE public.stock_transfers
    SET approved_by_name = public.fn_my_display_name(v_t.from_business_id), approved_at = NOW()
    WHERE id = v_t.id;
    RETURN public.fn_transfer_dispatch(v_t.id);
END;
$$;


ALTER FUNCTION "public"."approve_stock_transfer"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_supplier_bill"("p_id" "uuid", "p_note" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_b public.supplier_bills%ROWTYPE;
BEGIN
    SELECT * INTO v_b FROM public.supplier_bills WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That bill was not found.'; END IF;
    PERFORM public.assert_business_member(v_b.business_id);
    PERFORM public.assert_permission(v_b.business_id, 'supplier_bills.manage');
    PERFORM public.assert_permission(v_b.business_id, 'purchases.approve');
    IF v_b.status <> 'needs_check' THEN
        RAISE EXCEPTION 'This bill doesn''t need a check.';
    END IF;
    IF NULLIF(trim(COALESCE(p_note, '')), '') IS NULL THEN
        RAISE EXCEPTION 'Say why the difference is right (e.g. the price went up).';
    END IF;
    UPDATE public.supplier_bills
    SET status = 'open', check_note = trim(p_note), approved_by = public.fn_my_display_name(v_b.business_id), approved_at = NOW()
    WHERE id = p_id;
    PERFORM public.fn_bill_refresh(p_id);
END;
$$;


ALTER FUNCTION "public"."approve_supplier_bill"("p_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ask_supplier_prices"("p_purchase_id" "uuid", "p_supplier_ids" "uuid"[], "p_via" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_p  public.purchases%ROWTYPE;
    v_s  public.suppliers%ROWTYPE;
    v_me TEXT;
    v_n  INTEGER := 0;
BEGIN
    SELECT * INTO v_p FROM public.purchases WHERE id = p_purchase_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That purchase was not found.'; END IF;
    PERFORM public.assert_business_member(v_p.business_id);
    PERFORM public.assert_permission(v_p.business_id, 'purchases.request_quote');
    IF v_p.status NOT IN ('Pending', 'RFQ') THEN
        RAISE EXCEPTION 'Ask for prices on a draft, before it is ordered.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.purchase_items WHERE purchase_id = p_purchase_id) THEN
        RAISE EXCEPTION 'Add the items you want prices for first.';
    END IF;
    IF COALESCE(array_length(p_supplier_ids, 1), 0) = 0 THEN
        RAISE EXCEPTION 'Choose at least one supplier.';
    END IF;
    v_me := public.fn_my_display_name(v_p.business_id);
    FOR v_s IN SELECT * FROM public.suppliers WHERE id = ANY(p_supplier_ids) AND business_id = v_p.business_id AND deleted_at IS NULL LOOP
        INSERT INTO public.purchase_quotes (business_id, purchase_id, supplier_id, supplier_name, sent_via, asked_by)
        VALUES (v_p.business_id, v_p.id, v_s.id, COALESCE(NULLIF(v_s.company, ''), v_s.name), NULLIF(trim(COALESCE(p_via, '')), ''), v_me)
        ON CONFLICT (purchase_id, supplier_id) DO UPDATE SET sent_via = COALESCE(EXCLUDED.sent_via, public.purchase_quotes.sent_via), asked_at = NOW();
        v_n := v_n + 1;
    END LOOP;
    IF v_n = 0 THEN
        RAISE EXCEPTION 'Those suppliers were not found.';
    END IF;
    PERFORM public.fn_buying_ctx();
    UPDATE public.purchases SET status = 'RFQ', updated_at = NOW() WHERE id = p_purchase_id;
    RETURN v_n;
END;
$$;


ALTER FUNCTION "public"."ask_supplier_prices"("p_purchase_id" "uuid", "p_supplier_ids" "uuid"[], "p_via" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_business_member"("p_business_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF current_setting('role', TRUE) NOT IN ('anon', 'authenticated') THEN
        RETURN;
    END IF;

    IF (p_business_id = ANY(public.get_user_business_ids())) IS NOT TRUE THEN
        RAISE EXCEPTION 'You do not have access to this business.' USING ERRCODE = '42501';
    END IF;
END;
$$;


ALTER FUNCTION "public"."assert_business_member"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_permission"("p_business_id" "uuid", VARIADIC "p_permissions" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NOT public.has_permission(p_business_id, VARIADIC p_permissions) THEN
        RAISE EXCEPTION 'Your role does not allow this.' USING ERRCODE = '42501';
    END IF;
END;
$$;


ALTER FUNCTION "public"."assert_permission"("p_business_id" "uuid", VARIADIC "p_permissions" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_supplier"("p_business_id" "uuid", "p_code" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_s UUID := public.fn_my_supplier_id(p_business_id);
BEGIN
    IF v_s IS NULL THEN
        RAISE EXCEPTION 'You do not have supplier access to this business.' USING ERRCODE = '42501';
    END IF;
    IF p_code IS NOT NULL AND NOT public.supplier_can(p_business_id, p_code) THEN
        RAISE EXCEPTION 'The business has not shared this with suppliers.' USING ERRCODE = '42501';
    END IF;
    RETURN v_s;
END;
$$;


ALTER FUNCTION "public"."assert_supplier"("p_business_id" "uuid", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attach_card_payment_to_sale"("p_card_payment_id" "uuid", "p_transaction_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_card public.card_payments%ROWTYPE;
BEGIN
    SELECT * INTO v_card FROM public.card_payments WHERE id = p_card_payment_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Card payment not found.';
    END IF;
    PERFORM public.assert_business_member(v_card.business_id);
    PERFORM public.assert_permission(v_card.business_id, 'pos.create_sale', 'payments.card');
    IF v_card.purpose <> 'sale' OR v_card.status <> 'success' THEN
        RAISE EXCEPTION 'Only a paid card sale can be linked to a sale.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.transactions WHERE id = p_transaction_id AND business_id = v_card.business_id) THEN
        RAISE EXCEPTION 'Sale not found.';
    END IF;
    UPDATE public.card_payments SET transaction_id = p_transaction_id, updated_at = NOW()
    WHERE id = v_card.id AND transaction_id IS NULL;
END;
$$;


ALTER FUNCTION "public"."attach_card_payment_to_sale"("p_card_payment_id" "uuid", "p_transaction_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attach_sale_to_customer"("p_transaction_id" "uuid", "p_customer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_tx       public.transactions%ROWTYPE;
    v_customer public.customers%ROWTYPE;
    v_manager  BOOLEAN;
    v_points   INTEGER;
BEGIN
    SELECT * INTO v_tx FROM public.transactions
    WHERE id = p_transaction_id AND deleted_at IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Sale not found.';
    END IF;

    PERFORM public.assert_business_member(v_tx.business_id);
    PERFORM public.assert_permission(v_tx.business_id, 'pos.create_sale', 'orders.update', 'customers.loyalty');

    IF v_tx.customer_id IS NOT NULL THEN
        RAISE EXCEPTION 'This sale is already on %''s account.', COALESCE(v_tx.customer_name, 'a customer');
    END IF;
    IF v_tx.payment_method IN ('Credit_Debt', 'Credit') THEN
        RAISE EXCEPTION 'Credit sales get their customer when they are made.';
    END IF;

    v_manager := public.has_permission(v_tx.business_id, 'orders.update', 'customers.loyalty');
    IF NOT v_manager THEN
        IF NOT public.is_my_employee(v_tx.staff_id) THEN
            RAISE EXCEPTION 'You can only add a customer to your own sales. Ask a manager.' USING ERRCODE = '42501';
        END IF;
        IF v_tx.timestamp < NOW() - INTERVAL '24 hours' THEN
            RAISE EXCEPTION 'This sale is more than a day old. Ask a manager to add the customer.' USING ERRCODE = '42501';
        END IF;
    ELSIF v_tx.timestamp < NOW() - INTERVAL '30 days' THEN
        RAISE EXCEPTION 'Sales older than 30 days cannot be moved to a customer.';
    END IF;

    SELECT * INTO v_customer FROM public.customers
    WHERE id = p_customer_id AND business_id = v_tx.business_id AND deleted_at IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Customer not found.';
    END IF;

    UPDATE public.transactions
    SET customer_id = v_customer.id,
        customer_name = v_customer.name,
        updated_at = NOW()
    WHERE id = v_tx.id;

    v_points := GREATEST(0, FLOOR((v_tx.final_total - COALESCE(v_tx.delivery_fee, 0)) * 2))::INTEGER;

    UPDATE public.customers
    SET loyalty_points = COALESCE(loyalty_points, 0) + v_points,
        purchases_count = purchases_count + 1
    WHERE id = v_customer.id;

    IF v_points > 0 THEN
        INSERT INTO public.loyalty_points_earned (business_id, customer_id, points, source, amount, transaction_id)
        VALUES (v_tx.business_id, v_customer.id, v_points, 'sale', v_tx.final_total - COALESCE(v_tx.delivery_fee, 0), v_tx.id);
    END IF;

    RETURN jsonb_build_object('points', v_points, 'customerId', v_customer.id, 'customerName', v_customer.name);
END;
$$;


ALTER FUNCTION "public"."attach_sale_to_customer"("p_transaction_id" "uuid", "p_customer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_order_payment"("p_order_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_order public.online_orders%ROWTYPE;
    v_short TEXT;
BEGIN
    SELECT * INTO v_order FROM public.online_orders
    WHERE id = p_order_id AND account_id = p_user_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order not found.';
    END IF;
    IF v_order.status NOT IN ('pending_payment', 'payment_failed') THEN
        RAISE EXCEPTION 'This order has already been paid or closed.';
    END IF;

    SELECT i.product_name INTO v_short
    FROM public.online_order_items i
    JOIN public.products p ON p.id = i.product_id
    WHERE i.order_id = p_order_id AND p.stock < i.quantity
    LIMIT 1;
    IF v_short IS NOT NULL THEN
        RAISE EXCEPTION 'We no longer have enough % for this order. Please cancel it and order again.', v_short;
    END IF;

    RETURN jsonb_build_object('total', v_order.total, 'orderNumber', v_order.order_number, 'businessId', v_order.business_id);
END;
$$;


ALTER FUNCTION "public"."begin_order_payment"("p_order_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."buying_nightly"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_r RECORD;
    v_n INTEGER := 0;
BEGIN
    FOR v_r IN
        SELECT p.business_id, COUNT(*) AS low, string_agg(p.name, ', ' ORDER BY p.name) FILTER (WHERE TRUE) AS names
        FROM public.products p
        JOIN public.businesses b ON b.id = p.business_id AND b.deleted_at IS NULL
        WHERE p.deleted_at IS NULL
          AND COALESCE(p.reorder_level, NULLIF(p.min_stock, 0)) IS NOT NULL
          AND p.stock <= COALESCE(p.reorder_level, NULLIF(p.min_stock, 0))
          AND NOT EXISTS (
              SELECT 1 FROM public.purchase_items pi JOIN public.purchases pu ON pu.id = pi.purchase_id
              WHERE pi.product_id = p.id AND pu.status IN ('Pending', 'RFQ', 'Awaiting approval', 'Ordered', 'Part received')
                AND pi.qty_received < pi.quantity)
          AND NOT EXISTS (
              SELECT 1 FROM public.stock_transfer_items i JOIN public.stock_transfers t ON t.id = i.transfer_id
              WHERE t.to_business_id = p.business_id AND t.status IN ('requested', 'draft', 'awaiting_approval', 'in_transit')
                AND (i.to_product_id = p.id OR lower(btrim(i.product_name)) = lower(btrim(p.name))))
        GROUP BY p.business_id
    LOOP
        CONTINUE WHEN EXISTS (
            SELECT 1 FROM public.notifications n
            WHERE n.business_id = v_r.business_id AND n.type = 'Reorder Suggestion' AND n.created_at > NOW() - INTERVAL '20 hours');
        INSERT INTO public.notifications (business_id, title, message, type, priority, action_type, action_target, payload, created_by)
        VALUES (v_r.business_id, 'Time to reorder',
                v_r.low || CASE WHEN v_r.low = 1 THEN ' product is' ELSE ' products are' END || ' at or below the reorder level and not on order: '
                    || left(v_r.names, 160) || CASE WHEN length(v_r.names) > 160 THEN '…' ELSE '' END || '. See Buying → Reorder.',
                'Reorder Suggestion', 'medium', 'navigate', 'buying', jsonb_build_object('count', v_r.low), 'system');
        v_n := v_n + 1;
    END LOOP;

    FOR v_r IN
        SELECT sb.* FROM public.supplier_bills sb
        JOIN public.businesses b ON b.id = sb.business_id AND b.deleted_at IS NULL
        WHERE sb.status = 'open' AND sb.balance > 0 AND sb.due_date <= public.sd_today() + 3
          AND NOT EXISTS (
              SELECT 1 FROM public.notifications n
              WHERE n.business_id = sb.business_id AND n.type = 'Supplier Bill Due'
                AND n.payload->>'billId' = sb.id::TEXT AND n.created_at > NOW() - INTERVAL '6 days')
    LOOP
        INSERT INTO public.notifications (business_id, title, message, type, priority, action_type, action_target, payload, created_by)
        VALUES (v_r.business_id,
                CASE WHEN v_r.due_date < public.sd_today() THEN 'Supplier bill overdue' ELSE 'Supplier bill due soon' END,
                v_r.number || ' from ' || v_r.supplier_name || ': KSh ' || trim(to_char(v_r.balance, 'FM999,999,999,990'))
                    || CASE WHEN v_r.due_date < public.sd_today() THEN ' was due ' ELSE ' is due ' END || to_char(v_r.due_date, 'DD Mon') || '.',
                'Supplier Bill Due', 'high', 'navigate', 'buying', jsonb_build_object('billId', v_r.id), 'system');
        v_n := v_n + 1;
    END LOOP;
    RETURN v_n;
END;
$$;


ALTER FUNCTION "public"."buying_nightly"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."buying_overview"("p_business_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_role TEXT := public.fn_my_role(p_business_id);
    v_set  public.buying_settings%ROWTYPE;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'purchases.view', 'supplier_bills.manage', 'purchases.approve');
    SELECT * INTO v_set FROM public.buying_settings WHERE business_id = p_business_id;

    RETURN jsonb_build_object(
        'settings', jsonb_build_object(
            'tolerancePct', COALESCE(v_set.bill_tolerance_pct, 2),
            'safetyDays', COALESCE(v_set.safety_days, 3),
            'limits', COALESCE((SELECT jsonb_agg(jsonb_build_object('role', role, 'max', max_amount) ORDER BY role)
                                FROM public.purchase_approval_limits WHERE business_id = p_business_id), '[]'::JSONB),
            'canEdit', public.is_owner_or_admin(p_business_id),
            'updatedBy', v_set.updated_by, 'updatedAt', v_set.updated_at),
        'myRole', v_role,
        'myLimit', public.fn_role_limit(p_business_id, v_role),
        'approvals', jsonb_build_object(
            'purchases', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                    'id', p.id, 'ref', public.fn_purchase_ref(p), 'supplier', p.supplier_name, 'total', p.total_amount,
                    'by', p.created_by, 'date', p.date, 'mine', p.requested_by_user_id = public.fn_my_user_id(),
                    'canApprove', public.fn_can_approve(p_business_id, p.total_amount),
                    'items', (SELECT jsonb_agg(jsonb_build_object('name', i.name, 'quantity', i.quantity, 'unit', i.unit, 'price', i.price) ORDER BY i.created_at)
                              FROM public.purchase_items i WHERE i.purchase_id = p.id)
                ) ORDER BY p.date)
                FROM public.purchases p WHERE p.business_id = p_business_id AND p.status = 'Awaiting approval'), '[]'::JSONB),
            'transfers', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                    'id', t.id, 'reference', t.reference, 'toName', b.name, 'by', t.sent_by_name, 'createdAt', t.created_at,
                    'value', round(public.fn_transfer_value(t.id), 2),
                    'mine', t.sent_by_user_id = public.fn_my_user_id(),
                    'canApprove', public.fn_can_approve(p_business_id, public.fn_transfer_value(t.id))
                ) ORDER BY t.created_at)
                FROM public.stock_transfers t JOIN public.businesses b ON b.id = t.to_business_id
                WHERE t.from_business_id = p_business_id AND t.status = 'awaiting_approval'), '[]'::JSONB),
            'bills', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                    'id', sb.id, 'number', sb.number, 'supplier', sb.supplier_name, 'subtotal', sb.subtotal,
                    'receiptsValue', sb.receipts_value, 'difference', sb.difference, 'by', sb.created_by
                ) ORDER BY sb.created_at)
                FROM public.supplier_bills sb WHERE sb.business_id = p_business_id AND sb.status = 'needs_check'), '[]'::JSONB)
        ),
        'toBill', COALESCE((SELECT jsonb_agg(x ORDER BY x->>'supplier') FROM (
            SELECT jsonb_build_object(
                'purchaseId', p.id, 'ref', public.fn_purchase_ref(p), 'supplier', p.supplier_name, 'supplierId', p.supplier_id,
                'value', SUM(r.total_value),
                'receipts', jsonb_agg(jsonb_build_object('id', r.id, 'number', r.number, 'receivedAt', r.received_at, 'value', r.total_value) ORDER BY r.received_at)
            ) AS x
            FROM public.purchase_receipts r JOIN public.purchases p ON p.id = r.purchase_id
            WHERE r.business_id = p_business_id AND r.bill_id IS NULL
            GROUP BY p.id
        ) q), '[]'::JSONB),
        'bills', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                'id', sb.id, 'number', sb.number, 'supplier', sb.supplier_name, 'supplierId', sb.supplier_id, 'purchaseId', sb.purchase_id,
                'purchaseRef', (SELECT public.fn_purchase_ref(p) FROM public.purchases p WHERE p.id = sb.purchase_id),
                'supplierInvoiceNo', sb.supplier_invoice_no, 'billDate', sb.bill_date, 'dueDate', sb.due_date,
                'subtotal', sb.subtotal, 'vatTotal', sb.vat_total, 'total', sb.total, 'receiptsValue', sb.receipts_value,
                'difference', sb.difference, 'status', sb.status, 'checkNote', sb.check_note, 'approvedBy', sb.approved_by,
                'paid', sb.paid, 'balance', sb.balance, 'note', sb.note, 'by', sb.created_by, 'voidReason', sb.void_reason,
                'receipts', (SELECT jsonb_agg(r.number ORDER BY r.received_at) FROM public.purchase_receipts r WHERE r.bill_id = sb.id)
            ) ORDER BY sb.bill_date DESC, sb.number DESC)
            FROM (SELECT * FROM public.supplier_bills WHERE business_id = p_business_id ORDER BY bill_date DESC, created_at DESC LIMIT 300) sb), '[]'::JSONB),
        'returns', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                'id', r.id, 'number', r.number, 'supplier', r.supplier_name, 'purchaseId', r.purchase_id, 'reason', r.reason,
                'total', r.total, 'by', r.created_by, 'createdAt', r.created_at,
                'lines', (SELECT jsonb_agg(jsonb_build_object('name', l.name, 'quantity', l.quantity, 'unit', l.unit, 'unitCost', l.unit_cost))
                          FROM public.supplier_return_lines l WHERE l.return_id = r.id)
            ) ORDER BY r.created_at DESC)
            FROM (SELECT * FROM public.supplier_returns WHERE business_id = p_business_id ORDER BY created_at DESC LIMIT 200) r), '[]'::JSONB),
        'dueSoon', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                'id', sb.id, 'number', sb.number, 'supplier', sb.supplier_name, 'dueDate', sb.due_date, 'balance', sb.balance
            ) ORDER BY sb.due_date)
            FROM public.supplier_bills sb
            WHERE sb.business_id = p_business_id AND sb.status = 'open' AND sb.balance > 0
              AND sb.due_date <= public.sd_today() + 7), '[]'::JSONB)
    );
END;
$$;


ALTER FUNCTION "public"."buying_overview"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_customer_tier"("points" integer) RETURNS "public"."customer_tier"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
    IF points >= 60000 THEN
        RETURN 'Gold';
    ELSIF points >= 20000 THEN
        RETURN 'Silver';
    ELSE
        RETURN 'Bronze';
    END IF;
END;
$$;


ALTER FUNCTION "public"."calculate_customer_tier"("points" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_my_order"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    UPDATE public.online_orders
    SET status = 'cancelled'
    WHERE id = p_order_id
      AND account_id = auth.uid()
      AND status IN ('pending_payment', 'payment_failed');
    IF NOT FOUND THEN
        RAISE EXCEPTION 'This order can no longer be cancelled here. Please message us.';
    END IF;
END;
$$;


ALTER FUNCTION "public"."cancel_my_order"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_sales_delivery"("p_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_d   public.sales_deliveries%ROWTYPE;
    v_l   RECORD;
    v_old NUMERIC;
    v_who TEXT := public.acc_who();
BEGIN
    SELECT * INTO v_d FROM public.sales_deliveries WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'That delivery was not found.';
    END IF;
    PERFORM public.assert_business_member(v_d.business_id);
    PERFORM public.assert_permission(v_d.business_id, 'sales_orders.manage');
    IF v_d.cancelled_at IS NOT NULL THEN
        RETURN;
    END IF;
    PERFORM 1 FROM public.sales_orders WHERE id = v_d.order_id FOR UPDATE;
    FOR v_l IN SELECT * FROM public.sales_delivery_lines WHERE delivery_id = p_id LOOP
        UPDATE public.sales_order_lines SET qty_delivered = GREATEST(qty_delivered - v_l.quantity, 0) WHERE id = v_l.order_line_id;
        IF v_l.product_id IS NOT NULL THEN
            SELECT stock INTO v_old FROM public.products WHERE id = v_l.product_id FOR UPDATE;
            IF FOUND THEN
                UPDATE public.products SET stock = v_old + v_l.quantity, updated_at = NOW() WHERE id = v_l.product_id;
                INSERT INTO public.inventory_adjustments (business_id, product_id, product_name, type, quantity_adjusted,
                    previous_stock, new_stock, reason, reference_number, staff_name)
                VALUES (v_d.business_id, v_l.product_id, v_l.name, 'Restock', v_l.quantity, v_old, v_old + v_l.quantity,
                    'Delivery undone', v_d.number, v_who);
            END IF;
        END IF;
    END LOOP;
    UPDATE public.sales_deliveries
    SET cancelled_at = NOW(), cancelled_by = v_who, cancel_reason = left(NULLIF(trim(p_reason), ''), 300)
    WHERE id = p_id;
    PERFORM public.sd_order_refresh(v_d.order_id);
END;
$$;


ALTER FUNCTION "public"."cancel_sales_delivery"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_sales_order"("p_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_o public.sales_orders%ROWTYPE;
BEGIN
    SELECT * INTO v_o FROM public.sales_orders WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'That order was not found.';
    END IF;
    PERFORM public.assert_business_member(v_o.business_id);
    PERFORM public.assert_permission(v_o.business_id, 'sales_orders.manage');
    IF v_o.status = 'cancelled' THEN
        RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM public.sales_order_lines WHERE order_id = p_id AND (qty_delivered > 0 OR qty_invoiced > 0)) THEN
        RAISE EXCEPTION 'Undo its deliveries and void its invoices first; then the order can be cancelled.';
    END IF;
    UPDATE public.sales_orders
    SET status = 'cancelled', cancelled_at = NOW(), cancelled_by = public.acc_who(),
        cancel_reason = left(NULLIF(trim(p_reason), ''), 300), updated_at = NOW()
    WHERE id = p_id;
END;
$$;


ALTER FUNCTION "public"."cancel_sales_order"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_stock_transfer"("p_transfer_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_t       public.stock_transfers;
    v_item    public.stock_transfer_items;
    v_stock   NUMERIC(14,3);
    v_name    TEXT;
    v_me      TEXT;
    v_side    UUID;
BEGIN
    SELECT * INTO v_t FROM public.stock_transfers WHERE id = p_transfer_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer not found.';
    END IF;
    IF v_t.status IN ('cancelled', 'declined') THEN
        RETURN;
    END IF;
    IF v_t.status = 'received' THEN
        RAISE EXCEPTION 'This transfer was already received, so it can''t be cancelled. Send the stock back with a new transfer.';
    END IF;
    IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
        RAISE EXCEPTION 'Say why this transfer is being cancelled.';
    END IF;

    IF v_t.status = 'requested' THEN
        IF v_t.to_business_id = ANY(public.get_user_business_ids())
           AND public.has_permission(v_t.to_business_id, 'inventory.request_transfer', 'inventory.transfer_stock') THEN
            v_side := v_t.to_business_id;
        ELSE
            PERFORM public.assert_business_member(v_t.from_business_id);
            PERFORM public.assert_permission(v_t.from_business_id, 'inventory.transfer_stock');
            v_side := v_t.from_business_id;
        END IF;
    ELSE
        PERFORM public.assert_business_member(v_t.from_business_id);
        PERFORM public.assert_permission(v_t.from_business_id, 'inventory.transfer_stock');
        v_side := v_t.from_business_id;
    END IF;
    v_me := public.fn_my_display_name(v_side);

    IF v_t.status = 'in_transit' THEN
        FOR v_item IN SELECT * FROM public.stock_transfer_items WHERE transfer_id = v_t.id ORDER BY from_product_id LOOP
            CONTINUE WHEN v_item.from_product_id IS NULL;
            SELECT stock, name INTO v_stock, v_name FROM public.products WHERE id = v_item.from_product_id FOR UPDATE;
            CONTINUE WHEN NOT FOUND;
            UPDATE public.products SET stock = stock + v_item.quantity_sent, updated_at = NOW() WHERE id = v_item.from_product_id;
            INSERT INTO public.inventory_adjustments (
                business_id, product_id, product_name, type, quantity_adjusted, previous_stock, new_stock,
                reason, staff_name, reference_number, notes
            ) VALUES (
                v_t.from_business_id, v_item.from_product_id, v_name, 'Transfer Return', v_item.quantity_sent,
                v_stock, v_stock + v_item.quantity_sent,
                'Transfer cancelled', v_me, v_t.reference, btrim(p_reason)
            );
        END LOOP;
    END IF;

    UPDATE public.stock_transfers
    SET status = 'cancelled', cancelled_by_name = v_me, cancelled_at = NOW(),
        cancel_reason = btrim(p_reason), updated_at = NOW()
    WHERE id = v_t.id;

    -- Tell the other branch, unless nothing ever reached them (a draft never sent).
    IF v_t.status IN ('in_transit', 'requested') THEN
        INSERT INTO public.notifications (business_id, title, message, type, priority, action_type, action_target, payload, created_by)
        SELECT CASE WHEN v_side = v_t.from_business_id THEN v_t.to_business_id ELSE v_t.from_business_id END,
               CASE WHEN v_t.status = 'requested' THEN 'Stock request withdrawn' ELSE 'Transfer cancelled' END,
               b.name || ' cancelled ' || v_t.reference || ': ' || btrim(p_reason),
               'Stock Transfer', 'medium', 'navigate', 'stock-transfers',
               jsonb_build_object('transferId', v_t.id, 'reference', v_t.reference), 'system'
        FROM public.businesses b WHERE b.id = v_side;
    END IF;
END;
$$;


ALTER FUNCTION "public"."cancel_stock_transfer"("p_transfer_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_owner_exists"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
