CREATE OR REPLACE FUNCTION "public"."check_promo_code"("p_slug" "text", "p_code" "text", "p_subtotal" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_promo public.website_promo_codes%ROWTYPE;
    v_value NUMERIC;
BEGIN
    SELECT pc.* INTO v_promo
    FROM public.website_promo_codes pc
    JOIN public.businesses b ON b.id = pc.business_id
    WHERE b.website_slug = p_slug AND b.deleted_at IS NULL
      AND pc.code = upper(trim(COALESCE(p_code, '')));
    IF NOT FOUND THEN
        RAISE EXCEPTION 'We don''t recognise that promo code.';
    END IF;
    v_value := public.fn_promo_value(v_promo, COALESCE(p_subtotal, 0), auth.uid());
    RETURN jsonb_build_object(
        'code', v_promo.code,
        'description', v_promo.description,
        'kind', v_promo.kind,
        'value', v_promo.value,
        'saving', v_value
    );
END;
$$;


ALTER FUNCTION "public"."check_promo_code"("p_slug" "text", "p_code" "text", "p_subtotal" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("p_key" "text", "p_limit" integer, "p_window_seconds" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    INSERT INTO public.rate_limits AS r (key, window_start, count)
    VALUES (p_key, NOW(), 1)
    ON CONFLICT (key) DO UPDATE SET
        count        = CASE WHEN r.window_start < NOW() - make_interval(secs => p_window_seconds) THEN 1 ELSE r.count + 1 END,
        window_start = CASE WHEN r.window_start < NOW() - make_interval(secs => p_window_seconds) THEN NOW() ELSE r.window_start END
    RETURNING count INTO v_count;

    RETURN v_count <= p_limit;
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("p_key" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."choose_supplier_quote"("p_quote_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_q     public.purchase_quotes%ROWTYPE;
    v_p     public.purchases%ROWTYPE;
    v_total NUMERIC;
BEGIN
    SELECT * INTO v_q FROM public.purchase_quotes WHERE id = p_quote_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That quote was not found.'; END IF;
    PERFORM public.assert_business_member(v_q.business_id);
    PERFORM public.assert_permission(v_q.business_id, 'purchases.request_quote');
    PERFORM public.assert_permission(v_q.business_id, 'purchases.create', 'purchases.update');
    SELECT * INTO v_p FROM public.purchases WHERE id = v_q.purchase_id FOR UPDATE;
    IF v_p.status NOT IN ('Pending', 'RFQ') THEN
        RAISE EXCEPTION 'This purchase was already ordered.';
    END IF;
    IF v_q.status <> 'priced' THEN
        RAISE EXCEPTION 'Enter this supplier''s prices first.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.purchase_quote_lines WHERE quote_id = v_q.id AND available) THEN
        RAISE EXCEPTION 'This supplier can''t supply any of the items.';
    END IF;

    PERFORM public.fn_buying_ctx();
    DELETE FROM public.purchase_items pi
    WHERE pi.purchase_id = v_p.id
      AND NOT EXISTS (SELECT 1 FROM public.purchase_quote_lines ql WHERE ql.quote_id = v_q.id AND ql.purchase_item_id = pi.id AND ql.available);
    UPDATE public.purchase_items pi SET price = ql.unit_price
    FROM public.purchase_quote_lines ql
    WHERE ql.quote_id = v_q.id AND ql.purchase_item_id = pi.id;
    SELECT COALESCE(SUM(round(quantity * price, 2)), 0) INTO v_total FROM public.purchase_items WHERE purchase_id = v_p.id;

    UPDATE public.purchase_quotes SET status = CASE WHEN id = v_q.id THEN 'won' ELSE 'lost' END
    WHERE purchase_id = v_p.id;
    UPDATE public.purchases
    SET supplier_id = v_q.supplier_id, supplier_name = v_q.supplier_name, total_amount = v_total,
        status = 'Pending', updated_at = NOW()
    WHERE id = v_p.id;
    RETURN public.place_purchase_order(v_p.id);
END;
$$;


ALTER FUNCTION "public"."choose_supplier_quote"("p_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_purchase"("p_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_p public.purchases%ROWTYPE;
BEGIN
    SELECT * INTO v_p FROM public.purchases WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That purchase was not found.'; END IF;
    PERFORM public.assert_business_member(v_p.business_id);
    PERFORM public.assert_permission(v_p.business_id, 'purchases.update', 'purchases.approve', 'purchases.manage');
    IF v_p.status <> 'Part received' THEN
        RAISE EXCEPTION 'Only a part-received purchase can be closed.';
    END IF;
    IF NULLIF(trim(COALESCE(p_reason, '')), '') IS NULL THEN
        RAISE EXCEPTION 'Say why the rest isn''t coming.';
    END IF;
    PERFORM public.fn_buying_ctx();
    UPDATE public.purchases
    SET status = 'Received', closed_note = trim(p_reason), updated_at = NOW()
    WHERE id = p_id;
END;
$$;


ALTER FUNCTION "public"."close_purchase"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_airtel_payment"("p_reference" "text", "p_success" boolean, "p_airtel_money_id" "text", "p_code" "text", "p_message" "text", "p_raw" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_req  public.airtel_transactions%ROWTYPE;
    v_name TEXT;
    v_pid  UUID;
    v_ref  TEXT;
BEGIN
    SELECT * INTO v_req FROM public.airtel_transactions WHERE reference = p_reference FOR UPDATE;
    IF NOT FOUND THEN
        RETURN 'unknown';
    END IF;
    IF v_req.status = 'Completed' OR (v_req.status <> 'Pending' AND NOT p_success) THEN
        RETURN 'duplicate';
    END IF;

    IF NOT p_success THEN
        UPDATE public.airtel_transactions
        SET status = 'Failed', result_code = p_code, result_message = p_message,
            raw = COALESCE(p_raw, raw), updated_at = NOW()
        WHERE id = v_req.id;
        IF v_req.online_order_id IS NOT NULL THEN
            UPDATE public.online_orders SET status = 'payment_failed'
            WHERE id = v_req.online_order_id AND status = 'pending_payment'
              AND NOT EXISTS (SELECT 1 FROM public.mpesa_transactions m
                              WHERE m.online_order_id = v_req.online_order_id AND m.status = 'Pending')
              AND NOT EXISTS (SELECT 1 FROM public.card_payments c
                              WHERE c.online_order_id = v_req.online_order_id AND c.status = 'pending')
              AND NOT EXISTS (SELECT 1 FROM public.airtel_transactions t
                              WHERE t.online_order_id = v_req.online_order_id AND t.status = 'Pending' AND t.id <> v_req.id);
        END IF;
        RETURN 'failed';
    END IF;

    v_ref := COALESCE(NULLIF(trim(p_airtel_money_id), ''), 'AIRTEL-' || v_req.reference);

    IF v_req.online_order_id IS NOT NULL THEN
        UPDATE public.airtel_transactions
        SET status = 'Completed', airtel_money_id = v_ref, result_code = p_code, result_message = p_message,
            raw = COALESCE(p_raw, raw), paid_at = NOW(), updated_at = NOW()
        WHERE id = v_req.id;
        RETURN public.fn_settle_online_order_airtel(v_req.id);
    END IF;

    SELECT name INTO v_name FROM public.customers WHERE id = v_req.customer_id;

    v_pid := public.process_business_payment(
        v_req.business_id, v_ref, v_req.amount, 'Airtel Money',
        COALESCE(v_name, 'Airtel ' || v_req.phone), v_req.phone, 'Success', NOW(),
        v_req.customer_id, v_name,
        CASE WHEN v_req.customer_id IS NULL THEN 'walk-in' ELSE 'customer' END,
        COALESCE(v_req.description, 'Airtel Money prompt'), v_req.requested_by
    );

    UPDATE public.airtel_transactions
    SET status = 'Completed', airtel_money_id = v_ref, result_code = p_code, result_message = p_message,
        raw = COALESCE(p_raw, raw), payment_id = v_pid, paid_at = NOW(), updated_at = NOW()
    WHERE id = v_req.id;

    PERFORM public.fn_notify_staff(v_req.business_id, 'Airtel Money payment received',
        format('Ksh %s from %s (%s).', v_req.amount, COALESCE(v_name, v_req.phone), v_ref),
        jsonb_build_object('paymentId', v_pid));
    RETURN 'recorded';
END;
$$;


ALTER FUNCTION "public"."confirm_airtel_payment"("p_reference" "text", "p_success" boolean, "p_airtel_money_id" "text", "p_code" "text", "p_message" "text", "p_raw" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_online_order_payment"("p_checkout_request_id" "text", "p_result_code" integer, "p_amount" numeric, "p_receipt" "text", "p_raw" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_payment public.mpesa_transactions%ROWTYPE;
    v_order   public.online_orders%ROWTYPE;
    v_tx_id   UUID;
    v_short   TEXT;
    v_reason  TEXT;
BEGIN
    SELECT * INTO v_payment FROM public.mpesa_transactions
    WHERE checkout_request_id = p_checkout_request_id AND online_order_id IS NOT NULL
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN 'unknown';
    END IF;
    -- A status check can mark a row Failed before the customer's success callback arrives,
    -- so only Completed blocks a success. Money received must never be dropped.
    IF v_payment.status = 'Completed' OR (v_payment.status <> 'Pending' AND p_result_code <> 0) THEN
        RETURN 'duplicate';
    END IF;

    SELECT * INTO v_order FROM public.online_orders WHERE id = v_payment.online_order_id FOR UPDATE;

    IF p_result_code <> 0 THEN
        UPDATE public.mpesa_transactions
        SET status = 'Failed', raw_callback = p_raw
        WHERE id = v_payment.id;

        IF v_order.status = 'pending_payment' AND NOT EXISTS (
            SELECT 1 FROM public.mpesa_transactions m
            WHERE m.online_order_id = v_order.id AND m.status = 'Pending' AND m.id <> v_payment.id
        ) THEN
            UPDATE public.online_orders SET status = 'payment_failed' WHERE id = v_order.id;
        END IF;
        RETURN 'failed';
    END IF;

    UPDATE public.mpesa_transactions
    SET status = 'Completed',
        amount = COALESCE(p_amount, amount),
        receipt_number = p_receipt,
        mpesa_receipt_timestamp = NOW(),
        raw_callback = p_raw
    WHERE id = v_payment.id;

    IF COALESCE(p_amount, 0) <> v_order.total THEN
        v_reason := format('M-Pesa receipt %s paid %s but the order total is %s.', p_receipt, p_amount, v_order.total);
    ELSIF v_order.status NOT IN ('pending_payment', 'payment_failed') THEN
        v_reason := format('Extra M-Pesa payment %s of %s arrived on an order that was already %s. It may need a refund.',
                           p_receipt, p_amount, v_order.status);
    END IF;

    IF v_reason IS NOT NULL THEN
        UPDATE public.online_orders
        SET needs_attention = TRUE,
            attention_reason = concat_ws(' ', attention_reason, v_reason)
        WHERE id = v_order.id;
        PERFORM public.fn_notify_staff(v_order.business_id, 'Online payment needs checking',
            'Order #' || v_order.order_number || ': ' || v_reason, jsonb_build_object('orderId', v_order.id));
        RETURN 'flagged';
    END IF;

    SELECT i.product_name INTO v_short
    FROM public.online_order_items i
    JOIN public.products p ON p.id = i.product_id
    WHERE i.order_id = v_order.id AND p.stock < i.quantity
    LIMIT 1;

    INSERT INTO public.transactions
        (business_id, total, discount, tax, final_total, amount_paid, payment_method,
         customer_id, customer_name, staff_name, note, is_delivery, delivery_fee, reference_id)
    SELECT v_order.business_id, v_order.subtotal + v_order.delivery_fee, v_order.discount, 0, v_order.total, v_order.total, 'M-Pesa',
           public.fn_account_customer(a.id, v_order.business_id), v_order.customer_name, 'Website',
           'Online order #' || v_order.order_number || ', M-Pesa ' || COALESCE(p_receipt, ''),
           v_order.fulfilment = 'delivery', v_order.delivery_fee, 'online-' || v_order.id
    FROM (SELECT 1) one
    LEFT JOIN public.customer_accounts a ON a.id = v_order.account_id
    RETURNING id INTO v_tx_id;

    INSERT INTO public.transaction_items (transaction_id, product_id, product_name, unit_price, quantity, line_total)
    SELECT v_tx_id, product_id, product_name, unit_price, quantity, line_total
    FROM public.online_order_items
    WHERE order_id = v_order.id;

    UPDATE public.mpesa_transactions SET transaction_id = v_tx_id WHERE id = v_payment.id;

    UPDATE public.online_orders
    SET status = 'paid',
        paid_at = NOW(),
        mpesa_receipt = p_receipt,
        transaction_id = v_tx_id,
        needs_attention = v_short IS NOT NULL,
        attention_reason = CASE WHEN v_short IS NOT NULL
            THEN 'Paid, but stock of ' || v_short || ' ran short before payment arrived.' END
    WHERE id = v_order.id;

    PERFORM public.fn_customer_message(v_order.account_id, v_order.id,
        'We received your payment for order #' || v_order.order_number || '. M-Pesa receipt: ' || COALESCE(p_receipt, '-') || '.');
    PERFORM public.fn_notify_staff(v_order.business_id, 'New online order',
        'Order #' || v_order.order_number || ' from ' || v_order.customer_name || ' is paid.'
            || CASE WHEN v_short IS NOT NULL THEN ' Stock of ' || v_short || ' is short.' ELSE '' END,
        jsonb_build_object('orderId', v_order.id));

    RETURN 'paid';
END;
$$;


ALTER FUNCTION "public"."confirm_online_order_payment"("p_checkout_request_id" "text", "p_result_code" integer, "p_amount" numeric, "p_receipt" "text", "p_raw" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_store_payment_request"("p_checkout_request_id" "text", "p_result_code" integer, "p_amount" numeric, "p_receipt" "text", "p_raw" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_req     public.mpesa_transactions%ROWTYPE;
    v_name    TEXT;
    v_pid     UUID;
BEGIN
    SELECT * INTO v_req FROM public.mpesa_transactions
    WHERE checkout_request_id = p_checkout_request_id
      AND online_order_id IS NULL AND business_id IS NOT NULL
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN 'unknown';
    END IF;
    IF v_req.status = 'Completed' OR (v_req.status <> 'Pending' AND p_result_code <> 0) THEN
        RETURN 'duplicate';
    END IF;

    IF p_result_code <> 0 THEN
        UPDATE public.mpesa_transactions
        SET status = 'Failed', raw_callback = COALESCE(p_raw, raw_callback), updated_at = NOW()
        WHERE id = v_req.id;
        RETURN 'failed';
    END IF;

    IF p_receipt IS NULL THEN
        RAISE EXCEPTION 'A successful M-Pesa result arrived without a receipt number.';
    END IF;

    SELECT name INTO v_name FROM public.customers WHERE id = v_req.customer_id;

    v_pid := public.process_business_payment(
        v_req.business_id, p_receipt, COALESCE(p_amount, v_req.amount), 'M-Pesa',
        COALESCE(v_name, 'M-Pesa ' || v_req.phone), v_req.phone, 'Success', NOW(),
        v_req.customer_id, v_name,
        CASE WHEN v_req.customer_id IS NULL THEN 'walk-in' ELSE 'customer' END,
        COALESCE(v_req.description, 'M-Pesa prompt'), v_req.requested_by
    );

    UPDATE public.mpesa_transactions
    SET status = 'Completed', receipt_number = p_receipt,
        amount = COALESCE(p_amount, amount), mpesa_receipt_timestamp = NOW(),
        raw_callback = p_raw, payment_id = v_pid, updated_at = NOW()
    WHERE id = v_req.id;

    PERFORM public.fn_notify_staff(v_req.business_id, 'M-Pesa payment received',
        format('Ksh %s from %s (%s).', COALESCE(p_amount, v_req.amount), COALESCE(v_name, v_req.phone), p_receipt),
        jsonb_build_object('paymentId', v_pid));
    RETURN 'recorded';
END;
$$;


ALTER FUNCTION "public"."confirm_store_payment_request"("p_checkout_request_id" "text", "p_result_code" integer, "p_amount" numeric, "p_receipt" "text", "p_raw" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_assistant_quota"("p_business_id" "uuid", "p_visitor" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_visitor_uses INTEGER;
    v_business_uses INTEGER;
BEGIN
    INSERT INTO public.assistant_usage (bucket, window_start, uses)
    VALUES ('visitor:' || p_visitor, date_trunc('hour', NOW()), 1)
    ON CONFLICT (bucket, window_start) DO UPDATE SET uses = assistant_usage.uses + 1
    RETURNING uses INTO v_visitor_uses;

    INSERT INTO public.assistant_usage (bucket, window_start, uses)
    VALUES ('business:' || p_business_id, date_trunc('day', NOW()), 1)
    ON CONFLICT (bucket, window_start) DO UPDATE SET uses = assistant_usage.uses + 1
    RETURNING uses INTO v_business_uses;

    RETURN v_visitor_uses <= 40 AND v_business_uses <= 2000;
END;
$$;


ALTER FUNCTION "public"."consume_assistant_quota"("p_business_id" "uuid", "p_visitor" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_business_with_owner"("p_name" "text", "p_type" "text", "p_country" "text", "p_currency" "text", "p_logo_url" "text", "p_description" "text", "p_address" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_business_id UUID;
    v_user_id     UUID;
BEGIN
    IF NOT public.account_email_verified(auth.uid()) THEN
        RAISE EXCEPTION 'Please verify your email before creating a business.' USING ERRCODE = '42501';
    END IF;
    IF current_setting('role', TRUE) IN ('anon', 'authenticated')
       AND EXISTS (SELECT 1 FROM public.business_memberships WHERE role = 'Owner')
       AND NOT EXISTS (
           SELECT 1
           FROM public.business_memberships bm
           JOIN public.users u ON u.id = bm.user_id
           WHERE u.auth_user_id = auth.uid() AND bm.role = 'Owner' AND bm.status = 'Active'
       ) THEN
        RAISE EXCEPTION 'Only the business owner can create a new business.' USING ERRCODE = '42501';
    END IF;
    SELECT id INTO v_user_id
    FROM public.users
    WHERE auth_user_id = auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'User profile not found. Please complete signup first.';
    END IF;

    INSERT INTO public.businesses
        (name, business_type, country, currency, logo_url, description, address)
    VALUES
        (p_name, p_type, p_country, p_currency, p_logo_url, p_description, p_address)
    RETURNING id INTO v_business_id;

    -- Create the default main branch
    INSERT INTO public.branches (business_id, name, address)
    VALUES (v_business_id, 'Main branch', p_address);

    -- Activate the owner's membership
    INSERT INTO public.business_memberships (business_id, user_id, role, status)
    VALUES (v_business_id, v_user_id, 'Owner', 'Active');

    -- Create owner employee profile
    INSERT INTO public.employees
        (id, business_id, user_id, name, role, email, phone, pin, assigned_branches)
    SELECT
        v_user_id, v_business_id, v_user_id,
        name, 'Owner', email, phone, '0000',
        jsonb_build_array(v_business_id::TEXT)
    FROM public.users
    WHERE id = v_user_id
    ON CONFLICT (id) DO UPDATE SET
        business_id = v_business_id,
        role        = 'Owner';

    RETURN v_business_id;
END;
$$;


ALTER FUNCTION "public"."create_business_with_owner"("p_name" "text", "p_type" "text", "p_country" "text", "p_currency" "text", "p_logo_url" "text", "p_description" "text", "p_address" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_credit_note"("p_business_id" "uuid", "p_doc" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_inv_id  UUID := NULLIF(p_doc->>'invoiceId', '')::UUID;
    v_tx_id   UUID := NULLIF(p_doc->>'transactionId', '')::UUID;
    v_set     TEXT := COALESCE(NULLIF(p_doc->>'settlement', ''), 'refund');
    v_method  TEXT := NULLIF(p_doc->>'method', '');
    v_reason  TEXT := left(NULLIF(trim(p_doc->>'reason'), ''), 300);
    v_stock   BOOLEAN := COALESCE((p_doc->>'returnStock')::BOOLEAN, FALSE);
    v_i       public.sales_invoices%ROWTYPE;
    v_t       public.transactions%ROWTYPE;
    v_cust    UUID;
    v_cname   TEXT;
    v_id      UUID;
    v_no      TEXT;
    v_el      JSONB;
    v_il      public.sales_invoice_lines%ROWTYPE;
    v_ti      public.transaction_items%ROWTYPE;
    v_qty     NUMERIC;
    v_done    NUMERIC;
    v_net     NUMERIC;
    v_vat     NUMERIC;
    v_cost    NUMERIC;
    v_factor  NUMERIC;
    v_rate    NUMERIC;
    v_total   NUMERIC;
    v_room    NUMERIC;
    v_old     NUMERIC;
    v_wallet  NUMERIC;
    v_debt    NUMERIC;
    v_cp      RECORD;
    v_who     TEXT := public.acc_who();
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    IF v_reason IS NULL THEN
        RAISE EXCEPTION 'Say why (e.g. returned, damaged, wrong price).';
    END IF;
    IF jsonb_typeof(p_doc->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(p_doc->'lines') = 0 THEN
        RAISE EXCEPTION 'Tick at least one item to credit.';
    END IF;
    IF v_set NOT IN ('reduce', 'refund', 'wallet', 'debt') THEN
        RAISE EXCEPTION 'Choose how the customer gets it back.';
    END IF;
    IF v_set = 'refund' AND (v_method IS NULL OR v_method NOT IN ('Cash', 'M-Pesa', 'Airtel Money', 'Card', 'Bank')) THEN
        RAISE EXCEPTION 'Choose how the money is given back: Cash, M-Pesa, Airtel Money, Card or Bank.';
    END IF;
    IF v_set <> 'refund' THEN
        v_method := NULL;
    END IF;

    IF v_inv_id IS NOT NULL THEN
        SELECT * INTO v_i FROM public.sales_invoices WHERE id = v_inv_id AND business_id = p_business_id FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'That invoice was not found.';
        END IF;
        PERFORM public.assert_permission(p_business_id, 'invoices.manage');
        IF v_i.status = 'void' THEN
            RAISE EXCEPTION 'This invoice is void.';
        END IF;
        IF v_set NOT IN ('reduce', 'refund') THEN
            RAISE EXCEPTION 'An invoice is credited as less owed or as money back.';
        END IF;
        v_cust := v_i.customer_id;
        v_cname := v_i.customer_name;
    ELSIF v_tx_id IS NOT NULL THEN
        SELECT * INTO v_t FROM public.transactions WHERE id = v_tx_id AND business_id = p_business_id FOR UPDATE;
        IF NOT FOUND OR v_t.deleted_at IS NOT NULL THEN
            RAISE EXCEPTION 'That sale was not found.';
        END IF;
        IF NOT public.has_permission(p_business_id, 'refunds.create') THEN
            IF NOT public.has_permission(p_business_id, 'pos.cancel_sale')
               OR (v_t.timestamp AT TIME ZONE 'Africa/Nairobi')::DATE <> public.sd_today() THEN
                RAISE EXCEPTION 'You can refund only today''s sales. Ask a manager for older ones.';
            END IF;
        END IF;
        IF v_set = 'reduce' THEN
            RAISE EXCEPTION 'A till sale is refunded as money back, into the wallet, or off the customer''s debt.';
        END IF;
        IF v_set IN ('wallet', 'debt') AND v_t.customer_id IS NULL THEN
            RAISE EXCEPTION 'This sale has no customer. Give the money back instead.';
        END IF;
        v_cust := v_t.customer_id;
        v_cname := COALESCE(NULLIF(v_t.customer_name, ''), 'Walk-in');
        -- Shares of the cart discount and the VAT rate, as the till worked them out.
        SELECT CASE WHEN SUM(unit_price * quantity * (1 - discount_percentage / 100)) > 0
                    THEN (v_t.total - v_t.discount) / SUM(unit_price * quantity * (1 - discount_percentage / 100)) ELSE 0 END
        INTO v_factor FROM public.transaction_items WHERE transaction_id = v_tx_id;
        v_factor := LEAST(GREATEST(COALESCE(v_factor, 1), 0), 1);
        v_rate := CASE WHEN (v_t.total - v_t.discount) > 0 THEN COALESCE(v_t.tax, 0) / (v_t.total - v_t.discount) ELSE 0 END;
    ELSE
        RAISE EXCEPTION 'Choose the invoice or sale to credit.';
    END IF;

    v_no := public.sd_next_no(p_business_id, 'CN');
    INSERT INTO public.credit_notes (business_id, number, invoice_id, transaction_id, customer_id, customer_name, issue_date,
                                     reason, settlement, refund_method, return_stock, created_by)
    VALUES (p_business_id, v_no, v_inv_id, v_tx_id, v_cust, v_cname, public.sd_today(), v_reason, v_set, v_method, v_stock, v_who)
    RETURNING id INTO v_id;

    FOR v_el IN SELECT * FROM jsonb_array_elements(p_doc->'lines') LOOP
        v_qty := round(COALESCE(NULLIF(v_el->>'quantity', '')::NUMERIC, 0), 3);
        CONTINUE WHEN v_qty <= 0;
        IF v_inv_id IS NOT NULL THEN
            SELECT * INTO v_il FROM public.sales_invoice_lines
            WHERE id = NULLIF(v_el->>'invoiceLineId', '')::UUID AND invoice_id = v_inv_id FOR UPDATE;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'An item is not on this invoice.';
            END IF;
            IF v_il.qty_credited + v_qty > v_il.quantity THEN
                RAISE EXCEPTION 'Only % of % is left to credit.', v_il.quantity - v_il.qty_credited, v_il.name;
            END IF;
            IF v_il.qty_credited + v_qty = v_il.quantity THEN
                SELECT v_il.line_net - COALESCE(SUM(line_net), 0), v_il.line_vat - COALESCE(SUM(line_vat), 0)
                INTO v_net, v_vat FROM public.credit_note_lines WHERE invoice_line_id = v_il.id;
            ELSE
                v_net := round(v_il.line_net * v_qty / v_il.quantity, 2);
                v_vat := round(v_il.line_vat * v_qty / v_il.quantity, 2);
            END IF;
            -- Cost: what the delivered goods cost, else today's cost.
            SELECT CASE WHEN SUM(dl.quantity) > 0 THEN SUM(dl.quantity * dl.unit_cost) / SUM(dl.quantity) END INTO v_cost
            FROM public.sales_delivery_lines dl JOIN public.sales_deliveries d ON d.id = dl.delivery_id
            WHERE dl.order_line_id = v_il.order_line_id AND d.cancelled_at IS NULL;
            IF v_cost IS NULL THEN
                SELECT cost INTO v_cost FROM public.products WHERE id = v_il.product_id;
            END IF;
            INSERT INTO public.credit_note_lines (credit_note_id, business_id, invoice_line_id, product_id, name, quantity,
                                                  line_net, line_vat, line_total, unit_cost)
            VALUES (v_id, p_business_id, v_il.id, v_il.product_id, v_il.name, v_qty, v_net, v_vat, v_net + v_vat,
                    CASE WHEN v_stock AND v_il.product_id IS NOT NULL THEN round(COALESCE(v_cost, 0), 2) ELSE 0 END);
            UPDATE public.sales_invoice_lines SET qty_credited = qty_credited + v_qty WHERE id = v_il.id;
        ELSE
            SELECT * INTO v_ti FROM public.transaction_items
            WHERE id = NULLIF(v_el->>'transactionItemId', '')::UUID AND transaction_id = v_tx_id;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'An item is not on this sale.';
            END IF;
            SELECT COALESCE(SUM(cl.quantity), 0) INTO v_done
            FROM public.credit_note_lines cl WHERE cl.transaction_item_id = v_ti.id;
            IF v_done + v_qty > v_ti.quantity THEN
                RAISE EXCEPTION 'Only % of % is left to refund.', v_ti.quantity - v_done, v_ti.product_name;
            END IF;
            v_net := round(v_ti.unit_price * (1 - v_ti.discount_percentage / 100) * v_factor * v_qty, 2);
            v_vat := round(v_net * v_rate, 2);
            SELECT cost INTO v_cost FROM public.products WHERE id = v_ti.product_id;
            v_cost := COALESCE(v_ti.unit_cost, v_cost, 0);
            INSERT INTO public.credit_note_lines (credit_note_id, business_id, transaction_item_id, product_id, name, quantity,
                                                  line_net, line_vat, line_total, unit_cost)
            VALUES (v_id, p_business_id, v_ti.id, v_ti.product_id, v_ti.product_name, v_qty, v_net, v_vat, v_net + v_vat,
                    CASE WHEN v_stock THEN round(v_cost, 2) ELSE 0 END);
        END IF;
    END LOOP;

    UPDATE public.credit_notes c
    SET subtotal = s.net, vat_total = s.vat, total = s.net + s.vat, cost_total = s.cost
    FROM (SELECT COALESCE(SUM(line_net), 0) AS net, COALESCE(SUM(line_vat), 0) AS vat,
                 COALESCE(round(SUM(quantity * unit_cost), 2), 0) AS cost
          FROM public.credit_note_lines WHERE credit_note_id = v_id) s
    WHERE c.id = v_id
    RETURNING c.total INTO v_total;
    IF COALESCE(v_total, 0) <= 0 THEN
        RAISE EXCEPTION 'Tick at least one item with a quantity to credit.';
    END IF;

    -- How much may come back this way.
    IF v_inv_id IS NOT NULL THEN
        IF v_set = 'reduce' AND v_total > v_i.balance THEN
            RAISE EXCEPTION 'Only % is still owed. Credit the rest as money back.', to_char(GREATEST(v_i.balance, 0), 'FM999,999,990.00');
        ELSIF v_set = 'refund' AND v_total > v_i.amount_paid - v_i.amount_refunded THEN
            RAISE EXCEPTION 'Only % was paid on this invoice and not yet given back. Credit the rest as less owed.',
                to_char(GREATEST(v_i.amount_paid - v_i.amount_refunded, 0), 'FM999,999,990.00');
        END IF;
    ELSE
        SELECT v_t.final_total - CASE WHEN v_t.is_delivery THEN COALESCE(v_t.delivery_fee, 0) ELSE 0 END - COALESCE(SUM(total), 0)
        INTO v_room FROM public.credit_notes WHERE transaction_id = v_tx_id AND id <> v_id;
        IF v_total > v_room + 0.05 THEN
            RAISE EXCEPTION 'Only % of this sale is left to refund.', to_char(GREATEST(v_room, 0), 'FM999,999,990.00');
        END IF;
    END IF;

    -- Settle it.
    IF v_set = 'refund' THEN
        PERFORM public.fn_post_money_asset(p_business_id, v_method, -v_total, 'Refund ' || v_no || ' · ' || v_cname, NULL, NULL, v_who);
    ELSIF v_set = 'wallet' THEN
        SELECT COALESCE(wallet_balance, 0), COALESCE(debt_balance, 0) INTO v_wallet, v_debt
        FROM public.customers WHERE id = v_cust FOR UPDATE;
        UPDATE public.customers SET wallet_balance = v_wallet + v_total, updated_at = NOW() WHERE id = v_cust;
        INSERT INTO public.customer_ledger (business_id, customer_id, type, amount, wallet_balance, debt_balance,
                                            recorded_by, note, reference_id)
        VALUES (p_business_id, v_cust, 'refund', v_total, v_wallet + v_total, v_debt, v_who,
                'Credit note ' || v_no || ' into wallet', 'cn-' || v_id || '-wallet');
    ELSIF v_set = 'debt' THEN
        SELECT * INTO v_cp FROM public.credit_payments
        WHERE transaction_id = v_tx_id AND business_id = p_business_id AND status IN ('Open', 'Partial')
        ORDER BY created_at LIMIT 1 FOR UPDATE;
        IF NOT FOUND OR v_cp.balance < v_total THEN
            RAISE EXCEPTION 'Only % is still owed on this sale. Give the rest back as money or into the wallet.',
                to_char(COALESCE(v_cp.balance, 0), 'FM999,999,990.00');
        END IF;
        UPDATE public.credit_payments
        SET amount_owed = amount_owed - v_total,
            status = CASE WHEN amount_owed - v_total <= amount_paid THEN 'Settled'::public.credit_status ELSE status END,
            settled_at = CASE WHEN amount_owed - v_total <= amount_paid THEN NOW() ELSE settled_at END,
            updated_at = NOW()
        WHERE id = v_cp.id;
        SELECT COALESCE(wallet_balance, 0), COALESCE(debt_balance, 0) INTO v_wallet, v_debt
        FROM public.customers WHERE id = v_cust FOR UPDATE;
        UPDATE public.customers SET debt_balance = GREATEST(v_debt - v_total, 0), updated_at = NOW() WHERE id = v_cust;
        INSERT INTO public.customer_ledger (business_id, customer_id, type, amount, wallet_balance, debt_balance,
                                            recorded_by, note, reference_id, transaction_id)
        VALUES (p_business_id, v_cust, 'refund', v_total, v_wallet, GREATEST(v_debt - v_total, 0), v_who,
                'Credit note ' || v_no || ' taken off debt', 'cn-' || v_id || '-debt', v_tx_id);
    END IF;

    -- Stock back.
    IF v_stock THEN
        FOR v_el IN
            SELECT to_jsonb(cl) FROM public.credit_note_lines cl WHERE cl.credit_note_id = v_id AND cl.product_id IS NOT NULL
        LOOP
            SELECT stock INTO v_old FROM public.products WHERE id = (v_el->>'product_id')::UUID FOR UPDATE;
            IF FOUND THEN
                UPDATE public.products SET stock = v_old + (v_el->>'quantity')::NUMERIC, updated_at = NOW()
                WHERE id = (v_el->>'product_id')::UUID;
                INSERT INTO public.inventory_adjustments (business_id, product_id, product_name, type, quantity_adjusted,
                    previous_stock, new_stock, reason, reference_number, staff_name, notes)
                VALUES (p_business_id, (v_el->>'product_id')::UUID, v_el->>'name', 'Restock', (v_el->>'quantity')::NUMERIC,
                    v_old, v_old + (v_el->>'quantity')::NUMERIC, 'Returned', v_no, v_who, v_reason);
            END IF;
        END LOOP;
    END IF;

    IF v_inv_id IS NOT NULL THEN
        PERFORM public.sd_invoice_refresh(v_inv_id);
    END IF;
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."create_credit_note"("p_business_id" "uuid", "p_doc" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_customer_account"("p_slug" "text", "p_name" "text", "p_phone" "text") RETURNS "uuid"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT public.fn_create_customer_account(auth.uid(), p_slug, p_name, p_phone);
$$;


ALTER FUNCTION "public"."create_customer_account"("p_slug" "text", "p_name" "text", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_suggested_purchases"("p_business_id" "uuid", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_group RECORD;
    v_line  RECORD;
    v_id    UUID;
    v_name  TEXT;
    v_out   JSONB := '[]'::JSONB;
    v_total NUMERIC;
    v_me    TEXT := public.fn_my_display_name(p_business_id);
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'purchases.create');
    IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN
        RAISE EXCEPTION 'Choose what to order.';
    END IF;

    FOR v_group IN
        SELECT COALESCE(NULLIF(e->>'supplierId', '')::UUID, p.preferred_supplier_id) AS supplier_id
        FROM jsonb_array_elements(p_lines) e
        JOIN public.products p ON p.id = (e->>'productId')::UUID AND p.business_id = p_business_id AND p.deleted_at IS NULL
        GROUP BY 1
    LOOP
        v_name := NULL;
        IF v_group.supplier_id IS NOT NULL THEN
            SELECT COALESCE(NULLIF(company, ''), name) INTO v_name FROM public.suppliers
            WHERE id = v_group.supplier_id AND business_id = p_business_id;
        END IF;
        INSERT INTO public.purchases (business_id, supplier_id, supplier_name, status, notes, created_by, total_amount)
        VALUES (p_business_id, CASE WHEN v_name IS NOT NULL THEN v_group.supplier_id END,
                COALESCE(v_name, 'Supplier to choose'), 'Pending', 'Made from Suggested orders', v_me, 0)
        RETURNING id INTO v_id;
        v_total := 0;
        FOR v_line IN
            SELECT p.id, p.name, p.unit, COALESCE(p.supplier_price, p.cost, 0) AS price, SUM((e->>'quantity')::NUMERIC) AS qty
            FROM jsonb_array_elements(p_lines) e
            JOIN public.products p ON p.id = (e->>'productId')::UUID AND p.business_id = p_business_id AND p.deleted_at IS NULL
            WHERE COALESCE(NULLIF(e->>'supplierId', '')::UUID, p.preferred_supplier_id) IS NOT DISTINCT FROM v_group.supplier_id
            GROUP BY p.id, p.name, p.unit, p.supplier_price, p.cost
        LOOP
            CONTINUE WHEN COALESCE(v_line.qty, 0) <= 0;
            INSERT INTO public.purchase_items (purchase_id, product_id, name, quantity, unit, price)
            VALUES (v_id, v_line.id, v_line.name, round(v_line.qty, 3), COALESCE(NULLIF(v_line.unit, ''), 'pcs'), round(v_line.price, 2));
            v_total := v_total + round(round(v_line.qty, 3) * round(v_line.price, 2), 2);
        END LOOP;
        IF v_total = 0 AND NOT EXISTS (SELECT 1 FROM public.purchase_items WHERE purchase_id = v_id) THEN
            DELETE FROM public.purchases WHERE id = v_id;
            CONTINUE;
        END IF;
        UPDATE public.purchases SET total_amount = v_total WHERE id = v_id;
        v_out := v_out || jsonb_build_array(jsonb_build_object('id', v_id, 'supplierName', COALESCE(v_name, 'Supplier to choose'), 'total', v_total));
    END LOOP;
    IF jsonb_array_length(v_out) = 0 THEN
        RAISE EXCEPTION 'Enter a quantity for at least one product.';
    END IF;
    RETURN v_out;
END;
$$;


ALTER FUNCTION "public"."create_suggested_purchases"("p_business_id" "uuid", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_supplier_bill"("p_business_id" "uuid", "p_doc" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_p        public.purchases%ROWTYPE;
    v_ids      UUID[];
    v_value    NUMERIC;
    v_sub      NUMERIC := round(COALESCE(NULLIF(p_doc->>'subtotal', '')::NUMERIC, -1), 2);
    v_vat      NUMERIC := round(COALESCE(NULLIF(p_doc->>'vatTotal', '')::NUMERIC, 0), 2);
    v_date     DATE := COALESCE(NULLIF(p_doc->>'billDate', '')::DATE, public.sd_today());
    v_due      DATE;
    v_tol      NUMERIC;
    v_diff     NUMERIC;
    v_status   TEXT;
    v_id       UUID;
    v_no       TEXT;
    v_me       TEXT := public.fn_my_display_name(p_business_id);
    v_lock     DATE;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'supplier_bills.manage');
    SELECT * INTO v_p FROM public.purchases WHERE id = NULLIF(p_doc->>'purchaseId', '')::UUID AND business_id = p_business_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Choose the purchase this bill is for.'; END IF;
    IF v_sub < 0 THEN RAISE EXCEPTION 'Enter the bill amount before VAT.'; END IF;
    IF v_vat < 0 THEN RAISE EXCEPTION 'VAT can''t be below zero.'; END IF;
    v_due := COALESCE(NULLIF(p_doc->>'dueDate', '')::DATE, v_date + 30);
    IF v_due < v_date THEN RAISE EXCEPTION 'The due date can''t be before the bill date.'; END IF;
    SELECT lock_date INTO v_lock FROM public.acc_settings WHERE business_id = p_business_id;
    IF v_lock IS NOT NULL AND v_date <= v_lock THEN
        RAISE EXCEPTION 'The books are locked up to %. Use a later bill date.', to_char(v_lock, 'DD Mon YYYY');
    END IF;

    IF jsonb_typeof(p_doc->'receiptIds') = 'array' AND jsonb_array_length(p_doc->'receiptIds') > 0 THEN
        SELECT array_agg(value::UUID) INTO v_ids FROM jsonb_array_elements_text(p_doc->'receiptIds');
    ELSE
        SELECT array_agg(id) INTO v_ids FROM public.purchase_receipts WHERE purchase_id = v_p.id AND bill_id IS NULL;
    END IF;
    IF COALESCE(array_length(v_ids, 1), 0) = 0 THEN
        RAISE EXCEPTION 'Nothing on this purchase is waiting for a bill. Receive the goods first.';
    END IF;
    IF EXISTS (SELECT 1 FROM unnest(v_ids) i LEFT JOIN public.purchase_receipts r ON r.id = i
               WHERE r.id IS NULL OR r.purchase_id <> v_p.id OR r.bill_id IS NOT NULL) THEN
        RAISE EXCEPTION 'One of those deliveries is already billed or not on this purchase. Refresh and try again.';
    END IF;
    PERFORM 1 FROM public.purchase_receipts WHERE id = ANY(v_ids) FOR UPDATE;
    SELECT COALESCE(SUM(total_value), 0) INTO v_value FROM public.purchase_receipts WHERE id = ANY(v_ids);

    SELECT COALESCE(bill_tolerance_pct, 2) INTO v_tol FROM public.buying_settings WHERE business_id = p_business_id;
    v_tol := COALESCE(v_tol, 2);
    v_diff := v_sub - v_value;
    v_status := CASE WHEN abs(v_diff) > GREATEST(round(v_value * v_tol / 100, 2), 1) THEN 'needs_check' ELSE 'open' END;

    v_no := public.sd_next_no(p_business_id, 'BILL', v_date);
    INSERT INTO public.supplier_bills (
        business_id, number, supplier_id, supplier_name, purchase_id, supplier_invoice_no, bill_date, due_date,
        subtotal, vat_total, total, receipts_value, difference, status, balance, note, created_by
    ) VALUES (
        p_business_id, v_no, v_p.supplier_id, v_p.supplier_name, v_p.id, NULLIF(trim(COALESCE(p_doc->>'supplierInvoiceNo', '')), ''),
        v_date, v_due, v_sub, v_vat, v_sub + v_vat, v_value, v_diff, v_status, v_sub + v_vat,
        NULLIF(trim(COALESCE(p_doc->>'note', '')), ''), v_me
    ) RETURNING id INTO v_id;
    UPDATE public.purchase_receipts SET bill_id = v_id WHERE id = ANY(v_ids);

    IF v_status = 'needs_check' THEN
        PERFORM public.fn_buying_notify(p_business_id, NULL, 'Purchase Approval', 'Supplier bill needs a check',
            v_no || ' from ' || v_p.supplier_name || ' is KSh ' || trim(to_char(v_sub, 'FM999,999,999,990.00'))
                || ' before VAT, but the goods received are worth KSh ' || trim(to_char(v_value, 'FM999,999,999,990.00')) || '.',
            'buying', jsonb_build_object('billId', v_id));
    END IF;
    RETURN jsonb_build_object('id', v_id, 'number', v_no, 'status', v_status, 'difference', v_diff, 'receiptsValue', v_value);
END;
$$;


ALTER FUNCTION "public"."create_supplier_bill"("p_business_id" "uuid", "p_doc" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_supplier_return"("p_business_id" "uuid", "p_doc" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_sid    UUID := NULLIF(p_doc->>'supplierId', '')::UUID;
    v_sname  TEXT := NULLIF(trim(COALESCE(p_doc->>'supplierName', '')), '');
    v_pid    UUID := NULLIF(p_doc->>'purchaseId', '')::UUID;
    v_reason TEXT := NULLIF(trim(COALESCE(p_doc->>'reason', '')), '');
    v_p      public.purchases%ROWTYPE;
    v_el     JSONB;
    v_prod   public.products%ROWTYPE;
    v_qty    NUMERIC;
    v_cost   NUMERIC;
    v_total  NUMERIC := 0;
    v_id     UUID;
    v_no     TEXT;
    v_me     TEXT := public.fn_my_display_name(p_business_id);
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'purchases.update', 'purchases.manage', 'purchases.approve');
    PERFORM public.assert_permission(p_business_id, 'inventory.adjust_stock', 'inventory.receive_stock');
    IF v_reason IS NULL THEN RAISE EXCEPTION 'Say why the goods are going back.'; END IF;
    IF v_pid IS NOT NULL THEN
        SELECT * INTO v_p FROM public.purchases WHERE id = v_pid AND business_id = p_business_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'That purchase was not found.'; END IF;
        v_sid := COALESCE(v_sid, v_p.supplier_id);
        v_sname := COALESCE(v_sname, v_p.supplier_name);
    END IF;
    IF v_sid IS NOT NULL THEN
        SELECT COALESCE(NULLIF(company, ''), name) INTO v_sname FROM public.suppliers WHERE id = v_sid AND business_id = p_business_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'That supplier was not found.'; END IF;
    END IF;
    IF v_sname IS NULL THEN RAISE EXCEPTION 'Choose the supplier.'; END IF;
    IF jsonb_typeof(p_doc->'lines') <> 'array' OR jsonb_array_length(p_doc->'lines') = 0 THEN
        RAISE EXCEPTION 'Add what is going back.';
    END IF;

    v_no := public.sd_next_no(p_business_id, 'RTS');
    INSERT INTO public.supplier_returns (business_id, number, supplier_id, supplier_name, purchase_id, reason, created_by)
    VALUES (p_business_id, v_no, v_sid, v_sname, v_pid, v_reason, v_me)
    RETURNING id INTO v_id;

    FOR v_el IN SELECT * FROM jsonb_array_elements(p_doc->'lines') ORDER BY (value->>'productId') LOOP
        SELECT * INTO v_prod FROM public.products
        WHERE id = NULLIF(v_el->>'productId', '')::UUID AND business_id = p_business_id AND deleted_at IS NULL
        FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'One of the products is not in this branch any more.'; END IF;
        v_qty := round(COALESCE(NULLIF(v_el->>'quantity', '')::NUMERIC, 0), 3);
        IF v_qty <= 0 THEN RAISE EXCEPTION 'Enter how much % is going back.', v_prod.name; END IF;
        IF v_qty > v_prod.stock THEN
            RAISE EXCEPTION 'Only % % of % in stock.', public.fn_qty(v_prod.stock), v_prod.unit, v_prod.name;
        END IF;
        v_cost := NULLIF(v_el->>'unitCost', '')::NUMERIC;
        IF v_cost IS NULL AND v_pid IS NOT NULL THEN
            SELECT price INTO v_cost FROM public.purchase_items WHERE purchase_id = v_pid AND product_id = v_prod.id LIMIT 1;
        END IF;
        v_cost := round(COALESCE(v_cost, v_prod.cost, 0), 2);
        IF v_cost < 0 THEN RAISE EXCEPTION 'A cost can''t be below zero.'; END IF;

        INSERT INTO public.supplier_return_lines (business_id, return_id, product_id, name, unit, quantity, unit_cost)
        VALUES (p_business_id, v_id, v_prod.id, v_prod.name, v_prod.unit, v_qty, v_cost);
        UPDATE public.products SET stock = stock - v_qty, updated_at = NOW() WHERE id = v_prod.id;
        INSERT INTO public.inventory_adjustments
            (business_id, product_id, product_name, type, quantity_adjusted, previous_stock, new_stock,
             reason, staff_name, reference_number, notes)
        VALUES (p_business_id, v_prod.id, v_prod.name, 'Supplier Return', -v_qty, v_prod.stock, v_prod.stock - v_qty,
                'Sent back to ' || v_sname, v_me, v_no, v_reason);
        v_total := v_total + round(v_qty * v_cost, 2);
    END LOOP;

    UPDATE public.supplier_returns SET total = v_total WHERE id = v_id;
    RETURN jsonb_build_object('id', v_id, 'number', v_no, 'total', v_total);
END;
$$;


ALTER FUNCTION "public"."create_supplier_return"("p_business_id" "uuid", "p_doc" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."customer_open_invoices"("p_customer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_b UUID;
BEGIN
    SELECT business_id INTO v_b FROM public.customers WHERE id = p_customer_id;
    IF v_b IS NULL THEN RETURN '[]'::JSONB; END IF;
    PERFORM public.assert_business_member(v_b);
    PERFORM public.assert_permission(v_b, 'invoices.view', 'invoices.manage', 'customers.view');
    RETURN COALESCE((
        SELECT jsonb_agg(jsonb_build_object('id', i.id, 'number', i.number, 'issueDate', i.issue_date, 'dueDate', i.due_date,
                                            'total', i.total, 'balance', i.balance, 'status', i.status) ORDER BY i.issue_date DESC)
        FROM public.sales_invoices i
        WHERE i.customer_id = p_customer_id AND i.status NOT IN ('void') AND i.balance > 0
    ), '[]'::JSONB);
END;
$$;


