CREATE OR REPLACE FUNCTION "public"."find_duplicate_customers"("p_business_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    PERFORM public.assert_permission(p_business_id, 'customers.manage');

    WITH base AS (
        SELECT id, public.fn_phone_key(phone) AS phone_key, public.fn_email_key(email) AS email_key
        FROM public.customers
        WHERE business_id = p_business_id AND deleted_at IS NULL
    ),
    matches AS (
        SELECT 'phone' AS match_on, phone_key AS match_value, array_agg(id ORDER BY id) AS ids
        FROM base WHERE phone_key IS NOT NULL GROUP BY phone_key HAVING count(*) > 1
        UNION ALL
        SELECT 'email', email_key, array_agg(id ORDER BY id)
        FROM base WHERE email_key IS NOT NULL GROUP BY email_key HAVING count(*) > 1
    ),
    -- The same people matching on both phone and email show once.
    groups AS (
        SELECT DISTINCT ON (ids) match_on, match_value, ids
        FROM matches
        ORDER BY ids, match_on DESC
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'matchOn', g.match_on,
        'matchValue', g.match_value,
        'customerIds', to_jsonb(g.ids),
        'accountCustomerIds', COALESCE((
            SELECT jsonb_agg(DISTINCT a.customer_id)
            FROM public.customer_accounts a
            WHERE a.customer_id = ANY(g.ids)
        ), '[]'::jsonb)
    )), '[]'::jsonb) INTO v_result
    FROM groups g
    WHERE NOT EXISTS (
        SELECT 1 FROM public.customer_duplicate_dismissals d
        WHERE d.business_id = p_business_id AND d.customer_ids @> g.ids
    );

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."find_duplicate_customers"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_invitation"("p_invite_id" "uuid", "p_auth_user_id" "uuid", "p_name" "text", "p_phone" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_invite  RECORD;
    v_user_id UUID;
    v_shop    TEXT;
    v_name    TEXT;
BEGIN
    SELECT * INTO v_invite FROM public.invitations WHERE id = p_invite_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN;
    END IF;

    IF NOT public.account_email_verified(p_auth_user_id)
       OR NOT EXISTS (
           SELECT 1 FROM auth.users
           WHERE id = p_auth_user_id
             AND LOWER(TRIM(email)) = LOWER(TRIM(v_invite.email))
       ) THEN
        RAISE EXCEPTION 'Please verify your email before joining.';
    END IF;

    -- The name they typed, else the one the admin entered. Never the shop name.
    SELECT name INTO v_shop FROM public.businesses WHERE id = v_invite.business_id;
    v_name := NULLIF(TRIM(COALESCE(p_name, '')), '');
    IF v_name IS NULL OR v_name = TRIM(v_shop) THEN
        v_name := COALESCE(NULLIF(TRIM(v_invite.name), ''), v_name, 'Team member');
    END IF;

    SELECT id INTO v_user_id FROM public.users WHERE auth_user_id = p_auth_user_id;

    IF v_user_id IS NULL THEN
        INSERT INTO public.users (id, auth_user_id, name, email, phone, is_verified)
        VALUES (p_auth_user_id, p_auth_user_id, v_name, v_invite.email, p_phone, FALSE)
        RETURNING id INTO v_user_id;
    ELSE
        UPDATE public.users
        SET name = v_name, phone = COALESCE(NULLIF(p_phone, ''), phone), email = v_invite.email
        WHERE id = v_user_id;
    END IF;

    -- Someone at a supplier gets a supplier account, never a staff membership (20261119003).
    IF v_invite.supplier_id IS NOT NULL THEN
        INSERT INTO public.supplier_accounts (business_id, supplier_id, user_id, status, invited_by)
        VALUES (v_invite.business_id, v_invite.supplier_id, v_user_id, 'active',
                (SELECT u.name FROM public.users u WHERE u.id = v_invite.invited_by))
        ON CONFLICT (supplier_id, user_id) DO UPDATE SET status = 'active', removed_at = NULL, removed_by = NULL;
        DELETE FROM public.invitations WHERE id = v_invite.id;
        RETURN;
    END IF;

    -- The membership trigger creates or refreshes the employee row.
    INSERT INTO public.business_memberships (business_id, user_id, role, status)
    VALUES (v_invite.business_id, v_user_id, v_invite.role, 'Active')
    ON CONFLICT (business_id, user_id) DO UPDATE SET
        role   = v_invite.role,
        status = 'Active';
    PERFORM public.fn_sync_employee(v_invite.business_id, v_user_id);

    -- The code can't be used again.
    DELETE FROM public.invitations WHERE id = v_invite.id;
END;
$$;


ALTER FUNCTION "public"."finish_invitation"("p_invite_id" "uuid", "p_auth_user_id" "uuid", "p_name" "text", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flag_due_schedule_reminders"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_now   TIMESTAMP := (NOW() AT TIME ZONE 'Africa/Nairobi');
    v_today DATE := (NOW() AT TIME ZONE 'Africa/Nairobi')::DATE;
    v_grace INTERVAL := INTERVAL '10 minutes';
    v_schedule RECORD;
    v_user_id UUID;
    v_time TEXT;
BEGIN
    FOR v_schedule IN
        SELECT s.id, s.business_id, s.employee_id, s.title, s.start_time, s.notes, s.created_by
        FROM public.schedules s
        WHERE s.deleted_at IS NULL
          AND s.date <= v_today
          AND s.last_reminded_on IS DISTINCT FROM v_today
          AND CASE s.repeat
                  WHEN 'None'    THEN s.date = v_today
                  WHEN 'Daily'   THEN TRUE
                  WHEN 'Weekly'  THEN EXTRACT(DOW FROM s.date) = EXTRACT(DOW FROM v_today)
                  WHEN 'Monthly' THEN EXTRACT(DAY FROM s.date) = EXTRACT(DAY FROM v_today)
                  ELSE FALSE
              END
          AND v_today + date_trunc('minute', s.start_time) <= v_now
          AND v_today + date_trunc('minute', s.start_time) > v_now - v_grace
        FOR UPDATE SKIP LOCKED
    LOOP
        UPDATE public.schedules
        SET last_reminded_on = v_today, reminder_sent = TRUE
        WHERE id = v_schedule.id;

        SELECT e.user_id INTO v_user_id
        FROM public.employees e
        WHERE e.id = v_schedule.employee_id AND e.deleted_at IS NULL;

        -- Same format the app shows: 1:38 PM
        v_time := ltrim(to_char(v_schedule.start_time, 'HH12:MI AM'), '0');

        IF v_user_id IS NOT NULL THEN
            INSERT INTO public.notifications
                (business_id, user_id, title, message, type, priority,
                 action_type, action_target, payload, status)
            VALUES (
                v_schedule.business_id,
                v_user_id,
                COALESCE(NULLIF(v_schedule.title, ''), 'Reminder'),
                'Reminder for ' || v_time
                    || CASE WHEN NULLIF(trim(v_schedule.notes), '') IS NOT NULL
                            THEN '. ' || trim(v_schedule.notes) ELSE '' END,
                'Schedule Reminder',
                'high'::public.notification_priority,
                'navigate'::public.notification_action_type,
                'dashboard',
                jsonb_build_object(
                    'schedule_id', v_schedule.id,
                    'employee_id', v_schedule.employee_id,
                    'shift_date',  to_char(v_today, 'YYYY-MM-DD'),
                    'start_time',  to_char(v_schedule.start_time, 'HH24:MI')
                ),
                'pending'::public.notification_delivery_status
            );
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."flag_due_schedule_reminders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flag_order_payment_unconfirmed"("p_order_id" "uuid", "p_checkout_request_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_order public.online_orders%ROWTYPE;
    v_reason TEXT := 'M-Pesa reports this order as paid (' || p_checkout_request_id
        || ') but its confirmation never arrived. Check the M-Pesa statement.';
BEGIN
    UPDATE public.online_orders
    SET needs_attention = TRUE, attention_reason = v_reason
    WHERE id = p_order_id
      AND NOT needs_attention
      AND status IN ('pending_payment', 'payment_failed')
    RETURNING * INTO v_order;

    IF FOUND THEN
        PERFORM public.fn_notify_staff(v_order.business_id, 'Online payment needs checking',
            'Order #' || v_order.order_number || ': ' || v_reason, jsonb_build_object('orderId', v_order.id));
    END IF;
END;
$$;


