CREATE OR REPLACE FUNCTION "public"."fn_can_see_notification"("p_business_id" "uuid", "p_user_id" "uuid", "p_role" "text", "p_type" "text", "p_created_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_me     UUID;
    v_role   TEXT;
    v_joined TIMESTAMPTZ;
    v_perms  TEXT[];
    v_gated  BOOLEAN;
BEGIN
    SELECT u.id, m.role::TEXT, m.joined_at INTO v_me, v_role, v_joined
    FROM public.users u
    JOIN public.business_memberships m ON m.user_id = u.id
    WHERE u.auth_user_id = auth.uid() AND m.business_id = p_business_id AND m.status = 'Active';

    IF v_me IS NULL THEN
        RETURN FALSE;
    END IF;
    IF p_user_id IS NOT NULL THEN
        RETURN p_user_id = v_me;
    END IF;
    IF p_created_at < v_joined THEN
        RETURN FALSE;
    END IF;

    SELECT c.permissions, TRUE INTO v_perms, v_gated
    FROM public.fn_notification_catalog() c
    WHERE p_type = ANY(c.types) AND c.permissions IS NOT NULL
    LIMIT 1;

    IF v_gated THEN
        RETURN public.fn_user_has_permission(p_business_id, v_me, v_perms);
    END IF;
    RETURN p_role IS NULL OR v_role ILIKE p_role;
END;
$$;


ALTER FUNCTION "public"."fn_can_see_notification"("p_business_id" "uuid", "p_user_id" "uuid", "p_role" "text", "p_type" "text", "p_created_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_can_write_storage_folder"("p_folder" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_folder UUID;
    v_businesses UUID[];
BEGIN
    IF auth.uid() IS NULL
       OR p_folder !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
        RETURN FALSE;
    END IF;
    v_folder := p_folder::UUID;
    v_businesses := public.get_user_business_ids();

    IF v_folder = ANY(v_businesses) THEN
        RETURN TRUE;
    END IF;

    IF v_folder = auth.uid() THEN
        RETURN cardinality(v_businesses) > 0
            OR NOT EXISTS (SELECT 1 FROM public.customer_accounts WHERE id = auth.uid());
    END IF;

    RETURN FALSE;
END;
$_$;


ALTER FUNCTION "public"."fn_can_write_storage_folder"("p_folder" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cancel_points_when_off"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF public.fn_points_on(NEW.business_id) THEN
        RETURN NEW;
    END IF;
    UPDATE public.customers
    SET loyalty_points = GREATEST(0, loyalty_points - NEW.points)
    WHERE id = NEW.customer_id;
    RETURN NULL;
END;
$$;


