CREATE OR REPLACE FUNCTION "public"."fn_cancel_production_batch"("p_batch_id" "uuid", "p_staff_name" "text", "p_return_items" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_batch RECORD;
    v_item JSONB;
    v_product_id UUID;
    v_return_qty NUMERIC(14,6);
    v_waste_reason TEXT;
    v_product RECORD;
    v_consumed_qty NUMERIC(14,6);
    v_wasted_qty NUMERIC(14,6);
    v_current_stock NUMERIC(14,3);
    v_new_stock NUMERIC(14,3);
    v_result JSONB;
BEGIN
    PERFORM public.assert_permission((SELECT business_id FROM public.production_batches WHERE id = p_batch_id), 'production.update');
    PERFORM public.assert_business_member((SELECT business_id FROM public.production_batches WHERE id = p_batch_id));
    -- Fetch batch and lock row
    SELECT * INTO v_batch
    FROM public.production_batches
    WHERE id = p_batch_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Production batch % not found.', p_batch_id;
    END IF;

    IF v_batch.status = 'Cancelled' THEN
        RAISE EXCEPTION 'Batch % is already cancelled.', COALESCE(v_batch.reference_number, v_batch.id::text);
    END IF;

    IF v_batch.status = 'Completed' THEN
        RAISE EXCEPTION 'Cannot cancel an already completed batch (%).', COALESCE(v_batch.reference_number, v_batch.id::text);
    END IF;

    -- Update batch status to Cancelled
    UPDATE public.production_batches
    SET status = 'Cancelled',
        updated_at = NOW()
    WHERE id = p_batch_id;

    -- Process Restocking / Waste items
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_return_items)
    LOOP
        v_product_id := (v_item->>'productId')::UUID;
        v_return_qty := COALESCE((v_item->>'returnQty')::NUMERIC, 0);
        v_waste_reason := COALESCE(v_item->>'wasteReason', 'Production batch cancellation damage');

        IF v_product_id IS NOT NULL THEN
            SELECT id, name, stock INTO v_product
            FROM public.products
            WHERE id = v_product_id
            FOR UPDATE;

            IF FOUND THEN
                -- Calculate original consumed quantity for this ingredient from logs
                SELECT COALESCE(ABS(SUM(quantity_adjusted)), 0) INTO v_consumed_qty
                FROM public.inventory_adjustments
                WHERE batch_id = p_batch_id
                  AND product_id = v_product_id
                  AND type = 'Production Consumption';

                -- Prevent returning more than originally consumed
                IF v_return_qty > v_consumed_qty THEN
                    v_return_qty := v_consumed_qty;
                END IF;

                v_wasted_qty := GREATEST(0, v_consumed_qty - v_return_qty);

                -- 1. RESTOCK QUANTITY
                IF v_return_qty > 0 THEN
                    v_current_stock := v_product.stock;
                    v_new_stock := v_current_stock + v_return_qty;

                    UPDATE public.products
                    SET stock = v_new_stock,
                        updated_at = NOW()
                    WHERE id = v_product_id;

                    INSERT INTO public.inventory_adjustments (
                        business_id,
                        product_id,
                        product_name,
                        type,
                        quantity_adjusted,
                        previous_stock,
                        new_stock,
                        timestamp,
                        reason,
                        staff_name,
                        batch_id,
                        reference_number,
                        notes
                    ) VALUES (
                        v_batch.business_id,
                        v_product_id,
                        v_product.name,
                        'Production Reversal'::public.inventory_adjustment_type,
                        v_return_qty,
                        v_current_stock,
                        v_new_stock,
                        NOW(),
                        'Production reversal for cancelled batch ' || COALESCE(v_batch.reference_number, v_batch.id::text),
                        p_staff_name,
                        p_batch_id,
                        v_batch.reference_number,
                        'Restocked ' || v_return_qty || ' units of raw material to inventory.'
                    );
                END IF;

                -- 2. LOG WASTE QUANTITY (Stock not restored)
                IF v_wasted_qty > 0 THEN
                    SELECT stock INTO v_current_stock FROM public.products WHERE id = v_product_id;

                    INSERT INTO public.inventory_adjustments (
                        business_id,
                        product_id,
                        product_name,
                        type,
                        quantity_adjusted,
                        previous_stock,
                        new_stock,
                        timestamp,
                        reason,
                        staff_name,
                        batch_id,
                        reference_number,
                        notes
                    ) VALUES (
                        v_batch.business_id,
                        v_product_id,
                        v_product.name,
                        'Production Waste'::public.inventory_adjustment_type,
                        -v_wasted_qty,
                        v_current_stock,
                        v_current_stock,
                        NOW(),
                        v_waste_reason,
                        p_staff_name,
                        p_batch_id,
                        v_batch.reference_number,
                        'Recorded ' || v_wasted_qty || ' units as wasted/damaged during batch cancellation.'
                    );
                END IF;
            END IF;
        END IF;
    END LOOP;

    -- Return updated batch JSON
    SELECT row_to_json(b)::jsonb INTO v_result
    FROM public.production_batches b
    WHERE b.id = p_batch_id;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_cancel_production_batch"("p_batch_id" "uuid", "p_staff_name" "text", "p_return_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_capitalize_customer_name"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF TG_TABLE_NAME = 'customers' THEN
        NEW.name := public.fn_capitalize_words(NEW.name);
    ELSE
        NEW.customer_name := public.fn_capitalize_words(NEW.customer_name);
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_capitalize_customer_name"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_capitalize_words"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
    SELECT CASE WHEN p_text IS NULL THEN NULL ELSE
        (SELECT string_agg(upper(left(w, 1)) || substr(w, 2), ' ' ORDER BY n)
         FROM regexp_split_to_table(btrim(regexp_replace(p_text, '\s+', ' ', 'g')), ' ') WITH ORDINALITY AS t(w, n)
         WHERE w <> '')
    END;
$$;


ALTER FUNCTION "public"."fn_capitalize_words"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_check_invitation_email"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NEW.email IS NOT NULL AND NEW.email <> '' THEN
        IF EXISTS (
            SELECT 1 FROM public.users WHERE email = NEW.email LIMIT 1
        ) THEN
            RAISE EXCEPTION 'A registered user with this email address already exists in the system.';
        END IF;

        IF EXISTS (
            SELECT 1 FROM public.invitations
            WHERE email = NEW.email
              AND status = 'Pending'
              AND expires_at > NOW()
              AND id <> NEW.id
            LIMIT 1
        ) THEN
            RAISE EXCEPTION 'An active invitation for this email address already exists.';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_check_invitation_email"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_check_low_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Only notify when the threshold is newly crossed
    IF NEW.stock <= NEW.min_stock
       AND (OLD.stock IS NULL OR OLD.stock > NEW.min_stock)
    THEN
        INSERT INTO public.notifications
            (business_id, role, title, message, type, priority,
             action_type, action_target, payload, status)
        VALUES (
            NEW.business_id,
            'Owner',
            CASE
                WHEN NEW.stock = 0 THEN '🚨 Out of Stock: ' || NEW.name
                ELSE '⚠️ Low Stock: ' || NEW.name
            END,
            CASE
                WHEN NEW.stock = 0
                    THEN '"' || NEW.name || '" is completely out of stock. Reorder immediately!'
                ELSE '"' || NEW.name || '" has only ' || NEW.stock || ' ' || NEW.unit ||
                     ' remaining (min: ' || NEW.min_stock || '). Reorder soon.'
            END,
            CASE WHEN NEW.stock = 0 THEN 'Out Of Stock' ELSE 'Stock Almost Finished' END,
            CASE WHEN NEW.stock = 0 THEN 'critical'::public.notification_priority
                 ELSE 'high'::public.notification_priority END,
            'navigate',
            'inventory',
            jsonb_build_object(
                'productId',   NEW.id,
                'productName', NEW.name,
                'stock',       NEW.stock,
                'minStock',    NEW.min_stock
            ),
            'delivered'
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_check_low_stock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_complete_production_batch"("p_batch_id" "uuid", "p_staff_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_batch RECORD;
    v_product RECORD;
    v_current_stock NUMERIC(14,3);
    v_new_stock NUMERIC(14,3);
    v_result JSONB;
BEGIN
    PERFORM public.assert_permission((SELECT business_id FROM public.production_batches WHERE id = p_batch_id), 'production.update');
    PERFORM public.assert_business_member((SELECT business_id FROM public.production_batches WHERE id = p_batch_id));
    -- Fetch batch and lock row
    SELECT * INTO v_batch
    FROM public.production_batches
    WHERE id = p_batch_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Production batch % not found.', p_batch_id;
    END IF;

    IF v_batch.status = 'Completed' THEN
        RAISE EXCEPTION 'Batch % is already marked as Completed.', COALESCE(v_batch.reference_number, v_batch.id::text);
    END IF;

    IF v_batch.status = 'Cancelled' THEN
        RAISE EXCEPTION 'Cannot complete a cancelled batch (%).', COALESCE(v_batch.reference_number, v_batch.id::text);
    END IF;

    -- Update batch status
    UPDATE public.production_batches
    SET status = 'Completed',
        updated_at = NOW()
    WHERE id = p_batch_id;

    -- Add finished product to inventory if product_id is set
    IF v_batch.product_id IS NOT NULL AND v_batch.quantity_produced > 0 THEN
        SELECT id, name, stock INTO v_product
        FROM public.products
        WHERE id = v_batch.product_id
        FOR UPDATE;

        IF FOUND THEN
            v_current_stock := v_product.stock;
            v_new_stock := v_current_stock + v_batch.quantity_produced;

            UPDATE public.products
            SET stock = v_new_stock,
                updated_at = NOW()
            WHERE id = v_batch.product_id;

            -- Insert Stock Movement Audit Log
            INSERT INTO public.inventory_adjustments (
                business_id,
                product_id,
                product_name,
                type,
                quantity_adjusted,
                previous_stock,
                new_stock,
                timestamp,
                reason,
                staff_name,
                batch_id,
                reference_number,
                notes
            ) VALUES (
                v_batch.business_id,
                v_batch.product_id,
                v_product.name,
                'Production Output'::public.inventory_adjustment_type,
                v_batch.quantity_produced,
                v_current_stock,
                v_new_stock,
                NOW(),
                'Finished goods output for completed batch ' || COALESCE(v_batch.reference_number, v_batch.id::text),
                p_staff_name,
                p_batch_id,
                v_batch.reference_number,
                'Added ' || v_batch.quantity_produced || ' ' || v_batch.unit || ' to finished goods inventory.'
            );
        END IF;
    END IF;

    -- Return updated batch JSON
    SELECT row_to_json(b)::jsonb INTO v_result
    FROM public.production_batches b
    WHERE b.id = p_batch_id;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_complete_production_batch"("p_batch_id" "uuid", "p_staff_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_contact_allowed"("p_business_id" "uuid", "p_phone" "text", "p_email" "text", "p_purpose" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT NOT EXISTS (
        SELECT 1 FROM public.customers c
        WHERE c.business_id = p_business_id
          AND c.deleted_at IS NULL
          AND (public.fn_phone_key(c.phone) = public.fn_phone_key(p_phone)
               OR public.fn_email_key(c.email) = public.fn_email_key(p_email))
          AND NOT CASE WHEN p_purpose = 'promotion' THEN c.notify_promotions ELSE c.notify_service END
    );
$$;


ALTER FUNCTION "public"."fn_contact_allowed"("p_business_id" "uuid", "p_phone" "text", "p_email" "text", "p_purpose" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_create_customer_account"("p_uid" "uuid", "p_slug" "text", "p_name" "text", "p_phone" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_uid UUID := p_uid;
    v_business_id UUID;
    v_customer_id UUID;
    v_email TEXT;
    v_name TEXT := left(trim(COALESCE(p_name, '')), 100);
    v_phone TEXT := public.fn_normalize_ke_phone(p_phone);
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'Please sign in first.';
    END IF;
    -- The page and the auth listener can both call this right after sign-up.
    PERFORM pg_advisory_xact_lock(hashtextextended(v_uid::TEXT, 0));
    IF EXISTS (SELECT 1 FROM public.customer_accounts WHERE id = v_uid) THEN
        RETURN v_uid;
    END IF;
    IF v_name = '' THEN
        RAISE EXCEPTION 'Please enter your name.';
    END IF;
    IF v_phone IS NULL THEN
        RAISE EXCEPTION 'Please enter a valid Kenyan phone number, like 0712 345 678.';
    END IF;

    SELECT id INTO v_business_id
    FROM public.businesses
    WHERE website_slug = p_slug AND deleted_at IS NULL;
    IF v_business_id IS NULL THEN
        RAISE EXCEPTION 'This shop is not available.';
    END IF;

    SELECT email INTO v_email FROM auth.users WHERE id = v_uid;

    INSERT INTO public.customers (business_id, name, phone, email, description, last_modified_by)
    VALUES (v_business_id, v_name, v_phone, v_email, 'Website account', 'website')
    RETURNING id INTO v_customer_id;

    INSERT INTO public.customer_accounts (id, business_id, customer_id, name, phone, email)
    VALUES (v_uid, v_business_id, v_customer_id, v_name, v_phone, v_email);

    RETURN v_uid;
END;
$$;


ALTER FUNCTION "public"."fn_create_customer_account"("p_uid" "uuid", "p_slug" "text", "p_name" "text", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_create_production_batch"("p_business_id" "uuid", "p_bom_id" "uuid", "p_recipe_name" "text", "p_quantity_produced" numeric, "p_unit" "text", "p_status" "text", "p_staff_name" "text", "p_date" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_bom RECORD;
    v_ingredient RECORD;
    v_required_qty NUMERIC(14,6);
    v_current_stock NUMERIC(14,3);
    v_new_stock NUMERIC(14,3);
    v_finished_good RECORD;
    v_batch_id UUID;
    v_ref_no TEXT;
    v_batch_status TEXT;
    v_result JSONB;
BEGIN
    PERFORM public.assert_permission(p_business_id, 'production.create');
    PERFORM public.assert_business_member(p_business_id);
    -- Validate BOM existence
    SELECT * INTO v_bom
    FROM public.bill_of_materials
    WHERE id = p_bom_id AND business_id = p_business_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Bill of Materials with ID "%" does not exist for business "%".', p_bom_id, p_business_id;
    END IF;

    -- Validate quantity
    IF p_quantity_produced <= 0 THEN
        RAISE EXCEPTION 'Quantity produced must be greater than zero.';
    END IF;

    -- Validate Finished Product existence if linked
    IF v_bom.product_id IS NOT NULL THEN
        SELECT id, name, stock INTO v_finished_good
        FROM public.products
        WHERE id = v_bom.product_id;
    END IF;

    -- 1. PRE-CHECK INGREDIENTS STOCK & LOCK ROWS
    FOR v_ingredient IN
        SELECT
            bi.product_id,
            bi.quantity_required,
            bi.waste_percentage,
            bi.unit AS ingredient_unit,
            p.name AS product_name,
            p.stock AS current_stock
        FROM public.bom_ingredients bi
        JOIN public.products p ON p.id = bi.product_id
        WHERE bi.bom_id = p_bom_id
        FOR UPDATE OF p
    LOOP
        v_required_qty := v_ingredient.quantity_required
                         * (1.00 + v_ingredient.waste_percentage / 100.0)
                         * p_quantity_produced;

        IF v_ingredient.current_stock < v_required_qty THEN
            RAISE EXCEPTION 'Insufficient stock for "%": required %, available %.',
                v_ingredient.product_name,
                ROUND(v_required_qty, 3),
                ROUND(v_ingredient.current_stock, 3);
        END IF;
    END LOOP;

    -- Generate Reference Number
    v_ref_no := 'BATCH-' || to_char(COALESCE(p_date, NOW()), 'YYYYMMDD') || '-' || upper(substring(uuid_generate_v4()::text from 1 for 4));
    v_batch_status := COALESCE(p_status, 'In Progress');

    -- Insert Production Batch
    INSERT INTO public.production_batches (
        business_id,
        recipe_name,
        product_id,
        bom_id,
        quantity_produced,
        unit,
        status,
        staff_name,
        reference_number,
        date,
        created_at,
        updated_at
    ) VALUES (
        p_business_id,
        p_recipe_name,
        v_bom.product_id,
        p_bom_id,
        p_quantity_produced,
        p_unit,
        v_batch_status,
        p_staff_name,
        v_ref_no,
        COALESCE(p_date, NOW()),
        NOW(),
        NOW()
    )
    RETURNING id INTO v_batch_id;

    -- 2. DEDUCT RAW MATERIALS & LOG MOVEMENTS
    FOR v_ingredient IN
        SELECT
            bi.product_id,
            bi.quantity_required,
            bi.waste_percentage,
            p.name AS product_name,
            p.stock AS current_stock
        FROM public.bom_ingredients bi
        JOIN public.products p ON p.id = bi.product_id
        WHERE bi.bom_id = p_bom_id
    LOOP
        v_required_qty := v_ingredient.quantity_required
                         * (1.00 + v_ingredient.waste_percentage / 100.0)
                         * p_quantity_produced;

        v_current_stock := v_ingredient.current_stock;
        v_new_stock := v_current_stock - v_required_qty;

        -- Deduct stock
        UPDATE public.products
        SET stock = v_new_stock,
            updated_at = NOW()
        WHERE id = v_ingredient.product_id;

        -- Create Stock Movement Audit Log
        INSERT INTO public.inventory_adjustments (
            business_id,
            product_id,
            product_name,
            type,
            quantity_adjusted,
            previous_stock,
            new_stock,
            timestamp,
            reason,
            staff_name,
            batch_id,
            reference_number,
            notes
        ) VALUES (
            p_business_id,
            v_ingredient.product_id,
            v_ingredient.product_name,
            'Production Consumption'::public.inventory_adjustment_type,
            -v_required_qty,
            v_current_stock,
            v_new_stock,
            NOW(),
            'Production consumption for batch ' || v_ref_no || ' (' || p_recipe_name || ')',
            p_staff_name,
            v_batch_id,
            v_ref_no,
            'Raw material consumed for producing ' || p_quantity_produced || ' ' || p_unit || ' of ' || COALESCE(v_finished_good.name, p_recipe_name)
        );
    END LOOP;

    -- 3. IF DIRECTLY CREATED AS COMPLETED, ADD FINISHED GOOD STOCK
    IF v_batch_status = 'Completed' AND v_bom.product_id IS NOT NULL THEN
        SELECT stock INTO v_current_stock
        FROM public.products
        WHERE id = v_bom.product_id
        FOR UPDATE;

        v_new_stock := v_current_stock + p_quantity_produced;

        UPDATE public.products
        SET stock = v_new_stock,
            updated_at = NOW()
        WHERE id = v_bom.product_id;

        INSERT INTO public.inventory_adjustments (
            business_id,
            product_id,
            product_name,
            type,
            quantity_adjusted,
            previous_stock,
            new_stock,
            timestamp,
            reason,
            staff_name,
            batch_id,
            reference_number,
            notes
        ) VALUES (
            p_business_id,
            v_bom.product_id,
            v_finished_good.name,
            'Production Output'::public.inventory_adjustment_type,
            p_quantity_produced,
            v_current_stock,
            v_new_stock,
            NOW(),
            'Finished goods output for completed batch ' || v_ref_no,
            p_staff_name,
            v_batch_id,
            v_ref_no,
            'Added ' || p_quantity_produced || ' ' || p_unit || ' to inventory.'
        );
    END IF;

    -- Fetch newly created batch row as JSON
    SELECT row_to_json(b)::jsonb INTO v_result
    FROM public.production_batches b
    WHERE b.id = v_batch_id;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_create_production_batch"("p_business_id" "uuid", "p_bom_id" "uuid", "p_recipe_name" "text", "p_quantity_produced" numeric, "p_unit" "text", "p_status" "text", "p_staff_name" "text", "p_date" timestamp with time zone) OWNER TO "postgres";


