BEGIN
    IF v_target IS NOT NULL THEN
        NEW.ring := TRUE;
        NEW.action_type := 'navigate'::public.notification_action_type;
        IF NEW.action_target IS NULL OR NEW.action_target IN ('none', '', 'schedules') THEN
            NEW.action_target := v_target;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


