CREATE OR REPLACE FUNCTION "public"."fn_product_opening_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF COALESCE(NEW.stock, 0) > 0 AND NEW.deleted_at IS NULL THEN
        INSERT INTO public.inventory_adjustments (
            business_id, product_id, product_name, type, quantity_adjusted, previous_stock, new_stock,
            timestamp, reason, staff_name, last_modified_by
        ) VALUES (
            NEW.business_id, NEW.id, NEW.name, 'Restock', NEW.stock, 0, NEW.stock,
            COALESCE(NEW.created_at, NOW()), 'Opening stock',
            COALESCE((SELECT u.name FROM public.users u WHERE u.auth_user_id = auth.uid() LIMIT 1), 'System'),
            COALESCE(NEW.last_modified_by, 'system')
        );
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_product_opening_stock"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."website_promo_codes" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "business_id" "uuid" NOT NULL,
    "code" "text" NOT NULL,
    "description" "text",
    "kind" "text" NOT NULL,
    "value" numeric(14,2) NOT NULL,
    "min_order" numeric(14,2) DEFAULT 0 NOT NULL,
    "starts_at" timestamp with time zone,
    "ends_at" timestamp with time zone,
    "max_uses" integer,
    "once_per_customer" boolean DEFAULT true NOT NULL,
    "show_on_website" boolean DEFAULT false NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "website_promo_codes_check" CHECK ((("kind" <> 'percent'::"text") OR ("value" <= (90)::numeric))),
    CONSTRAINT "website_promo_codes_check1" CHECK ((("ends_at" IS NULL) OR ("starts_at" IS NULL) OR ("ends_at" > "starts_at"))),
    CONSTRAINT "website_promo_codes_code_check" CHECK (("code" ~ '^[A-Z0-9][A-Z0-9-]{2,23}$'::"text")),
    CONSTRAINT "website_promo_codes_description_check" CHECK ((("description" IS NULL) OR ("length"("description") <= 200))),
    CONSTRAINT "website_promo_codes_kind_check" CHECK (("kind" = ANY (ARRAY['percent'::"text", 'amount'::"text"]))),
    CONSTRAINT "website_promo_codes_max_uses_check" CHECK ((("max_uses" IS NULL) OR ("max_uses" > 0))),
    CONSTRAINT "website_promo_codes_min_order_check" CHECK (("min_order" >= (0)::numeric)),
    CONSTRAINT "website_promo_codes_value_check" CHECK (("value" > (0)::numeric))
);


ALTER TABLE "public"."website_promo_codes" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_promo_value"("p_promo" "public"."website_promo_codes", "p_subtotal" numeric, "p_account_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_uses INTEGER;
BEGIN
    IF NOT p_promo.active OR (p_promo.starts_at IS NOT NULL AND NOW() < p_promo.starts_at) THEN
        RAISE EXCEPTION 'That promo code isn''t active yet.';
    END IF;
    IF p_promo.ends_at IS NOT NULL AND NOW() >= p_promo.ends_at THEN
        RAISE EXCEPTION 'That promo code has expired.';
    END IF;
    IF p_subtotal < p_promo.min_order THEN
        RAISE EXCEPTION 'That code needs an order of at least % in products.', p_promo.min_order;
    END IF;
    IF p_promo.max_uses IS NOT NULL THEN
        SELECT count(*) INTO v_uses FROM public.online_orders
        WHERE promo_code_id = p_promo.id AND status <> 'cancelled';
        IF v_uses >= p_promo.max_uses THEN
            RAISE EXCEPTION 'That promo code has been fully used.';
        END IF;
    END IF;
    IF p_account_id IS NOT NULL AND p_promo.once_per_customer AND EXISTS (
        SELECT 1 FROM public.online_orders
        WHERE promo_code_id = p_promo.id AND account_id = p_account_id AND status <> 'cancelled'
    ) THEN
        RAISE EXCEPTION 'You have already used that promo code.';
    END IF;

    RETURN LEAST(
        p_subtotal,
        CASE WHEN p_promo.kind = 'percent'
             THEN round(p_subtotal * p_promo.value / 100, 2)
             ELSE p_promo.value END
    );
END;
$$;


ALTER FUNCTION "public"."fn_promo_value"("p_promo" "public"."website_promo_codes", "p_subtotal" numeric, "p_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_purchase_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.requested_by_user_id IS NULL THEN
            NEW.requested_by_user_id := public.fn_my_user_id();
        END IF;
    END IF;
    IF public.fn_in_buying_ctx() THEN
        RETURN NEW;
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF NEW.status NOT IN ('Pending', 'Ordered') THEN
            RAISE EXCEPTION 'Save a new purchase as a draft or as ordered.';
        END IF;
        IF NEW.status = 'Ordered' THEN
            IF public.fn_needs_approval(NEW.business_id, NEW.total_amount) THEN
                NEW.status := 'Awaiting approval';
            ELSE
                NEW.ordered_at := NOW();
                NEW.approved_amount := NEW.total_amount;
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    -- UPDATE
    IF OLD.status IN ('Part received', 'Received') OR EXISTS (SELECT 1 FROM public.purchase_receipts r WHERE r.purchase_id = OLD.id) THEN
        IF NEW.status IS DISTINCT FROM OLD.status OR NEW.total_amount IS DISTINCT FROM OLD.total_amount
           OR NEW.supplier_id IS DISTINCT FROM OLD.supplier_id OR NEW.supplier_name IS DISTINCT FROM OLD.supplier_name THEN
            RAISE EXCEPTION 'Goods have arrived on this purchase, so it can''t be changed. Close it, or return goods to the supplier.';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.status IS DISTINCT FROM OLD.status THEN
        IF NEW.status = 'Cancelled' THEN
            NULL;
        ELSIF NEW.status = 'Pending' AND OLD.status IN ('RFQ', 'Awaiting approval', 'Ordered') THEN
            NULL;
        ELSIF NEW.status = 'Ordered' AND OLD.status = 'Awaiting approval' THEN
            NEW.status := 'Awaiting approval'; -- an edit saved as ordered stays waiting
        ELSIF NEW.status = 'Ordered' AND OLD.status IN ('Pending', 'RFQ') THEN
            IF public.fn_needs_approval(NEW.business_id, NEW.total_amount) THEN
                NEW.status := 'Awaiting approval';
            ELSE
                NEW.ordered_at := NOW();
                NEW.approved_amount := NEW.total_amount;
            END IF;
        ELSIF NEW.status IN ('Part received', 'Received') THEN
            RAISE EXCEPTION 'Receive the goods with Receive, so stock and the books follow.';
        ELSE
            RAISE EXCEPTION 'A purchase can''t go from % to % here.', OLD.status, NEW.status;
        END IF;
    ELSIF NEW.status = 'Ordered' AND NEW.total_amount > COALESCE(OLD.approved_amount, OLD.total_amount) THEN
        -- Made bigger after it was placed: check the limit again.
        IF public.fn_needs_approval(NEW.business_id, NEW.total_amount) THEN
            NEW.status := 'Awaiting approval';
        ELSE
            NEW.approved_amount := NEW.total_amount;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_purchase_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_purchase_item_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_p public.purchases%ROWTYPE;
BEGIN
    SELECT * INTO v_p FROM public.purchases WHERE id = COALESCE(NEW.purchase_id, OLD.purchase_id);
    IF NOT FOUND THEN
        RETURN COALESCE(NEW, OLD);
    END IF;
    IF NOT public.fn_in_buying_ctx() THEN
        IF v_p.status IN ('Part received', 'Received') THEN
            RAISE EXCEPTION 'Goods have arrived on this purchase, so its items can''t be changed.';
        END IF;
        IF TG_OP <> 'DELETE' THEN
            NEW.qty_received := COALESCE(CASE WHEN TG_OP = 'UPDATE' THEN OLD.qty_received END, 0);
            NEW.qty_damaged := COALESCE(CASE WHEN TG_OP = 'UPDATE' THEN OLD.qty_damaged END, 0);
        END IF;
    END IF;
    IF TG_OP <> 'DELETE' AND NEW.for_business_id IS NOT NULL THEN
        IF NEW.for_business_id = v_p.business_id THEN
            NEW.for_business_id := NULL;
        ELSIF NOT public.fn_branches_share_owner(v_p.business_id, NEW.for_business_id) THEN
            RAISE EXCEPTION 'You can only buy for another branch of this business.';
        END IF;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."fn_purchase_item_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_purchase_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NEW.status = 'Awaiting approval' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
        PERFORM public.fn_buying_notify(
            NEW.business_id, NULL, 'Purchase Approval', 'Purchase needs approval',
            public.fn_purchase_ref(NEW) || ' to ' || NEW.supplier_name || ' for KSh '
                || trim(to_char(NEW.total_amount, 'FM999,999,999,990.00')) || COALESCE(' from ' || NULLIF(NEW.created_by, ''), '')
                || ' is above their limit.',
            'buying', jsonb_build_object('purchaseId', NEW.id));
    END IF;
    RETURN NULL;
END;
$$;


