    AS $$
    SELECT CASE WHEN p_role IS NULL OR p_role IN ('Owner', 'Admin', 'Administrator') THEN NULL
           ELSE (SELECT max_amount FROM public.purchase_approval_limits WHERE business_id = p_business_id AND role = p_role) END;
