CREATE OR REPLACE FUNCTION "public"."fn_sd_link_customer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_key TEXT := public.fn_phone_key(NEW.customer_phone);
    v_id  UUID;
BEGIN
    IF NEW.customer_id IS NOT NULL OR v_key IS NULL THEN
        RETURN NEW;
    END IF;
    SELECT id INTO v_id
    FROM public.customers
    WHERE business_id = NEW.business_id AND deleted_at IS NULL AND merged_into_id IS NULL
      AND public.fn_phone_key(phone) = v_key
    ORDER BY created_at
    LIMIT 1;
    IF v_id IS NULL AND TG_TABLE_NAME <> 'quotes' AND NULLIF(trim(NEW.customer_name), '') IS NOT NULL THEN
        INSERT INTO public.customers (business_id, name, phone, customer_type, last_modified_by)
        VALUES (NEW.business_id, left(trim(NEW.customer_name), 120), NEW.customer_phone,
                CASE WHEN TG_TABLE_NAME = 'sales_invoices' OR NEW.customer_name ~* '(ltd|limited|hotel|school|shop|store|supermarket|enterprise|company|co\.|restaurant|cafe|hospital)'
                     THEN 'business' ELSE 'individual' END,
                'quotes_invoices')
        RETURNING id INTO v_id;
    END IF;
    NEW.customer_id := v_id;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sd_link_customer"() OWNER TO "postgres";


