CREATE OR REPLACE FUNCTION "public"."fn_stamp_delivery_zone"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_name TEXT;
BEGIN
    SELECT NULLIF(trim(u.name), '') INTO v_name FROM public.users u WHERE u.auth_user_id = auth.uid();
    NEW.name := trim(NEW.name);
    NEW.updated_at := NOW();
    IF TG_OP = 'INSERT' THEN
        NEW.created_by := auth.uid();
        NEW.created_by_name := v_name;
    ELSE
        -- Who first added an area never changes.
        NEW.created_by := OLD.created_by;
        NEW.created_by_name := OLD.created_by_name;
    END IF;
    NEW.updated_by_name := v_name;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_stamp_delivery_zone"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_storage_folder_permission"("p_folder" "text", VARIADIC "p_permissions" "text"[]) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
BEGIN
    IF auth.uid() IS NULL
       OR p_folder !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
        RETURN FALSE;
    END IF;
    RETURN public.has_permission(p_folder::UUID, VARIADIC p_permissions);
END;
$_$;


