CREATE OR REPLACE FUNCTION "public"."fn_supplier_portal_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_p public.purchases%ROWTYPE;
BEGIN
    IF TG_TABLE_NAME = 'purchases' THEN
        IF NEW.supplier_id IS NOT NULL AND NEW.status = 'Ordered'
           AND (TG_OP = 'INSERT' OR OLD.status NOT IN ('Ordered', 'Part received', 'Received')) THEN
            PERFORM public.fn_notify_supplier(NEW.business_id, NEW.supplier_id, 'New order',
                (SELECT name FROM public.businesses WHERE id = NEW.business_id) || ' ordered from you: ' || public.fn_purchase_ref(NEW)
                    || ', KSh ' || to_char(NEW.total_amount, 'FM999,999,990.00') || '. Confirm when you will deliver.',
                jsonb_build_object('purchaseId', NEW.id));
        END IF;
    ELSIF TG_TABLE_NAME = 'purchase_quotes' THEN
        SELECT * INTO v_p FROM public.purchases WHERE id = NEW.purchase_id;
        PERFORM public.fn_notify_supplier(NEW.business_id, NEW.supplier_id, 'Price request',
            (SELECT name FROM public.businesses WHERE id = NEW.business_id) || ' asks for your prices on ' || public.fn_purchase_ref(v_p) || '.',
            jsonb_build_object('quoteId', NEW.id));
    ELSIF TG_TABLE_NAME = 'supplier_payments' THEN
        IF NEW.supplier_id IS NOT NULL AND NEW.voided_at IS NULL THEN
            PERFORM public.fn_notify_supplier(NEW.business_id, NEW.supplier_id, 'Payment sent',
                (SELECT name FROM public.businesses WHERE id = NEW.business_id) || ' paid you KSh ' || to_char(NEW.amount, 'FM999,999,990.00')
                    || ' by ' || NEW.method || COALESCE(' (' || NEW.reference || ')', '') || '.',
                jsonb_build_object('paymentId', NEW.id));
        END IF;
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_supplier_portal_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_employee"("p_business_id" "uuid", "p_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user public.users%ROWTYPE;
    v_role public.employee_role;
    v_id   UUID;
BEGIN
    SELECT * INTO v_user FROM public.users WHERE id = p_user_id;
    SELECT role INTO v_role FROM public.business_memberships
    WHERE business_id = p_business_id AND user_id = p_user_id AND status = 'Active';
    IF v_user.id IS NULL OR v_role IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT id INTO v_id FROM public.employees
    WHERE business_id = p_business_id AND user_id = p_user_id
    ORDER BY (deleted_at IS NULL) DESC, created_at
    LIMIT 1;

    IF v_id IS NULL THEN
        v_id := CASE WHEN EXISTS (SELECT 1 FROM public.employees WHERE id = p_user_id)
                     THEN gen_random_uuid() ELSE p_user_id END;
        INSERT INTO public.employees (id, business_id, user_id, name, role, email, phone, avatar, assigned_branches)
        VALUES (v_id, p_business_id, p_user_id, COALESCE(NULLIF(trim(v_user.name), ''), 'Team member'), v_role,
                v_user.email, v_user.phone, v_user.avatar, jsonb_build_array(p_business_id::TEXT));
    ELSE
        UPDATE public.employees
        SET name = COALESCE(NULLIF(trim(v_user.name), ''), name),
            role = v_role,
            email = v_user.email,
            phone = v_user.phone,
            avatar = COALESCE(v_user.avatar, avatar),
            deleted_at = NULL
        WHERE id = v_id
          AND (name, role, email, phone, avatar, deleted_at) IS DISTINCT FROM
              (COALESCE(NULLIF(trim(v_user.name), ''), name), v_role, v_user.email, v_user.phone,
               COALESCE(v_user.avatar, avatar), NULL::TIMESTAMPTZ);
    END IF;
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."fn_sync_employee"("p_business_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_transfer_dispatch"("p_transfer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_t       public.stock_transfers%ROWTYPE;
    v_item    public.stock_transfer_items%ROWTYPE;
    v_prod    public.products%ROWTYPE;
    v_to_name TEXT;
    v_from    TEXT;
    v_me      TEXT;
    v_count   INTEGER := 0;
    v_value   NUMERIC := 0;
BEGIN
    SELECT * INTO v_t FROM public.stock_transfers WHERE id = p_transfer_id FOR UPDATE;
    SELECT name INTO v_to_name FROM public.businesses WHERE id = v_t.to_business_id;
    SELECT name INTO v_from FROM public.businesses WHERE id = v_t.from_business_id;
    v_me := public.fn_my_display_name(v_t.from_business_id);

    FOR v_item IN SELECT * FROM public.stock_transfer_items WHERE transfer_id = v_t.id ORDER BY from_product_id LOOP
        SELECT * INTO v_prod FROM public.products
        WHERE id = v_item.from_product_id AND business_id = v_t.from_business_id AND deleted_at IS NULL
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION '% is not in this branch any more. Remove it from the transfer.', v_item.product_name;
        END IF;
        IF v_item.quantity_sent > v_prod.stock THEN
            RAISE EXCEPTION 'Only % % of % left here. You can''t send %.',
                public.fn_qty(v_prod.stock), v_prod.unit, v_prod.name, public.fn_qty(v_item.quantity_sent);
        END IF;
        UPDATE public.stock_transfer_items
        SET product_name = v_prod.name, sku = v_prod.sku, unit = v_prod.unit, category = v_prod.category,
            unit_cost = v_prod.cost, unit_price = v_prod.price
        WHERE id = v_item.id;
        UPDATE public.products SET stock = stock - v_item.quantity_sent, updated_at = NOW() WHERE id = v_prod.id;
        INSERT INTO public.inventory_adjustments (
            business_id, product_id, product_name, type, quantity_adjusted, previous_stock, new_stock,
            reason, staff_name, reference_number, notes
        ) VALUES (
            v_t.from_business_id, v_prod.id, v_prod.name, 'Transfer Out', -v_item.quantity_sent,
            v_prod.stock, v_prod.stock - v_item.quantity_sent,
            'Sent to ' || v_to_name, v_me, v_t.reference, v_t.note
        );
        v_count := v_count + 1;
        v_value := v_value + v_item.quantity_sent * v_prod.cost;
    END LOOP;
    IF v_count = 0 THEN
        RAISE EXCEPTION 'Add at least one product to send.';
    END IF;

    UPDATE public.stock_transfers
    SET status = 'in_transit', sent_at = NOW(),
        sent_by_name = COALESCE(sent_by_name, v_me), sent_by_user_id = COALESCE(sent_by_user_id, public.fn_my_user_id()),
        updated_at = NOW()
    WHERE id = v_t.id;

    INSERT INTO public.notifications (business_id, title, message, type, priority, action_type, action_target, payload, created_by)
    VALUES (
        v_t.to_business_id, 'Stock on the way',
        v_from || ' sent ' || v_count || CASE WHEN v_count = 1 THEN ' product' ELSE ' products' END
            || ' (' || v_t.reference || '). Check it when it arrives and confirm what came.',
        'Stock Transfer', 'high', 'navigate', 'stock-transfers',
        jsonb_build_object('transferId', v_t.id, 'reference', v_t.reference), 'system'
    );
    RETURN jsonb_build_object('id', v_t.id, 'reference', v_t.reference, 'status', 'in_transit', 'lines', v_count, 'costValue', ROUND(v_value, 2));
END;
$$;


ALTER FUNCTION "public"."fn_transfer_dispatch"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_transfer_go"("p_transfer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_t     public.stock_transfers%ROWTYPE;
    v_value NUMERIC;
    v_to    TEXT;
BEGIN
    SELECT * INTO v_t FROM public.stock_transfers WHERE id = p_transfer_id FOR UPDATE;
    v_value := public.fn_transfer_value(p_transfer_id);
    IF public.fn_needs_approval(v_t.from_business_id, v_value) THEN
        UPDATE public.stock_transfers SET status = 'awaiting_approval', updated_at = NOW() WHERE id = v_t.id;
        SELECT name INTO v_to FROM public.businesses WHERE id = v_t.to_business_id;
        PERFORM public.fn_buying_notify(v_t.from_business_id, NULL, 'Purchase Approval', 'Transfer needs approval',
            v_t.reference || ' to ' || v_to || ' is worth KSh ' || trim(to_char(v_value, 'FM999,999,999,990'))
                || ' at cost, above ' || COALESCE(v_t.sent_by_name, 'the sender') || '''s limit.',
            'stock-transfers', jsonb_build_object('transferId', v_t.id, 'reference', v_t.reference));
        RETURN jsonb_build_object('id', v_t.id, 'reference', v_t.reference, 'status', 'awaiting_approval', 'costValue', ROUND(v_value, 2));
    END IF;
    RETURN public.fn_transfer_dispatch(p_transfer_id);
END;
$$;


ALTER FUNCTION "public"."fn_transfer_go"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_transfer_value"("p_transfer_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT COALESCE(SUM(i.quantity_sent * COALESCE(p.cost, i.unit_cost)), 0)
    FROM public.stock_transfer_items i
    LEFT JOIN public.products p ON p.id = i.from_product_id
    WHERE i.transfer_id = p_transfer_id;
$$;


ALTER FUNCTION "public"."fn_transfer_value"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trap_product_hard_deletes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM public.transaction_items WHERE product_id = OLD.id LIMIT 1
    ) THEN
        UPDATE public.products
        SET deleted_at = NOW(), sync_status = 'synced'
        WHERE id = OLD.id;
        RETURN NULL;  -- Cancel the DELETE
    END IF;
    RETURN OLD;       -- Allow the DELETE
END;
$$;


