CREATE OR REPLACE FUNCTION "public"."fn_users_protect_verified"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF current_user IN ('anon', 'authenticated') THEN
        -- The app can't vouch for an email address; keep what the server set.
        NEW.verified_email := CASE WHEN TG_OP = 'UPDATE' THEN OLD.verified_email ELSE NULL END;
    ELSIF NEW.is_verified IS TRUE
          AND (TG_OP = 'INSERT' OR OLD.is_verified IS NOT TRUE)
          AND NEW.verified_email IS NULL THEN
        -- Server code (seed data, older functions) that marks a row verified
        NEW.verified_email := NEW.email;
    END IF;

    NEW.is_verified := NEW.verified_email IS NOT NULL
        AND LOWER(TRIM(NEW.verified_email)) = LOWER(TRIM(COALESCE(NEW.email, '')));
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_users_protect_verified"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_valid_ad_cards"("p_cards" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_card JSONB;
    v_href TEXT;
    v_image TEXT;
BEGIN
    IF p_cards IS NULL OR jsonb_typeof(p_cards) <> 'array' OR jsonb_array_length(p_cards) > 9 THEN
        RETURN FALSE;
    END IF;
    FOR v_card IN SELECT value FROM jsonb_array_elements(p_cards) LOOP
        IF jsonb_typeof(v_card) <> 'object' THEN RETURN FALSE; END IF;
        IF EXISTS (
            SELECT 1 FROM jsonb_object_keys(v_card) k
            WHERE k NOT IN ('id', 'kind', 'title', 'body', 'kicker', 'ctaLabel', 'href', 'image', 'tone', 'hidden')
        ) THEN RETURN FALSE; END IF;
        IF v_card->>'kind' IS NULL OR v_card->>'kind' NOT IN ('poster', 'strip') THEN RETURN FALSE; END IF;
        IF jsonb_typeof(v_card->'title') IS DISTINCT FROM 'string'
           OR length(trim(v_card->>'title')) NOT BETWEEN 1 AND 60 THEN RETURN FALSE; END IF;
        IF v_card ? 'id' AND (jsonb_typeof(v_card->'id') <> 'string' OR length(v_card->>'id') > 40) THEN RETURN FALSE; END IF;
        IF v_card ? 'body' AND (jsonb_typeof(v_card->'body') <> 'string' OR length(v_card->>'body') > 120) THEN RETURN FALSE; END IF;
        IF v_card ? 'kicker' AND (jsonb_typeof(v_card->'kicker') <> 'string' OR length(v_card->>'kicker') > 30) THEN RETURN FALSE; END IF;
        IF v_card ? 'ctaLabel' AND (jsonb_typeof(v_card->'ctaLabel') <> 'string' OR length(v_card->>'ctaLabel') > 24) THEN RETURN FALSE; END IF;
        IF v_card ? 'hidden' AND jsonb_typeof(v_card->'hidden') <> 'boolean' THEN RETURN FALSE; END IF;
        IF v_card ? 'tone' AND (v_card->>'tone' IS NULL
           OR v_card->>'tone' NOT IN ('ember', 'espresso', 'butter', 'peach', 'sage', 'cream')) THEN RETURN FALSE; END IF;
        IF v_card ? 'href' THEN
            IF jsonb_typeof(v_card->'href') <> 'string' THEN RETURN FALSE; END IF;
            v_href := v_card->>'href';
            -- A page on this site ("/shop?category=Milk", not "//elsewhere") or a secure web address.
            IF length(v_href) > 300
               OR v_href !~ '^(/([A-Za-z0-9._~%!$&''()*+,;=:@/?#-]*)?|https://[A-Za-z0-9.-]+(:[0-9]+)?(/[A-Za-z0-9._~%!$&''()*+,;=:@/?#-]*)?)$'
               OR v_href ~ '^//' THEN
                RETURN FALSE;
            END IF;
        END IF;
        IF v_card ? 'image' THEN
            IF jsonb_typeof(v_card->'image') <> 'string' THEN RETURN FALSE; END IF;
            v_image := v_card->>'image';
            IF length(v_image) > 500
               OR v_image !~ '^(https://[A-Za-z0-9.-]+(:[0-9]+)?/[A-Za-z0-9._~%!$&''()*+,;=:@/?-]*|/hero/[a-z0-9-]+\.(webp|png|jpg))$' THEN
                RETURN FALSE;
            END IF;
        END IF;
    END LOOP;
    RETURN TRUE;
END;
$_$;


ALTER FUNCTION "public"."fn_valid_ad_cards"("p_cards" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_valid_hero_slides"("p_slides" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_slide JSONB;
    v_image JSONB;
    v_href  TEXT;
    v_box   JSONB;
BEGIN
    IF p_slides IS NULL OR jsonb_typeof(p_slides) <> 'array' OR jsonb_array_length(p_slides) > 6 THEN
        RETURN FALSE;
    END IF;
    FOR v_slide IN SELECT value FROM jsonb_array_elements(p_slides) LOOP
        IF jsonb_typeof(v_slide) <> 'object' THEN RETURN FALSE; END IF;
        -- Only the known keys, so nothing unexpected reaches the public website.
        IF EXISTS (
            SELECT 1 FROM jsonb_object_keys(v_slide) k
            WHERE k NOT IN ('id', 'title', 'body', 'ctaLabel', 'ctaHref', 'images', 'positions', 'phone', 'side', 'tone', 'hidden')
        ) THEN RETURN FALSE; END IF;
        IF jsonb_typeof(v_slide->'title') IS DISTINCT FROM 'string'
           OR length(trim(v_slide->>'title')) NOT BETWEEN 1 AND 90 THEN RETURN FALSE; END IF;
        IF v_slide ? 'id' AND (jsonb_typeof(v_slide->'id') <> 'string' OR length(v_slide->>'id') > 40) THEN RETURN FALSE; END IF;
        IF v_slide ? 'body' AND (jsonb_typeof(v_slide->'body') <> 'string' OR length(v_slide->>'body') > 160) THEN RETURN FALSE; END IF;
        IF v_slide ? 'hidden' AND jsonb_typeof(v_slide->'hidden') <> 'boolean' THEN RETURN FALSE; END IF;
        -- Layout choices: where the pictures go on phones and on wider screens, and the colour.
        IF v_slide ? 'phone' AND (jsonb_typeof(v_slide->'phone') <> 'string'
           OR v_slide->>'phone' NOT IN ('beside', 'above', 'below', 'none')) THEN RETURN FALSE; END IF;
        IF v_slide ? 'side' AND (jsonb_typeof(v_slide->'side') <> 'string'
           OR v_slide->>'side' NOT IN ('right', 'left')) THEN RETURN FALSE; END IF;
        IF v_slide ? 'tone' AND (jsonb_typeof(v_slide->'tone') <> 'string'
           OR v_slide->>'tone' NOT IN ('ember', 'espresso', 'butter', 'peach', 'sage', 'cream')) THEN RETURN FALSE; END IF;
        IF v_slide ? 'ctaLabel' AND (jsonb_typeof(v_slide->'ctaLabel') <> 'string' OR length(v_slide->>'ctaLabel') > 30) THEN RETURN FALSE; END IF;
        IF v_slide ? 'ctaHref' THEN
            IF jsonb_typeof(v_slide->'ctaHref') <> 'string' THEN RETURN FALSE; END IF;
            v_href := v_slide->>'ctaHref';
            -- A page on this site ("/shop?category=Milk", not "//elsewhere") or a secure web address.
            IF length(v_href) > 300
               OR v_href !~ '^(/([A-Za-z0-9._~%!$&''()*+,;=:@/?#-]*)?|https://[A-Za-z0-9.-]+(:[0-9]+)?(/[A-Za-z0-9._~%!$&''()*+,;=:@/?#-]*)?)$'
               OR v_href ~ '^//' THEN
                RETURN FALSE;
            END IF;
        END IF;
        IF jsonb_typeof(v_slide->'images') IS DISTINCT FROM 'array'
           OR jsonb_array_length(v_slide->'images') NOT BETWEEN 1 AND 3 THEN RETURN FALSE; END IF;
        FOR v_image IN SELECT value FROM jsonb_array_elements(v_slide->'images') LOOP
            IF jsonb_typeof(v_image) <> 'string'
               OR length(v_image #>> '{}') > 500
               OR (v_image #>> '{}') !~ '^(https://[A-Za-z0-9.-]+(:[0-9]+)?/[A-Za-z0-9._~%!$&''()*+,;=:@/?-]*|/hero/[a-z0-9-]+\.(webp|png|jpg))$' THEN
                RETURN FALSE;
            END IF;
        END LOOP;
        -- Optional: where each picture sits, one box per picture, in percent of the display.
        IF v_slide ? 'positions' THEN
            IF jsonb_typeof(v_slide->'positions') <> 'array'
               OR jsonb_array_length(v_slide->'positions') <> jsonb_array_length(v_slide->'images') THEN RETURN FALSE; END IF;
            FOR v_box IN SELECT value FROM jsonb_array_elements(v_slide->'positions') LOOP
                IF jsonb_typeof(v_box) <> 'object'
                   OR EXISTS (SELECT 1 FROM jsonb_object_keys(v_box) k WHERE k NOT IN ('x', 'y', 'w', 'h'))
                   OR jsonb_typeof(v_box->'x') IS DISTINCT FROM 'number'
                   OR jsonb_typeof(v_box->'y') IS DISTINCT FROM 'number'
                   OR jsonb_typeof(v_box->'w') IS DISTINCT FROM 'number'
                   OR jsonb_typeof(v_box->'h') IS DISTINCT FROM 'number'
                   OR (v_box->>'x')::numeric NOT BETWEEN -50 AND 100
                   OR (v_box->>'y')::numeric NOT BETWEEN -50 AND 100
                   OR (v_box->>'w')::numeric NOT BETWEEN 8 AND 200
                   OR (v_box->>'h')::numeric NOT BETWEEN 8 AND 200 THEN
                    RETURN FALSE;
                END IF;
            END LOOP;
        END IF;
    END LOOP;
    RETURN TRUE;
END;
$_$;


ALTER FUNCTION "public"."fn_valid_hero_slides"("p_slides" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_wallet_pays_debt"("p_customer_id" "uuid", "p_recorded_by" "text" DEFAULT 'System'::"text") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_c       RECORD;
    v_amount  NUMERIC(14,2);
    v_left    NUMERIC(14,2);
    v_applied NUMERIC(14,2);
    v_rec     RECORD;
BEGIN
    SELECT id, business_id, COALESCE(wallet_balance, 0) AS wallet, COALESCE(debt_balance, 0) AS debt
    INTO v_c
    FROM public.customers
    WHERE id = p_customer_id AND merged_into_id IS NULL
    FOR UPDATE;

    IF NOT FOUND OR v_c.wallet <= 0 OR v_c.debt <= 0 THEN
        RETURN 0;
    END IF;

    v_amount := LEAST(v_c.wallet, v_c.debt);

    UPDATE public.customers
    SET wallet_balance = v_c.wallet - v_amount,
        debt_balance   = v_c.debt - v_amount
    WHERE id = p_customer_id;

    -- Oldest credit records are settled first, the same as a cash payment towards debt.
    v_left := v_amount;
    FOR v_rec IN
        SELECT id, balance FROM public.credit_payments
        WHERE customer_id = p_customer_id AND business_id = v_c.business_id AND status IN ('Open', 'Partial')
        ORDER BY created_at ASC, id ASC
        FOR UPDATE
    LOOP
        EXIT WHEN v_left <= 0;
        v_applied := LEAST(v_left, v_rec.balance);
        v_left := v_left - v_applied;
        UPDATE public.credit_payments
        SET amount_paid = amount_paid + v_applied,
            status = CASE WHEN amount_paid + v_applied >= amount_owed THEN 'Settled'::public.credit_status ELSE 'Partial'::public.credit_status END,
            settled_at = CASE WHEN amount_paid + v_applied >= amount_owed THEN NOW() ELSE NULL END,
            updated_at = NOW()
        WHERE id = v_rec.id;
    END LOOP;

    INSERT INTO public.wallet_transactions
        (business_id, customer_id, amount, balance_before, balance_after, reason, recorded_by)
    VALUES (v_c.business_id, p_customer_id, -v_amount, v_c.wallet, v_c.wallet - v_amount,
            'Wallet money paid off debt', COALESCE(p_recorded_by, 'System'));

    -- 'wallet_usage', not 'debt_payment': this money already came in when the wallet was topped up.
    INSERT INTO public.customer_ledger
        (business_id, customer_id, type, amount, wallet_balance, debt_balance, recorded_by, note)
    VALUES (v_c.business_id, p_customer_id, 'wallet_usage', v_amount,
            v_c.wallet - v_amount, v_c.debt - v_amount, COALESCE(p_recorded_by, 'System'),
            'Wallet money paid off debt');

    -- Money towards a debt earns 1 point per KSh 1 (wallet top-ups earn nothing when paid in).
    IF FLOOR(v_amount) > 0 THEN
        UPDATE public.customers SET loyalty_points = COALESCE(loyalty_points, 0) + FLOOR(v_amount)::INTEGER
        WHERE id = p_customer_id;
        INSERT INTO public.loyalty_points_earned (business_id, customer_id, points, source, amount)
        VALUES (v_c.business_id, p_customer_id, FLOOR(v_amount)::INTEGER, 'debt_payment', v_amount);
    END IF;

    RETURN v_amount;
END;
$$;


ALTER FUNCTION "public"."fn_wallet_pays_debt"("p_customer_id" "uuid", "p_recorded_by" "text") OWNER TO "postgres";


