CREATE OR REPLACE FUNCTION "public"."get_business_dashboard_metrics"("p_business_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    result JSON;
BEGIN
    PERFORM public.assert_permission(p_business_id, 'home.view', 'reports.view');
    PERFORM public.assert_business_member(p_business_id);
    SELECT json_build_object(
        'totalSales',    COALESCE(SUM(t.final_total), 0),
        'orderCount',    COUNT(t.id),
        'aov',           COALESCE(AVG(t.final_total), 0),
        'totalExpenses', (
            SELECT COALESCE(SUM(e.amount), 0)
            FROM public.expenses e
            WHERE e.business_id = p_business_id
              AND e.date BETWEEN p_start_date AND p_end_date
              AND e.deleted_at IS NULL
        )
    ) INTO result
    FROM public.transactions t
    WHERE t.business_id = p_business_id
      AND t.timestamp BETWEEN p_start_date AND p_end_date
      AND t.deleted_at IS NULL;

    RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_business_dashboard_metrics"("p_business_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_business_payments"("p_business_id" "uuid", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "reference_code" "text", "amount" numeric, "method" "text", "sender_name" "text", "sender_phone" "text", "status" "text", "date" timestamp with time zone, "customer_id" "uuid", "customer_name" "text", "payment_type" "text", "description" "text", "applied_to" "text", "debt_applied" numeric, "wallet_applied" numeric, "recorded_by" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT public.assert_permission(p_business_id, 'payments.view');
    SELECT public.assert_business_member(p_business_id);
    SELECT
        p.id, p.reference_code, p.amount, p.method,
        p.sender_name, p.sender_phone, p.status, p.date,
        p.customer_id, p.customer_name, p.payment_type, p.description,
        p.applied_to, p.debt_applied, p.wallet_applied, p.recorded_by, p.created_at
    FROM public.payments p
    WHERE p.business_id = p_business_id
    ORDER BY p.date DESC
    LIMIT p_limit OFFSET p_offset;
$$;


