CREATE OR REPLACE FUNCTION "public"."get_finance_report"("p_business_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v      JSONB;
    v_inc  NUMERIC := 0;
    v_cost NUMERIC := 0;
    v_cnt  INTEGER := 0;
    v_owed NUMERIC := 0;
    v_from DATE := (p_start AT TIME ZONE 'Africa/Nairobi')::DATE;
    v_to   DATE := (p_end AT TIME ZONE 'Africa/Nairobi')::DATE;
    v_daily JSONB;
BEGIN
    v := public.get_finance_report_till(p_business_id, p_start, p_end);

    WITH doc AS (
        SELECT l.entry_date AS d,
               SUM(CASE WHEN a.type = 'income' THEN l.credit - l.debit ELSE 0 END) AS inc,
               SUM(CASE WHEN a.system_key = 'cogs' THEN l.debit - l.credit ELSE 0 END) AS cost
        FROM public.acc_lines l
        JOIN public.acc_entries e ON e.id = l.entry_id
        JOIN public.acc_accounts a ON a.id = l.account_id
        WHERE e.business_id = p_business_id
          AND e.source_type IN ('sales_delivery', 'sales_invoice', 'credit_note')
          AND l.entry_date BETWEEN v_from AND v_to
        GROUP BY l.entry_date
    )
    SELECT COALESCE(SUM(inc), 0), COALESCE(SUM(cost), 0),
           COALESCE((SELECT jsonb_agg(
               CASE WHEN x.d IS NULL THEN dd ELSE dd || jsonb_build_object(
                   'sales', (dd->>'sales')::NUMERIC + x.inc,
                   'cost', (dd->>'cost')::NUMERIC + x.cost,
                   'profit', (dd->>'profit')::NUMERIC + x.inc - x.cost) END
               ORDER BY dd->>'day')
             FROM jsonb_array_elements(v->'daily') dd
             LEFT JOIN doc x ON to_char(x.d, 'YYYY-MM-DD') = dd->>'day'), '[]'::JSONB)
    INTO v_inc, v_cost, v_daily
    FROM doc;

    SELECT COUNT(*), COALESCE(SUM(GREATEST(0, balance)), 0)
    INTO v_cnt, v_owed
    FROM public.sales_invoices
    WHERE business_id = p_business_id AND status <> 'void'
      AND issue_date BETWEEN v_from AND v_to;

    RETURN v
        || jsonb_build_object(
            'daily', v_daily,
            'invoices', jsonb_build_object('count', v_cnt, 'income', v_inc, 'cost', v_cost, 'owed', v_owed),
            'profit', (v->'profit') || jsonb_build_object(
                'sales', (v->'profit'->>'sales')::NUMERIC + v_inc,
                'costOfGoods', (v->'profit'->>'costOfGoods')::NUMERIC + v_cost,
                'gross', (v->'profit'->>'gross')::NUMERIC + v_inc - v_cost,
                'net', (v->'profit'->>'net')::NUMERIC + v_inc - v_cost,
                'invoiced', v_inc));
END;
$$;


ALTER FUNCTION "public"."get_finance_report"("p_business_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_finance_report_till"("p_business_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_sales      JSONB;
    v_methods    JSONB;
    v_cogs       JSONB;
    v_expenses   JSONB;
    v_exp_cats   JSONB;
    v_exp_list   JSONB;
    v_points     JSONB;
    v_money_in   JSONB;
    v_debts      JSONB;
    v_wallets    JSONB;
    v_daily      JSONB;
    v_activity   JSONB;
    v_products   JSONB;
    v_goods      NUMERIC := 0;
    v_cost       NUMERIC := 0;
    v_exp_total  NUMERIC := 0;
    v_pts_debt   NUMERIC := 0;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'finance.view');

    -- Sales
    SELECT jsonb_build_object(
        'count', COUNT(*),
        'total', COALESCE(SUM(final_total), 0),
        'vat', COALESCE(SUM(tax), 0),
        'delivery', COALESCE(SUM(CASE WHEN is_delivery THEN delivery_fee ELSE 0 END), 0),
        'discounts', COALESCE(SUM(discount), 0),
        'net', COALESCE(SUM(final_total - tax), 0),
        'paid', COALESCE(SUM(final_total) FILTER (WHERE payment_method NOT IN ('Credit_Debt', 'Credit')), 0),
        'credit', COALESCE(SUM(final_total) FILTER (WHERE payment_method IN ('Credit_Debt', 'Credit')), 0),
        'creditCount', COUNT(*) FILTER (WHERE payment_method IN ('Credit_Debt', 'Credit')),
        'walletUsed', COALESCE(SUM(wallet_applied) FILTER (WHERE payment_method IN ('Credit_Debt', 'Credit')), 0),
        'creditOwed', COALESCE(SUM(GREATEST(0, final_total - COALESCE(amount_paid, 0) - COALESCE(wallet_applied, 0)))
                        FILTER (WHERE payment_method IN ('Credit_Debt', 'Credit')), 0)
    ), COALESCE(SUM(final_total - tax), 0)
    INTO v_sales, v_goods
    FROM public.transactions
    WHERE business_id = p_business_id AND deleted_at IS NULL
      AND timestamp >= p_start AND timestamp <= p_end;

    SELECT COALESCE(jsonb_object_agg(m, amt), '{}'::JSONB) INTO v_methods
    FROM (
        SELECT payment_method::TEXT AS m, SUM(final_total) AS amt
        FROM public.transactions
        WHERE business_id = p_business_id AND deleted_at IS NULL
          AND timestamp >= p_start AND timestamp <= p_end
        GROUP BY payment_method
    ) x;

    -- Cost of goods: the cost recorded on the sale line, else the product's cost now
    SELECT jsonb_build_object(
        'total', COALESCE(SUM(ti.quantity * COALESCE(ti.unit_cost, p.cost, 0)), 0),
        'estimatedLines', COUNT(*) FILTER (WHERE ti.unit_cost IS NULL),
        'lines', COUNT(*)
    ), COALESCE(SUM(ti.quantity * COALESCE(ti.unit_cost, p.cost, 0)), 0)
    INTO v_cogs, v_cost
    FROM public.transaction_items ti
    JOIN public.transactions t ON t.id = ti.transaction_id
    LEFT JOIN public.products p ON p.id = ti.product_id
    WHERE t.business_id = p_business_id AND t.deleted_at IS NULL
      AND t.timestamp >= p_start AND t.timestamp <= p_end;

    -- Best and worst products by profit
    SELECT COALESCE(jsonb_agg(row_to_json(x) ORDER BY x.profit DESC), '[]'::JSONB) INTO v_products
    FROM (
        SELECT ti.product_name AS name,
               SUM(ti.quantity) AS qty,
               SUM(ti.line_total) AS revenue,
               SUM(ti.quantity * COALESCE(ti.unit_cost, p.cost, 0)) AS cost,
               SUM(ti.line_total) - SUM(ti.quantity * COALESCE(ti.unit_cost, p.cost, 0)) AS profit
        FROM public.transaction_items ti
        JOIN public.transactions t ON t.id = ti.transaction_id
        LEFT JOIN public.products p ON p.id = ti.product_id
        WHERE t.business_id = p_business_id AND t.deleted_at IS NULL
          AND t.timestamp >= p_start AND t.timestamp <= p_end
        GROUP BY ti.product_name
        ORDER BY 5 DESC
        LIMIT 50
    ) x;

    -- Expenses (petty cash is part of them)
    SELECT jsonb_build_object(
        'total', COALESCE(SUM(amount), 0),
        'pettyCash', COALESCE(SUM(amount) FILTER (WHERE source = 'petty_cash'), 0),
        'pettyCashCount', COUNT(*) FILTER (WHERE source = 'petty_cash'),
        'count', COUNT(*)
    ), COALESCE(SUM(amount), 0)
    INTO v_expenses, v_exp_total
    FROM public.expenses
    WHERE business_id = p_business_id AND deleted_at IS NULL
      AND date >= p_start AND date <= p_end;

    SELECT COALESCE(jsonb_agg(row_to_json(x) ORDER BY x.amount DESC), '[]'::JSONB) INTO v_exp_cats
    FROM (
        SELECT category, SUM(amount) AS amount, COUNT(*) AS count,
               SUM(amount) FILTER (WHERE source = 'petty_cash') AS "pettyCash"
        FROM public.expenses
        WHERE business_id = p_business_id AND deleted_at IS NULL
          AND date >= p_start AND date <= p_end
        GROUP BY category
    ) x;

    SELECT COALESCE(jsonb_agg(row_to_json(x) ORDER BY x.date DESC), '[]'::JSONB) INTO v_exp_list
    FROM (
        SELECT id, date, category, description, amount, staff_name AS "staffName",
               source, payment_method AS method, receipt_ref AS "receiptRef"
        FROM public.expenses
        WHERE business_id = p_business_id AND deleted_at IS NULL
          AND date >= p_start AND date <= p_end
        ORDER BY date DESC
        LIMIT 300
    ) x;

    -- Points: earned, used (and what they cost), and what customers still hold
    SELECT COALESCE(SUM(value), 0) INTO v_pts_debt
    FROM public.loyalty_redemptions
    WHERE business_id = p_business_id AND refunded_at IS NULL AND kind = 'account'
      AND created_at >= p_start AND created_at <= p_end;

    SELECT jsonb_build_object(
        'earned', (SELECT COALESCE(SUM(points), 0) FROM public.loyalty_points_earned
                   WHERE business_id = p_business_id AND created_at >= p_start AND created_at <= p_end),
        'earnedBySource', (SELECT COALESCE(jsonb_object_agg(source, pts), '{}'::JSONB) FROM (
                   SELECT source, SUM(points) AS pts FROM public.loyalty_points_earned
                   WHERE business_id = p_business_id AND created_at >= p_start AND created_at <= p_end
                   GROUP BY source) s),
        'used', (SELECT COALESCE(jsonb_agg(row_to_json(u)), '[]'::JSONB) FROM (
                   SELECT kind, COUNT(*) AS count, SUM(points) AS points, SUM(value) AS value
                   FROM public.loyalty_redemptions
                   WHERE business_id = p_business_id AND refunded_at IS NULL
                     AND created_at >= p_start AND created_at <= p_end
                   GROUP BY kind) u),
        'usedValue', (SELECT COALESCE(SUM(value), 0) FROM public.loyalty_redemptions
                   WHERE business_id = p_business_id AND refunded_at IS NULL
                     AND created_at >= p_start AND created_at <= p_end),
        'debtPaidWithPoints', v_pts_debt,
        'outstandingPoints', (SELECT COALESCE(SUM(loyalty_points), 0) FROM public.customers
                   WHERE business_id = p_business_id AND deleted_at IS NULL AND merged_into_id IS NULL),
        'outstandingValue', (SELECT COALESCE(SUM(loyalty_points * public.fn_point_value(business_id, tier)), 0) FROM public.customers
                   WHERE business_id = p_business_id AND deleted_at IS NULL AND merged_into_id IS NULL)
    ) INTO v_points;

    -- Money that came in. Customer money is counted once, from the customer ledger, which every
    -- payment, debt payment and top-up writes to. Voided payments are left out.
    WITH voided AS (
        SELECT reference_code FROM public.payments
        WHERE business_id = p_business_id AND status = 'Voided'
    ), ledger AS (
        SELECT l.type, l.amount FROM public.customer_ledger l
        WHERE l.business_id = p_business_id
          AND l.created_at >= p_start AND l.created_at <= p_end
          AND l.type IN ('debt_payment', 'wallet_topup')
          AND NOT EXISTS (SELECT 1 FROM voided v
                          WHERE l.reference_id IN (v.reference_code || '-debt-payment', v.reference_code || '-wallet-topup'))
    )
    SELECT jsonb_build_object(
        'sales', COALESCE((v_sales->>'paid')::NUMERIC, 0),
        'debtRepaid', COALESCE((SELECT SUM(amount) FROM ledger WHERE type = 'debt_payment'), 0),
        'walletTopups', COALESCE((SELECT SUM(amount) FROM ledger WHERE type = 'wallet_topup'), 0),
        'otherPayments', COALESCE((SELECT SUM(amount - debt_applied - wallet_applied) FROM public.payments
                          WHERE business_id = p_business_id AND status = 'Success'
                            AND date >= p_start AND date <= p_end), 0)
    ) INTO v_money_in;

    -- Debts as they stand now, with their age
    SELECT jsonb_build_object(
        'outstanding', (SELECT COALESCE(SUM(debt_balance), 0) FROM public.customers
                        WHERE business_id = p_business_id AND deleted_at IS NULL AND merged_into_id IS NULL),
        'debtors', (SELECT COUNT(*) FROM public.customers
                    WHERE business_id = p_business_id AND deleted_at IS NULL AND merged_into_id IS NULL AND debt_balance > 0),
        'aging', (SELECT jsonb_build_object(
                    'week', COALESCE(SUM(balance) FILTER (WHERE created_at >= NOW() - INTERVAL '7 days'), 0),
                    'month', COALESCE(SUM(balance) FILTER (WHERE created_at < NOW() - INTERVAL '7 days' AND created_at >= NOW() - INTERVAL '30 days'), 0),
                    'quarter', COALESCE(SUM(balance) FILTER (WHERE created_at < NOW() - INTERVAL '30 days' AND created_at >= NOW() - INTERVAL '90 days'), 0),
                    'older', COALESCE(SUM(balance) FILTER (WHERE created_at < NOW() - INTERVAL '90 days'), 0))
                  FROM public.credit_payments
                  WHERE business_id = p_business_id AND status IN ('Open', 'Partial')),
        'top', (SELECT COALESCE(jsonb_agg(row_to_json(d)), '[]'::JSONB) FROM (
                  SELECT c.id, c.name, c.phone, c.debt_balance AS owed,
                         (SELECT MIN(cp.created_at) FROM public.credit_payments cp
                          WHERE cp.customer_id = c.id AND cp.status IN ('Open', 'Partial')) AS since
                  FROM public.customers c
                  WHERE c.business_id = p_business_id AND c.deleted_at IS NULL AND c.merged_into_id IS NULL AND c.debt_balance > 0
                  ORDER BY c.debt_balance DESC
                  LIMIT 15) d)
    ) INTO v_debts;

    SELECT jsonb_build_object(
        'held', COALESCE(SUM(wallet_balance), 0),
        'customers', COUNT(*) FILTER (WHERE wallet_balance > 0)
    ) INTO v_wallets
    FROM public.customers
    WHERE business_id = p_business_id AND deleted_at IS NULL AND merged_into_id IS NULL;

    -- Day by day, on the Kenya clock
    WITH days AS (
        SELECT generate_series(
            date_trunc('day', p_start AT TIME ZONE 'Africa/Nairobi'),
            date_trunc('day', p_end AT TIME ZONE 'Africa/Nairobi'),
            INTERVAL '1 day') AS d
        LIMIT 400
    ), s AS (
        SELECT date_trunc('day', t.timestamp AT TIME ZONE 'Africa/Nairobi') AS d,
               SUM(t.final_total - t.tax) AS sales
        FROM public.transactions t
        WHERE t.business_id = p_business_id AND t.deleted_at IS NULL AND t.timestamp >= p_start AND t.timestamp <= p_end
        GROUP BY 1
    ), c AS (
        SELECT date_trunc('day', t.timestamp AT TIME ZONE 'Africa/Nairobi') AS d,
               SUM(ti.quantity * COALESCE(ti.unit_cost, p.cost, 0)) AS cost
        FROM public.transaction_items ti
        JOIN public.transactions t ON t.id = ti.transaction_id
        LEFT JOIN public.products p ON p.id = ti.product_id
        WHERE t.business_id = p_business_id AND t.deleted_at IS NULL AND t.timestamp >= p_start AND t.timestamp <= p_end
        GROUP BY 1
    ), e AS (
        SELECT date_trunc('day', date AT TIME ZONE 'Africa/Nairobi') AS d, SUM(amount) AS expenses
        FROM public.expenses
        WHERE business_id = p_business_id AND deleted_at IS NULL AND date >= p_start AND date <= p_end
        GROUP BY 1
    ), r AS (
        SELECT date_trunc('day', created_at AT TIME ZONE 'Africa/Nairobi') AS d, SUM(value) AS points
        FROM public.loyalty_redemptions
        WHERE business_id = p_business_id AND refunded_at IS NULL AND kind = 'account'
          AND created_at >= p_start AND created_at <= p_end
        GROUP BY 1
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'day', to_char(days.d, 'YYYY-MM-DD'),
        'sales', COALESCE(s.sales, 0),
        'cost', COALESCE(c.cost, 0),
        'expenses', COALESCE(e.expenses, 0),
        'points', COALESCE(r.points, 0),
        'profit', COALESCE(s.sales, 0) - COALESCE(c.cost, 0) - COALESCE(e.expenses, 0) - COALESCE(r.points, 0)
    ) ORDER BY days.d), '[]'::JSONB) INTO v_daily
    FROM days
    LEFT JOIN s ON s.d = days.d
    LEFT JOIN c ON c.d = days.d
    LEFT JOIN e ON e.d = days.d
    LEFT JOIN r ON r.d = days.d;

    -- What happened, newest first
    SELECT COALESCE(jsonb_agg(row_to_json(a) ORDER BY a.at DESC), '[]'::JSONB) INTO v_activity
    FROM (
        (SELECT t.timestamp AS at,
                CASE WHEN t.payment_method IN ('Credit_Debt', 'Credit') THEN 'credit_sale' ELSE 'sale' END AS kind,
                t.final_total AS amount,
                COALESCE(t.wallet_applied, 0) AS wallet,
                t.payment_method::TEXT AS method,
                t.customer_name AS customer,
                t.staff_name AS "by",
                NULL::TEXT AS detail
         FROM public.transactions t
         WHERE t.business_id = p_business_id AND t.deleted_at IS NULL AND t.timestamp >= p_start AND t.timestamp <= p_end
         ORDER BY t.timestamp DESC LIMIT 200)
        UNION ALL
        (SELECT e.date, CASE WHEN e.source = 'petty_cash' THEN 'petty_cash' ELSE 'expense' END, e.amount, 0,
                e.payment_method, NULL, e.staff_name, e.category || COALESCE(': ' || NULLIF(e.description, ''), '')
         FROM public.expenses e
         WHERE e.business_id = p_business_id AND e.deleted_at IS NULL AND e.date >= p_start AND e.date <= p_end
         ORDER BY e.date DESC LIMIT 200)
        UNION ALL
        (SELECT l.created_at, l.type, l.amount, 0, NULL, c.name, l.recorded_by, NULL
         FROM public.customer_ledger l
         JOIN public.customers c ON c.id = l.customer_id
         WHERE l.business_id = p_business_id AND l.created_at >= p_start AND l.created_at <= p_end
           AND (l.type IN ('debt_payment', 'wallet_topup') OR (l.type = 'wallet_usage' AND l.transaction_id IS NULL))
         ORDER BY l.created_at DESC LIMIT 200)
        UNION ALL
        (SELECT r.created_at, 'points_' || r.kind, r.value, 0, NULL, c.name, r.recorded_by, r.points::TEXT
         FROM public.loyalty_redemptions r
         JOIN public.customers c ON c.id = r.customer_id
         WHERE r.business_id = p_business_id AND r.refunded_at IS NULL AND r.created_at >= p_start AND r.created_at <= p_end
         ORDER BY r.created_at DESC LIMIT 200)
        UNION ALL
        (SELECT p.voided_at, 'payment_voided', p.amount, 0, p.method, p.customer_name, p.voided_by, p.void_reason
         FROM public.payments p
         WHERE p.business_id = p_business_id AND p.status = 'Voided' AND p.voided_at >= p_start AND p.voided_at <= p_end
         ORDER BY p.voided_at DESC LIMIT 100)
        ORDER BY 1 DESC
        LIMIT 400
    ) a;

    RETURN jsonb_build_object(
        'start', p_start,
        'end', p_end,
        'sales', v_sales,
        'salesByMethod', v_methods,
        'costOfGoods', v_cogs,
        'expenses', v_expenses,
        'expenseCategories', v_exp_cats,
        'expenseList', v_exp_list,
        'points', v_points,
        'moneyIn', v_money_in,
        'debts', v_debts,
        'wallets', v_wallets,
        'products', v_products,
        'daily', v_daily,
        'activity', v_activity,
        'profit', jsonb_build_object(
            'sales', v_goods,
            'costOfGoods', v_cost,
            'gross', v_goods - v_cost,
            'expenses', v_exp_total,
            'pointsToDebt', v_pts_debt,
            'net', v_goods - v_cost - v_exp_total - v_pts_debt
        )
    );
END;
$$;


ALTER FUNCTION "public"."get_finance_report_till"("p_business_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_invitation_by_token"("p_token" "text") RETURNS TABLE("id" "uuid", "business_id" "uuid", "business_name" "text", "invitee_name" "text", "email" "text", "phone" "text", "role" "public"."employee_role", "expires_at" timestamp with time zone, "status" "public"."invitation_status")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NOT public.invite_guesses_left() THEN
        RETURN;
    END IF;

    RETURN QUERY
    SELECT i.id, i.business_id, b.name, i.name, i.email, i.phone, i.role, i.expires_at, i.status
    FROM public.invitations i
    JOIN public.businesses b ON b.id = i.business_id
    WHERE i.invitation_token = p_token
      AND i.status = 'Pending'
      AND i.expires_at > NOW();

    IF NOT FOUND THEN
        PERFORM public.check_rate_limit(public.invite_guess_key(), 1000000, 900);
    END IF;
END;
$$;


ALTER FUNCTION "public"."get_invitation_by_token"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_money_assets"("p_business_id" "uuid") RETURNS TABLE("method" "text", "balance" numeric, "last_payment_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT public.assert_permission(p_business_id, 'payments.view');
    SELECT public.assert_business_member(p_business_id);
    SELECT method, balance, last_payment_at
    FROM public.money_assets
    WHERE business_id = p_business_id
    ORDER BY balance DESC;
$$;


ALTER FUNCTION "public"."get_money_assets"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_alarms"() RETURNS TABLE("id" "uuid", "business_id" "uuid", "title" "text", "notes" "text", "date" "date", "start_time" "text", "repeat" "text", "last_reminded_on" "date", "updated_at" timestamp with time zone, "user_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    WITH me AS (SELECT u.id FROM public.users u WHERE u.auth_user_id = auth.uid())
    SELECT s.id, s.business_id, COALESCE(NULLIF(s.title, ''), 'Reminder'), s.notes, s.date,
           to_char(s.start_time, 'HH24:MI'), s.repeat::TEXT, s.last_reminded_on, s.updated_at, me.id
    FROM public.schedules s, me
    WHERE s.deleted_at IS NULL
      AND public.fn_schedule_user(s.employee_id) = me.id
      AND s.business_id = ANY(public.get_user_business_ids())
      AND (s.repeat::TEXT <> 'None' OR s.date >= (NOW() AT TIME ZONE 'Africa/Nairobi')::DATE - 1)
    ORDER BY s.date, s.start_time;
$$;


ALTER FUNCTION "public"."get_my_alarms"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_contact_preferences"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT jsonb_build_object('service', c.notify_service, 'promotions', c.notify_promotions)
    FROM public.customer_accounts a
    JOIN public.customers c ON c.id = a.customer_id
    WHERE a.id = auth.uid();
$$;


ALTER FUNCTION "public"."get_my_contact_preferences"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_deliveries"("p_business_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_rider UUID;
BEGIN
    PERFORM public.assert_permission(p_business_id, 'deliveries.view');
    v_rider := public.fn_my_employee_id(p_business_id);
    IF v_rider IS NULL THEN
        RETURN '[]'::JSONB;
    END IF;

    RETURN COALESCE((
        SELECT jsonb_agg(to_jsonb(d) - 'rider_id' - 'is_open' ORDER BY d.assigned_at DESC)
        FROM public.fn_delivery_rows(p_business_id) d
        WHERE d.rider_id = v_rider
    ), '[]'::JSONB);
END;
$$;


ALTER FUNCTION "public"."get_my_deliveries"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_notification_settings"("p_business_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user UUID;
BEGIN
    SELECT u.id INTO v_user
    FROM public.users u
    JOIN public.business_memberships m ON m.user_id = u.id
    WHERE u.auth_user_id = auth.uid() AND m.business_id = p_business_id AND m.status = 'Active';
    IF v_user IS NULL THEN
        RAISE EXCEPTION 'Your role does not allow this.' USING ERRCODE = '42501';
    END IF;

    RETURN jsonb_build_object(
        'userId', v_user,
        'role', (SELECT m.role::TEXT FROM public.business_memberships m
                 WHERE m.user_id = v_user AND m.business_id = p_business_id),
        'paused', EXISTS (SELECT 1 FROM public.notification_preferences p
                          WHERE p.business_id = p_business_id AND p.user_id = v_user
                            AND p.category = 'all' AND NOT p.enabled),
        'categories', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'category', c.category,
                'types', to_jsonb(c.types),
                'locked', c.locked,
                'followsRole', c.permissions IS NULL,
                'enabled', c.locked OR NOT EXISTS (
                    SELECT 1 FROM public.notification_preferences p
                    WHERE p.business_id = p_business_id AND p.user_id = v_user
                      AND p.category = c.category AND NOT p.enabled)
            ))
            FROM public.fn_notification_catalog() c
            WHERE public.fn_user_has_permission(p_business_id, v_user, c.permissions)
        ), '[]'::jsonb),
        'hiddenTypes', COALESCE((
            SELECT jsonb_agg(t)
            FROM public.fn_notification_catalog() c, unnest(c.types) t
            WHERE NOT public.fn_user_has_permission(p_business_id, v_user, c.permissions)
        ), '[]'::jsonb)
    );
END;
$$;


ALTER FUNCTION "public"."get_my_notification_settings"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_rewards"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT jsonb_build_object(
        'points', c.loyalty_points,
        'tier', c.tier,
        'wallet', c.wallet_balance,
        'debt', c.debt_balance,
        'pointValue', public.fn_point_value(c.business_id, c.tier),
        'minRedeem', COALESCE(s.min_redeem_points, 100),
        'enabled', COALESCE(s.points_enabled, TRUE)
    )
    FROM public.customer_accounts a
    JOIN public.customers c ON c.id = a.customer_id
    LEFT JOIN public.loyalty_settings s ON s.business_id = c.business_id
    WHERE a.id = auth.uid();
$$;


ALTER FUNCTION "public"."get_my_rewards"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_ringing_alerts"("p_business_id" "uuid") RETURNS TABLE("id" "uuid", "title" "text", "message" "text", "type" "text", "action_target" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT n.id, n.title, n.message, n.type, n.action_target, n.created_at
    FROM public.notifications n
    WHERE n.business_id = p_business_id
      AND p_business_id = ANY(public.get_user_business_ids())
      AND n.ring AND n.accepted_at IS NULL AND n.deleted_at IS NULL
      AND n.created_at > NOW() - INTERVAL '12 hours'
      AND public.fn_is_alert_recipient(n, (SELECT u.id FROM public.users u WHERE u.auth_user_id = auth.uid()))
    ORDER BY n.created_at;
$$;


ALTER FUNCTION "public"."get_my_ringing_alerts"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_ideas"("p_slug" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', i.id,
        'kind', i.kind,
        'title', i.title,
        'description', i.description,
        'imageUrl', i.image_url,
        'staffNote', i.staff_note,
        'status', i.status,
        'productId', CASE WHEN i.status = 'available' THEN i.product_id END,
        'suggestedBy', i.suggested_name,
        'votes', i.vote_count,
        'voted', EXISTS (SELECT 1 FROM public.website_product_idea_votes v WHERE v.idea_id = i.id AND v.account_id = auth.uid()),
        'mine', i.suggested_by IS NOT NULL AND i.suggested_by = auth.uid(),
        'createdAt', i.created_at
    ) ORDER BY
        CASE i.status WHEN 'open' THEN 0 WHEN 'planned' THEN 1 WHEN 'pending' THEN 2 ELSE 3 END,
        i.sort_order DESC, i.vote_count DESC, i.created_at DESC), '[]'::jsonb)
    FROM public.website_product_ideas i
    JOIN public.businesses b ON b.id = i.business_id
    WHERE b.website_slug = p_slug AND b.deleted_at IS NULL
      AND (i.status IN ('open', 'planned', 'available')
           OR (i.status = 'pending' AND i.suggested_by IS NOT NULL AND i.suggested_by = auth.uid()));
$$;


ALTER FUNCTION "public"."get_product_ideas"("p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_storefront"("p_slug" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT jsonb_build_object(
        'business', jsonb_build_object(
            'name', b.name,
            'slug', b.website_slug,
            'description', b.description,
            'address', b.address,
            'contactEmail', NULLIF(b.contact_email, ''),
            'contactPhone', NULLIF(b.contact_phone, ''),
            'logoUrl', b.logo_url,
            'coverImageUrl', b.cover_image_url,
            'primaryColor', b.primary_color,
            'currency', b.currency,
            'paymentMethods', to_jsonb(b.default_payment_methods)
        ),
        'settings', jsonb_build_object(
            'deliveryEnabled', COALESCE(s.delivery_enabled, TRUE),
            'deliveryFee', COALESCE(s.delivery_fee, 0),
            'minOrder', COALESCE(s.min_order, 0),
            'assistantEnabled', COALESCE(s.assistant_enabled, TRUE),
            'openingHours', NULLIF(trim(s.opening_hours), ''),
            'whatsapp', NULLIF(trim(s.whatsapp), '')
        ),
        'pages', COALESCE(s.pages, '{}'::jsonb),
        -- Home page slides from Online Store > Home banner; hidden ones never leave the database.
        'heroSlides', COALESCE((
            SELECT jsonb_agg(slide) FROM jsonb_array_elements(s.hero_slides) AS slide
            WHERE COALESCE((slide->>'hidden')::boolean, FALSE) IS FALSE
        ), '[]'::jsonb),
        -- Advert cards from Online Store > Adverts; hidden ones never leave the database.
        'adCards', COALESCE((
            SELECT jsonb_agg(card) FROM jsonb_array_elements(s.ad_cards) AS card
            WHERE COALESCE((card->>'hidden')::boolean, FALSE) IS FALSE
        ), '[]'::jsonb),
        -- Branches customers can switch between: this shop and every other shop with the same
        -- owner that has its website switched on. The website shows a store picker at two or more.
        'stores', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'slug', x.website_slug,
                'name', x.name,
                'address', x.address,
                'phone', NULLIF(x.contact_phone, ''),
                'logoUrl', x.logo_url,
                'openingHours', NULLIF(trim(xs.opening_hours), '')
            ) ORDER BY x.name)
            FROM public.businesses x
            LEFT JOIN public.website_settings xs ON xs.business_id = x.id
            WHERE x.deleted_at IS NULL
              AND NULLIF(trim(COALESCE(x.website_slug, '')), '') IS NOT NULL
              AND (x.id = b.id OR public.fn_branches_share_owner(b.id, x.id))
        ), '[]'::jsonb),
        'loyalty', jsonb_build_object(
            'enabled', COALESCE(l.points_enabled, TRUE),
            'pointsPerShilling', 2,
            'valueBronze', COALESCE(l.value_bronze, 0.02),
            'valueSilver', COALESCE(l.value_silver, 0.01),
            'valueGold', COALESCE(l.value_gold, 0.005),
            'minRedeem', COALESCE(l.min_redeem_points, 100)
        ),
        'reviews', COALESCE((
            SELECT jsonb_agg(r ORDER BY r->>'createdAt' DESC)
            FROM (
                SELECT jsonb_build_object(
                    'id', rv.id,
                    'productId', rv.product_id,
                    'rating', rv.rating,
                    'title', rv.title,
                    'body', rv.body,
                    'name', rv.display_name,
                    'verified', rv.verified,
                    'featured', rv.featured,
                    'reply', rv.staff_reply,
                    'createdAt', rv.created_at
                ) AS r
                FROM public.website_reviews rv
                WHERE rv.business_id = b.id AND rv.status = 'approved'
                ORDER BY rv.featured DESC, rv.created_at DESC
                LIMIT 300
            ) recent
        ), '[]'::jsonb),
        'promotions', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'code', pc.code,
                'description', pc.description,
                'kind', pc.kind,
                'value', pc.value,
                'minOrder', pc.min_order,
                'endsAt', pc.ends_at
            ) ORDER BY pc.created_at DESC)
            FROM public.website_promo_codes pc
            WHERE pc.business_id = b.id AND pc.active AND pc.show_on_website
              AND (pc.starts_at IS NULL OR pc.starts_at <= NOW())
              AND (pc.ends_at IS NULL OR pc.ends_at > NOW())
        ), '[]'::jsonb),
        'deliveryZones', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('id', z.id, 'name', z.name, 'fee', z.fee) ORDER BY z.name)
            FROM public.delivery_zones z
            WHERE z.business_id = b.id AND z.active
        ), '[]'::jsonb),
        'branches', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('name', br.name, 'address', br.address) ORDER BY br.name)
            FROM public.branches br
            WHERE br.business_id = b.id AND br.deleted_at IS NULL
        ), '[]'::jsonb),
        'products', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', p.id,
                'name', p.name,
                'category', p.category,
                'price', p.price,
                -- The "was" price for an offer ribbon; only when it is really higher.
                'wasPrice', CASE WHEN p.website_was_price > p.price THEN p.website_was_price END,
                'unit', p.unit,
                'description', p.description,
                'image', p.image,
                'inStock', p.stock > 0
            ) ORDER BY p.category, p.name)
            FROM public.products p
            WHERE p.business_id = b.id
              AND p.deleted_at IS NULL
              AND p.show_on_website
              AND p.price > 0
        ), '[]'::jsonb),
        'articles', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', a.id,
                'slug', a.slug,
                'title', a.title,
                'summary', a.summary,
                'body', a.body,
                'category', a.category,
                'coverImageUrl', a.cover_image_url,
                'publishedAt', a.published_at
            ) ORDER BY a.published_at DESC)
            FROM public.website_articles a
            WHERE a.business_id = b.id AND a.published
        ), '[]'::jsonb)
    )
    FROM public.businesses b
    LEFT JOIN public.website_settings s ON s.business_id = b.id
    LEFT JOIN public.loyalty_settings l ON l.business_id = b.id
    WHERE b.website_slug = p_slug
      AND b.deleted_at IS NULL;
$$;


ALTER FUNCTION "public"."get_public_storefront"("p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_business_ids"() RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_ids UUID[];
BEGIN
    SELECT array_agg(bm.business_id)
    INTO v_ids
    FROM public.business_memberships bm
    JOIN public.users u ON bm.user_id = u.id
    WHERE u.auth_user_id = auth.uid()
      AND bm.status = 'Active';

    RETURN COALESCE(v_ids, ARRAY[]::UUID[]);
END;
$$;


ALTER FUNCTION "public"."get_user_business_ids"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_phone TEXT := COALESCE(NEW.raw_user_meta_data->>'phone', NEW.phone);
BEGIN
    IF EXISTS (SELECT 1 FROM public.users u WHERE u.phone = v_phone AND u.id <> NEW.id) THEN
        v_phone := NULL;
    END IF;

    INSERT INTO public.users (id, auth_user_id, name, email, phone, is_verified)
    VALUES (
        NEW.id,
        NEW.id,
        COALESCE(
            NULLIF(NEW.raw_user_meta_data->>'name', ''),
            NULLIF(NEW.raw_user_meta_data->>'full_name', ''),
            NULLIF(split_part(COALESCE(NEW.email, ''), '@', 1), ''),
            'User'
        ),
        NEW.email,
        v_phone,
        FALSE
    )
    ON CONFLICT (id) DO UPDATE SET
        email = EXCLUDED.email,
        phone = COALESCE(public.users.phone, EXCLUDED.phone);

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_till_payment"("p_till_payment_id" "uuid", "p_action" "text", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text", "p_handled_by" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_row  public.mpesa_till_payments%ROWTYPE;
    v_name TEXT;
    v_pid  UUID;
    v_by   TEXT := COALESCE(NULLIF(trim(p_handled_by), ''), 'Staff');
BEGIN
    SELECT * INTO v_row FROM public.mpesa_till_payments WHERE id = p_till_payment_id FOR UPDATE;
    IF NOT FOUND OR v_row.business_id IS NULL THEN
        RAISE EXCEPTION 'Till payment not found.';
    END IF;

    PERFORM public.assert_business_member(v_row.business_id);
    PERFORM public.assert_permission(v_row.business_id, 'payments.verify', 'payments.mpesa');

    IF p_action = 'reopen' THEN
        IF v_row.status NOT IN ('matched_sale', 'ignored') THEN
            RAISE EXCEPTION 'Only payments marked as a sale or ignored can go back to the queue. Void the payment instead.';
        END IF;
        UPDATE public.mpesa_till_payments
        SET status = 'unclaimed', handled_by = NULL, handled_at = NULL, note = NULL
        WHERE id = v_row.id;
        RETURN NULL;
    END IF;

    IF v_row.status <> 'unclaimed' THEN
        RAISE EXCEPTION 'This payment was already handled by %.', COALESCE(v_row.handled_by, 'someone else');
    END IF;

    IF p_action IN ('customer', 'walk_in') THEN
        IF p_action = 'customer' THEN
            SELECT name INTO v_name FROM public.customers
            WHERE id = p_customer_id AND business_id = v_row.business_id AND deleted_at IS NULL;
            IF v_name IS NULL THEN
                RAISE EXCEPTION 'Choose a customer for this payment.';
            END IF;
        END IF;

        v_pid := public.process_business_payment(
            v_row.business_id, v_row.trans_id, v_row.amount, 'M-Pesa',
            COALESCE(v_row.payer_name, v_name, 'M-Pesa customer'), v_row.msisdn, 'Success', v_row.trans_time,
            CASE WHEN p_action = 'customer' THEN p_customer_id END, v_name,
            CASE WHEN p_action = 'customer' THEN 'customer' ELSE 'walk-in' END,
            COALESCE(NULLIF(trim(p_note), ''), 'M-Pesa till payment'), v_by
        );
        UPDATE public.mpesa_till_payments
        SET status = 'recorded', payment_id = v_pid,
            customer_id = CASE WHEN p_action = 'customer' THEN p_customer_id END,
            handled_by = v_by, handled_at = NOW(), note = NULLIF(trim(p_note), '')
        WHERE id = v_row.id;
        RETURN v_pid;
    END IF;

    IF p_action = 'ignore' AND COALESCE(trim(p_note), '') = '' THEN
        RAISE EXCEPTION 'Say why this payment is being ignored.';
    END IF;
    IF p_action NOT IN ('sale', 'ignore') THEN
        RAISE EXCEPTION 'Unknown action %.', p_action;
    END IF;

    UPDATE public.mpesa_till_payments
    SET status = CASE WHEN p_action = 'sale' THEN 'matched_sale' ELSE 'ignored' END,
        handled_by = v_by, handled_at = NOW(), note = NULLIF(trim(p_note), '')
    WHERE id = v_row.id;
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."handle_till_payment"("p_till_payment_id" "uuid", "p_action" "text", "p_customer_id" "uuid", "p_note" "text", "p_handled_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_permission"("p_business_id" "uuid", VARIADIC "p_permissions" "text"[]) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_role TEXT;
    v_code TEXT;
    v_granted BOOLEAN;
BEGIN
    IF COALESCE(current_setting('role', TRUE), 'none') NOT IN ('anon', 'authenticated') THEN
        RETURN TRUE;
    END IF;

    SELECT bm.role::TEXT INTO v_role
    FROM public.business_memberships bm
    JOIN public.users u ON u.id = bm.user_id
    WHERE u.auth_user_id = auth.uid()
      AND bm.business_id = p_business_id
      AND bm.status = 'Active';

    IF v_role IS NULL THEN
        RETURN FALSE;
    END IF;
    IF v_role IN ('Owner', 'Admin', 'Administrator') THEN
        RETURN TRUE;
    END IF;

    FOREACH v_code IN ARRAY p_permissions LOOP
        SELECT rp.granted INTO v_granted
        FROM public.role_permissions rp
        WHERE rp.business_id = p_business_id AND rp.role::TEXT = v_role AND rp.permission = v_code;

        IF COALESCE(v_granted, v_code = ANY(
            COALESCE((SELECT d.permissions FROM public.role_default_permissions d WHERE d.role = v_role), '{}')
        )) THEN
            RETURN TRUE;
        END IF;
    END LOOP;

    RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."has_permission"("p_business_id" "uuid", VARIADIC "p_permissions" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invite_guess_key"() RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
    SELECT 'invite:ip:' || COALESCE(
        NULLIF(TRIM(split_part(COALESCE(
            current_setting('request.headers', TRUE)::json->>'cf-connecting-ip',
            current_setting('request.headers', TRUE)::json->>'x-forwarded-for',
            current_setting('request.headers', TRUE)::json->>'x-real-ip',
            ''), ',', 1)), ''),
        'unknown');
$$;


ALTER FUNCTION "public"."invite_guess_key"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invite_guesses_left"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT NOT EXISTS (
        SELECT 1 FROM public.rate_limits
        WHERE key = public.invite_guess_key()
          AND window_start > NOW() - INTERVAL '15 minutes'
          AND count >= 10
    );
$$;


ALTER FUNCTION "public"."invite_guesses_left"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invite_supplier_user"("p_supplier_id" "uuid", "p_name" "text", "p_email" "text", "p_phone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_s     public.suppliers%ROWTYPE;
    v_email TEXT := lower(btrim(COALESCE(p_email, '')));
    v_code  TEXT := '';
    v_chars TEXT := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
    v_id    UUID;
    i       INTEGER;
BEGIN
    SELECT * INTO v_s FROM public.suppliers WHERE id = p_supplier_id AND deleted_at IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'That supplier was not found.'; END IF;
    PERFORM public.assert_business_member(v_s.business_id);
    PERFORM public.assert_permission(v_s.business_id, 'suppliers.portal');
    IF v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
        RAISE EXCEPTION 'Enter the email address they will sign in with.';
    END IF;
    IF EXISTS (
        SELECT 1 FROM public.business_memberships m JOIN public.users u ON u.id = m.user_id
        WHERE m.business_id = v_s.business_id AND m.status = 'Active' AND lower(u.email) = v_email
    ) THEN
        RAISE EXCEPTION 'That email belongs to someone on your team. Use the supplier''s own email.';
    END IF;
    IF EXISTS (
        SELECT 1 FROM public.supplier_accounts a JOIN public.users u ON u.id = a.user_id
        WHERE a.supplier_id = p_supplier_id AND a.status = 'active' AND lower(u.email) = v_email
    ) THEN
        RAISE EXCEPTION 'They already have app access for this supplier.';
    END IF;
    DELETE FROM public.invitations
    WHERE business_id = v_s.business_id AND supplier_id = p_supplier_id AND lower(email) = v_email;
    FOR i IN 1..6 LOOP
        v_code := v_code || substr(v_chars, 1 + floor(random() * length(v_chars))::INTEGER, 1);
    END LOOP;
    INSERT INTO public.invitations (business_id, invited_by, name, email, phone, role, invitation_token, expires_at, status, supplier_id)
    VALUES (v_s.business_id, public.fn_my_user_id(), left(COALESCE(NULLIF(btrim(p_name), ''), v_s.name), 120), v_email,
            NULLIF(btrim(COALESCE(p_phone, '')), ''), 'Supplier', v_code, NOW() + INTERVAL '7 days', 'Pending', p_supplier_id)
    RETURNING id INTO v_id;
    RETURN jsonb_build_object('id', v_id, 'code', v_code, 'supplierName', COALESCE(NULLIF(v_s.company, ''), v_s.name));
END;
$_$;


ALTER FUNCTION "public"."invite_supplier_user"("p_supplier_id" "uuid", "p_name" "text", "p_email" "text", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invoice_ageing"("p_business_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_today DATE := public.sd_today();
    v_rows  JSONB;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'invoices.view', 'invoices.manage');
    WITH open_inv AS (
        SELECT COALESCE(i.customer_id::TEXT, 'name:' || lower(i.customer_name)) AS k, i.customer_id, i.customer_name,
               i.balance, v_today - i.due_date AS late
        FROM public.sales_invoices i
        WHERE i.business_id = p_business_id AND i.status IN ('unpaid', 'part_paid') AND i.balance > 0
    )
    SELECT COALESCE(jsonb_agg(r ORDER BY (r->>'total')::NUMERIC DESC), '[]'::JSONB) INTO v_rows
    FROM (
        SELECT jsonb_build_object(
            'customerId', MAX(customer_id::TEXT), 'name', MAX(customer_name), 'invoices', COUNT(*),
            'notDue', SUM(balance) FILTER (WHERE late <= 0),
            'd1_30', SUM(balance) FILTER (WHERE late BETWEEN 1 AND 30),
            'd31_60', SUM(balance) FILTER (WHERE late BETWEEN 31 AND 60),
            'd61_90', SUM(balance) FILTER (WHERE late BETWEEN 61 AND 90),
            'd90', SUM(balance) FILTER (WHERE late > 90),
            'total', SUM(balance), 'oldest', MAX(late)) AS r
        FROM open_inv GROUP BY k
    ) x;
    RETURN v_rows;
END;
$$;


ALTER FUNCTION "public"."invoice_ageing"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invoice_sales_order"("p_order_id" "uuid", "p_lines" "jsonb", "p_issue_date" "date" DEFAULT NULL::"date", "p_terms_days" integer DEFAULT NULL::integer, "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_o     public.sales_orders%ROWTYPE;
    v_l     public.sales_order_lines%ROWTYPE;
    v_c     public.customers%ROWTYPE;
    v_id    UUID;
    v_qty   NUMERIC;
    v_net   NUMERIC;
    v_vat   NUMERIC;
    v_fee   NUMERIC := 0;
    v_count INTEGER := 0;
    v_issue DATE := COALESCE(p_issue_date, public.sd_today());
    v_terms INTEGER;
BEGIN
    SELECT * INTO v_o FROM public.sales_orders WHERE id = p_order_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'That order was not found.';
    END IF;
    PERFORM public.assert_business_member(v_o.business_id);
    PERFORM public.assert_permission(v_o.business_id, 'invoices.manage');
    IF v_o.status = 'cancelled' THEN
        RAISE EXCEPTION 'This order was cancelled.';
    END IF;
    IF v_o.customer_id IS NOT NULL THEN
        SELECT * INTO v_c FROM public.customers WHERE id = v_o.customer_id;
    END IF;
    v_terms := COALESCE(p_terms_days, public.sd_terms_days(v_c.payment_terms), 0);
    IF v_terms < 0 OR v_terms > 365 THEN
        RAISE EXCEPTION 'Payment terms are 0 to 365 days.';
    END IF;
    IF v_o.delivery_fee > 0 AND NOT EXISTS (
        SELECT 1 FROM public.sales_invoices WHERE order_id = p_order_id AND status <> 'void' AND delivery_fee > 0
    ) THEN
        v_fee := v_o.delivery_fee;
    END IF;

    INSERT INTO public.sales_invoices (business_id, number, order_id, customer_id, customer_name, customer_phone,
                                       issue_date, terms_days, due_date, notes, delivery_fee, created_by)
    VALUES (v_o.business_id, public.sd_next_no(v_o.business_id, 'INV', v_issue), v_o.id, v_o.customer_id, v_o.customer_name,
            v_o.customer_phone, v_issue, v_terms, v_issue + v_terms, left(NULLIF(trim(p_notes), ''), 1000), v_fee, public.acc_who())
    RETURNING id INTO v_id;

    FOR v_l IN SELECT * FROM public.sales_order_lines WHERE order_id = p_order_id ORDER BY position FOR UPDATE LOOP
        IF p_lines IS NULL THEN
            v_qty := GREATEST(v_l.quantity - v_l.qty_invoiced, 0);
        ELSE
            SELECT round(COALESCE(SUM(NULLIF(x->>'quantity', '')::NUMERIC), 0), 3) INTO v_qty
            FROM jsonb_array_elements(p_lines) x WHERE x->>'lineId' = v_l.id::TEXT;
        END IF;
        CONTINUE WHEN v_qty <= 0;
        IF v_l.qty_invoiced + v_qty > v_l.quantity THEN
            RAISE EXCEPTION 'Only % % of % is left to invoice.', v_l.quantity - v_l.qty_invoiced, COALESCE(v_l.unit, ''), v_l.name;
        END IF;
        -- The last part takes what is left, so the parts add up to the order to the cent.
        IF v_l.qty_invoiced + v_qty = v_l.quantity THEN
            SELECT v_l.line_net - COALESCE(SUM(il.line_net), 0), v_l.line_vat - COALESCE(SUM(il.line_vat), 0)
            INTO v_net, v_vat
            FROM public.sales_invoice_lines il JOIN public.sales_invoices i ON i.id = il.invoice_id
            WHERE il.order_line_id = v_l.id AND i.status <> 'void';
        ELSE
            v_net := round(v_l.line_net * v_qty / v_l.quantity, 2);
            v_vat := round(v_l.line_vat * v_qty / v_l.quantity, 2);
        END IF;
        INSERT INTO public.sales_invoice_lines (invoice_id, business_id, order_line_id, position, product_id, name, unit,
            quantity, unit_price, discount_pct, vat_rate, line_net, line_vat, line_total)
        VALUES (v_id, v_o.business_id, v_l.id, v_l.position, v_l.product_id, v_l.name, v_l.unit, v_qty, v_l.unit_price,
            v_l.discount_pct, v_l.vat_rate, v_net, v_vat, v_net + v_vat);
        UPDATE public.sales_order_lines SET qty_invoiced = qty_invoiced + v_qty WHERE id = v_l.id;
        v_count := v_count + 1;
    END LOOP;

    IF v_count = 0 THEN
        RAISE EXCEPTION 'Everything on this order is already invoiced.';
    END IF;
    UPDATE public.sales_invoices i
    SET subtotal = s.net, vat_total = s.vat, total = s.net + s.vat + i.delivery_fee
    FROM (SELECT COALESCE(SUM(line_net), 0) AS net, COALESCE(SUM(line_vat), 0) AS vat FROM public.sales_invoice_lines WHERE invoice_id = v_id) s
    WHERE i.id = v_id;
    PERFORM public.sd_invoice_refresh(v_id);
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."invoice_sales_order"("p_order_id" "uuid", "p_lines" "jsonb", "p_issue_date" "date", "p_terms_days" integer, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_my_employee"("p_employee_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.employees e
        JOIN public.users u ON u.id = e.user_id
        WHERE e.id = p_employee_id AND u.auth_user_id = auth.uid()
    );
$$;


ALTER FUNCTION "public"."is_my_employee"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_owner_or_admin"("p_business_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_exists BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM public.business_memberships bm
        JOIN public.users u ON bm.user_id = u.id
        WHERE u.auth_user_id = auth.uid()
          AND bm.business_id = p_business_id
          AND bm.role IN ('Owner', 'Admin', 'Administrator')
          AND bm.status = 'Active'
    ) INTO v_exists;

    RETURN COALESCE(v_exists, FALSE);
END;
$$;


ALTER FUNCTION "public"."is_owner_or_admin"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_invoice"("p_business_id" "uuid", "p_customer_id" "uuid", "p_prefix" "text", "p_issued_at" "date", "p_due_at" "date", "p_balance_due" numeric, "p_document" "jsonb", "p_created_by" "text") RETURNS TABLE("id" "uuid", "number" integer, "invoice_no" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
    v_number INTEGER;
    v_prefix TEXT := upper(regexp_replace(COALESCE(p_prefix, ''), '[^A-Za-z0-9]', '', 'g'));
    v_no     TEXT;
    v_id     UUID;
BEGIN
    PERFORM public.assert_permission(p_business_id, 'customers.debts');

    IF p_customer_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.customers c WHERE c.id = p_customer_id AND c.business_id = p_business_id
    ) THEN
        RAISE EXCEPTION 'That customer is not in this business.' USING ERRCODE = '42501';
    END IF;
    IF p_document IS NULL OR jsonb_typeof(p_document) <> 'object' THEN
        RAISE EXCEPTION 'The invoice is empty.';
    END IF;

    INSERT INTO public.invoice_counters AS c (business_id, last_number)
    VALUES (p_business_id, 1)
    ON CONFLICT (business_id) DO UPDATE SET last_number = c.last_number + 1, updated_at = NOW()
    RETURNING c.last_number INTO v_number;

    v_no := CASE WHEN v_prefix = '' THEN '' ELSE v_prefix || '-' END || lpad(v_number::TEXT, 4, '0');

    INSERT INTO public.invoices (business_id, customer_id, number, invoice_no, issued_at, due_at, balance_due, document, created_by)
    VALUES (p_business_id, p_customer_id, v_number, v_no, COALESCE(p_issued_at, CURRENT_DATE), p_due_at,
            COALESCE(p_balance_due, 0), p_document, left(p_created_by, 120))
    RETURNING invoices.id INTO v_id;

    RETURN QUERY SELECT v_id, v_number, v_no;
END;
$$;


ALTER FUNCTION "public"."issue_invoice"("p_business_id" "uuid", "p_customer_id" "uuid", "p_prefix" "text", "p_issued_at" "date", "p_due_at" "date", "p_balance_due" numeric, "p_document" "jsonb", "p_created_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kra_next_invoice_no"("p_business_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_next INTEGER;
BEGIN
    UPDATE public.kra_etims_settings
       SET last_invoice_no = last_invoice_no + 1, updated_at = NOW()
     WHERE business_id = p_business_id
    RETURNING last_invoice_no INTO v_next;
    IF v_next IS NULL THEN
        RAISE EXCEPTION 'KRA eTIMS is not set up for this business.';
    END IF;
    RETURN v_next;
END;
$$;


ALTER FUNCTION "public"."kra_next_invoice_no"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_till_points"("p_redemption_id" "uuid", "p_transaction_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_row public.loyalty_redemptions%ROWTYPE;
BEGIN
    SELECT * INTO v_row FROM public.loyalty_redemptions
    WHERE id = p_redemption_id AND refunded_at IS NULL AND order_id IS NULL AND transaction_id IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    PERFORM public.assert_permission(v_row.business_id, 'customers.loyalty');

    UPDATE public.loyalty_redemptions r
    SET transaction_id = t.id
    FROM public.transactions t
    WHERE r.id = p_redemption_id
      AND t.id = p_transaction_id
      AND t.business_id = v_row.business_id
      AND t.customer_id = v_row.customer_id;
END;
$$;


ALTER FUNCTION "public"."link_till_points"("p_redemption_id" "uuid", "p_transaction_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_petty_cash"("p_business_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("id" "uuid", "date" timestamp with time zone, "category" "text", "description" "text", "amount" numeric, "staff_name" "text", "receipt_ref" "text", "mine" boolean, "removed" boolean, "removed_by" "text", "removed_reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_me  public.employees;
    v_all BOOLEAN;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'pettycash.record', 'expenses.view', 'finance.view');
    v_me := public.fn_my_employee(p_business_id);
    v_all := public.has_permission(p_business_id, 'expenses.view', 'finance.view');

    RETURN QUERY
    SELECT e.id, e.date, e.category, e.description, e.amount, e.staff_name, e.receipt_ref,
           (v_me.id IS NOT NULL AND e.employee_id = v_me.id),
           e.deleted_at IS NOT NULL, e.removed_by, e.removed_reason
    FROM public.expenses e
    WHERE e.business_id = p_business_id
      AND e.source = 'petty_cash'
      AND e.date >= p_start AND e.date <= p_end
      AND (v_all OR (v_me.id IS NOT NULL AND e.employee_id = v_me.id))
    ORDER BY e.date DESC
    LIMIT 500;
END;
$$;


ALTER FUNCTION "public"."list_petty_cash"("p_business_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_stock_transfers"("p_business_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_out JSONB;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'inventory.transfer_stock', 'inventory.receive_stock', 'inventory.stock_history', 'inventory.request_transfer');

    SELECT COALESCE(jsonb_agg(row_data ORDER BY sort_key DESC), '[]'::JSONB) INTO v_out
    FROM (
        SELECT COALESCE(t.requested_at, t.created_at) AS sort_key,
               jsonb_build_object(
                   'id', t.id,
                   'reference', t.reference,
                   'direction', CASE WHEN t.from_business_id = p_business_id THEN 'out' ELSE 'in' END,
                   'fromBusinessId', t.from_business_id,
                   'fromName', bf.name,
                   'toBusinessId', t.to_business_id,
                   'toName', bt.name,
                   'status', t.status,
                   'note', t.note,
                   'sentBy', t.sent_by_name,
                   'sentAt', t.sent_at,
                   'createdAt', t.created_at,
                   'receivedBy', t.received_by_name,
                   'receivedAt', t.received_at,
                   'receiveNote', t.receive_note,
                   'cancelledBy', t.cancelled_by_name,
                   'cancelledAt', t.cancelled_at,
                   'cancelReason', t.cancel_reason,
                   'requestedBy', t.requested_by_name,
                   'requestedAt', t.requested_at,
                   'requestNote', t.request_note,
                   'declinedBy', t.declined_by_name,
                   'declinedAt', t.declined_at,
                   'declineReason', t.decline_reason,
                   'approvedBy', t.approved_by_name,
                   'approvedAt', t.approved_at,
                   'purchaseId', t.purchase_id,
                   'costValue', (SELECT ROUND(SUM(i.quantity_sent * i.unit_cost), 2) FROM public.stock_transfer_items i WHERE i.transfer_id = t.id),
                   'items', COALESCE((
                       SELECT jsonb_agg(jsonb_build_object(
                           'id', i.id,
                           'fromProductId', i.from_product_id,
                           'toProductId', i.to_product_id,
                           'productName', i.product_name,
                           'sku', i.sku,
                           'unit', i.unit,
                           'unitCost', i.unit_cost,
                           'quantityRequested', i.quantity_requested,
                           'quantitySent', i.quantity_sent,
                           'quantityReceived', i.quantity_received,
                           'quantityLate', i.quantity_late,
                           'quantityFound', i.quantity_found,
                           'quantityWrittenOff', i.quantity_written_off,
                           'stillShort', CASE WHEN t.status = 'received'
                               THEN GREATEST(i.quantity_sent - COALESCE(i.quantity_received, 0) - i.quantity_late - i.quantity_found - i.quantity_written_off, 0)
                               ELSE 0 END
                       ) ORDER BY i.product_name)
                       FROM public.stock_transfer_items i WHERE i.transfer_id = t.id
                   ), '[]'::JSONB)
               ) AS row_data
        FROM public.stock_transfers t
        JOIN public.businesses bf ON bf.id = t.from_business_id
        JOIN public.businesses bt ON bt.id = t.to_business_id
        WHERE (t.from_business_id = p_business_id OR t.to_business_id = p_business_id)
          -- A draft is the sender's own business until it is sent.
          AND NOT (t.status = 'draft' AND t.to_business_id = p_business_id)
        ORDER BY COALESCE(t.requested_at, t.created_at) DESC
        LIMIT LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500)
    ) q;

    RETURN v_out;
END;
$$;


ALTER FUNCTION "public"."list_stock_transfers"("p_business_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_transfer_branches"("p_business_id" "uuid") RETURNS TABLE("id" "uuid", "name" "text", "address" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'inventory.transfer_stock', 'inventory.receive_stock', 'inventory.request_transfer', 'purchases.create');
    RETURN QUERY
    SELECT b.id, b.name, b.address
    FROM public.businesses b
    WHERE b.id <> p_business_id AND b.deleted_at IS NULL AND public.fn_branches_share_owner(p_business_id, b.id)
    ORDER BY b.name;
END;
$$;


ALTER FUNCTION "public"."list_transfer_branches"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_mpesa_payment"("p_checkout_request_id" "text", "p_merchant_request_id" "text", "p_phone" "text", "p_amount" numeric, "p_status" "text", "p_receipt_number" "text", "p_business_id" "uuid" DEFAULT NULL::"uuid", "p_raw_callback" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    INSERT INTO public.mpesa_transactions
        (checkout_request_id, merchant_request_id, phone, amount, status,
         receipt_number, business_id, raw_callback, mpesa_receipt_timestamp)
    VALUES (
        p_checkout_request_id,
        p_merchant_request_id,
        p_phone,
        p_amount,
        p_status::public.mpesa_status,
        p_receipt_number,
        p_business_id,
        p_raw_callback,
        CASE WHEN p_status = 'Completed' THEN NOW() ELSE NULL END
    )
    ON CONFLICT (checkout_request_id) DO UPDATE SET
        status                  = EXCLUDED.status,
        receipt_number          = EXCLUDED.receipt_number,
        mpesa_receipt_timestamp = CASE WHEN EXCLUDED.status = 'Completed' THEN NOW() ELSE NULL END,
        raw_callback            = EXCLUDED.raw_callback,
        updated_at              = NOW();

    -- Notify the owner of the M-Pesa payment result
    IF p_business_id IS NOT NULL THEN
        INSERT INTO public.notifications
            (business_id, role, title, message, type, priority,
             action_type, action_target, payload, status)
        VALUES (
            p_business_id,
            'Owner',
            CASE
                WHEN p_status = 'Completed' THEN '✅ M-Pesa Payment Received'
                ELSE '❌ M-Pesa Payment Failed'
            END,
            CASE
                WHEN p_status = 'Completed'
                    THEN 'KES ' || p_amount || ' received from ' || p_phone ||
                         COALESCE(' (Receipt: ' || p_receipt_number || ')', '')
                ELSE 'Payment of KES ' || p_amount || ' from ' || p_phone ||
                     ' failed. Ref: ' || p_checkout_request_id
            END,
            'Payment Received',
            'high',
            'navigate',
            'sales',
            jsonb_build_object(
                'amount',        p_amount,
                'phone',         p_phone,
                'receiptNumber', p_receipt_number,
                'status',        p_status
            ),
            'delivered'
        );
    END IF;
END;
$$;


ALTER FUNCTION "public"."log_mpesa_payment"("p_checkout_request_id" "text", "p_merchant_request_id" "text", "p_phone" "text", "p_amount" numeric, "p_status" "text", "p_receipt_number" "text", "p_business_id" "uuid", "p_raw_callback" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_sizes"("p_business_id" "uuid") RETURNS TABLE("log" "text", "row_count" bigint, "oldest" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF public.is_owner_or_admin(p_business_id) IS NOT TRUE THEN
        RAISE EXCEPTION 'Only an owner or admin can see this.' USING ERRCODE = '42501';
    END IF;

    RETURN QUERY
    SELECT 'sales', COUNT(*), MIN(timestamp) FROM public.transactions WHERE business_id = p_business_id
    UNION ALL
    SELECT 'stock', COUNT(*), MIN(timestamp) FROM public.inventory_adjustments WHERE business_id = p_business_id
    UNION ALL
    SELECT 'points_used', COUNT(*), MIN(created_at) FROM public.loyalty_redemptions WHERE business_id = p_business_id
    UNION ALL
    SELECT 'points_earned', COUNT(*), MIN(created_at) FROM public.loyalty_points_earned WHERE business_id = p_business_id
    UNION ALL
    SELECT 'audit', COUNT(*), MIN(timestamp) FROM public.audit_logs WHERE business_id = p_business_id
    UNION ALL
    SELECT 'backups', COUNT(*), MIN(timestamp) FROM public.backup_history_logs WHERE business_id = p_business_id
    UNION ALL
    SELECT 'crashes', COUNT(*), MIN(last_seen_at) FROM public.crash_reports WHERE business_id = p_business_id;
END;
$$;


ALTER FUNCTION "public"."log_sizes"("p_business_id" "uuid") OWNER TO "postgres";


