CREATE OR REPLACE FUNCTION "public"."merge_customers"("p_keep_id" "uuid", "p_merge_id" "uuid", "p_name" "text", "p_phone" "text", "p_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_keep  public.customers%ROWTYPE;
    v_merge public.customers%ROWTYPE;
    v_name  TEXT := left(trim(COALESCE(p_name, '')), 100);
    v_phone TEXT := trim(COALESCE(p_phone, ''));
    v_by    TEXT;
    v_fk    RECORD;
    v_count BIGINT;
    v_moved JSONB := '{}'::jsonb;
    v_debt  NUMERIC(14,2);
    v_wallet NUMERIC(14,2);
    v_offset NUMERIC(14,2);
    v_merge_id UUID := uuid_generate_v4();
    v_open RECORD;
    v_applied NUMERIC(14,2);
    v_left NUMERIC(14,2);
BEGIN
    IF p_keep_id IS NULL OR p_merge_id IS NULL OR p_keep_id = p_merge_id THEN
        RAISE EXCEPTION 'Please choose two different customers.';
    END IF;

    -- A fixed lock order, so two people merging the same pair can't deadlock.
    PERFORM 1 FROM public.customers WHERE id IN (p_keep_id, p_merge_id) ORDER BY id FOR UPDATE;

    SELECT * INTO v_keep FROM public.customers WHERE id = p_keep_id AND deleted_at IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'The customer to keep was not found.';
    END IF;
    SELECT * INTO v_merge FROM public.customers WHERE id = p_merge_id AND deleted_at IS NULL;
    IF NOT FOUND OR v_merge.business_id <> v_keep.business_id THEN
        RAISE EXCEPTION 'The customer to merge was not found.';
    END IF;

    PERFORM public.assert_permission(v_keep.business_id, 'customers.manage');

    IF v_name = '' THEN
        RAISE EXCEPTION 'Please choose a name.';
    END IF;
    IF v_phone = '' THEN
        RAISE EXCEPTION 'Please choose a phone number.';
    END IF;

    v_by := COALESCE((SELECT name FROM public.users WHERE auth_user_id = auth.uid()), 'system');

    -- Every table pointing at customers moves across, including any added later.
    FOR v_fk IN
        SELECT c.conrelid AS tbl, c.conrelid::regclass::text AS tbl_name, a.attname AS col
        FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = c.conkey[1]
        WHERE c.contype = 'f'
          AND c.confrelid = 'public.customers'::regclass
          AND c.conrelid <> 'public.customers'::regclass
    LOOP
        EXECUTE format('UPDATE %s SET %I = $1 WHERE %I = $2', v_fk.tbl_name, v_fk.col, v_fk.col)
            USING p_keep_id, p_merge_id;
        GET DIAGNOSTICS v_count = ROW_COUNT;
        IF v_count > 0 THEN
            v_moved := v_moved || jsonb_build_object(v_fk.tbl_name, v_count);
        END IF;

        -- Reports read the name saved on each row.
        IF EXISTS (SELECT 1 FROM pg_attribute
                   WHERE attrelid = v_fk.tbl AND attname = 'customer_name' AND NOT attisdropped) THEN
            EXECUTE format('UPDATE %s SET customer_name = $1 WHERE %I = $2 AND customer_name IS DISTINCT FROM $1',
                           v_fk.tbl_name, v_fk.col)
                USING v_name, p_keep_id;
        END IF;
    END LOOP;

    -- Tracked report items hold the id as text.
    UPDATE public.report_tracked_items t
    SET item_key = p_keep_id::TEXT, label = v_name
    WHERE t.item_type = 'customer' AND t.item_key = p_merge_id::TEXT
      AND NOT EXISTS (SELECT 1 FROM public.report_tracked_items o
                      WHERE o.business_id = t.business_id AND o.item_type = 'customer'
                        AND o.item_key = p_keep_id::TEXT);
    DELETE FROM public.report_tracked_items
    WHERE item_type = 'customer' AND item_key = p_merge_id::TEXT AND business_id = v_keep.business_id;

    -- Wallet money clears debt first, because a customer can't hold debt and wallet together.
    v_debt   := v_keep.debt_balance + v_merge.debt_balance;
    v_wallet := v_keep.wallet_balance + v_merge.wallet_balance;
    v_offset := LEAST(v_debt, v_wallet);
    v_debt   := v_debt - v_offset;
    v_wallet := v_wallet - v_offset;

    UPDATE public.customers
    SET merged_into_id = p_keep_id,
        deleted_at = NOW(),
        debt_balance = 0,
        wallet_balance = 0,
        loyalty_points = 0,
        purchases_count = 0,
        last_modified_by = v_by
    WHERE id = p_merge_id;

    -- Records merged into this one earlier now point at the record that survives.
    UPDATE public.customers SET merged_into_id = p_keep_id WHERE merged_into_id = p_merge_id;

    UPDATE public.customers
    SET name = v_name,
        phone = v_phone,
        email = NULLIF(trim(COALESCE(p_email, '')), ''),
        debt_balance = v_debt,
        wallet_balance = v_wallet,
        loyalty_points = v_keep.loyalty_points + v_merge.loyalty_points,
        tier = GREATEST(v_keep.tier, v_merge.tier),
        purchases_count = v_keep.purchases_count + v_merge.purchases_count,
        join_date = LEAST(v_keep.join_date, v_merge.join_date),
        -- An opt-out on either record stands, and so does agreeing to offers.
        notify_service = v_keep.notify_service AND v_merge.notify_service,
        notify_promotions = v_keep.notify_promotions OR v_merge.notify_promotions,
        last_modified_by = v_by
    WHERE id = p_keep_id;

    -- The wallet money used on debt also settles the oldest open debts, so they match the balance.
    v_left := v_offset;
    FOR v_open IN
        SELECT id, balance FROM public.credit_payments
        WHERE customer_id = p_keep_id AND status IN ('Open', 'Partial')
        ORDER BY created_at
    LOOP
        EXIT WHEN v_left <= 0;
        v_applied := LEAST(v_left, v_open.balance);
        v_left := v_left - v_applied;
        UPDATE public.credit_payments
        SET amount_paid = amount_paid + v_applied,
            status = CASE WHEN amount_paid + v_applied >= amount_owed
                          THEN 'Settled'::public.credit_status ELSE 'Partial'::public.credit_status END,
            settled_at = CASE WHEN amount_paid + v_applied >= amount_owed THEN NOW() END
        WHERE id = v_open.id;
    END LOOP;

    IF v_merge.debt_balance > 0 THEN
        INSERT INTO public.customer_ledger
            (business_id, customer_id, type, amount, wallet_balance, debt_balance, recorded_by, note, reference_id)
        VALUES (v_keep.business_id, p_keep_id, 'debt_adjustment', v_merge.debt_balance, v_wallet, v_debt, v_by,
                'Debt moved from merged record: ' || v_merge.name, 'merge-debt-' || v_merge_id);
    END IF;
    IF v_merge.wallet_balance > 0 THEN
        INSERT INTO public.customer_ledger
            (business_id, customer_id, type, amount, wallet_balance, debt_balance, recorded_by, note, reference_id)
        VALUES (v_keep.business_id, p_keep_id, 'wallet_topup', v_merge.wallet_balance, v_wallet, v_debt, v_by,
                'Wallet moved from merged record: ' || v_merge.name, 'merge-wallet-' || v_merge_id);
    END IF;

    INSERT INTO public.customer_merges
        (id, business_id, kept_customer_id, merged_customer_id, kept_before, merged_before, moved_rows, merged_by)
    VALUES (v_merge_id, v_keep.business_id, p_keep_id, p_merge_id, to_jsonb(v_keep), to_jsonb(v_merge), v_moved, v_by);

    RETURN jsonb_build_object(
        'keepId', p_keep_id,
        'debt', v_debt,
        'wallet', v_wallet,
        'points', v_keep.loyalty_points + v_merge.loyalty_points,
        'movedRows', v_moved
    );
END;
$_$;


ALTER FUNCTION "public"."merge_customers"("p_keep_id" "uuid", "p_merge_id" "uuid", "p_name" "text", "p_phone" "text", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."otp_after_password_reset"("p_auth_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    UPDATE public.invitations
    SET claimed_by = NULL, claimed_at = NULL, claimed_name = NULL, claimed_phone = NULL
    WHERE claimed_by = p_auth_user_id;

    UPDATE public.users u SET verified_email = au.email
    FROM auth.users au
    WHERE au.id = p_auth_user_id AND u.auth_user_id = au.id;

    UPDATE auth.users SET email_confirmed_at = COALESCE(email_confirmed_at, NOW())
    WHERE id = p_auth_user_id;

    BEGIN
        DELETE FROM auth.sessions WHERE user_id = p_auth_user_id;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING '[otp_after_password_reset] could not end sessions: %', SQLERRM;
    END;
END;
$$;


ALTER FUNCTION "public"."otp_after_password_reset"("p_auth_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."otp_check"("p_email" "text", "p_type" "text", "p_code" "text", "p_consume" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_email TEXT := LOWER(TRIM(p_email));
    v_otp   public.otps%ROWTYPE;
BEGIN
    SELECT * INTO v_otp
    FROM public.otps
    WHERE email = v_email AND type = p_type
    FOR UPDATE;

    IF NOT FOUND OR v_otp.expires_at <= NOW() OR v_otp.attempts >= 5 THEN
        RETURN FALSE;
    END IF;

    IF TRIM(v_otp.code) <> TRIM(p_code) THEN
        UPDATE public.otps SET attempts = attempts + 1 WHERE id = v_otp.id;
        RETURN FALSE;
    END IF;

    IF p_consume THEN
        DELETE FROM public.otps WHERE id = v_otp.id;
    END IF;

    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."otp_check"("p_email" "text", "p_type" "text", "p_code" "text", "p_consume" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."otp_confirm_signup"("p_email" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_email TEXT := LOWER(TRIM(p_email));
    v_auth  RECORD;
    v_inv   RECORD;
BEGIN
    FOR v_auth IN SELECT id, email FROM auth.users WHERE LOWER(TRIM(email)) = v_email LOOP
        UPDATE auth.users
        SET email_confirmed_at = COALESCE(email_confirmed_at, NOW()),
            raw_app_meta_data  = COALESCE(raw_app_meta_data, '{}') ||
                                 jsonb_build_object('provider', 'email', 'providers', ARRAY['email'])
        WHERE id = v_auth.id;

        UPDATE public.users SET verified_email = v_auth.email WHERE auth_user_id = v_auth.id;

        FOR v_inv IN
            SELECT id, claimed_name, claimed_phone FROM public.invitations
            WHERE claimed_by = v_auth.id
              AND status = 'Pending'
              AND claimed_at > NOW() - INTERVAL '7 days'
        LOOP
            -- One bad invitation must not stop the email being verified.
            BEGIN
                PERFORM public.finish_invitation(v_inv.id, v_auth.id, v_inv.claimed_name, v_inv.claimed_phone);
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING '[otp_confirm_signup] invitation % not finished: %', v_inv.id, SQLERRM;
            END;
        END LOOP;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."otp_confirm_signup"("p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."otp_issue"("p_email" "text", "p_type" "text", "p_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_email TEXT := LOWER(TRIM(p_email));
BEGIN
    IF EXISTS (
        SELECT 1 FROM public.otps
        WHERE email = v_email AND type = p_type AND created_at > NOW() - INTERVAL '45 seconds'
    ) THEN
        RETURN FALSE;
    END IF;

    INSERT INTO public.otps (email, code, type, expires_at, attempts)
    VALUES (v_email, p_code, p_type, NOW() + INTERVAL '15 minutes', 0)
    ON CONFLICT (email, type) DO UPDATE SET
        code       = EXCLUDED.code,
        expires_at = EXCLUDED.expires_at,
        attempts   = 0,
        created_at = NOW();

    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."otp_issue"("p_email" "text", "p_type" "text", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."otp_lookup_user"("p_email" "text") RETURNS TABLE("auth_user_id" "uuid", "user_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT au.id,
           COALESCE(u.name, au.raw_user_meta_data->>'name', au.raw_user_meta_data->>'full_name', 'User')
    FROM auth.users au
    LEFT JOIN public.users u ON u.auth_user_id = au.id
    WHERE LOWER(TRIM(au.email)) = LOWER(TRIM(p_email))
    LIMIT 1;
$$;


ALTER FUNCTION "public"."otp_lookup_user"("p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_online_order"("p_items" "jsonb", "p_fulfilment" "text", "p_address" "text", "p_notes" "text", "p_zone_id" "uuid" DEFAULT NULL::"uuid", "p_points" integer DEFAULT 0, "p_promo_code" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_order_id UUID;
    v_order    public.online_orders%ROWTYPE;
    v_promo    public.website_promo_codes%ROWTYPE;
    v_saving   NUMERIC(14,2);
    v_raw      NUMERIC(14,2);
    v_total    NUMERIC(14,2);
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Please sign in first.';
    END IF;
    IF (
        SELECT count(*) FROM public.online_orders
        WHERE account_id = auth.uid() AND status IN ('pending_payment', 'payment_failed')
    ) >= 5 THEN
        RAISE EXCEPTION 'You have several unpaid orders. Please pay or cancel one first.';
    END IF;

    v_order_id := public.fn_build_online_order(auth.uid(), p_items, p_fulfilment, p_address, p_notes, NULL, p_zone_id, p_points);

    IF NULLIF(trim(COALESCE(p_promo_code, '')), '') IS NOT NULL THEN
        SELECT * INTO v_order FROM public.online_orders WHERE id = v_order_id;
        -- Locked, so two orders can't both take the last use of a limited code.
        SELECT * INTO v_promo FROM public.website_promo_codes
        WHERE business_id = v_order.business_id AND code = upper(trim(p_promo_code))
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'We don''t recognise that promo code.';
        END IF;
        v_saving := public.fn_promo_value(v_promo, v_order.subtotal, auth.uid());

        v_raw := v_order.subtotal + v_order.delivery_fee - COALESCE(v_order.points_value, 0) - v_saving;
        v_total := floor(v_raw);
        IF v_total < 1 THEN
            RAISE EXCEPTION 'With that code and your points the total is under 1 shilling. Please use fewer points.';
        END IF;

        UPDATE public.online_orders
        SET promo_code_id = v_promo.id,
            promo_code = v_promo.code,
            promo_value = v_saving,
            total = v_total,
            discount = subtotal + delivery_fee - v_total
        WHERE id = v_order_id;
    END IF;

    RETURN v_order_id;
END;
$$;


ALTER FUNCTION "public"."place_online_order"("p_items" "jsonb", "p_fulfilment" "text", "p_address" "text", "p_notes" "text", "p_zone_id" "uuid", "p_points" integer, "p_promo_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_purchase_order"("p_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_p      public.purchases%ROWTYPE;
    v_status TEXT;
BEGIN
    SELECT * INTO v_p FROM public.purchases WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That purchase was not found.'; END IF;
    PERFORM public.assert_business_member(v_p.business_id);
    PERFORM public.assert_permission(v_p.business_id, 'purchases.create', 'purchases.update');
    IF v_p.status NOT IN ('Pending', 'RFQ') THEN
        RAISE EXCEPTION 'Only a draft can be placed as an order.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.purchase_items WHERE purchase_id = p_id) THEN
        RAISE EXCEPTION 'Add at least one item first.';
    END IF;
    v_status := CASE WHEN public.fn_needs_approval(v_p.business_id, v_p.total_amount) THEN 'Awaiting approval' ELSE 'Ordered' END;
    PERFORM public.fn_buying_ctx();
    UPDATE public.purchases
    SET status = v_status,
        ordered_at = CASE WHEN v_status = 'Ordered' THEN NOW() END,
        approved_amount = CASE WHEN v_status = 'Ordered' THEN total_amount END,
        updated_at = NOW()
    WHERE id = p_id;
    UPDATE public.purchase_quotes SET status = 'lost' WHERE purchase_id = p_id AND status IN ('asked', 'priced');
    RETURN v_status;
END;
$$;


ALTER FUNCTION "public"."place_purchase_order"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_business_payment"("p_business_id" "uuid", "p_reference_code" "text", "p_amount" numeric, "p_method" "text", "p_sender_name" "text", "p_sender_phone" "text", "p_status" "text" DEFAULT 'Success'::"text", "p_date" timestamp with time zone DEFAULT "now"(), "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_customer_name" "text" DEFAULT NULL::"text", "p_payment_type" "text" DEFAULT 'walk-in'::"text", "p_description" "text" DEFAULT NULL::"text", "p_recorded_by" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_payment_id     UUID;
    v_amount         NUMERIC(14,2) := round(COALESCE(p_amount, 0), 2);
    v_status         TEXT := COALESCE(p_status, 'Success');
    v_customer_id    UUID := p_customer_id;
    v_merged_into    UUID;
    v_debt_before    NUMERIC(14,2) := 0;
    v_debt_after     NUMERIC(14,2) := 0;
    v_wallet_before  NUMERIC(14,2) := 0;
    v_wallet_after   NUMERIC(14,2) := 0;
    v_debt_applied   NUMERIC(14,2) := 0;
    v_wallet_applied NUMERIC(14,2) := 0;
    v_applied_to     TEXT := 'none';
    v_existing_id    UUID;
    v_by             TEXT := COALESCE(NULLIF(trim(p_recorded_by), ''), 'System');
    v_left           NUMERIC(14,2);
    v_take           NUMERIC(14,2);
    v_rec            RECORD;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'payments.cash', 'payments.mpesa', 'payments.verify', 'payments.card', 'payments.airtel');

    -- Same business + reference: already recorded, so return it (safe to retry).
    IF p_reference_code IS NOT NULL THEN
        SELECT id INTO v_existing_id
        FROM public.payments
        WHERE business_id = p_business_id AND reference_code = p_reference_code
        LIMIT 1;
        IF v_existing_id IS NOT NULL THEN
            RETURN v_existing_id;
        END IF;
    END IF;

    IF v_amount <= 0 THEN
        RAISE EXCEPTION 'Amount must be greater than zero.';
    END IF;
    IF p_method IS NULL OR p_method NOT IN ('Cash', 'M-Pesa', 'Airtel Money', 'Card', 'Bank') THEN
        RAISE EXCEPTION 'Choose Cash, M-Pesa, Airtel Money, Card or Bank.';
    END IF;
    IF v_status NOT IN ('Success', 'Pending', 'Failed') THEN
        RAISE EXCEPTION 'A payment is Success, Pending or Failed.';
    END IF;

    IF v_customer_id IS NOT NULL THEN
        SELECT merged_into_id INTO v_merged_into
        FROM public.customers WHERE id = v_customer_id AND business_id = p_business_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'That customer was not found in this business.';
        END IF;
        v_customer_id := COALESCE(v_merged_into, v_customer_id);

        SELECT COALESCE(wallet_balance, 0), COALESCE(debt_balance, 0)
        INTO v_wallet_before, v_debt_before
        FROM public.customers
        WHERE id = v_customer_id AND business_id = p_business_id
        FOR UPDATE;
    END IF;

    -- Debt first, the rest to the wallet.
    IF v_status = 'Success' AND v_customer_id IS NOT NULL THEN
        v_debt_applied   := LEAST(v_debt_before, v_amount);
        v_wallet_applied := v_amount - v_debt_applied;
        v_debt_after     := v_debt_before - v_debt_applied;
        v_wallet_after   := v_wallet_before + v_wallet_applied;
        v_applied_to := CASE
            WHEN v_debt_applied > 0 AND v_wallet_applied > 0 THEN 'mixed'
            WHEN v_debt_applied > 0 THEN 'debt'
            WHEN v_wallet_applied > 0 THEN 'wallet'
            ELSE 'none' END;
    END IF;

    INSERT INTO public.payments (
        business_id, reference_code, amount, method,
        sender_name, sender_phone, status, date,
        customer_id, customer_name, payment_type, description,
        applied_to, debt_applied, wallet_applied, reference_id, recorded_by
    )
    VALUES (
        p_business_id, p_reference_code, v_amount, p_method,
        p_sender_name, p_sender_phone, v_status, COALESCE(p_date, NOW()),
        v_customer_id, COALESCE(p_customer_name, p_sender_name),
        CASE WHEN v_customer_id IS NULL THEN 'walk-in' ELSE COALESCE(p_payment_type, 'customer') END,
        p_description,
        v_applied_to, v_debt_applied, v_wallet_applied,
        p_reference_code, v_by
    )
    RETURNING id INTO v_payment_id;

    IF v_status <> 'Success' THEN
        RETURN v_payment_id;
    END IF;

    PERFORM public.fn_post_money_asset(
        p_business_id, p_method, v_amount,
        COALESCE(p_description, 'Payment: ' || p_reference_code), v_payment_id, NULL, v_by
    );
    UPDATE public.money_assets SET last_payment_at = COALESCE(p_date, NOW())
    WHERE business_id = p_business_id AND method = p_method;

    IF v_customer_id IS NULL OR (v_debt_applied = 0 AND v_wallet_applied = 0) THEN
        RETURN v_payment_id;
    END IF;

    UPDATE public.customers
    SET debt_balance = v_debt_after, wallet_balance = v_wallet_after
    WHERE id = v_customer_id;

    IF v_debt_applied > 0 THEN
        INSERT INTO public.customer_ledger (
            business_id, customer_id, type, amount, wallet_balance,
            debt_balance, recorded_by, note, reference_id
        )
        VALUES (
            p_business_id, v_customer_id, 'debt_payment', v_debt_applied,
            v_wallet_after, v_debt_after, v_by,
            COALESCE(p_description, 'Debt payment via ' || p_method),
            p_reference_code || '-debt-payment'
        )
        ON CONFLICT (business_id, reference_id) WHERE reference_id IS NOT NULL DO NOTHING;

        -- Points for money towards a debt come from this row's trigger.
        INSERT INTO public.debt_payments (
            business_id, customer_id, amount_paid, remaining_debt,
            payment_method, recorded_by, note
        )
        VALUES (
            p_business_id, v_customer_id, v_debt_applied, v_debt_after,
            p_method, v_by, COALESCE(p_description, 'Debt payment via ' || p_method)
        );

        -- Oldest credit first.
        v_left := v_debt_applied;
        FOR v_rec IN
            SELECT id, balance FROM public.credit_payments
            WHERE customer_id = v_customer_id AND business_id = p_business_id
              AND status IN ('Open', 'Partial')
            ORDER BY created_at ASC, id ASC
            FOR UPDATE
        LOOP
            EXIT WHEN v_left <= 0;
            v_take := LEAST(v_left, v_rec.balance);
            v_left := v_left - v_take;
            UPDATE public.credit_payments
            SET amount_paid = amount_paid + v_take,
                status = CASE WHEN amount_paid + v_take >= amount_owed
                              THEN 'Settled'::public.credit_status ELSE 'Partial'::public.credit_status END,
                settled_at = CASE WHEN amount_paid + v_take >= amount_owed THEN NOW() ELSE NULL END,
                updated_at = NOW()
            WHERE id = v_rec.id;
        END LOOP;
    END IF;

    IF v_wallet_applied > 0 THEN
        INSERT INTO public.customer_ledger (
            business_id, customer_id, type, amount, wallet_balance,
            debt_balance, recorded_by, note, reference_id
        )
        VALUES (
            p_business_id, v_customer_id, 'wallet_topup', v_wallet_applied,
            v_wallet_after, v_debt_after, v_by,
            COALESCE(p_description, 'Wallet top-up via ' || p_method),
            p_reference_code || '-wallet-topup'
        )
        ON CONFLICT (business_id, reference_id) WHERE reference_id IS NOT NULL DO NOTHING;
    END IF;

    RETURN v_payment_id;
END;
$$;


ALTER FUNCTION "public"."process_business_payment"("p_business_id" "uuid", "p_reference_code" "text", "p_amount" numeric, "p_method" "text", "p_sender_name" "text", "p_sender_phone" "text", "p_status" "text", "p_date" timestamp with time zone, "p_customer_id" "uuid", "p_customer_name" "text", "p_payment_type" "text", "p_description" "text", "p_recorded_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_customer_transaction"("p_business_id" "uuid", "p_customer_id" "uuid", "p_customer_name" "text", "p_staff_id" "uuid", "p_staff_name" "text", "p_total" numeric, "p_discount" numeric, "p_tax" numeric, "p_final_total" numeric, "p_amount_paid" numeric, "p_payment_method" "public"."payment_method", "p_timestamp" timestamp with time zone, "p_note" "text", "p_is_delivery" boolean, "p_delivery_fee" numeric, "p_rider_name" "text", "p_reference_id" "text", "p_items" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_tx_id          UUID;
    v_wallet_before  NUMERIC(14,2);
    v_wallet_after   NUMERIC(14,2);
    v_debt_before    NUMERIC(14,2);
    v_debt_after     NUMERIC(14,2);
    v_wallet_used    NUMERIC(14,2);
    v_debt_created   NUMERIC(14,2);
    v_item           JSONB;
    v_line_total     NUMERIC(14,2);
BEGIN
    PERFORM public.assert_permission(p_business_id, 'pos.create_sale');
    PERFORM public.assert_business_member(p_business_id); IF p_customer_id IS NOT NULL THEN PERFORM public.assert_business_member((SELECT business_id FROM public.customers WHERE id = p_customer_id)); END IF; PERFORM public.assert_business_member(pr.business_id) FROM public.products pr WHERE pr.id IN (SELECT (e->>'product_id')::UUID FROM jsonb_array_elements(COALESCE(p_items, '[]'::JSONB)) e WHERE e->>'product_id' IS NOT NULL);
    -- Idempotency check: if this reference_id was already processed, return existing tx
    IF p_reference_id IS NOT NULL THEN
        SELECT id INTO v_tx_id
        FROM public.transactions
        WHERE business_id = p_business_id
          AND reference_id = p_reference_id
          AND deleted_at IS NULL;

        IF FOUND THEN
            RETURN v_tx_id;
        END IF;
    END IF;

    -- Validate customer exists
    IF NOT EXISTS (SELECT 1 FROM public.customers WHERE id = p_customer_id) THEN
        RAISE EXCEPTION 'Customer not found: %', p_customer_id;
    END IF;

    -- Fetch current balances
    SELECT wallet_balance, debt_balance
    INTO v_wallet_before, v_debt_before
    FROM public.customers
    WHERE id = p_customer_id;

    v_wallet_before := COALESCE(v_wallet_before, 0);
    v_debt_before   := COALESCE(v_debt_before, 0);

    -- Compute wallet usage and debt creation
    -- For credit sales: wallet is applied first, remaining becomes debt
    IF p_payment_method IN ('Credit_Debt', 'Credit') THEN
        v_wallet_used  := LEAST(v_wallet_before, p_final_total);
        v_debt_created := GREATEST(0, p_final_total - v_wallet_used);
    ELSE
        v_wallet_used  := 0;
        v_debt_created := 0;
    END IF;

    -- Insert transaction header
    INSERT INTO public.transactions
        (business_id, total, discount, tax, final_total, amount_paid,
         wallet_applied, payment_method, customer_id, customer_name,
         staff_id, staff_name, status, timestamp, note, is_delivery,
         delivery_fee, rider_name, reference_id)
    VALUES (
        p_business_id, p_total, p_discount, p_tax, p_final_total,
        p_amount_paid, v_wallet_used, p_payment_method, p_customer_id,
        p_customer_name, p_staff_id, p_staff_name, 'Synced',
        COALESCE(p_timestamp, NOW()), p_note, COALESCE(p_is_delivery, FALSE),
        COALESCE(p_delivery_fee, 0), p_rider_name, p_reference_id
    )
    RETURNING id INTO v_tx_id;

    -- Insert transaction items
    IF p_items IS NOT NULL AND jsonb_array_length(p_items) > 0 THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
        LOOP
            v_line_total := ROUND(
                (COALESCE((v_item->>'unit_price')::NUMERIC, 0) *
                 (1 - COALESCE((v_item->>'discount_percentage')::NUMERIC, 0) / 100)) *
                COALESCE((v_item->>'quantity')::NUMERIC, 1),
                2
            );

            INSERT INTO public.transaction_items
                (transaction_id, product_id, product_name, unit_price,
                 quantity, discount_percentage, line_total)
            VALUES (
                v_tx_id,
                (v_item->>'product_id')::UUID,
                COALESCE(v_item->>'product_name', 'Unknown Product'),
                COALESCE((v_item->>'unit_price')::NUMERIC, 0),
                COALESCE((v_item->>'quantity')::NUMERIC, 1),
                COALESCE((v_item->>'discount_percentage')::NUMERIC, 0),
                v_line_total
            );
        END LOOP;
    END IF;

    -- Apply wallet deduction
    IF v_wallet_used > 0 THEN
        v_wallet_after := GREATEST(0, v_wallet_before - v_wallet_used);

        UPDATE public.customers
        SET wallet_balance = v_wallet_after
        WHERE id = p_customer_id;

        INSERT INTO public.wallet_transactions
            (business_id, customer_id, amount, balance_before, balance_after,
             reason, transaction_id, recorded_by)
        VALUES (
            p_business_id, p_customer_id, -v_wallet_used,
            v_wallet_before, v_wallet_after,
            'Applied to checkout sale', v_tx_id, p_staff_name
        );

        INSERT INTO public.customer_ledger
            (business_id, customer_id, type, amount, wallet_balance, debt_balance,
             recorded_by, note, transaction_id, reference_id)
        VALUES (
            p_business_id, p_customer_id, 'wallet_usage', v_wallet_used,
            v_wallet_after, v_debt_before, p_staff_name,
            'Paid for order ' || v_tx_id::TEXT || ' using wallet credit',
            v_tx_id, 'tx-' || v_tx_id::TEXT || '-wallet-usage'
        )
        ON CONFLICT (business_id, reference_id) WHERE reference_id IS NOT NULL DO NOTHING;
    END IF;

    -- Create debt record if applicable
    IF v_debt_created > 0 THEN
        -- credit record: created by the sale trigger, once per sale

        v_debt_after := v_debt_before + v_debt_created;

        UPDATE public.customers
        SET debt_balance = v_debt_after
        WHERE id = p_customer_id;

        INSERT INTO public.customer_ledger
            (business_id, customer_id, type, amount, wallet_balance, debt_balance,
             recorded_by, note, transaction_id, reference_id)
        VALUES (
            p_business_id, p_customer_id, 'debt_creation', v_debt_created,
            COALESCE(v_wallet_after, v_wallet_before), v_debt_after, p_staff_name,
            'Outstanding balance for order ' || v_tx_id::TEXT || ' charged to debt',
            v_tx_id, 'tx-' || v_tx_id::TEXT || '-debt-creation'
        )
        ON CONFLICT (business_id, reference_id) WHERE reference_id IS NOT NULL DO NOTHING;
    END IF;

    RETURN v_tx_id;
END;
$$;


ALTER FUNCTION "public"."process_customer_transaction"("p_business_id" "uuid", "p_customer_id" "uuid", "p_customer_name" "text", "p_staff_id" "uuid", "p_staff_name" "text", "p_total" numeric, "p_discount" numeric, "p_tax" numeric, "p_final_total" numeric, "p_amount_paid" numeric, "p_payment_method" "public"."payment_method", "p_timestamp" timestamp with time zone, "p_note" "text", "p_is_delivery" boolean, "p_delivery_fee" numeric, "p_rider_name" "text", "p_reference_id" "text", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_debt_payment"("p_business_id" "uuid", "p_customer_id" "uuid", "p_amount" numeric, "p_method" "text", "p_recorded_by" "text", "p_note" "text", "p_reference_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_wallet_before NUMERIC(14,2);
    v_debt_before   NUMERIC(14,2);
    v_debt_after    NUMERIC(14,2);
    v_rem_payment   NUMERIC(14,2);
    v_applied       NUMERIC(14,2);
    v_rec           RECORD;
BEGIN
    PERFORM public.assert_permission(p_business_id, 'customers.debts', 'payments.cash');
    PERFORM public.assert_business_member(p_business_id); IF p_customer_id IS NOT NULL THEN PERFORM public.assert_business_member((SELECT business_id FROM public.customers WHERE id = p_customer_id)); END IF;
    -- Idempotency check
    IF p_reference_id IS NOT NULL THEN
        IF EXISTS (
            SELECT 1 FROM public.customer_ledger
            WHERE business_id = p_business_id
              AND reference_id = p_reference_id
        ) THEN
            RETURN;
        END IF;
    END IF;

    -- Validate
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Amount must be greater than zero.';
    END IF;

    SELECT wallet_balance, debt_balance
    INTO v_wallet_before, v_debt_before
    FROM public.customers
    WHERE id = p_customer_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Customer not found: %', p_customer_id;
    END IF;

    v_wallet_before := COALESCE(v_wallet_before, 0);
    v_debt_before   := COALESCE(v_debt_before, 0);

    IF p_amount > v_debt_before THEN
        RAISE EXCEPTION 'Cannot pay off more than outstanding debt.';
    END IF;

    v_debt_after := v_debt_before - p_amount;

    -- Update customer debt
    UPDATE public.customers
    SET debt_balance = v_debt_after
    WHERE id = p_customer_id;

    -- Create debt payment record
    INSERT INTO public.debt_payments
        (business_id, customer_id, amount_paid, remaining_debt,
         payment_method, recorded_by, note)
    VALUES (
        p_business_id, p_customer_id, p_amount, v_debt_after,
        p_method, p_recorded_by, COALESCE(p_note, '')
    );

    -- Update credit_payments FIFO
    v_rem_payment := p_amount;
    FOR v_rec IN
        SELECT id, amount_owed, amount_paid AS existing_paid, balance
        FROM public.credit_payments
        WHERE customer_id = p_customer_id
          AND business_id = p_business_id
          AND status IN ('Open', 'Partial')
        ORDER BY created_at ASC
    LOOP
        EXIT WHEN v_rem_payment <= 0;

        v_applied := LEAST(v_rem_payment, v_rec.balance);
        v_rem_payment := v_rem_payment - v_applied;

        UPDATE public.credit_payments
        SET
            amount_paid = amount_paid + v_applied,
            status = CASE
                WHEN (amount_paid + v_applied) >= amount_owed
                    THEN 'Settled'::public.credit_status
                ELSE 'Partial'::public.credit_status
            END,
            settled_at = CASE
                WHEN (amount_paid + v_applied) >= amount_owed THEN NOW()
                ELSE NULL
            END,
            updated_at = NOW()
        WHERE id = v_rec.id;
    END LOOP;

    -- Create ledger entry
    INSERT INTO public.customer_ledger
        (business_id, customer_id, type, amount, wallet_balance, debt_balance,
         recorded_by, note, reference_id)
    VALUES (
        p_business_id, p_customer_id, 'debt_payment', p_amount,
        v_wallet_before, v_debt_after, p_recorded_by,
        COALESCE(p_note, 'Debt payment via ' || p_method),
        p_reference_id
    )
    ON CONFLICT (business_id, reference_id) WHERE reference_id IS NOT NULL DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."process_debt_payment"("p_business_id" "uuid", "p_customer_id" "uuid", "p_amount" numeric, "p_method" "text", "p_recorded_by" "text", "p_note" "text", "p_reference_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_wallet_spend"("p_business_id" "uuid", "p_customer_id" "uuid", "p_amount" numeric, "p_recorded_by" "text", "p_note" "text", "p_reference_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_wallet_before NUMERIC(14,2);
    v_wallet_after  NUMERIC(14,2);
    v_debt_before   NUMERIC(14,2);
BEGIN
    PERFORM public.assert_permission(p_business_id, 'pos.create_sale', 'customers.debts');
    PERFORM public.assert_business_member(p_business_id); IF p_customer_id IS NOT NULL THEN PERFORM public.assert_business_member((SELECT business_id FROM public.customers WHERE id = p_customer_id)); END IF;
    -- Idempotency check
    IF p_reference_id IS NOT NULL THEN
        IF EXISTS (
            SELECT 1 FROM public.customer_ledger
            WHERE business_id = p_business_id
              AND reference_id = p_reference_id
        ) THEN
            RETURN;
        END IF;
    END IF;

    -- Validate
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Amount must be greater than zero.';
    END IF;

    SELECT wallet_balance, debt_balance
    INTO v_wallet_before, v_debt_before
    FROM public.customers
    WHERE id = p_customer_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Customer not found: %', p_customer_id;
    END IF;

    v_wallet_before := COALESCE(v_wallet_before, 0);
    v_debt_before   := COALESCE(v_debt_before, 0);

    IF p_amount > v_wallet_before THEN
        RAISE EXCEPTION 'Insufficient wallet balance.';
    END IF;

    v_wallet_after := v_wallet_before - p_amount;

    -- Update customer wallet
    UPDATE public.customers
    SET wallet_balance = v_wallet_after
    WHERE id = p_customer_id;

    -- Create ledger entry
    INSERT INTO public.customer_ledger
        (business_id, customer_id, type, amount, wallet_balance, debt_balance,
         recorded_by, note, reference_id)
    VALUES (
        p_business_id, p_customer_id, 'wallet_usage', p_amount,
        v_wallet_after, v_debt_before, p_recorded_by,
        COALESCE(p_note, 'Wallet credit spent'),
        p_reference_id
    )
    ON CONFLICT (business_id, reference_id) WHERE reference_id IS NOT NULL DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."process_wallet_spend"("p_business_id" "uuid", "p_customer_id" "uuid", "p_amount" numeric, "p_recorded_by" "text", "p_note" "text", "p_reference_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_wallet_topup"("p_business_id" "uuid", "p_customer_id" "uuid", "p_amount" numeric, "p_recorded_by" "text", "p_note" "text", "p_reference_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_wallet_before NUMERIC(14,2);
    v_wallet_after  NUMERIC(14,2);
    v_debt_before   NUMERIC(14,2);
    v_debt_after    NUMERIC(14,2);
    v_debt_paid     NUMERIC(14,2);
    v_wallet_dep    NUMERIC(14,2);
BEGIN
    PERFORM public.assert_permission(p_business_id, 'customers.debts');
    PERFORM public.assert_business_member(p_business_id); IF p_customer_id IS NOT NULL THEN PERFORM public.assert_business_member((SELECT business_id FROM public.customers WHERE id = p_customer_id)); END IF;
    -- Idempotency check
    IF p_reference_id IS NOT NULL THEN
        IF EXISTS (
            SELECT 1 FROM public.customer_ledger
            WHERE business_id = p_business_id
              AND reference_id = p_reference_id
        ) THEN
            RETURN;
        END IF;
    END IF;

    -- Validate
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Amount must be greater than zero.';
    END IF;

    SELECT wallet_balance, debt_balance
    INTO v_wallet_before, v_debt_before
    FROM public.customers
    WHERE id = p_customer_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Customer not found: %', p_customer_id;
    END IF;

    v_wallet_before := COALESCE(v_wallet_before, 0);
    v_debt_before   := COALESCE(v_debt_before, 0);

    -- Apply payment: first to debt, then to wallet
    v_debt_paid  := LEAST(v_debt_before, p_amount);
    v_wallet_dep := p_amount - v_debt_paid;

    v_debt_after  := v_debt_before - v_debt_paid;
    v_wallet_after := v_wallet_before + v_wallet_dep;

    -- Update customer balances
    UPDATE public.customers
    SET debt_balance = v_debt_after,
        wallet_balance = v_wallet_after
    WHERE id = p_customer_id;

    -- Debt paid by the top-up settles the oldest credit records (settles the oldest credit records)
    IF v_debt_paid > 0 THEN
        DECLARE
            v_left    NUMERIC(14,2) := v_debt_paid;
            v_applied NUMERIC(14,2);
            v_rec     RECORD;
        BEGIN
            FOR v_rec IN
                SELECT id, balance FROM public.credit_payments
                WHERE customer_id = p_customer_id AND business_id = p_business_id AND status IN ('Open', 'Partial')
                ORDER BY created_at ASC, id ASC
                FOR UPDATE
            LOOP
                EXIT WHEN v_left <= 0;
                v_applied := LEAST(v_left, v_rec.balance);
                v_left := v_left - v_applied;
                UPDATE public.credit_payments
                SET amount_paid = amount_paid + v_applied,
                    status = CASE WHEN amount_paid + v_applied >= amount_owed THEN 'Settled'::public.credit_status ELSE 'Partial'::public.credit_status END,
                    settled_at = CASE WHEN amount_paid + v_applied >= amount_owed THEN NOW() ELSE NULL END,
                    updated_at = NOW()
                WHERE id = v_rec.id;
            END LOOP;
        END;
        UPDATE public.customers SET loyalty_points = COALESCE(loyalty_points, 0) + FLOOR(v_debt_paid)::INTEGER WHERE id = p_customer_id;
        IF to_regclass('public.loyalty_points_earned') IS NOT NULL AND FLOOR(v_debt_paid) > 0 THEN
            INSERT INTO public.loyalty_points_earned (business_id, customer_id, points, source, amount)
            VALUES (p_business_id, p_customer_id, FLOOR(v_debt_paid)::INTEGER, 'debt_payment', v_debt_paid);
        END IF;
    END IF;

    -- Ledger entry for debt payment (if any)
    IF v_debt_paid > 0 THEN
        INSERT INTO public.customer_ledger
            (business_id, customer_id, type, amount, wallet_balance, debt_balance,
             recorded_by, note, reference_id)
        VALUES (
            p_business_id, p_customer_id, 'debt_payment', v_debt_paid,
            v_wallet_after, v_debt_after, p_recorded_by,
            COALESCE(p_note, 'Debt automatically paid off via wallet deposit'),
            p_reference_id || '-debt-payment'
        )
        ON CONFLICT (business_id, reference_id) WHERE reference_id IS NOT NULL DO NOTHING;
    END IF;

    -- Ledger entry for wallet top-up (if any)
    IF v_wallet_dep > 0 THEN
        INSERT INTO public.customer_ledger
            (business_id, customer_id, type, amount, wallet_balance, debt_balance,
             recorded_by, note, reference_id)
        VALUES (
            p_business_id, p_customer_id, 'wallet_topup', v_wallet_dep,
            v_wallet_after, v_debt_after, p_recorded_by,
            COALESCE(p_note, 'Wallet top-up'),
            p_reference_id || '-wallet-topup'
        )
        ON CONFLICT (business_id, reference_id) WHERE reference_id IS NOT NULL DO NOTHING;
    END IF;
END;
$$;


ALTER FUNCTION "public"."process_wallet_topup"("p_business_id" "uuid", "p_customer_id" "uuid", "p_amount" numeric, "p_recorded_by" "text", "p_note" "text", "p_reference_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_details"("p_purchase_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_p public.purchases%ROWTYPE;
BEGIN
    SELECT * INTO v_p FROM public.purchases WHERE id = p_purchase_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'That purchase was not found.'; END IF;
    PERFORM public.assert_business_member(v_p.business_id);
    PERFORM public.assert_permission(v_p.business_id, 'purchases.view');
    RETURN jsonb_build_object(
        'receipts', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                'id', r.id, 'number', r.number, 'receivedAt', r.received_at, 'by', r.received_by, 'note', r.note,
                'value', r.total_value, 'damagedValue', r.damaged_value, 'billId', r.bill_id,
                'billNumber', (SELECT b.number FROM public.supplier_bills b WHERE b.id = r.bill_id),
                'lines', (SELECT jsonb_agg(jsonb_build_object('name', l.name, 'unit', l.unit, 'received', l.qty_received, 'damaged', l.qty_damaged, 'price', l.unit_price))
                          FROM public.purchase_receipt_lines l WHERE l.receipt_id = r.id)
            ) ORDER BY r.received_at)
            FROM public.purchase_receipts r WHERE r.purchase_id = v_p.id), '[]'::JSONB),
        'quotes', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                'id', q.id, 'supplierId', q.supplier_id, 'supplier', q.supplier_name, 'status', q.status, 'sentVia', q.sent_via,
                'deliveryDays', q.delivery_days, 'note', q.note, 'total', q.total, 'askedAt', q.asked_at, 'pricedAt', q.priced_at,
                'phone', s.phone, 'email', s.email,
                'lines', COALESCE((SELECT jsonb_agg(jsonb_build_object('itemId', l.purchase_item_id, 'price', l.unit_price, 'available', l.available))
                          FROM public.purchase_quote_lines l WHERE l.quote_id = q.id), '[]'::JSONB)
            ) ORDER BY q.asked_at)
            FROM public.purchase_quotes q LEFT JOIN public.suppliers s ON s.id = q.supplier_id
            WHERE q.purchase_id = v_p.id), '[]'::JSONB),
        'bills', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                'id', b.id, 'number', b.number, 'status', b.status, 'total', b.total, 'balance', b.balance, 'billDate', b.bill_date
            ) ORDER BY b.bill_date) FROM public.supplier_bills b WHERE b.purchase_id = v_p.id), '[]'::JSONB),
        'returns', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', r.id, 'number', r.number, 'total', r.total, 'createdAt', r.created_at))
            FROM public.supplier_returns r WHERE r.purchase_id = v_p.id), '[]'::JSONB),
        'transfers', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', t.id, 'reference', t.reference, 'status', t.status,
                'toName', (SELECT name FROM public.businesses WHERE id = t.to_business_id)))
            FROM public.stock_transfers t WHERE t.purchase_id = v_p.id), '[]'::JSONB),
        'unbilledValue', COALESCE((SELECT SUM(total_value) FROM public.purchase_receipts WHERE purchase_id = v_p.id AND bill_id IS NULL), 0)
    );
END;
$$;


ALTER FUNCTION "public"."purchase_details"("p_purchase_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_to_order"("p_quote_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_q  public.quotes%ROWTYPE;
    v_id UUID;
BEGIN
    SELECT * INTO v_q FROM public.quotes WHERE id = p_quote_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'That quote was not found.';
    END IF;
    PERFORM public.assert_business_member(v_q.business_id);
    PERFORM public.assert_permission(v_q.business_id, 'quotes.manage');
    PERFORM public.assert_permission(v_q.business_id, 'sales_orders.manage');
    IF v_q.status = 'accepted' THEN
        RETURN v_q.order_id;
    ELSIF v_q.status = 'declined' THEN
        RAISE EXCEPTION 'This quote was declined. Put it back to draft first.';
    END IF;

    INSERT INTO public.sales_orders (business_id, number, quote_id, customer_id, customer_name, customer_phone, order_date,
                                     notes, terms, delivery_fee, created_by)
    VALUES (v_q.business_id, public.sd_next_no(v_q.business_id, 'SO'), v_q.id, v_q.customer_id, v_q.customer_name,
            v_q.customer_phone, public.sd_today(), v_q.notes, v_q.terms, v_q.delivery_fee, public.acc_who())
    RETURNING id INTO v_id;
    INSERT INTO public.sales_order_lines (order_id, business_id, position, product_id, name, unit, quantity, unit_price,
                                          discount_pct, vat_rate, line_net, line_vat, line_total)
    SELECT v_id, business_id, position, product_id, name, unit, quantity, unit_price, discount_pct, vat_rate,
           line_net, line_vat, line_total
    FROM public.quote_lines WHERE quote_id = v_q.id;
    PERFORM public.sd_order_totals(v_id);
    UPDATE public.quotes SET status = 'accepted', decided_at = NOW(), order_id = v_id, updated_at = NOW() WHERE id = v_q.id;
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."quote_to_order"("p_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_purchase"("p_purchase_id" "uuid", "p_staff_name" "text", "p_update_cost" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_lines JSONB;
    v_r     JSONB;
BEGIN
    SELECT COALESCE(jsonb_agg(jsonb_build_object('itemId', id, 'received', quantity - qty_received)), '[]'::JSONB) INTO v_lines
    FROM public.purchase_items WHERE purchase_id = p_purchase_id AND qty_received < quantity;
    IF jsonb_array_length(v_lines) = 0 THEN
        -- Nothing listed: mark it received, as before.
        PERFORM public.assert_permission((SELECT business_id FROM public.purchases WHERE id = p_purchase_id),
            'purchases.update', 'purchases.approve', 'purchases.manage');
        PERFORM public.fn_buying_ctx();
        UPDATE public.purchases SET status = 'Received', received_at = NOW(),
            received_by = COALESCE(NULLIF(trim(p_staff_name), ''), 'Staff'), updated_at = NOW()
        WHERE id = p_purchase_id AND status NOT IN ('Received', 'Cancelled', 'RFQ', 'Awaiting approval');
        RETURN 0;
    END IF;
    v_r := public.receive_purchase_lines(p_purchase_id, v_lines, NULL, p_update_cost);
    RETURN (v_r->>'stocked')::INTEGER;
END;
$$;


ALTER FUNCTION "public"."receive_purchase"("p_purchase_id" "uuid", "p_staff_name" "text", "p_update_cost" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_purchase_lines"("p_purchase_id" "uuid", "p_lines" "jsonb", "p_note" "text" DEFAULT NULL::"text", "p_update_cost" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_p        public.purchases%ROWTYPE;
    v_item     public.purchase_items%ROWTYPE;
    v_prod     public.products%ROWTYPE;
    v_el       JSONB;
    v_rec      NUMERIC;
    v_dmg      NUMERIC;
    v_left     NUMERIC;
    v_me       TEXT;
    v_ref      TEXT;
    v_receipt  UUID;
    v_no       TEXT;
    v_value    NUMERIC := 0;
    v_dvalue   NUMERIC := 0;
    v_lines    INTEGER := 0;
    v_stocked  INTEGER := 0;
    v_open     BOOLEAN;
    v_tr       UUID;
    v_branch   TEXT;
    v_drafts   INTEGER := 0;
BEGIN
    SELECT * INTO v_p FROM public.purchases WHERE id = p_purchase_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That purchase was not found.'; END IF;
    PERFORM public.assert_business_member(v_p.business_id);
    PERFORM public.assert_permission(v_p.business_id, 'purchases.update', 'purchases.approve', 'purchases.manage');
    PERFORM public.assert_permission(v_p.business_id, 'inventory.receive_stock', 'inventory.adjust_stock');

    IF v_p.status = 'Received' THEN
        RAISE EXCEPTION 'Everything on this purchase has arrived.';
    ELSIF v_p.status = 'Cancelled' THEN
        RAISE EXCEPTION 'A cancelled purchase can''t be received.';
    ELSIF v_p.status IN ('RFQ', 'Awaiting approval') THEN
        RAISE EXCEPTION 'This purchase isn''t ordered yet (%).', CASE v_p.status WHEN 'RFQ' THEN 'asking suppliers for prices' ELSE 'waiting for approval' END;
    ELSIF v_p.status = 'Pending' AND public.fn_needs_approval(v_p.business_id, v_p.total_amount) THEN
        RAISE EXCEPTION 'This purchase is above your limit. Place the order so it can be approved first.';
    END IF;
    IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
        RAISE EXCEPTION 'Say what arrived.';
    END IF;

    v_me := public.fn_my_display_name(v_p.business_id);
    v_ref := public.fn_purchase_ref(v_p);
    v_no := public.sd_next_no(v_p.business_id, 'GRN');
    INSERT INTO public.purchase_receipts (business_id, purchase_id, number, received_by, note)
    VALUES (v_p.business_id, v_p.id, v_no, v_me, NULLIF(trim(COALESCE(p_note, '')), ''))
    RETURNING id INTO v_receipt;

    PERFORM public.fn_buying_ctx();

    FOR v_item IN
        SELECT pi.* FROM public.purchase_items pi
        WHERE pi.purchase_id = v_p.id
          AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_lines) e WHERE (e->>'itemId')::UUID = pi.id)
        ORDER BY pi.product_id NULLS LAST, pi.id
        FOR UPDATE
    LOOP
        SELECT e INTO v_el FROM jsonb_array_elements(p_lines) e WHERE (e->>'itemId')::UUID = v_item.id LIMIT 1;
        v_rec := round(COALESCE(NULLIF(v_el->>'received', '')::NUMERIC, 0), 3);
        v_dmg := round(COALESCE(NULLIF(v_el->>'damaged', '')::NUMERIC, 0), 3);
        v_left := v_item.quantity - v_item.qty_received;
        IF v_rec < 0 OR v_dmg < 0 THEN
            RAISE EXCEPTION 'Amounts for % can''t be below zero.', v_item.name;
        END IF;
        IF v_rec > v_left THEN
            RAISE EXCEPTION 'Only % % of % is still to come. Receive that, then restock the extra.',
                public.fn_qty(v_left), v_item.unit, v_item.name;
        END IF;
        IF v_rec + v_dmg > v_left THEN
            RAISE EXCEPTION 'For %, good plus damaged is more than the % % still to come.', v_item.name, public.fn_qty(v_left), v_item.unit;
        END IF;
        CONTINUE WHEN v_rec = 0 AND v_dmg = 0;

        INSERT INTO public.purchase_receipt_lines
            (business_id, receipt_id, purchase_item_id, product_id, name, unit, unit_price, qty_received, qty_damaged)
        VALUES (v_p.business_id, v_receipt, v_item.id, v_item.product_id, v_item.name, v_item.unit, v_item.price, v_rec, v_dmg);
        UPDATE public.purchase_items SET qty_received = qty_received + v_rec, qty_damaged = qty_damaged + v_dmg WHERE id = v_item.id;
        v_value := v_value + round(v_rec * v_item.price, 2);
        v_dvalue := v_dvalue + round(v_dmg * v_item.price, 2);
        v_lines := v_lines + 1;

        IF v_rec > 0 AND v_item.product_id IS NOT NULL THEN
            SELECT * INTO v_prod FROM public.products
            WHERE id = v_item.product_id AND business_id = v_p.business_id AND deleted_at IS NULL
            FOR UPDATE;
            IF FOUND THEN
                UPDATE public.products
                SET stock = stock + v_rec,
                    cost = CASE WHEN p_update_cost THEN v_item.price ELSE cost END,
                    updated_at = NOW()
                WHERE id = v_prod.id;
                INSERT INTO public.inventory_adjustments
                    (business_id, product_id, product_name, type, quantity_adjusted,
                     previous_stock, new_stock, reason, staff_name, reference_number, notes)
                VALUES (
                    v_p.business_id, v_prod.id, v_prod.name, 'Restock', v_rec,
                    v_prod.stock, v_prod.stock + v_rec,
                    'Received from ' || v_p.supplier_name, v_me, v_no,
                    'Purchase ' || v_ref || ' at KSh ' || v_item.price || ' per ' || v_item.unit
                        || CASE WHEN v_dmg > 0 THEN ' · ' || public.fn_qty(v_dmg) || ' damaged, not added' ELSE '' END
                );
                v_stocked := v_stocked + 1;

                -- Central buying: what arrived for another branch goes on a draft transfer.
                IF v_item.for_business_id IS NOT NULL AND v_item.for_business_id <> v_p.business_id
                   AND public.fn_branches_share_owner(v_p.business_id, v_item.for_business_id) THEN
                    SELECT id INTO v_tr FROM public.stock_transfers
                    WHERE from_business_id = v_p.business_id AND to_business_id = v_item.for_business_id
                      AND purchase_id = v_p.id AND status = 'draft'
                    LIMIT 1;
                    IF v_tr IS NULL THEN
                        INSERT INTO public.stock_transfers (reference, from_business_id, to_business_id, status, note, sent_by_name, sent_by_user_id, purchase_id)
                        VALUES (
                            'TR-' || to_char(NOW() AT TIME ZONE 'Africa/Nairobi', 'YYMMDD') || '-' || upper(substr(md5(gen_random_uuid()::TEXT), 1, 5)),
                            v_p.business_id, v_item.for_business_id, 'draft', 'Their share of purchase ' || v_ref,
                            v_me, public.fn_my_user_id(), v_p.id)
                        RETURNING id INTO v_tr;
                        v_drafts := v_drafts + 1;
                    END IF;
                    IF EXISTS (SELECT 1 FROM public.stock_transfer_items WHERE transfer_id = v_tr AND from_product_id = v_prod.id) THEN
                        UPDATE public.stock_transfer_items
                        SET quantity_sent = quantity_sent + v_rec, quantity_requested = COALESCE(quantity_requested, 0) + v_rec
                        WHERE transfer_id = v_tr AND from_product_id = v_prod.id;
                    ELSE
                        INSERT INTO public.stock_transfer_items
                            (transfer_id, from_product_id, product_name, sku, unit, category, unit_cost, unit_price, quantity_sent, quantity_requested)
                        VALUES (v_tr, v_prod.id, v_prod.name, v_prod.sku, v_prod.unit, v_prod.category,
                                CASE WHEN p_update_cost THEN v_item.price ELSE v_prod.cost END, v_prod.price, v_rec, v_rec);
                    END IF;
                    v_tr := NULL;
                END IF;
            END IF;
        END IF;
    END LOOP;

    IF v_lines = 0 THEN
        RAISE EXCEPTION 'Enter how much of at least one item arrived.';
    END IF;

    UPDATE public.purchase_receipts SET total_value = v_value, damaged_value = v_dvalue WHERE id = v_receipt;

    SELECT EXISTS (SELECT 1 FROM public.purchase_items WHERE purchase_id = v_p.id AND qty_received < quantity) INTO v_open;
    UPDATE public.purchases
    SET status = CASE WHEN v_open THEN 'Part received' ELSE 'Received' END,
        received_at = NOW(), received_by = v_me, reference_number = v_ref,
        ordered_at = COALESCE(ordered_at, NOW()),
        approved_amount = COALESCE(approved_amount, total_amount),
        updated_at = NOW()
    WHERE id = v_p.id;

    IF v_drafts > 0 THEN
        PERFORM public.fn_buying_notify(v_p.business_id, NULL, 'Stock Transfer', 'Transfers ready to send',
            'Goods for ' || v_drafts || CASE WHEN v_drafts = 1 THEN ' branch' ELSE ' branches' END || ' arrived on ' || v_ref
                || '. Their transfers are drafted on Stock Transfers; check and send them.',
            'stock-transfers', jsonb_build_object('purchaseId', v_p.id));
    END IF;

    RETURN jsonb_build_object('receiptId', v_receipt, 'number', v_no, 'lines', v_lines, 'stocked', v_stocked,
        'value', v_value, 'damagedValue', v_dvalue, 'complete', NOT v_open, 'transfersDrafted', v_drafts);
END;
$$;


ALTER FUNCTION "public"."receive_purchase_lines"("p_purchase_id" "uuid", "p_lines" "jsonb", "p_note" "text", "p_update_cost" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_stock_transfer"("p_transfer_id" "uuid", "p_lines" "jsonb" DEFAULT '[]'::"jsonb", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_t         public.stock_transfers;
    v_item      public.stock_transfer_items;
    v_src       public.products;
    v_dest      public.products;
    v_from_name TEXT;
    v_me        TEXT;
    v_qty       NUMERIC(14,3);
    v_given     JSONB;
    v_new_cost  NUMERIC(14,2);
    v_short     NUMERIC := 0;
    v_short_n   INTEGER := 0;
    v_created   INTEGER := 0;
BEGIN
    SELECT * INTO v_t FROM public.stock_transfers WHERE id = p_transfer_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer not found.';
    END IF;
    PERFORM public.assert_business_member(v_t.to_business_id);
    PERFORM public.assert_permission(v_t.to_business_id, 'inventory.receive_stock', 'inventory.transfer_stock');

    IF v_t.status = 'received' THEN
        RETURN jsonb_build_object('id', v_t.id, 'reference', v_t.reference, 'already', TRUE);
    END IF;
    IF v_t.status = 'cancelled' THEN
        RAISE EXCEPTION 'This transfer was cancelled by the sender, so there is nothing to receive.';
    END IF;

    SELECT name INTO v_from_name FROM public.businesses WHERE id = v_t.from_business_id;
    v_me := public.fn_my_display_name(v_t.to_business_id);

    FOR v_item IN SELECT * FROM public.stock_transfer_items WHERE transfer_id = v_t.id ORDER BY id LOOP
        SELECT e INTO v_given
        FROM jsonb_array_elements(COALESCE(p_lines, '[]'::JSONB)) e
        WHERE (e->>'item_id')::UUID = v_item.id
        LIMIT 1;

        v_qty := CASE WHEN v_given IS NULL OR v_given->>'quantity_received' IS NULL
                      THEN v_item.quantity_sent
                      ELSE ROUND((v_given->>'quantity_received')::NUMERIC, 3) END;
        IF v_qty < 0 THEN
            RAISE EXCEPTION 'Received amount for % can''t be below zero.', v_item.product_name;
        END IF;
        IF v_qty > v_item.quantity_sent THEN
            RAISE EXCEPTION 'More % came than was sent (% %). Receive what was sent, then restock the extra.',
                v_item.product_name, trim(to_char(v_item.quantity_sent, 'FM999999990.###')), v_item.unit;
        END IF;

        -- The same product here: same SKU first, then same name.
        v_dest := NULL;
        IF NULLIF(btrim(COALESCE(v_item.sku, '')), '') IS NOT NULL THEN
            SELECT * INTO v_dest FROM public.products
            WHERE business_id = v_t.to_business_id AND sku = v_item.sku AND deleted_at IS NULL
            FOR UPDATE;
        END IF;
        IF v_dest.id IS NULL THEN
            SELECT * INTO v_dest FROM public.products
            WHERE business_id = v_t.to_business_id AND deleted_at IS NULL
              AND lower(btrim(name)) = lower(btrim(v_item.product_name))
            ORDER BY created_at
            LIMIT 1
            FOR UPDATE;
        END IF;

        IF v_dest.id IS NOT NULL AND lower(btrim(v_dest.unit)) <> lower(btrim(v_item.unit)) THEN
            RAISE EXCEPTION '% is counted in % here but in % at %. Make the units match first.',
                v_item.product_name, v_dest.unit, v_item.unit, v_from_name;
        END IF;

        IF v_dest.id IS NULL THEN
            -- Not sold here yet: add it, copying the sender's details. Its selling price can
            -- be changed afterwards; its cost is what the stock cost the business.
            SELECT * INTO v_src FROM public.products WHERE id = v_item.from_product_id;
            INSERT INTO public.products (
                business_id, name, category, price, cost, image, stock, min_stock, unit, sku,
                description, perishable, expiry_days, last_modified_by
            ) VALUES (
                v_t.to_business_id, v_item.product_name, v_item.category, v_item.unit_price, v_item.unit_cost,
                v_src.image, 0, COALESCE(v_src.min_stock, 0), v_item.unit,
                CASE WHEN v_item.sku IS NOT NULL AND NOT EXISTS (
                    SELECT 1 FROM public.products x WHERE x.business_id = v_t.to_business_id AND x.sku = v_item.sku
                ) THEN v_item.sku END,
                v_src.description, COALESCE(v_src.perishable, TRUE), v_src.expiry_days, v_me
            )
            RETURNING * INTO v_dest;
            v_created := v_created + 1;
        END IF;

        IF v_qty > 0 THEN
            -- Weighted average: what was already here at its cost, plus what came at the sender's.
            v_new_cost := CASE
                WHEN v_dest.stock <= 0 THEN v_item.unit_cost
                ELSE ROUND((v_dest.stock * v_dest.cost + v_qty * v_item.unit_cost) / (v_dest.stock + v_qty), 2)
            END;

            UPDATE public.products
            SET stock = stock + v_qty, cost = v_new_cost, updated_at = NOW()
            WHERE id = v_dest.id;

            INSERT INTO public.inventory_adjustments (
                business_id, product_id, product_name, type, quantity_adjusted, previous_stock, new_stock,
                reason, staff_name, reference_number, notes
            ) VALUES (
                v_t.to_business_id, v_dest.id, v_dest.name, 'Transfer In', v_qty,
                v_dest.stock, v_dest.stock + v_qty,
                'From ' || v_from_name
                    || CASE WHEN v_qty < v_item.quantity_sent
                            THEN ' (' || trim(to_char(v_item.quantity_sent - v_qty, 'FM999999990.###')) || ' ' || v_item.unit || ' short)'
                            ELSE '' END,
                v_me, v_t.reference, NULLIF(btrim(COALESCE(p_note, '')), '')
            );
        END IF;

        IF v_qty < v_item.quantity_sent THEN
            v_short := v_short + (v_item.quantity_sent - v_qty) * v_item.unit_cost;
            v_short_n := v_short_n + 1;
        END IF;

        UPDATE public.stock_transfer_items
        SET quantity_received = v_qty, to_product_id = v_dest.id
        WHERE id = v_item.id;
    END LOOP;

    UPDATE public.stock_transfers
    SET status = 'received', received_by_name = v_me, received_at = NOW(),
        receive_note = NULLIF(btrim(COALESCE(p_note, '')), ''), updated_at = NOW()
    WHERE id = v_t.id;

    IF v_short_n > 0 THEN
        INSERT INTO public.notifications (business_id, title, message, type, priority, action_type, action_target, payload, created_by)
        SELECT v_t.from_business_id, 'Transfer arrived short',
               b.name || ' received ' || v_t.reference || ' with ' || v_short_n
                   || CASE WHEN v_short_n = 1 THEN ' product' ELSE ' products' END
                   || ' short (KSh ' || trim(to_char(ROUND(v_short), 'FM999,999,999,990')) || ' at cost).',
               'Stock Transfer', 'high', 'navigate', 'stock-transfers',
               jsonb_build_object('transferId', v_t.id, 'reference', v_t.reference), 'system'
        FROM public.businesses b WHERE b.id = v_t.to_business_id;
    END IF;

    RETURN jsonb_build_object('id', v_t.id, 'reference', v_t.reference, 'shortValue', ROUND(v_short, 2), 'productsAdded', v_created);
END;
$$;


ALTER FUNCTION "public"."receive_stock_transfer"("p_transfer_id" "uuid", "p_lines" "jsonb", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_bill_payment"("p_bill_id" "uuid", "p_amount" numeric, "p_method" "text", "p_reference" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_paid_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_b  public.supplier_bills%ROWTYPE;
    v_id UUID;
BEGIN
    SELECT * INTO v_b FROM public.supplier_bills WHERE id = p_bill_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That bill was not found.'; END IF;
    PERFORM public.assert_business_member(v_b.business_id);
    IF v_b.status = 'needs_check' THEN
        RAISE EXCEPTION 'Check this bill first: its amount differs from the goods received.';
    ELSIF v_b.status = 'void' THEN
        RAISE EXCEPTION 'This bill is void.';
    END IF;
    IF round(COALESCE(p_amount, 0), 2) > v_b.balance THEN
        RAISE EXCEPTION 'Only KSh % is left to pay on this bill.', trim(to_char(v_b.balance, 'FM999,999,999,990.00'));
    END IF;
    v_id := public.record_supplier_payment(v_b.business_id, v_b.supplier_id, v_b.supplier_name, v_b.purchase_id,
        p_amount, p_method, COALESCE(NULLIF(trim(COALESCE(p_reference, '')), ''), v_b.supplier_invoice_no),
        COALESCE(NULLIF(trim(COALESCE(p_note, '')), ''), 'Bill ' || v_b.number), p_paid_at);
    UPDATE public.supplier_payments SET bill_id = v_b.id WHERE id = v_id;
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."record_bill_payment"("p_bill_id" "uuid", "p_amount" numeric, "p_method" "text", "p_reference" "text", "p_note" "text", "p_paid_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_invoice_payment"("p_invoice_id" "uuid", "p_amount" numeric, "p_method" "text", "p_reference" "text" DEFAULT NULL::"text", "p_paid_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_payment_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_i      public.sales_invoices%ROWTYPE;
    v_py     public.payments%ROWTYPE;
    v_pid    UUID := p_payment_id;
    v_amount NUMERIC := round(COALESCE(p_amount, 0), 2);
    v_used   NUMERIC;
    v_ref    TEXT := NULLIF(upper(trim(COALESCE(p_reference, ''))), '');
    v_id     UUID;
    v_who    TEXT := public.acc_who();
BEGIN
    SELECT * INTO v_i FROM public.sales_invoices WHERE id = p_invoice_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'That invoice was not found.';
    END IF;
    PERFORM public.assert_business_member(v_i.business_id);
    PERFORM public.assert_permission(v_i.business_id, 'invoices.manage');
    IF v_i.status = 'void' THEN
        RAISE EXCEPTION 'This invoice is void.';
    END IF;
    IF v_i.balance <= 0 THEN
        RAISE EXCEPTION 'Nothing is owed on this invoice.';
    END IF;

    IF v_pid IS NULL THEN
        IF v_amount <= 0 THEN
            RAISE EXCEPTION 'Enter an amount above zero.';
        END IF;
        IF v_amount > v_i.balance THEN
            RAISE EXCEPTION 'Only % is owed on this invoice.', to_char(v_i.balance, 'FM999,999,990.00');
        END IF;
        -- A reference already in Payments (the same M-Pesa code) is that payment, not a new one.
        IF v_ref IS NOT NULL THEN
            SELECT id INTO v_pid FROM public.payments WHERE business_id = v_i.business_id AND reference_code = v_ref LIMIT 1;
        END IF;
        IF v_pid IS NULL THEN
            v_pid := public.process_business_payment(
                v_i.business_id, COALESCE(v_ref, 'INV-PAY-' || upper(left(replace(gen_random_uuid()::TEXT, '-', ''), 10))),
                v_amount, p_method, v_i.customer_name, v_i.customer_phone, 'Success', COALESCE(p_paid_at, NOW()),
                NULL, v_i.customer_name, 'walk-in', 'Invoice ' || v_i.number, v_who);
        END IF;
    END IF;

    SELECT * INTO v_py FROM public.payments WHERE id = v_pid AND business_id = v_i.business_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'That payment was not found in this branch.';
    END IF;
    IF v_py.status <> 'Success' THEN
        RAISE EXCEPTION 'Payment % is not a completed payment.', COALESCE(v_py.reference_code, '');
    END IF;
    IF COALESCE(v_py.debt_applied, 0) > 0 OR COALESCE(v_py.wallet_applied, 0) > 0 THEN
        RAISE EXCEPTION 'Payment % already went to a customer''s debt or wallet.', COALESCE(v_py.reference_code, '');
    END IF;
    SELECT COALESCE(SUM(amount), 0) INTO v_used FROM public.invoice_payments WHERE payment_id = v_pid AND voided_at IS NULL;
    IF v_amount <= 0 OR p_payment_id IS NOT NULL THEN
        v_amount := LEAST(v_py.amount - v_used, v_i.balance);
    END IF;
    IF v_amount <= 0 THEN
        RAISE EXCEPTION 'Payment % is already used in full.', COALESCE(v_py.reference_code, '');
    END IF;
    IF v_amount > v_py.amount - v_used THEN
        RAISE EXCEPTION 'Only % of payment % is still free.', to_char(v_py.amount - v_used, 'FM999,999,990.00'), COALESCE(v_py.reference_code, '');
    END IF;
    IF v_amount > v_i.balance THEN
        v_amount := v_i.balance;
    END IF;

    INSERT INTO public.invoice_payments (business_id, invoice_id, payment_id, amount, method, reference, paid_at, recorded_by)
    VALUES (v_i.business_id, v_i.id, v_pid, v_amount, v_py.method, v_py.reference_code, COALESCE(p_paid_at, v_py.date, NOW()), v_who)
    RETURNING id INTO v_id;
    PERFORM public.sd_invoice_refresh(v_i.id);
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."record_invoice_payment"("p_invoice_id" "uuid", "p_amount" numeric, "p_method" "text", "p_reference" "text", "p_paid_at" timestamp with time zone, "p_payment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_order_checkout"("p_order_id" "uuid", "p_checkout_request_id" "text", "p_merchant_request_id" "text", "p_phone" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    INSERT INTO public.mpesa_transactions
        (business_id, online_order_id, checkout_request_id, merchant_request_id, phone, amount)
    SELECT business_id, id, p_checkout_request_id, p_merchant_request_id, p_phone, total
    FROM public.online_orders
    WHERE id = p_order_id;

    UPDATE public.online_orders
    SET status = 'pending_payment'
    WHERE id = p_order_id AND status = 'payment_failed';
END;
$$;


ALTER FUNCTION "public"."record_order_checkout"("p_order_id" "uuid", "p_checkout_request_id" "text", "p_merchant_request_id" "text", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_petty_cash"("p_business_id" "uuid", "p_amount" numeric, "p_category" "text", "p_description" "text", "p_receipt_ref" "text" DEFAULT NULL::"text", "p_reference_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_me  public.employees;
    v_row public.expenses;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'pettycash.record', 'expenses.create');

    IF p_reference_id IS NOT NULL THEN
        SELECT * INTO v_row FROM public.expenses WHERE business_id = p_business_id AND reference_id = p_reference_id;
        IF FOUND THEN
            RETURN jsonb_build_object('id', v_row.id, 'amount', v_row.amount);
        END IF;
    END IF;

    IF COALESCE(p_amount, 0) <= 0 THEN
        RAISE EXCEPTION 'Enter how much was spent.';
    END IF;
    IF p_amount > 1000000 THEN
        RAISE EXCEPTION 'That amount is too large for petty cash. Ask a manager to record it as an expense.';
    END IF;
    IF NULLIF(btrim(COALESCE(p_description, '')), '') IS NULL THEN
        RAISE EXCEPTION 'Say what the money was spent on.';
    END IF;

    v_me := public.fn_my_employee(p_business_id);

    INSERT INTO public.expenses (
        business_id, category, amount, description, date, staff_name, receipt_ref,
        payment_method, source, employee_id, reference_id, last_modified_by
    ) VALUES (
        p_business_id,
        COALESCE(NULLIF(btrim(p_category), ''), 'Petty cash'),
        ROUND(p_amount, 2),
        btrim(p_description),
        NOW(),
        COALESCE(v_me.name, 'Staff'),
        NULLIF(btrim(COALESCE(p_receipt_ref, '')), ''),
        'Cash',
        'petty_cash',
        v_me.id,
        p_reference_id,
        COALESCE(v_me.name, 'Staff')
    )
    RETURNING * INTO v_row;

    RETURN jsonb_build_object('id', v_row.id, 'amount', v_row.amount);
END;
$$;


ALTER FUNCTION "public"."record_petty_cash"("p_business_id" "uuid", "p_amount" numeric, "p_category" "text", "p_description" "text", "p_receipt_ref" "text", "p_reference_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_supplier_payment"("p_business_id" "uuid", "p_supplier_id" "uuid", "p_supplier_name" "text", "p_purchase_id" "uuid", "p_amount" numeric, "p_method" "text", "p_reference" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_paid_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_name TEXT := NULLIF(trim(COALESCE(p_supplier_name, '')), '');
    v_by   TEXT := public.acc_who();
    v_id   UUID;
    v_lock DATE;
    v_at   TIMESTAMPTZ := COALESCE(p_paid_at, NOW());
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'accounting.manage', 'purchases.approve');
    IF COALESCE(p_amount, 0) <= 0 THEN RAISE EXCEPTION 'Enter how much was paid.'; END IF;
    IF p_method NOT IN ('Cash', 'M-Pesa', 'Airtel Money', 'Card', 'Bank') THEN
        RAISE EXCEPTION 'Choose Cash, M-Pesa, Airtel Money, Card or Bank.';
    END IF;
    IF p_supplier_id IS NOT NULL THEN
        SELECT name INTO v_name FROM public.suppliers WHERE id = p_supplier_id AND business_id = p_business_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'That supplier was not found.'; END IF;
    END IF;
    IF p_purchase_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.purchases WHERE id = p_purchase_id AND business_id = p_business_id) THEN
        RAISE EXCEPTION 'That purchase was not found.';
    END IF;
    IF v_name IS NULL THEN RAISE EXCEPTION 'Choose the supplier.'; END IF;
    SELECT lock_date INTO v_lock FROM public.acc_settings WHERE business_id = p_business_id;
    IF v_lock IS NOT NULL AND (v_at AT TIME ZONE 'Africa/Nairobi')::DATE <= v_lock THEN
        RAISE EXCEPTION 'The books are locked up to %. Choose a later date.', to_char(v_lock, 'DD Mon YYYY');
    END IF;

    INSERT INTO public.supplier_payments (business_id, supplier_id, supplier_name, purchase_id, amount, method, paid_at, reference, note, recorded_by)
    VALUES (p_business_id, p_supplier_id, v_name, p_purchase_id, round(p_amount, 2), p_method, v_at,
            NULLIF(trim(COALESCE(p_reference, '')), ''), NULLIF(trim(COALESCE(p_note, '')), ''), v_by)
    RETURNING id INTO v_id;

    PERFORM public.fn_post_money_asset(p_business_id, p_method, -round(p_amount, 2), 'Paid supplier ' || v_name, NULL, NULL, v_by);
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."record_supplier_payment"("p_business_id" "uuid", "p_supplier_id" "uuid", "p_supplier_name" "text", "p_purchase_id" "uuid", "p_amount" numeric, "p_method" "text", "p_reference" "text", "p_note" "text", "p_paid_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_till_payment"("p_raw" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_trans_id  TEXT := NULLIF(trim(p_raw->>'TransID'), '');
    v_amount    NUMERIC := NULLIF(p_raw->>'TransAmount', '')::NUMERIC;
    v_short     TEXT := NULLIF(trim(p_raw->>'BusinessShortCode'), '');
    v_ref       TEXT := NULLIF(trim(p_raw->>'BillRefNumber'), '');
    v_name      TEXT := NULLIF(trim(concat_ws(' ', p_raw->>'FirstName', p_raw->>'MiddleName', p_raw->>'LastName')), '');
    v_time      TIMESTAMPTZ;
    v_biz       UUID;
    v_cust_id   UUID;
    v_cust_name TEXT;
    v_row_id    UUID;
    v_pid       UUID;
BEGIN
    IF v_trans_id IS NULL OR COALESCE(v_amount, 0) <= 0 THEN
        RAISE EXCEPTION 'Till confirmation is missing TransID or TransAmount.';
    END IF;

    BEGIN
        -- Safaricom sends Nairobi local time as YYYYMMDDHHmmss.
        v_time := COALESCE(to_timestamp(p_raw->>'TransTime', 'YYYYMMDDHH24MISS')::TIMESTAMP AT TIME ZONE 'Africa/Nairobi', NOW());
    EXCEPTION WHEN OTHERS THEN
        v_time := NOW();
    END;

    SELECT business_id INTO v_biz FROM public.mpesa_settings WHERE till_number = v_short;
    IF v_biz IS NULL AND (SELECT count(*) FROM public.mpesa_settings WHERE till_number IS NOT NULL) = 1 THEN
        -- Some tills report the store number here, so a single configured till takes it.
        SELECT business_id INTO v_biz FROM public.mpesa_settings WHERE till_number IS NOT NULL;
    END IF;

    INSERT INTO public.mpesa_till_payments (
        business_id, trans_id, trans_type, amount, short_code, bill_ref, msisdn, payer_name, trans_time, raw
    )
    VALUES (
        v_biz, v_trans_id, p_raw->>'TransactionType', v_amount, v_short, v_ref,
        NULLIF(p_raw->>'MSISDN', ''), v_name, v_time, p_raw
    )
    ON CONFLICT (trans_id) DO NOTHING
    RETURNING id INTO v_row_id;

    IF v_row_id IS NULL THEN
        RETURN 'duplicate';
    END IF;
    IF v_biz IS NULL THEN
        RAISE WARNING 'Till payment % for short code % matches no business', v_trans_id, v_short;
        RETURN 'no_business';
    END IF;

    -- Paybill-style payments carry the account number, so those settle themselves.
    IF v_ref IS NOT NULL THEN
        SELECT id, name INTO v_cust_id, v_cust_name FROM public.customers
        WHERE business_id = v_biz AND deleted_at IS NULL
          AND upper(account_number) = upper(v_ref);
    END IF;

    IF v_cust_id IS NOT NULL THEN
        v_pid := public.process_business_payment(
            v_biz, v_trans_id, v_amount, 'M-Pesa', COALESCE(v_name, v_cust_name),
            p_raw->>'MSISDN', 'Success', v_time, v_cust_id, v_cust_name, 'customer',
            'M-Pesa till payment', 'M-Pesa'
        );
        UPDATE public.mpesa_till_payments
        SET status = 'recorded', customer_id = v_cust_id, payment_id = v_pid,
            handled_by = 'Matched by account number', handled_at = NOW()
        WHERE id = v_row_id;
        PERFORM public.fn_notify_staff(v_biz, 'M-Pesa payment received',
            format('Ksh %s from %s (%s).', v_amount, v_cust_name, v_trans_id),
            jsonb_build_object('paymentId', v_pid));
        RETURN 'recorded';
    END IF;

    PERFORM public.fn_notify_staff(v_biz, 'M-Pesa till payment to assign',
        format('Ksh %s from %s (%s). Open Payments > M-Pesa to assign it.', v_amount, COALESCE(v_name, 'a customer'), v_trans_id),
        jsonb_build_object('tillPaymentId', v_row_id));
    RETURN 'queued';
END;
$$;


ALTER FUNCTION "public"."record_till_payment"("p_raw" "jsonb") OWNER TO "postgres";


