CREATE OR REPLACE FUNCTION "public"."refresh_dashboard_snapshot"("p_business_id" "uuid", "p_date" "date" DEFAULT CURRENT_DATE, "p_timeframe" "text" DEFAULT 'daily'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_start          TIMESTAMPTZ;
    v_end            TIMESTAMPTZ;
    v_total_sales    NUMERIC(14,2);
    v_total_expenses NUMERIC(14,2);
    v_order_count    INTEGER;
    v_avg_order      NUMERIC(14,2);
    v_top_product    UUID;
    v_top_category   TEXT;
    v_pay_breakdown  JSONB;
BEGIN
    v_end := (p_date + 1)::TIMESTAMPTZ;
    v_start := CASE p_timeframe
        WHEN 'weekly'  THEN (p_date - INTERVAL '6 days')::TIMESTAMPTZ
        WHEN 'monthly' THEN (p_date - INTERVAL '29 days')::TIMESTAMPTZ
        ELSE p_date::TIMESTAMPTZ
    END;

    SELECT
        COALESCE(SUM(final_total), 0),
        COUNT(*),
        COALESCE(AVG(final_total), 0)
    INTO v_total_sales, v_order_count, v_avg_order
    FROM public.transactions
    WHERE business_id = p_business_id
      AND timestamp >= v_start
      AND timestamp < v_end
      AND deleted_at IS NULL;

    SELECT COALESCE(SUM(amount), 0)
    INTO v_total_expenses
    FROM public.expenses
    WHERE business_id = p_business_id
      AND date >= v_start
      AND date < v_end
      AND deleted_at IS NULL;

    SELECT p.id
    INTO v_top_product
    FROM public.transaction_items ti
    JOIN public.transactions t ON ti.transaction_id = t.id
    JOIN public.products p ON ti.product_id = p.id
    WHERE t.business_id = p_business_id
      AND t.timestamp >= v_start
      AND t.timestamp < v_end
      AND t.deleted_at IS NULL
    GROUP BY p.id
    ORDER BY SUM(ti.quantity) DESC
    LIMIT 1;

    SELECT p.category
    INTO v_top_category
    FROM public.transaction_items ti
    JOIN public.transactions t ON ti.transaction_id = t.id
    JOIN public.products p ON ti.product_id = p.id
    WHERE t.business_id = p_business_id
      AND t.timestamp >= v_start
      AND t.timestamp < v_end
      AND t.deleted_at IS NULL
    GROUP BY p.category
    ORDER BY SUM(ti.line_total) DESC
    LIMIT 1;

    SELECT jsonb_object_agg(payment_method, total_amount)
    INTO v_pay_breakdown
    FROM (
        SELECT
            payment_method::TEXT,
            SUM(final_total) AS total_amount
        FROM public.transactions
        WHERE business_id = p_business_id
          AND timestamp >= v_start
          AND timestamp < v_end
          AND deleted_at IS NULL
        GROUP BY payment_method
    ) pm;

    INSERT INTO public.dashboard_analytics_snapshots
        (business_id, snapshot_date, timeframe, total_sales, total_expenses,
         order_count, avg_order_value, top_product_id, top_category, payment_breakdown)
    VALUES (
        p_business_id, p_date, p_timeframe,
        v_total_sales, v_total_expenses,
        v_order_count, v_avg_order,
        v_top_product, v_top_category,
        COALESCE(v_pay_breakdown, '{}')
    )
    ON CONFLICT (business_id, snapshot_date, timeframe) DO UPDATE SET
        total_sales     = EXCLUDED.total_sales,
        total_expenses  = EXCLUDED.total_expenses,
        order_count     = EXCLUDED.order_count,
        avg_order_value = EXCLUDED.avg_order_value,
        top_product_id  = EXCLUDED.top_product_id,
        top_category    = EXCLUDED.top_category,
        payment_breakdown = EXCLUDED.payment_breakdown;
END;
$$;


ALTER FUNCTION "public"."refresh_dashboard_snapshot"("p_business_id" "uuid", "p_date" "date", "p_timeframe" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refund_till_points"("p_redemption_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_row public.loyalty_redemptions%ROWTYPE;
BEGIN
    SELECT * INTO v_row FROM public.loyalty_redemptions
    WHERE id = p_redemption_id AND refunded_at IS NULL AND order_id IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    PERFORM public.assert_permission(v_row.business_id, 'customers.loyalty');

    UPDATE public.customers SET loyalty_points = loyalty_points + v_row.points WHERE id = v_row.customer_id;
    UPDATE public.loyalty_redemptions SET refunded_at = NOW() WHERE id = p_redemption_id;
END;
$$;


ALTER FUNCTION "public"."refund_till_points"("p_redemption_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_device_token"("p_token" "text", "p_platform" "text" DEFAULT 'android'::"text", "p_sound" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_me UUID := (SELECT u.id FROM public.users u WHERE u.auth_user_id = auth.uid());
BEGIN
    IF v_me IS NULL THEN
        RAISE EXCEPTION 'Please sign in again.' USING ERRCODE = '42501';
    END IF;
    IF p_token IS NULL OR length(p_token) < 20 OR length(p_token) > 4096 THEN
        RAISE EXCEPTION 'That device token is not valid.';
    END IF;

    -- A token is one phone. Whoever registers it now is its only owner.
    DELETE FROM public.device_fcm_tokens WHERE device_token = p_token AND user_id <> v_me;

    INSERT INTO public.device_fcm_tokens (user_id, device_token, device_type, sound, updated_at)
    VALUES (v_me, p_token, left(COALESCE(p_platform, 'android'), 20),
            COALESCE(NULLIF(left(p_sound, 60), ''), 'beep'), NOW())   -- 'beep' is the column default
    ON CONFLICT (user_id, device_token) DO UPDATE
        SET device_type = EXCLUDED.device_type,
            sound = CASE WHEN NULLIF(p_sound, '') IS NULL THEN public.device_fcm_tokens.sound ELSE EXCLUDED.sound END,
            updated_at = NOW();
END;
$$;


ALTER FUNCTION "public"."register_device_token"("p_token" "text", "p_platform" "text", "p_sound" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_purchase"("p_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_p  public.purchases%ROWTYPE;
    v_me TEXT;
BEGIN
    SELECT * INTO v_p FROM public.purchases WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That purchase was not found.'; END IF;
    PERFORM public.assert_business_member(v_p.business_id);
    PERFORM public.assert_permission(v_p.business_id, 'purchases.approve');
    IF v_p.status <> 'Awaiting approval' THEN
        RAISE EXCEPTION 'This purchase is not waiting for approval.';
    END IF;
    IF NULLIF(trim(COALESCE(p_reason, '')), '') IS NULL THEN
        RAISE EXCEPTION 'Say why it is not approved.';
    END IF;
    v_me := public.fn_my_display_name(v_p.business_id);
    PERFORM public.fn_buying_ctx();
    UPDATE public.purchases
    SET status = 'Pending', rejected_by = v_me, rejected_at = NOW(), reject_reason = trim(p_reason), updated_at = NOW()
    WHERE id = p_id;
    IF v_p.requested_by_user_id IS NOT NULL THEN
        PERFORM public.fn_buying_notify(v_p.business_id, v_p.requested_by_user_id, 'Purchase Approval', 'Purchase not approved',
            v_me || ' did not approve ' || public.fn_purchase_ref(v_p) || ' to ' || v_p.supplier_name || ': ' || trim(p_reason)
                || '. It is back to a draft.',
            'suppliers', jsonb_build_object('purchaseId', v_p.id));
    END IF;
END;
$$;


ALTER FUNCTION "public"."reject_purchase"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_petty_cash"("p_expense_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_row public.expenses;
    v_me  public.employees;
BEGIN
    SELECT * INTO v_row FROM public.expenses WHERE id = p_expense_id AND source = 'petty_cash' FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Entry not found.';
    END IF;
    PERFORM public.assert_business_member(v_row.business_id);
    IF v_row.deleted_at IS NOT NULL THEN
        RETURN;
    END IF;
    IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
        RAISE EXCEPTION 'Say why this entry is being removed.';
    END IF;

    v_me := public.fn_my_employee(v_row.business_id);
    IF NOT public.has_permission(v_row.business_id, 'expenses.delete') THEN
        IF v_me.id IS NULL OR v_row.employee_id IS DISTINCT FROM v_me.id THEN
            RAISE EXCEPTION 'Only a manager can remove someone else''s entry.' USING ERRCODE = '42501';
        END IF;
        IF v_row.created_at < NOW() - INTERVAL '24 hours' THEN
            RAISE EXCEPTION 'This entry is more than a day old. Ask a manager to remove it.' USING ERRCODE = '42501';
        END IF;
    END IF;

    UPDATE public.expenses
    SET deleted_at = NOW(),
        removed_by = COALESCE(v_me.name, 'Staff'),
        removed_reason = btrim(p_reason),
        last_modified_by = COALESCE(v_me.name, 'Staff')
    WHERE id = p_expense_id;
END;
$$;


ALTER FUNCTION "public"."remove_petty_cash"("p_expense_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_supplier_access"("p_account_id" "uuid" DEFAULT NULL::"uuid", "p_invitation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_b UUID;
BEGIN
    IF p_account_id IS NOT NULL THEN
        SELECT business_id INTO v_b FROM public.supplier_accounts WHERE id = p_account_id;
    ELSE
        SELECT business_id INTO v_b FROM public.invitations WHERE id = p_invitation_id AND supplier_id IS NOT NULL;
    END IF;
    IF v_b IS NULL THEN RAISE EXCEPTION 'That access was not found.'; END IF;
    PERFORM public.assert_business_member(v_b);
    PERFORM public.assert_permission(v_b, 'suppliers.portal');
    IF p_account_id IS NOT NULL THEN
        UPDATE public.supplier_accounts
        SET status = 'removed', removed_at = NOW(), removed_by = public.fn_my_display_name(v_b)
        WHERE id = p_account_id;
    ELSE
        DELETE FROM public.invitations WHERE id = p_invitation_id;
    END IF;
END;
$$;


ALTER FUNCTION "public"."remove_supplier_access"("p_account_id" "uuid", "p_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_overview"("p_business_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_safety INTEGER;
    v_out    JSONB;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'purchases.view', 'purchases.create', 'inventory.request_transfer');
    SELECT safety_days INTO v_safety FROM public.buying_settings WHERE business_id = p_business_id;
    v_safety := COALESCE(v_safety, 3);

    WITH prods AS (
        SELECT p.*, COALESCE(p.reorder_level, NULLIF(p.min_stock, 0)) AS lvl
        FROM public.products p
        WHERE p.business_id = p_business_id AND p.deleted_at IS NULL
    ), sold AS (
        SELECT ti.product_id, SUM(ti.quantity) AS qty
        FROM public.transaction_items ti
        JOIN public.transactions t ON t.id = ti.transaction_id
        WHERE t.business_id = p_business_id AND t.deleted_at IS NULL AND t.timestamp >= NOW() - INTERVAL '30 days'
        GROUP BY ti.product_id
    ), ordered AS (
        SELECT pi.product_id, SUM(GREATEST(pi.quantity - pi.qty_received, 0)) AS qty
        FROM public.purchase_items pi JOIN public.purchases pu ON pu.id = pi.purchase_id
        WHERE pu.business_id = p_business_id AND pu.status IN ('Pending', 'RFQ', 'Awaiting approval', 'Ordered', 'Part received')
          AND pi.product_id IS NOT NULL AND (pi.for_business_id IS NULL OR pi.for_business_id = p_business_id)
        GROUP BY pi.product_id
    ), coming AS (
        SELECT p.id AS product_id, SUM(i.quantity_sent) AS qty
        FROM public.stock_transfers t
        JOIN public.stock_transfer_items i ON i.transfer_id = t.id
        JOIN prods p ON i.to_product_id = p.id
             OR (i.to_product_id IS NULL AND ((NULLIF(i.sku, '') IS NOT NULL AND i.sku = p.sku) OR lower(btrim(i.product_name)) = lower(btrim(p.name))))
        WHERE t.to_business_id = p_business_id AND t.status IN ('requested', 'draft', 'awaiting_approval', 'in_transit')
        GROUP BY p.id
    ), calc AS (
        SELECT p.*, COALESCE(s.qty, 0) AS sold30, COALESCE(o.qty, 0) AS on_order, COALESCE(c.qty, 0) AS on_way,
               CASE WHEN p.lvl IS NOT NULL AND p.stock <= p.lvl
                    THEN GREATEST(COALESCE(p.reorder_qty, p.lvl * 2 - p.stock), 0) ELSE 0 END AS want
        FROM prods p
        LEFT JOIN sold s ON s.product_id = p.id
        LEFT JOIN ordered o ON o.product_id = p.id
        LEFT JOIN coming c ON c.product_id = p.id
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'productId', c.id, 'name', c.name, 'unit', c.unit, 'sku', c.sku, 'category', c.category,
        'stock', c.stock, 'cost', c.cost, 'minStock', c.min_stock,
        'reorderLevel', c.reorder_level, 'reorderQty', c.reorder_qty, 'level', c.lvl,
        'supplierId', c.preferred_supplier_id, 'supplierName', (SELECT COALESCE(NULLIF(s.company, ''), s.name) FROM public.suppliers s WHERE s.id = c.preferred_supplier_id),
        'supplierPrice', c.supplier_price, 'leadDays', c.lead_time_days,
        'sold30', c.sold30, 'avgDaily', round(c.sold30 / 30.0, 3),
        'suggestedLevel', CASE WHEN c.sold30 > 0 THEN ceil(c.sold30 / 30.0 * (COALESCE(c.lead_time_days, 3) + v_safety)) END,
        'onOrder', c.on_order, 'onTheWay', c.on_way,
        'low', c.lvl IS NOT NULL AND c.stock <= c.lvl,
        'need', GREATEST(c.want - c.on_order - c.on_way, 0),
        'transferFrom', CASE WHEN c.want - c.on_order - c.on_way > 0 THEN (
            SELECT jsonb_build_object('businessId', b.id, 'name', b.name, 'productId', x.id, 'spare', x.stock - COALESCE(x.reorder_level, NULLIF(x.min_stock, 0), 0))
            FROM public.businesses b
            JOIN public.products x ON x.business_id = b.id AND x.deleted_at IS NULL
                 AND ((NULLIF(c.sku, '') IS NOT NULL AND x.sku = c.sku) OR lower(btrim(x.name)) = lower(btrim(c.name)))
                 AND lower(btrim(x.unit)) = lower(btrim(c.unit))
            WHERE b.id <> p_business_id AND b.deleted_at IS NULL AND public.fn_branches_share_owner(p_business_id, b.id)
              AND x.stock - COALESCE(x.reorder_level, NULLIF(x.min_stock, 0), 0) >= c.want - c.on_order - c.on_way
            ORDER BY x.stock - COALESCE(x.reorder_level, NULLIF(x.min_stock, 0), 0) DESC
            LIMIT 1) END
    ) ORDER BY (c.lvl IS NOT NULL AND c.stock <= c.lvl) DESC, c.name), '[]'::JSONB) INTO v_out
    FROM calc c;

    RETURN jsonb_build_object('products', v_out, 'safetyDays', v_safety);
END;
$$;


ALTER FUNCTION "public"."reorder_overview"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_crash"("p_fingerprint" "text", "p_message" "text", "p_stack" "text", "p_screen" "text", "p_platform" "text", "p_app_version" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_business_id UUID := (public.get_user_business_ids())[1];
BEGIN
    IF v_business_id IS NULL AND (SELECT COUNT(*) FROM public.crash_reports WHERE business_id IS NULL) >= 2000 THEN
        RETURN;
    END IF;

    INSERT INTO public.crash_reports (business_id, fingerprint, message, stack, screen, platform, app_version)
    VALUES (v_business_id, LEFT(p_fingerprint, 64), LEFT(p_message, 500), LEFT(p_stack, 4000),
            LEFT(p_screen, 64), LEFT(p_platform, 32), LEFT(p_app_version, 32))
    ON CONFLICT (COALESCE(business_id, '00000000-0000-0000-0000-000000000000'::UUID), fingerprint)
    DO UPDATE SET occurrences = public.crash_reports.occurrences + 1, last_seen_at = NOW();
END;
$$;


ALTER FUNCTION "public"."report_crash"("p_fingerprint" "text", "p_message" "text", "p_stack" "text", "p_screen" "text", "p_platform" "text", "p_app_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_password_reset_otp"("p_email" "text") RETURNS TABLE("user_exists" boolean, "user_name" "text", "otp_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_name TEXT;
    v_otp       TEXT;
    v_clean_email TEXT;
BEGIN
    v_clean_email := LOWER(TRIM(p_email));

    -- Check if user exists in public.users (case-insensitive)
    SELECT u.name INTO v_user_name
    FROM public.users u
    WHERE LOWER(TRIM(u.email)) = v_clean_email
    LIMIT 1;

    -- Fallback: check auth.users metadata if not found in public.users
    IF v_user_name IS NULL THEN
        SELECT COALESCE(raw_user_meta_data->>'full_name', raw_user_meta_data->>'name', 'User') INTO v_user_name
        FROM auth.users
        WHERE LOWER(TRIM(email)) = v_clean_email
        LIMIT 1;
    END IF;

    -- If user does not exist in either table, return false
    IF v_user_name IS NULL THEN
        RETURN QUERY SELECT FALSE, NULL::TEXT, NULL::TEXT;
        RETURN;
    END IF;

    -- Generate random 6-digit OTP code
    v_otp := LPAD(FLOOR(RANDOM() * 900000 + 100000)::TEXT, 6, '0');

    -- Save OTP in public.otps table
    INSERT INTO public.otps (email, code, type, expires_at)
    VALUES (v_clean_email, v_otp, 'password_reset', NOW() + INTERVAL '15 minutes')
    ON CONFLICT (email, type) DO UPDATE SET
        code       = EXCLUDED.code,
        expires_at = EXCLUDED.expires_at,
        created_at = NOW();

    RETURN QUERY SELECT TRUE, v_user_name, v_otp;
END;
$$;


ALTER FUNCTION "public"."request_password_reset_otp"("p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_stock_transfer"("p_to_business_id" "uuid", "p_from_business_id" "uuid", "p_items" "jsonb", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_t    public.stock_transfers%ROWTYPE;
    v_line RECORD;
    v_me   TEXT;
    v_name TEXT;
    v_n    INTEGER := 0;
BEGIN
    PERFORM public.assert_business_member(p_to_business_id);
    PERFORM public.assert_permission(p_to_business_id, 'inventory.request_transfer', 'inventory.transfer_stock');
    IF p_from_business_id IS NULL OR p_from_business_id = p_to_business_id
       OR NOT EXISTS (SELECT 1 FROM public.businesses WHERE id = p_from_business_id AND deleted_at IS NULL)
       OR NOT public.fn_branches_share_owner(p_from_business_id, p_to_business_id) THEN
        RAISE EXCEPTION 'You can only ask another branch of this business.';
    END IF;
    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'Add at least one product to ask for.';
    END IF;
    IF jsonb_array_length(p_items) > 200 THEN
        RAISE EXCEPTION 'Ask for at most 200 products at a time.';
    END IF;
    v_me := public.fn_my_display_name(p_to_business_id);

    INSERT INTO public.stock_transfers (
        reference, from_business_id, to_business_id, status, note, requested_by_name, requested_by_user_id, requested_at, request_note
    ) VALUES (
        'TR-' || to_char(NOW() AT TIME ZONE 'Africa/Nairobi', 'YYMMDD') || '-' || upper(substr(md5(gen_random_uuid()::TEXT), 1, 5)),
        p_from_business_id, p_to_business_id, 'requested', NULLIF(btrim(COALESCE(p_note, '')), ''),
        v_me, public.fn_my_user_id(), NOW(), NULLIF(btrim(COALESCE(p_note, '')), '')
    ) RETURNING * INTO v_t;

    FOR v_line IN
        WITH wanted AS (
            SELECT (e->>'product_id')::UUID AS product_id, SUM((e->>'quantity')::NUMERIC) AS qty
            FROM jsonb_array_elements(p_items) e GROUP BY 1
        )
        SELECT p.*, w.qty,
               CASE WHEN p.business_id = p_to_business_id THEN p.id ELSE (
                   -- Picked from the other branch's list: the same product here, if there is one
                   -- (same SKU, else same name); none means receiving adds it.
                   SELECT x.id FROM public.products x
                   WHERE x.business_id = p_to_business_id AND x.deleted_at IS NULL
                     AND ((NULLIF(p.sku, '') IS NOT NULL AND x.sku = p.sku) OR lower(btrim(x.name)) = lower(btrim(p.name)))
                   ORDER BY (x.sku IS NOT DISTINCT FROM p.sku) DESC, x.created_at
                   LIMIT 1) END AS here_id
        FROM wanted w
        JOIN public.products p ON p.id = w.product_id AND p.business_id IN (p_to_business_id, p_from_business_id) AND p.deleted_at IS NULL
    LOOP
        IF v_line.qty IS NULL OR v_line.qty <= 0 THEN
            RAISE EXCEPTION 'Enter how much % you need.', v_line.name;
        END IF;
        INSERT INTO public.stock_transfer_items (
            transfer_id, to_product_id, product_name, sku, unit, category, unit_cost, unit_price, quantity_sent, quantity_requested
        ) VALUES (
            v_t.id, v_line.here_id, v_line.name, v_line.sku, v_line.unit, v_line.category, 0, v_line.price,
            ROUND(v_line.qty, 3), ROUND(v_line.qty, 3)
        );
        v_n := v_n + 1;
    END LOOP;
    IF v_n = 0 THEN
        RAISE EXCEPTION 'Those products were not found. Refresh and try again.';
    END IF;

    SELECT name INTO v_name FROM public.businesses WHERE id = p_to_business_id;
    INSERT INTO public.notifications (business_id, title, message, type, priority, action_type, action_target, payload, created_by)
    VALUES (
        p_from_business_id, 'Stock requested',
        v_name || ' is asking for ' || v_n || CASE WHEN v_n = 1 THEN ' product' ELSE ' products' END
            || ' (' || v_t.reference || ')' || COALESCE(': ' || v_t.request_note, '') || '. Send it or decline.',
        'Stock Transfer', 'high', 'navigate', 'stock-transfers',
        jsonb_build_object('transferId', v_t.id, 'reference', v_t.reference), 'system'
    );
    RETURN jsonb_build_object('id', v_t.id, 'reference', v_t.reference, 'status', 'requested', 'lines', v_n);
END;
$$;


ALTER FUNCTION "public"."request_stock_transfer"("p_to_business_id" "uuid", "p_from_business_id" "uuid", "p_items" "jsonb", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rider_accept_delivery"("p_source" "text", "p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_order    public.online_orders%ROWTYPE;
    v_sale     public.transactions%ROWTYPE;
    v_user     UUID;
    v_employee UUID;
    v_name     TEXT;
BEGIN
    IF p_source = 'online' THEN
        SELECT * INTO v_order FROM public.online_orders WHERE id = p_id FOR UPDATE;
        IF NOT FOUND OR v_order.fulfilment <> 'delivery' THEN
            RAISE EXCEPTION 'That delivery was not found.';
        END IF;
        PERFORM public.assert_permission(v_order.business_id, 'deliveries.complete');
        v_user := public.fn_my_rider_user(v_order.business_id);
        v_employee := public.fn_sync_employee(v_order.business_id, v_user);

        IF v_order.rider_id = v_employee THEN
            RETURN;
        END IF;
        IF v_order.rider_id IS NOT NULL THEN
            RAISE EXCEPTION 'Another rider has already taken this delivery.';
        END IF;
        IF v_order.status NOT IN ('paid', 'preparing') THEN
            RAISE EXCEPTION 'This delivery is no longer open.';
        END IF;

        SELECT name INTO v_name FROM public.users WHERE id = v_user;
        UPDATE public.online_orders SET rider_id = v_employee, rider_assigned_at = NOW() WHERE id = p_id;
        PERFORM public.fn_notify_staff(v_order.business_id, 'Rider accepted delivery',
            COALESCE(v_name, 'A rider') || ' will deliver order #' || v_order.order_number || '.',
            jsonb_build_object('orderId', p_id));
        PERFORM public.fn_customer_message(v_order.account_id, p_id,
            'A rider has picked up your order #' || v_order.order_number || '. It will be on its way soon.');
    ELSIF p_source = 'sale' THEN
        SELECT * INTO v_sale FROM public.transactions WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
        IF NOT FOUND OR NOT v_sale.is_delivery THEN
            RAISE EXCEPTION 'That delivery was not found.';
        END IF;
        PERFORM public.assert_permission(v_sale.business_id, 'deliveries.complete');
        v_user := public.fn_my_rider_user(v_sale.business_id);
        v_employee := public.fn_sync_employee(v_sale.business_id, v_user);

        IF v_sale.rider_id = v_employee THEN
            RETURN;
        END IF;
        IF v_sale.rider_id IS NOT NULL OR NULLIF(trim(COALESCE(v_sale.rider_name, '')), '') IS NOT NULL THEN
            RAISE EXCEPTION 'Another rider has already taken this delivery.';
        END IF;
        IF COALESCE(v_sale.delivery_status, 'assigned') <> 'assigned' THEN
            RAISE EXCEPTION 'This delivery is no longer open.';
        END IF;

        SELECT name INTO v_name FROM public.users WHERE id = v_user;
        UPDATE public.transactions
        SET rider_id = v_employee, rider_name = COALESCE(v_name, 'Rider'), delivery_status = 'assigned'
        WHERE id = p_id;
    ELSE
        RAISE EXCEPTION 'That delivery was not found.';
    END IF;
END;
$$;


ALTER FUNCTION "public"."rider_accept_delivery"("p_source" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rider_release_delivery"("p_source" "text", "p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_order public.online_orders%ROWTYPE;
    v_sale  public.transactions%ROWTYPE;
    v_user  UUID;
BEGIN
    IF p_source = 'online' THEN
        SELECT * INTO v_order FROM public.online_orders WHERE id = p_id FOR UPDATE;
        IF NOT FOUND OR v_order.rider_id IS NULL
           OR v_order.rider_id IS DISTINCT FROM public.fn_my_employee_id(v_order.business_id) THEN
            RAISE EXCEPTION 'This delivery is not assigned to you.' USING ERRCODE = '42501';
        END IF;
        PERFORM public.assert_permission(v_order.business_id, 'deliveries.complete');
        IF v_order.status NOT IN ('paid', 'preparing') THEN
            RAISE EXCEPTION 'You have already started this delivery.';
        END IF;
        SELECT u.id INTO v_user FROM public.users u WHERE u.auth_user_id = auth.uid();

        UPDATE public.online_orders SET rider_id = NULL, rider_assigned_at = NULL WHERE id = p_id;
        PERFORM public.fn_notify_staff(v_order.business_id, 'Delivery needs a rider',
            'The rider gave back order #' || v_order.order_number || '.', jsonb_build_object('orderId', p_id));
        PERFORM public.fn_notify_riders(v_order.business_id, 'Delivery request',
            'Order #' || v_order.order_number || COALESCE(' to ' || v_order.delivery_zone, '') || ' needs a rider.',
            jsonb_build_object('orderId', p_id), v_user);
    ELSIF p_source = 'sale' THEN
        SELECT * INTO v_sale FROM public.transactions WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
        IF NOT FOUND OR v_sale.rider_id IS NULL
           OR v_sale.rider_id IS DISTINCT FROM public.fn_my_employee_id(v_sale.business_id) THEN
            RAISE EXCEPTION 'This delivery is not assigned to you.' USING ERRCODE = '42501';
        END IF;
        PERFORM public.assert_permission(v_sale.business_id, 'deliveries.complete');
        IF COALESCE(v_sale.delivery_status, 'assigned') <> 'assigned' THEN
            RAISE EXCEPTION 'You have already started this delivery.';
        END IF;
        SELECT u.id INTO v_user FROM public.users u WHERE u.auth_user_id = auth.uid();

        UPDATE public.transactions SET rider_id = NULL, rider_name = NULL WHERE id = p_id;
        PERFORM public.fn_notify_riders(v_sale.business_id, 'Delivery request',
            'A till delivery for ' || COALESCE(v_sale.customer_name, 'a customer') || ' needs a rider.',
            jsonb_build_object('saleId', p_id), v_user);
    ELSE
        RAISE EXCEPTION 'That delivery was not found.';
    END IF;
END;
$$;


ALTER FUNCTION "public"."rider_release_delivery"("p_source" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rider_update_delivery"("p_source" "text", "p_id" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_order public.online_orders%ROWTYPE;
    v_sale  public.transactions%ROWTYPE;
BEGIN
    IF p_status NOT IN ('out_for_delivery', 'delivered', 'failed') THEN
        RAISE EXCEPTION 'That delivery status is not valid.';
    END IF;

    IF p_source = 'online' THEN
        SELECT * INTO v_order FROM public.online_orders WHERE id = p_id FOR UPDATE;
        IF NOT FOUND OR v_order.rider_id IS NULL
           OR v_order.rider_id IS DISTINCT FROM public.fn_my_employee_id(v_order.business_id) THEN
            RAISE EXCEPTION 'This delivery is not assigned to you.' USING ERRCODE = '42501';
        END IF;
        PERFORM public.assert_permission(v_order.business_id, CASE WHEN p_status = 'failed' THEN 'deliveries.cancel' ELSE 'deliveries.complete' END);

        IF p_status = 'failed' THEN
            -- Staff decide what happens next, because the customer has already paid.
            UPDATE public.online_orders
            SET needs_attention = TRUE,
                attention_reason = concat_ws(' ', attention_reason, 'The rider could not complete this delivery.'),
                rider_id = NULL
            WHERE id = p_id;
            PERFORM public.fn_notify_staff(v_order.business_id, 'Delivery not completed',
                'Order #' || v_order.order_number || ' could not be delivered.', jsonb_build_object('orderId', p_id));
        ELSIF p_status = 'out_for_delivery' THEN
            IF v_order.status NOT IN ('paid', 'preparing') THEN
                RAISE EXCEPTION 'This order can''t go out for delivery yet.';
            END IF;
            UPDATE public.online_orders SET status = 'out_for_delivery' WHERE id = p_id;
            PERFORM public.fn_customer_message(v_order.account_id, p_id,
                'Your order #' || v_order.order_number || ' is on the way.');
        ELSE
            IF v_order.status <> 'out_for_delivery' THEN
                RAISE EXCEPTION 'Please mark this order as out for delivery first.';
            END IF;
            UPDATE public.online_orders SET status = 'completed', delivered_at = NOW() WHERE id = p_id;
            PERFORM public.fn_customer_message(v_order.account_id, p_id,
                'Your order #' || v_order.order_number || ' has been delivered. Thank you!');
        END IF;
    ELSIF p_source = 'sale' THEN
        SELECT * INTO v_sale FROM public.transactions WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
        IF NOT FOUND OR v_sale.rider_id IS NULL
           OR v_sale.rider_id IS DISTINCT FROM public.fn_my_employee_id(v_sale.business_id) THEN
            RAISE EXCEPTION 'This delivery is not assigned to you.' USING ERRCODE = '42501';
        END IF;
        PERFORM public.assert_permission(v_sale.business_id, CASE WHEN p_status = 'failed' THEN 'deliveries.cancel' ELSE 'deliveries.complete' END);
        UPDATE public.transactions
        SET delivery_status = p_status,
            delivered_at = CASE WHEN p_status = 'delivered' THEN NOW() ELSE delivered_at END
        WHERE id = p_id;
    ELSE
        RAISE EXCEPTION 'That delivery was not found.';
    END IF;
END;
$$;


ALTER FUNCTION "public"."rider_update_delivery"("p_source" "text", "p_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_customer_portal_daily"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_today DATE := public.fn_nairobi_today();
    v_schedule public.customer_order_schedules%ROWTYPE;
    v_order_id UUID;
    v_number BIGINT;
    v_total NUMERIC;
    v_created INTEGER := 0;
BEGIN
    UPDATE public.online_orders
    SET status = 'cancelled'
    WHERE status IN ('pending_payment', 'payment_failed')
      AND created_at < NOW() - INTERVAL '48 hours'
      AND NOT EXISTS (
          SELECT 1 FROM public.mpesa_transactions m
          WHERE m.online_order_id = online_orders.id AND m.status = 'Pending'
            AND m.created_at > NOW() - INTERVAL '1 hour'
      );

    DELETE FROM public.assistant_usage WHERE window_start < NOW() - INTERVAL '3 days';

    FOR v_schedule IN
        SELECT * FROM public.customer_order_schedules
        WHERE active AND next_run_date <= v_today
        FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            v_order_id := public.fn_build_online_order(
                v_schedule.account_id, v_schedule.items, v_schedule.fulfilment,
                v_schedule.delivery_address, v_schedule.notes, v_schedule.id);
            SELECT order_number, total INTO v_number, v_total FROM public.online_orders WHERE id = v_order_id;
            PERFORM public.fn_customer_message(v_schedule.account_id, v_order_id,
                'Your scheduled order #' || v_number || ' is ready. Please pay ' || v_total || ' from your Orders page to confirm it.');
            v_created := v_created + 1;
        EXCEPTION WHEN OTHERS THEN
            PERFORM public.fn_customer_message(v_schedule.account_id, NULL,
                'We couldn''t prepare your scheduled order today: ' || SQLERRM);
        END;

        UPDATE public.customer_order_schedules
        SET last_run_date = v_today,
            next_run_date = public.fn_next_schedule_date(days_of_week, v_today + 1)
        WHERE id = v_schedule.id;
    END LOOP;

    RETURN v_created;
END;
$$;


ALTER FUNCTION "public"."run_customer_portal_daily"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_due_backups"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_url     TEXT;
    v_key     TEXT;
    v_now     TIMESTAMP := NOW() AT TIME ZONE 'Africa/Nairobi';
    v_started INTEGER := 0;
    v_config  RECORD;
BEGIN
    SELECT decrypted_secret INTO v_url FROM vault.decrypted_secrets WHERE name = 'project_url';
    SELECT decrypted_secret INTO v_key FROM vault.decrypted_secrets WHERE name = 'service_role_key';
    IF v_url IS NULL OR v_key IS NULL THEN
        RAISE WARNING 'run_due_backups: Vault secrets project_url and service_role_key are not set.';
        RETURN 0;
    END IF;

    FOR v_config IN
        SELECT business_id
        FROM public.google_sheets_backup
        WHERE enabled
          AND google_sheet_url IS NOT NULL
          AND google_service_account IS NOT NULL
          AND CASE schedule
                WHEN 'every_12h' THEN
                    -- 11 hours, so an hourly job can't slip a 12-hour cycle by an extra hour.
                    last_backup_at IS NULL OR last_backup_at < NOW() - INTERVAL '11 hours'
                ELSE
                    EXTRACT(HOUR FROM v_now) >= CASE schedule WHEN 'nightly_3am' THEN 3 ELSE 0 END
                    AND (last_backup_at IS NULL
                         OR (last_backup_at AT TIME ZONE 'Africa/Nairobi')::DATE < v_now::DATE)
              END
    LOOP
        PERFORM net.http_post(
            url := v_url || '/functions/v1/backup-config',
            headers := jsonb_build_object(
                'Content-Type', 'application/json',
                'Authorization', 'Bearer ' || v_key
            ),
            body := jsonb_build_object('action', 'run', 'businessId', v_config.business_id),
            timeout_milliseconds := 300000
        );
        v_started := v_started + 1;
    END LOOP;

    RETURN v_started;
END;
$$;


ALTER FUNCTION "public"."run_due_backups"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sale_refund_lines"("p_transaction_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_t      public.transactions%ROWTYPE;
    v_factor NUMERIC;
    v_rate   NUMERIC;
    v_lines  JSONB;
    v_done   NUMERIC;
    v_owed   NUMERIC;
BEGIN
    SELECT * INTO v_t FROM public.transactions WHERE id = p_transaction_id;
    IF NOT FOUND OR v_t.deleted_at IS NOT NULL THEN
        RAISE EXCEPTION 'That sale was not found.';
    END IF;
    PERFORM public.assert_business_member(v_t.business_id);
    PERFORM public.assert_permission(v_t.business_id, 'refunds.create', 'pos.cancel_sale');
    SELECT CASE WHEN SUM(unit_price * quantity * (1 - discount_percentage / 100)) > 0
                THEN (v_t.total - v_t.discount) / SUM(unit_price * quantity * (1 - discount_percentage / 100)) ELSE 0 END
    INTO v_factor FROM public.transaction_items WHERE transaction_id = p_transaction_id;
    v_factor := LEAST(GREATEST(COALESCE(v_factor, 1), 0), 1);
    v_rate := CASE WHEN (v_t.total - v_t.discount) > 0 THEN COALESCE(v_t.tax, 0) / (v_t.total - v_t.discount) ELSE 0 END;
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', ti.id, 'productId', ti.product_id, 'name', ti.product_name, 'quantity', ti.quantity,
        'left', ti.quantity - COALESCE(c.qty, 0),
        'unitNet', round(ti.unit_price * (1 - ti.discount_percentage / 100) * v_factor, 4),
        'vatRate', round(v_rate * 100, 2)) ORDER BY ti.created_at, ti.id), '[]'::JSONB)
    INTO v_lines
    FROM public.transaction_items ti
    LEFT JOIN (SELECT transaction_item_id, SUM(quantity) AS qty FROM public.credit_note_lines GROUP BY 1) c
        ON c.transaction_item_id = ti.id
    WHERE ti.transaction_id = p_transaction_id;
    SELECT COALESCE(SUM(total), 0) INTO v_done FROM public.credit_notes WHERE transaction_id = p_transaction_id;
    SELECT COALESCE(SUM(balance), 0) INTO v_owed FROM public.credit_payments
    WHERE transaction_id = p_transaction_id AND status IN ('Open', 'Partial');
    RETURN jsonb_build_object(
        'receipt', public.fn_receipt_number(v_t.id), 'customerId', v_t.customer_id, 'customerName', v_t.customer_name,
        'paymentMethod', v_t.payment_method, 'finalTotal', v_t.final_total, 'refunded', v_done, 'owedOnSale', v_owed,
        'today', (v_t.timestamp AT TIME ZONE 'Africa/Nairobi')::DATE = public.sd_today(),
        'fullAccess', public.has_permission(v_t.business_id, 'refunds.create'),
        'lines', v_lines);
END;
$$;


ALTER FUNCTION "public"."sale_refund_lines"("p_transaction_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sales_docs"("p_business_id" "uuid", "p_since" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_since  DATE := COALESCE(p_since, public.sd_today() - 365);
    v_today  DATE := public.sd_today();
    v_quotes JSONB := '[]'::JSONB;
    v_orders JSONB := '[]'::JSONB;
    v_invs   JSONB := '[]'::JSONB;
    v_cns    JSONB := '[]'::JSONB;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    IF public.has_permission(p_business_id, 'quotes.view', 'quotes.manage') THEN
        SELECT COALESCE(jsonb_agg(to_jsonb(q) - 'business_id'
                   || jsonb_build_object('expired', q.status IN ('draft', 'sent') AND q.valid_until < v_today,
                                         'order_number', o.number,
                                         'lines', public.sd_lines_json('quote_lines', 'quote_id', q.id))
                   ORDER BY q.created_at DESC), '[]'::JSONB)
        INTO v_quotes
        FROM public.quotes q LEFT JOIN public.sales_orders o ON o.id = q.order_id
        WHERE q.business_id = p_business_id AND (q.issue_date >= v_since OR q.status IN ('draft', 'sent'));
    END IF;
    IF public.has_permission(p_business_id, 'sales_orders.view', 'sales_orders.manage') THEN
        SELECT COALESCE(jsonb_agg(to_jsonb(o) - 'business_id'
                   || jsonb_build_object(
                        'quote_number', q.number,
                        'lines', public.sd_lines_json('sales_order_lines', 'order_id', o.id),
                        'deliveries', (SELECT COALESCE(jsonb_agg(to_jsonb(d) - 'business_id'
                                          || jsonb_build_object('lines', (SELECT COALESCE(jsonb_agg(to_jsonb(dl) - 'business_id'), '[]'::JSONB)
                                                                          FROM public.sales_delivery_lines dl WHERE dl.delivery_id = d.id))
                                          ORDER BY d.delivered_at), '[]'::JSONB)
                                       FROM public.sales_deliveries d WHERE d.order_id = o.id),
                        'invoices', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', i.id, 'number', i.number, 'total', i.total,
                                          'balance', i.balance, 'status', i.status) ORDER BY i.created_at), '[]'::JSONB)
                                     FROM public.sales_invoices i WHERE i.order_id = o.id))
                   ORDER BY o.created_at DESC), '[]'::JSONB)
        INTO v_orders
        FROM public.sales_orders o LEFT JOIN public.quotes q ON q.id = o.quote_id
        WHERE o.business_id = p_business_id AND (o.order_date >= v_since OR o.status NOT IN ('paid', 'cancelled'));
    END IF;
    IF public.has_permission(p_business_id, 'invoices.view', 'invoices.manage') THEN
        SELECT COALESCE(jsonb_agg(to_jsonb(i) - 'business_id'
                   || jsonb_build_object(
                        'overdue', i.status IN ('unpaid', 'part_paid') AND i.due_date < v_today,
                        'days_late', GREATEST(v_today - i.due_date, 0),
                        'order_number', o.number,
                        'lines', public.sd_lines_json('sales_invoice_lines', 'invoice_id', i.id),
                        'payments', (SELECT COALESCE(jsonb_agg(to_jsonb(p) - 'business_id' ORDER BY p.paid_at), '[]'::JSONB)
                                     FROM public.invoice_payments p WHERE p.invoice_id = i.id),
                        'credit_notes', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', c.id, 'number', c.number, 'total', c.total,
                                             'settlement', c.settlement) ORDER BY c.created_at), '[]'::JSONB)
                                         FROM public.credit_notes c WHERE c.invoice_id = i.id))
                   ORDER BY i.created_at DESC), '[]'::JSONB)
        INTO v_invs
        FROM public.sales_invoices i LEFT JOIN public.sales_orders o ON o.id = i.order_id
        WHERE i.business_id = p_business_id AND (i.issue_date >= v_since OR i.status IN ('unpaid', 'part_paid'));
    END IF;
    IF public.has_permission(p_business_id, 'invoices.view', 'invoices.manage', 'refunds.create', 'orders.view') THEN
        SELECT COALESCE(jsonb_agg(to_jsonb(c) - 'business_id'
                   || jsonb_build_object(
                        'invoice_number', i.number,
                        'receipt_number', CASE WHEN c.transaction_id IS NOT NULL THEN public.fn_receipt_number(c.transaction_id) END,
                        'lines', (SELECT COALESCE(jsonb_agg(to_jsonb(cl) - 'business_id'), '[]'::JSONB)
                                  FROM public.credit_note_lines cl WHERE cl.credit_note_id = c.id))
                   ORDER BY c.created_at DESC), '[]'::JSONB)
        INTO v_cns
        FROM public.credit_notes c LEFT JOIN public.sales_invoices i ON i.id = c.invoice_id
        WHERE c.business_id = p_business_id AND c.issue_date >= v_since;
    END IF;
    RETURN jsonb_build_object('quotes', v_quotes, 'orders', v_orders, 'invoices', v_invs, 'creditNotes', v_cns);
END;
$$;


ALTER FUNCTION "public"."sales_docs"("p_business_id" "uuid", "p_since" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_buying_settings"("p_business_id" "uuid", "p_tolerance_pct" numeric, "p_safety_days" integer, "p_limits" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_by TEXT := public.fn_my_display_name(p_business_id);
    v_el JSONB;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    IF NOT public.is_owner_or_admin(p_business_id) THEN
        RAISE EXCEPTION 'Only the owner or an admin can set approval limits.';
    END IF;
    INSERT INTO public.buying_settings (business_id, bill_tolerance_pct, safety_days, updated_by, updated_at)
    VALUES (p_business_id, COALESCE(p_tolerance_pct, 2), COALESCE(p_safety_days, 3), v_by, NOW())
    ON CONFLICT (business_id) DO UPDATE
    SET bill_tolerance_pct = EXCLUDED.bill_tolerance_pct, safety_days = EXCLUDED.safety_days,
        updated_by = v_by, updated_at = NOW();

    DELETE FROM public.purchase_approval_limits WHERE business_id = p_business_id;
    FOR v_el IN SELECT * FROM jsonb_array_elements(COALESCE(p_limits, '[]'::JSONB)) LOOP
        CONTINUE WHEN NULLIF(v_el->>'max', '') IS NULL OR COALESCE(v_el->>'role', '') IN ('', 'Owner', 'Admin', 'Administrator');
        IF (v_el->>'max')::NUMERIC < 0 THEN
            RAISE EXCEPTION 'A limit can''t be below zero.';
        END IF;
        INSERT INTO public.purchase_approval_limits (business_id, role, max_amount, updated_by)
        VALUES (p_business_id, v_el->>'role', round((v_el->>'max')::NUMERIC, 2), v_by)
        ON CONFLICT (business_id, role) DO UPDATE SET max_amount = EXCLUDED.max_amount, updated_by = v_by, updated_at = NOW();
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."save_buying_settings"("p_business_id" "uuid", "p_tolerance_pct" numeric, "p_safety_days" integer, "p_limits" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_order_schedule"("p_id" "uuid", "p_items" "jsonb", "p_days" integer[], "p_fulfilment" "text", "p_address" "text", "p_notes" "text", "p_active" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_account public.customer_accounts%ROWTYPE;
    v_id UUID;
    v_address TEXT := NULLIF(trim(COALESCE(p_address, '')), '');
    v_next DATE;
BEGIN
    SELECT * INTO v_account FROM public.customer_accounts WHERE id = auth.uid();
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Please finish setting up your account first.';
    END IF;

    IF COALESCE(array_length(p_days, 1), 0) = 0 OR EXISTS (SELECT 1 FROM unnest(p_days) d WHERE d NOT BETWEEN 0 AND 6) THEN
        RAISE EXCEPTION 'Please choose at least one day.';
    END IF;
    IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 30 THEN
        RAISE EXCEPTION 'Please add at least one product.';
    END IF;
    IF p_fulfilment NOT IN ('delivery', 'pickup') THEN
        RAISE EXCEPTION 'Please choose delivery or pickup.';
    END IF;
    IF p_fulfilment = 'delivery' AND v_address IS NULL THEN
        RAISE EXCEPTION 'Please enter your delivery location.';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_items) e
        LEFT JOIN public.products p
            ON p.id = (e->>'productId')::UUID
           AND p.business_id = v_account.business_id
           AND p.deleted_at IS NULL AND p.show_on_website AND p.price > 0
        WHERE p.id IS NULL
           OR COALESCE((e->>'quantity')::NUMERIC, 0) <= 0
           OR (e->>'quantity')::NUMERIC > 1000
    ) THEN
        RAISE EXCEPTION 'Please check the products in your schedule.';
    END IF;

    -- Starts tomorrow, so saving a schedule never creates an order immediately.
    v_next := public.fn_next_schedule_date(p_days, public.fn_nairobi_today() + 1);

    IF p_id IS NULL THEN
        IF (SELECT count(*) FROM public.customer_order_schedules WHERE account_id = v_account.id) >= 10 THEN
            RAISE EXCEPTION 'You can have up to 10 schedules.';
        END IF;
        INSERT INTO public.customer_order_schedules
            (business_id, account_id, items, days_of_week, fulfilment, delivery_address, notes, active, next_run_date)
        VALUES
            (v_account.business_id, v_account.id, p_items, p_days, p_fulfilment,
             CASE WHEN p_fulfilment = 'delivery' THEN v_address END,
             left(NULLIF(trim(COALESCE(p_notes, '')), ''), 500), COALESCE(p_active, TRUE), v_next)
        RETURNING id INTO v_id;
    ELSE
        UPDATE public.customer_order_schedules
        SET items = p_items,
            days_of_week = p_days,
            fulfilment = p_fulfilment,
            delivery_address = CASE WHEN p_fulfilment = 'delivery' THEN v_address END,
            notes = left(NULLIF(trim(COALESCE(p_notes, '')), ''), 500),
            active = COALESCE(p_active, TRUE),
            next_run_date = v_next
        WHERE id = p_id AND account_id = v_account.id
        RETURNING id INTO v_id;
        IF v_id IS NULL THEN
            RAISE EXCEPTION 'Schedule not found.';
        END IF;
    END IF;

    RETURN v_id;
EXCEPTION
    WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'Please check the products in your schedule.';
END;
$$;


ALTER FUNCTION "public"."save_order_schedule"("p_id" "uuid", "p_items" "jsonb", "p_days" integer[], "p_fulfilment" "text", "p_address" "text", "p_notes" "text", "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_otp"("p_email" "text", "p_code" "text", "p_type" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    INSERT INTO public.otps (email, code, type, expires_at)
    VALUES (p_email, p_code, p_type, NOW() + INTERVAL '15 minutes')
    ON CONFLICT (email, type) DO UPDATE SET
        code       = EXCLUDED.code,
        expires_at = EXCLUDED.expires_at,
        created_at = NOW();
END;
$$;


ALTER FUNCTION "public"."save_otp"("p_email" "text", "p_code" "text", "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_petty_cash_category"("p_business_id" "uuid", "p_id" "uuid", "p_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_name TEXT := btrim(COALESCE(p_name, ''));
    v_old  TEXT;
    v_id   UUID;
BEGIN
    IF NOT public.is_owner_or_admin(p_business_id) THEN
        RAISE EXCEPTION 'Only an owner or admin can change these.' USING ERRCODE = '42501';
    END IF;
    IF length(v_name) = 0 THEN
        RAISE EXCEPTION 'Type a name.';
    END IF;
    IF length(v_name) > 40 THEN
        RAISE EXCEPTION 'Keep the name under 40 letters.';
    END IF;
    IF EXISTS (
        SELECT 1 FROM public.petty_cash_categories
        WHERE business_id = p_business_id AND lower(btrim(name)) = lower(v_name) AND id IS DISTINCT FROM p_id
    ) THEN
        RAISE EXCEPTION '"%" is already on the list.', v_name;
    END IF;

    IF p_id IS NULL THEN
        INSERT INTO public.petty_cash_categories (business_id, name, sort_order)
        VALUES (
            p_business_id, v_name,
            COALESCE((SELECT MAX(sort_order) + 1 FROM public.petty_cash_categories WHERE business_id = p_business_id), 1)
        )
        RETURNING id INTO v_id;
        RETURN v_id;
    END IF;

    SELECT name INTO v_old FROM public.petty_cash_categories WHERE id = p_id AND business_id = p_business_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'That choice is no longer there.';
    END IF;

    UPDATE public.petty_cash_categories SET name = v_name WHERE id = p_id;
    UPDATE public.expenses
    SET category = v_name
    WHERE business_id = p_business_id AND source = 'petty_cash' AND category = v_old;
    RETURN p_id;
END;
$$;


ALTER FUNCTION "public"."save_petty_cash_category"("p_business_id" "uuid", "p_id" "uuid", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_quote"("p_business_id" "uuid", "p_id" "uuid", "p_doc" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_q     public.quotes%ROWTYPE;
    v_c     public.customers%ROWTYPE;
    v_lines JSONB;
    v_name  TEXT;
    v_issue DATE := COALESCE(NULLIF(p_doc->>'issueDate', '')::DATE, public.sd_today());
    v_valid DATE := COALESCE(NULLIF(p_doc->>'validUntil', '')::DATE, v_issue + 14);
    v_fee   NUMERIC := round(COALESCE(NULLIF(p_doc->>'deliveryFee', '')::NUMERIC, 0), 2);
    v_id    UUID := p_id;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'quotes.manage');
    v_c := public.sd_customer(p_business_id, NULLIF(p_doc->>'customerId', '')::UUID);
    v_name := COALESCE(NULLIF(trim(p_doc->>'customerName'), ''), v_c.name);
    IF v_name IS NULL THEN
        RAISE EXCEPTION 'Choose or type who the quote is for.';
    END IF;
    IF v_valid < v_issue THEN
        RAISE EXCEPTION '"Valid until" can''t be before the quote date.';
    END IF;
    IF v_fee < 0 THEN
        RAISE EXCEPTION 'The delivery fee can''t be below zero.';
    END IF;
    v_lines := public.sd_norm_lines(p_business_id, p_doc->'lines');

    IF v_id IS NULL THEN
        INSERT INTO public.quotes (business_id, number, customer_id, customer_name, customer_phone, issue_date, valid_until,
                                   notes, terms, delivery_fee, created_by)
        VALUES (p_business_id, public.sd_next_no(p_business_id, 'QT', v_issue), v_c.id, left(v_name, 120),
                left(COALESCE(NULLIF(trim(p_doc->>'customerPhone'), ''), v_c.phone), 30), v_issue, v_valid,
                left(NULLIF(trim(p_doc->>'notes'), ''), 1000), left(NULLIF(trim(p_doc->>'terms'), ''), 1000), v_fee, public.acc_who())
        RETURNING id INTO v_id;
    ELSE
        SELECT * INTO v_q FROM public.quotes WHERE id = v_id AND business_id = p_business_id FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'That quote was not found.';
        END IF;
        IF v_q.status NOT IN ('draft', 'sent') THEN
            RAISE EXCEPTION 'An accepted or declined quote can''t be changed.';
        END IF;
        UPDATE public.quotes
        SET customer_id = v_c.id, customer_name = left(v_name, 120),
            customer_phone = left(COALESCE(NULLIF(trim(p_doc->>'customerPhone'), ''), v_c.phone), 30),
            issue_date = v_issue, valid_until = v_valid,
            notes = left(NULLIF(trim(p_doc->>'notes'), ''), 1000), terms = left(NULLIF(trim(p_doc->>'terms'), ''), 1000),
            delivery_fee = v_fee, updated_at = NOW()
        WHERE id = v_id;
        DELETE FROM public.quote_lines WHERE quote_id = v_id;
    END IF;

    INSERT INTO public.quote_lines (quote_id, business_id, position, product_id, name, unit, quantity, unit_price,
                                    discount_pct, vat_rate, line_net, line_vat, line_total)
    SELECT v_id, p_business_id, l.position, l.product_id, l.name, l.unit, l.quantity, l.unit_price,
           l.discount_pct, l.vat_rate, l.line_net, l.line_vat, l.line_total
    FROM jsonb_to_recordset(v_lines) AS l(position INTEGER, product_id UUID, name TEXT, unit TEXT, quantity NUMERIC,
         unit_price NUMERIC, discount_pct NUMERIC, vat_rate NUMERIC, line_net NUMERIC, line_vat NUMERIC, line_total NUMERIC);

    UPDATE public.quotes q
    SET subtotal = s.net, vat_total = s.vat, total = s.net + s.vat + q.delivery_fee
    FROM (SELECT COALESCE(SUM(line_net), 0) AS net, COALESCE(SUM(line_vat), 0) AS vat FROM public.quote_lines WHERE quote_id = v_id) s
    WHERE q.id = v_id;
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."save_quote"("p_business_id" "uuid", "p_id" "uuid", "p_doc" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_reorder_settings"("p_business_id" "uuid", "p_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_el JSONB;
    v_n  INTEGER := 0;
    v_by TEXT := public.fn_my_display_name(p_business_id);
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'products.update', 'inventory.manage', 'purchases.create');
    FOR v_el IN SELECT * FROM jsonb_array_elements(COALESCE(p_rows, '[]'::JSONB)) LOOP
        IF NULLIF(v_el->>'supplierId', '') IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM public.suppliers WHERE id = (v_el->>'supplierId')::UUID AND business_id = p_business_id) THEN
            RAISE EXCEPTION 'That supplier was not found.';
        END IF;
        UPDATE public.products SET
            reorder_level = round(NULLIF(v_el->>'level', '')::NUMERIC, 3),
            reorder_qty = NULLIF(round(NULLIF(v_el->>'qty', '')::NUMERIC, 3), 0),
            preferred_supplier_id = NULLIF(v_el->>'supplierId', '')::UUID,
            supplier_price = round(NULLIF(v_el->>'price', '')::NUMERIC, 2),
            lead_time_days = NULLIF(v_el->>'leadDays', '')::INTEGER,
            last_modified_by = v_by,
            updated_at = NOW()
        WHERE id = (v_el->>'productId')::UUID AND business_id = p_business_id AND deleted_at IS NULL;
        v_n := v_n + 1;
    END LOOP;
    RETURN v_n;
END;
$$;


ALTER FUNCTION "public"."save_reorder_settings"("p_business_id" "uuid", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_sales_order"("p_business_id" "uuid", "p_id" "uuid", "p_doc" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_o     public.sales_orders%ROWTYPE;
    v_c     public.customers%ROWTYPE;
    v_lines JSONB;
    v_name  TEXT;
    v_date  DATE := COALESCE(NULLIF(p_doc->>'orderDate', '')::DATE, public.sd_today());
    v_fee   NUMERIC := round(COALESCE(NULLIF(p_doc->>'deliveryFee', '')::NUMERIC, 0), 2);
    v_id    UUID := p_id;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'sales_orders.manage');
    v_c := public.sd_customer(p_business_id, NULLIF(p_doc->>'customerId', '')::UUID);
    v_name := COALESCE(NULLIF(trim(p_doc->>'customerName'), ''), v_c.name);
    IF v_name IS NULL THEN
        RAISE EXCEPTION 'Choose or type who the order is for.';
    END IF;
    IF v_fee < 0 THEN
        RAISE EXCEPTION 'The delivery fee can''t be below zero.';
    END IF;
    v_lines := public.sd_norm_lines(p_business_id, p_doc->'lines');

    IF v_id IS NULL THEN
        INSERT INTO public.sales_orders (business_id, number, customer_id, customer_name, customer_phone, order_date,
                                         expected_date, notes, terms, delivery_fee, created_by)
        VALUES (p_business_id, public.sd_next_no(p_business_id, 'SO', v_date), v_c.id, left(v_name, 120),
                left(COALESCE(NULLIF(trim(p_doc->>'customerPhone'), ''), v_c.phone), 30), v_date,
                NULLIF(p_doc->>'expectedDate', '')::DATE, left(NULLIF(trim(p_doc->>'notes'), ''), 1000),
                left(NULLIF(trim(p_doc->>'terms'), ''), 1000), v_fee, public.acc_who())
        RETURNING id INTO v_id;
    ELSE
        SELECT * INTO v_o FROM public.sales_orders WHERE id = v_id AND business_id = p_business_id FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'That order was not found.';
        END IF;
        IF v_o.status = 'cancelled' THEN
            RAISE EXCEPTION 'A cancelled order can''t be changed.';
        END IF;
        IF EXISTS (SELECT 1 FROM public.sales_order_lines WHERE order_id = v_id AND (qty_delivered > 0 OR qty_invoiced > 0)) THEN
            RAISE EXCEPTION 'Part of this order was delivered or invoiced, so its items can''t be changed.';
        END IF;
        UPDATE public.sales_orders
        SET customer_id = v_c.id, customer_name = left(v_name, 120),
            customer_phone = left(COALESCE(NULLIF(trim(p_doc->>'customerPhone'), ''), v_c.phone), 30),
            order_date = v_date, expected_date = NULLIF(p_doc->>'expectedDate', '')::DATE,
            notes = left(NULLIF(trim(p_doc->>'notes'), ''), 1000), terms = left(NULLIF(trim(p_doc->>'terms'), ''), 1000),
            delivery_fee = v_fee, updated_at = NOW()
        WHERE id = v_id;
        DELETE FROM public.sales_order_lines WHERE order_id = v_id;
    END IF;

    INSERT INTO public.sales_order_lines (order_id, business_id, position, product_id, name, unit, quantity, unit_price,
                                          discount_pct, vat_rate, line_net, line_vat, line_total)
    SELECT v_id, p_business_id, l.position, l.product_id, l.name, l.unit, l.quantity, l.unit_price,
           l.discount_pct, l.vat_rate, l.line_net, l.line_vat, l.line_total
    FROM jsonb_to_recordset(v_lines) AS l(position INTEGER, product_id UUID, name TEXT, unit TEXT, quantity NUMERIC,
         unit_price NUMERIC, discount_pct NUMERIC, vat_rate NUMERIC, line_net NUMERIC, line_vat NUMERIC, line_total NUMERIC);
    PERFORM public.sd_order_totals(v_id);
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."save_sales_order"("p_business_id" "uuid", "p_id" "uuid", "p_doc" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_supplier_quote"("p_quote_id" "uuid", "p_lines" "jsonb", "p_delivery_days" integer DEFAULT NULL::integer, "p_note" "text" DEFAULT NULL::"text") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_q     public.purchase_quotes%ROWTYPE;
    v_el    JSONB;
    v_total NUMERIC;
BEGIN
    SELECT * INTO v_q FROM public.purchase_quotes WHERE id = p_quote_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That quote was not found.'; END IF;
    PERFORM public.assert_business_member(v_q.business_id);
    PERFORM public.assert_permission(v_q.business_id, 'purchases.request_quote');
    IF v_q.status IN ('won', 'lost') THEN
        RAISE EXCEPTION 'A supplier was already chosen for this purchase.';
    END IF;
    FOR v_el IN SELECT * FROM jsonb_array_elements(COALESCE(p_lines, '[]'::JSONB)) LOOP
        IF NOT EXISTS (SELECT 1 FROM public.purchase_items WHERE id = (v_el->>'itemId')::UUID AND purchase_id = v_q.purchase_id) THEN
            RAISE EXCEPTION 'One of the items is not on this purchase. Refresh and try again.';
        END IF;
        IF COALESCE(NULLIF(v_el->>'price', '')::NUMERIC, 0) < 0 THEN
            RAISE EXCEPTION 'A price can''t be below zero.';
        END IF;
        INSERT INTO public.purchase_quote_lines (business_id, quote_id, purchase_item_id, unit_price, available)
        VALUES (v_q.business_id, v_q.id, (v_el->>'itemId')::UUID, round(COALESCE(NULLIF(v_el->>'price', '')::NUMERIC, 0), 2),
                COALESCE((v_el->>'available')::BOOLEAN, TRUE))
        ON CONFLICT (quote_id, purchase_item_id) DO UPDATE SET unit_price = EXCLUDED.unit_price, available = EXCLUDED.available;
    END LOOP;
    SELECT COALESCE(SUM(round(pi.quantity * ql.unit_price, 2)), 0) INTO v_total
    FROM public.purchase_quote_lines ql JOIN public.purchase_items pi ON pi.id = ql.purchase_item_id
    WHERE ql.quote_id = v_q.id AND ql.available;
    UPDATE public.purchase_quotes
    SET status = 'priced', priced_at = NOW(), total = v_total, delivery_days = p_delivery_days,
        note = NULLIF(trim(COALESCE(p_note, '')), '')
    WHERE id = v_q.id;
    RETURN v_total;
END;
$$;


ALTER FUNCTION "public"."save_supplier_quote"("p_quote_id" "uuid", "p_lines" "jsonb", "p_delivery_days" integer, "p_note" "text") OWNER TO "postgres";


