CREATE TABLE IF NOT EXISTS "public"."customers" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "business_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "phone" "text" NOT NULL,
    "email" "text",
    "loyalty_points" integer DEFAULT 0 NOT NULL,
    "join_date" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tier" "public"."customer_tier" DEFAULT 'Bronze'::"public"."customer_tier" NOT NULL,
    "purchases_count" integer DEFAULT 0 NOT NULL,
    "debt_balance" numeric(14,2) DEFAULT 0.00 NOT NULL,
    "wallet_balance" numeric(14,2) DEFAULT 0.00 NOT NULL,
    "description" "text",
    "version" integer DEFAULT 1 NOT NULL,
    "sync_status" "public"."sync_status" DEFAULT 'synced'::"public"."sync_status" NOT NULL,
    "last_modified_by" "text" DEFAULT 'system'::"text" NOT NULL,
    "deleted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "customer_type" "text" DEFAULT 'individual'::"text" NOT NULL,
    "payment_terms" "text" DEFAULT 'pay_now'::"text" NOT NULL,
    "delivery_frequency" "text" DEFAULT 'none'::"text" NOT NULL,
    "merged_into_id" "uuid",
    "notify_service" boolean DEFAULT true NOT NULL,
    "notify_promotions" boolean DEFAULT false NOT NULL,
    "account_number" "text" DEFAULT ("nextval"('"public"."customer_account_number_seq"'::"regclass"))::"text" NOT NULL,
    CONSTRAINT "customers_customer_type_check" CHECK (("customer_type" = ANY (ARRAY['individual'::"text", 'institution'::"text", 'business'::"text", 'other'::"text"]))),
    CONSTRAINT "customers_debt_balance_check" CHECK (("debt_balance" >= (0)::numeric)),
    CONSTRAINT "customers_delivery_frequency_check" CHECK (("delivery_frequency" = ANY (ARRAY['none'::"text", 'daily'::"text", 'weekly'::"text", 'monthly'::"text"]))),
    CONSTRAINT "customers_loyalty_points_check" CHECK (("loyalty_points" >= 0)),
    CONSTRAINT "customers_name_check" CHECK (("length"(TRIM(BOTH FROM "name")) > 0)),
    CONSTRAINT "customers_payment_terms_check" CHECK (("payment_terms" = ANY (ARRAY['pay_now'::"text", 'weekly'::"text", 'monthly'::"text"]))),
    CONSTRAINT "customers_purchases_count_check" CHECK (("purchases_count" >= 0)),
    CONSTRAINT "customers_wallet_balance_check" CHECK (("wallet_balance" >= (0)::numeric))
);


