CREATE OR REPLACE FUNCTION "public"."send_customer_message"("p_body" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_account public.customer_accounts%ROWTYPE;
    v_body TEXT := trim(COALESCE(p_body, ''));
BEGIN
    SELECT * INTO v_account FROM public.customer_accounts WHERE id = auth.uid();
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Please finish setting up your account first.';
    END IF;
    IF length(v_body) NOT BETWEEN 1 AND 1000 THEN
        RAISE EXCEPTION 'Please write a message of up to 1000 characters.';
    END IF;
    IF (
        SELECT count(*) FROM public.customer_messages
        WHERE account_id = v_account.id AND sender = 'customer'
          AND created_at > NOW() - INTERVAL '1 hour'
    ) >= 20 THEN
        RAISE EXCEPTION 'You have sent many messages. Please wait a little before sending more.';
    END IF;

    INSERT INTO public.customer_messages (business_id, account_id, sender, body)
    VALUES (v_account.business_id, v_account.id, 'customer', v_body);

    PERFORM public.fn_notify_staff(v_account.business_id, 'New customer message',
        v_account.name || ': ' || left(v_body, 120), jsonb_build_object('accountId', v_account.id));
END;
$$;


ALTER FUNCTION "public"."send_customer_message"("p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_draft_transfer"("p_transfer_id" "uuid", "p_items" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_t  public.stock_transfers%ROWTYPE;
    v_el JSONB;
BEGIN
    SELECT * INTO v_t FROM public.stock_transfers WHERE id = p_transfer_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Transfer not found.'; END IF;
    PERFORM public.assert_business_member(v_t.from_business_id);
    PERFORM public.assert_permission(v_t.from_business_id, 'inventory.transfer_stock');
    IF v_t.status <> 'draft' THEN
        RAISE EXCEPTION 'Only a draft transfer can be sent this way.';
    END IF;
    FOR v_el IN SELECT * FROM jsonb_array_elements(COALESCE(p_items, '[]'::JSONB)) LOOP
        IF round(COALESCE(NULLIF(v_el->>'quantity', '')::NUMERIC, 0), 3) <= 0 THEN
            DELETE FROM public.stock_transfer_items WHERE id = (v_el->>'item_id')::UUID AND transfer_id = v_t.id;
        ELSE
            UPDATE public.stock_transfer_items SET quantity_sent = round((v_el->>'quantity')::NUMERIC, 3)
            WHERE id = (v_el->>'item_id')::UUID AND transfer_id = v_t.id;
        END IF;
    END LOOP;
    UPDATE public.stock_transfers
    SET sent_by_name = public.fn_my_display_name(v_t.from_business_id), sent_by_user_id = public.fn_my_user_id()
    WHERE id = v_t.id;
    RETURN public.fn_transfer_go(v_t.id);
END;
$$;


ALTER FUNCTION "public"."send_draft_transfer"("p_transfer_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_stock_transfer"("p_from_business_id" "uuid", "p_to_business_id" "uuid", "p_items" "jsonb", "p_note" "text" DEFAULT NULL::"text", "p_reference_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_existing  public.stock_transfers;
    v_transfer  public.stock_transfers;
    v_line      RECORD;
BEGIN
    PERFORM public.assert_business_member(p_from_business_id);
    PERFORM public.assert_permission(p_from_business_id, 'inventory.transfer_stock');

    IF p_reference_id IS NOT NULL THEN
        SELECT * INTO v_existing FROM public.stock_transfers
        WHERE from_business_id = p_from_business_id AND client_reference = p_reference_id;
        IF FOUND THEN
            RETURN jsonb_build_object('id', v_existing.id, 'reference', v_existing.reference, 'status', v_existing.status);
        END IF;
    END IF;

    IF p_to_business_id IS NULL OR p_to_business_id = p_from_business_id THEN
        RAISE EXCEPTION 'Choose the branch the stock is going to.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.businesses WHERE id = p_to_business_id AND deleted_at IS NULL)
       OR NOT public.fn_branches_share_owner(p_from_business_id, p_to_business_id) THEN
        RAISE EXCEPTION 'You can only send stock to another branch of this business.';
    END IF;
    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'Add at least one product to send.';
    END IF;
    IF jsonb_array_length(p_items) > 200 THEN
        RAISE EXCEPTION 'Send at most 200 products at a time.';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_items) e
        LEFT JOIN public.products p ON p.id = (e->>'product_id')::UUID
        WHERE p.id IS NULL OR p.business_id <> p_from_business_id OR p.deleted_at IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'One of the products is not in this branch any more. Refresh and try again.';
    END IF;

    INSERT INTO public.stock_transfers (
        reference, from_business_id, to_business_id, status, note, sent_by_name, sent_by_user_id, client_reference
    ) VALUES (
        'TR-' || to_char(NOW() AT TIME ZONE 'Africa/Nairobi', 'YYMMDD') || '-' || upper(substr(md5(gen_random_uuid()::TEXT), 1, 5)),
        p_from_business_id, p_to_business_id, 'draft',
        NULLIF(btrim(COALESCE(p_note, '')), ''),
        public.fn_my_display_name(p_from_business_id), public.fn_my_user_id(), p_reference_id
    )
    RETURNING * INTO v_transfer;

    FOR v_line IN
        WITH wanted AS (
            SELECT (e->>'product_id')::UUID AS product_id, SUM((e->>'quantity')::NUMERIC) AS qty
            FROM jsonb_array_elements(p_items) e
            GROUP BY 1
        )
        SELECT p.id, p.name, p.sku, p.unit, p.category, p.cost, p.price, w.qty
        FROM wanted w JOIN public.products p ON p.id = w.product_id
        ORDER BY p.id
    LOOP
        IF v_line.qty IS NULL OR v_line.qty <= 0 THEN
            RAISE EXCEPTION 'Enter how much % to send.', v_line.name;
        END IF;
        INSERT INTO public.stock_transfer_items (
            transfer_id, from_product_id, product_name, sku, unit, category, unit_cost, unit_price, quantity_sent, quantity_requested
        ) VALUES (
            v_transfer.id, v_line.id, v_line.name, v_line.sku, v_line.unit, v_line.category,
            v_line.cost, v_line.price, ROUND(v_line.qty, 3), ROUND(v_line.qty, 3)
        );
    END LOOP;

    RETURN public.fn_transfer_go(v_transfer.id);
END;
$$;


ALTER FUNCTION "public"."send_stock_transfer"("p_from_business_id" "uuid", "p_to_business_id" "uuid", "p_items" "jsonb", "p_note" "text", "p_reference_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_customer_payment_terms"("p_customer_id" "uuid", "p_terms" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_b UUID;
BEGIN
    SELECT business_id INTO v_b FROM public.customers WHERE id = p_customer_id;
    IF v_b IS NULL THEN
        RAISE EXCEPTION 'That customer was not found.';
    END IF;
    PERFORM public.assert_business_member(v_b);
    PERFORM public.assert_permission(v_b, 'invoices.manage');
    IF p_terms NOT IN ('pay_now', 'weekly', 'monthly') THEN
        RAISE EXCEPTION 'Terms are pay now, weekly or monthly.';
    END IF;
    UPDATE public.customers SET payment_terms = p_terms, updated_at = NOW() WHERE id = p_customer_id;
END;
$$;


ALTER FUNCTION "public"."set_customer_payment_terms"("p_customer_id" "uuid", "p_terms" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_invoice_archived"("p_invoice_id" "uuid", "p_archived" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_business UUID;
BEGIN
    SELECT business_id INTO v_business FROM public.invoices WHERE id = p_invoice_id;
    IF v_business IS NULL THEN
        RAISE EXCEPTION 'That invoice was not found.' USING ERRCODE = 'P0002';
    END IF;
    PERFORM public.assert_permission(v_business, 'customers.debts');

    UPDATE public.invoices
       SET archived_at = CASE WHEN p_archived THEN COALESCE(archived_at, NOW()) ELSE NULL END
     WHERE id = p_invoice_id;
END;
$$;


ALTER FUNCTION "public"."set_invoice_archived"("p_invoice_id" "uuid", "p_archived" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_my_notification_setting"("p_business_id" "uuid", "p_category" "text", "p_enabled" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user UUID;
BEGIN
    SELECT u.id INTO v_user
    FROM public.users u
    JOIN public.business_memberships m ON m.user_id = u.id
    WHERE u.auth_user_id = auth.uid() AND m.business_id = p_business_id AND m.status = 'Active';
    IF v_user IS NULL THEN
        RAISE EXCEPTION 'Your role does not allow this.' USING ERRCODE = '42501';
    END IF;

    IF p_category <> 'all' AND NOT EXISTS (
        SELECT 1 FROM public.fn_notification_catalog() c WHERE c.category = p_category AND NOT c.locked
    ) THEN
        RAISE EXCEPTION 'That notification setting can''t be changed.';
    END IF;

    INSERT INTO public.notification_preferences (business_id, user_id, category, enabled)
    VALUES (p_business_id, v_user, p_category, COALESCE(p_enabled, TRUE))
    ON CONFLICT (business_id, user_id, category) DO UPDATE SET enabled = EXCLUDED.enabled;
END;
$$;


ALTER FUNCTION "public"."set_my_notification_setting"("p_business_id" "uuid", "p_category" "text", "p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_payment_methods"("p_business_id" "uuid", "p_methods" "text"[]) RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_all  TEXT[] := ARRAY['Cash', 'M-Pesa', 'Airtel Money', 'Card', 'Bank'];
    v_list TEXT[];
    v_bad  TEXT;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'payments.configure');

    SELECT m INTO v_bad FROM unnest(COALESCE(p_methods, '{}')) m WHERE NOT (m = ANY(v_all)) LIMIT 1;
    IF v_bad IS NOT NULL THEN
        RAISE EXCEPTION '% isn''t a payment method. Choose from Cash, M-Pesa, Airtel Money, Card and Bank.', v_bad;
    END IF;

    SELECT array_agg(m ORDER BY array_position(v_all, m)) INTO v_list
    FROM (SELECT DISTINCT m FROM unnest(p_methods) m) d;
    IF COALESCE(cardinality(v_list), 0) = 0 THEN
        RAISE EXCEPTION 'Keep at least one payment method on.';
    END IF;

    UPDATE public.businesses SET default_payment_methods = v_list WHERE id = p_business_id;
    RETURN v_list;
END;
$$;


ALTER FUNCTION "public"."set_payment_methods"("p_business_id" "uuid", "p_methods" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_quote_status"("p_id" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_q public.quotes%ROWTYPE;
BEGIN
    SELECT * INTO v_q FROM public.quotes WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'That quote was not found.';
    END IF;
    PERFORM public.assert_business_member(v_q.business_id);
    PERFORM public.assert_permission(v_q.business_id, 'quotes.manage');
    IF v_q.status = 'accepted' THEN
        RAISE EXCEPTION 'This quote was accepted and is now order-based; change the order instead.';
    END IF;
    IF p_status = 'sent' THEN
        UPDATE public.quotes SET status = 'sent', sent_at = COALESCE(sent_at, NOW()), updated_at = NOW() WHERE id = p_id;
    ELSIF p_status = 'declined' THEN
        UPDATE public.quotes SET status = 'declined', decided_at = NOW(), updated_at = NOW() WHERE id = p_id;
    ELSIF p_status = 'draft' THEN
        UPDATE public.quotes SET status = 'draft', decided_at = NULL, updated_at = NOW() WHERE id = p_id;
    ELSE
        RAISE EXCEPTION 'A quote can be sent, declined or put back to draft.';
    END IF;
END;
$$;


ALTER FUNCTION "public"."set_quote_status"("p_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_card_payment"("p_reference" "text", "p_success" boolean, "p_amount_paid" numeric, "p_provider_reference" "text", "p_card_brand" "text", "p_card_last4" "text", "p_failure_reason" "text", "p_raw" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_card   public.card_payments%ROWTYPE;
    v_pid    UUID;
    v_result TEXT := 'paid';
    v_last4  TEXT := CASE WHEN p_card_last4 ~ '^[0-9]{4}$' THEN p_card_last4 END;
BEGIN
    SELECT * INTO v_card FROM public.card_payments WHERE reference = p_reference FOR UPDATE;
    IF NOT FOUND THEN
        RETURN 'unknown';
    END IF;
    IF v_card.status = 'success' THEN
        RETURN 'duplicate';
    END IF;

    IF NOT p_success THEN
        IF v_card.status = 'pending' THEN
            UPDATE public.card_payments
            SET status = 'failed', failure_reason = left(COALESCE(p_failure_reason, 'Not paid'), 300),
                raw = COALESCE(p_raw, raw), updated_at = NOW()
            WHERE id = v_card.id;
            IF v_card.online_order_id IS NOT NULL THEN
                UPDATE public.online_orders SET status = 'payment_failed'
                WHERE id = v_card.online_order_id AND status = 'pending_payment'
                  AND NOT EXISTS (SELECT 1 FROM public.mpesa_transactions m
                                  WHERE m.online_order_id = v_card.online_order_id AND m.status = 'Pending');
            END IF;
        END IF;
        RETURN 'failed';
    END IF;

    UPDATE public.card_payments
    SET status = 'success',
        amount_paid = round(COALESCE(p_amount_paid, amount), 2),
        provider_reference = COALESCE(p_provider_reference, provider_reference),
        card_brand = COALESCE(initcap(p_card_brand), card_brand),
        card_last4 = COALESCE(v_last4, card_last4),
        failure_reason = NULL,
        raw = COALESCE(p_raw, raw),
        paid_at = NOW(),
        updated_at = NOW()
    WHERE id = v_card.id
    RETURNING * INTO v_card;

    IF v_card.purpose = 'payment' THEN
        v_pid := public.process_business_payment(
            v_card.business_id, v_card.reference, v_card.amount_paid, 'Card',
            COALESCE(v_card.payer_name, 'Card payment'), v_card.payer_phone, 'Success', NOW(),
            v_card.customer_id, NULL,
            CASE WHEN v_card.customer_id IS NULL THEN 'walk-in' ELSE 'customer' END,
            COALESCE(v_card.description, 'Card payment') || COALESCE(' (' || v_card.card_brand || ' •••• ' || v_card.card_last4 || ')', ''),
            v_card.requested_by
        );
        UPDATE public.card_payments SET payment_id = v_pid WHERE id = v_card.id;
    ELSIF v_card.purpose = 'online_order' THEN
        v_result := public.fn_settle_online_order_card(v_card.id);
    END IF;

    IF v_card.purpose <> 'online_order' AND v_card.amount_paid <> v_card.amount THEN
        PERFORM public.fn_notify_staff(v_card.business_id, 'Card payment amount differs',
            format('Card payment %s was for %s but %s was paid.', v_card.reference, v_card.amount, v_card.amount_paid),
            jsonb_build_object('cardPaymentId', v_card.id));
    END IF;

    RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."settle_card_payment"("p_reference" "text", "p_success" boolean, "p_amount_paid" numeric, "p_provider_reference" "text", "p_card_brand" "text", "p_card_last4" "text", "p_failure_reason" "text", "p_raw" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_customer_debt_fifo"("p_business_id" "uuid", "p_customer_id" "uuid", "p_amount_paid" numeric, "p_recorded_by" "text") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_rec            RECORD;
    v_rem_payment    NUMERIC(14,2) := p_amount_paid;
    v_applied        NUMERIC(14,2);
    v_customer_name  TEXT;
    v_wallet_before  NUMERIC(14,2);
BEGIN
    PERFORM public.assert_permission(p_business_id, 'customers.debts');
    PERFORM public.assert_business_member(p_business_id); IF p_customer_id IS NOT NULL THEN PERFORM public.assert_business_member((SELECT business_id FROM public.customers WHERE id = p_customer_id)); END IF;
    SELECT name, wallet_balance
    INTO v_customer_name, v_wallet_before
    FROM public.customers
    WHERE id = p_customer_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Customer not found: %', p_customer_id;
    END IF;

    -- Iterate open debts oldest-first (FIFO)
    FOR v_rec IN
        SELECT id, amount_owed, amount_paid AS existing_paid, balance
        FROM public.credit_payments
        WHERE customer_id = p_customer_id
          AND business_id = p_business_id
          AND status IN ('Open', 'Partial')
        ORDER BY created_at ASC
    LOOP
        EXIT WHEN v_rem_payment <= 0;

        v_applied     := LEAST(v_rem_payment, v_rec.balance);
        v_rem_payment := v_rem_payment - v_applied;

        UPDATE public.credit_payments
        SET
            amount_paid = amount_paid + v_applied,
            status = CASE
                WHEN (amount_paid + v_applied) >= amount_owed
                    THEN 'Settled'::public.credit_status
                ELSE 'Partial'::public.credit_status
            END,
            settled_at = CASE
                WHEN (amount_paid + v_applied) >= amount_owed THEN NOW()
                ELSE NULL
            END,
            updated_at = NOW()
        WHERE id = v_rec.id;

        UPDATE public.customers
        SET debt_balance = GREATEST(0.00, debt_balance - v_applied)
        WHERE id = p_customer_id;
    END LOOP;

    -- Credit any surplus payment to the wallet
    IF v_rem_payment > 0 THEN
        UPDATE public.customers
        SET wallet_balance = wallet_balance + v_rem_payment
        WHERE id = p_customer_id;

        INSERT INTO public.wallet_transactions
            (business_id, customer_id, amount, balance_before, balance_after,
             reason, recorded_by)
        VALUES (
            p_business_id,
            p_customer_id,
            v_rem_payment,
            v_wallet_before,
            v_wallet_before + v_rem_payment,
            'Excess repayment from FIFO debt settlement',
            p_recorded_by
        );
    END IF;

    RETURN v_rem_payment;
END;
$$;


ALTER FUNCTION "public"."settle_customer_debt_fifo"("p_business_id" "uuid", "p_customer_id" "uuid", "p_amount_paid" numeric, "p_recorded_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_transfer_shortage"("p_transfer_id" "uuid", "p_lines" "jsonb", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_t      public.stock_transfers%ROWTYPE;
    v_item   public.stock_transfer_items%ROWTYPE;
    v_el     JSONB;
    v_action TEXT;
    v_open   NUMERIC;
    v_qty    NUMERIC;
    v_prod   public.products%ROWTYPE;
    v_from   TEXT;
    v_to     TEXT;
    v_me     TEXT;
    v_cost   NUMERIC;
    v_n      INTEGER := 0;
    v_note   TEXT := NULLIF(btrim(COALESCE(p_note, '')), '');
BEGIN
    SELECT * INTO v_t FROM public.stock_transfers WHERE id = p_transfer_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Transfer not found.'; END IF;
    IF v_t.status <> 'received' THEN
        RAISE EXCEPTION 'Only a received transfer can have its shortage settled.';
    END IF;
    SELECT name INTO v_from FROM public.businesses WHERE id = v_t.from_business_id;
    SELECT name INTO v_to FROM public.businesses WHERE id = v_t.to_business_id;

    FOR v_el IN SELECT * FROM jsonb_array_elements(COALESCE(p_lines, '[]'::JSONB)) LOOP
        SELECT * INTO v_item FROM public.stock_transfer_items WHERE id = (v_el->>'item_id')::UUID AND transfer_id = v_t.id FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'One of the lines is not on this transfer.'; END IF;
        v_action := v_el->>'action';
        v_open := v_item.quantity_sent - COALESCE(v_item.quantity_received, 0) - v_item.quantity_late
                  - v_item.quantity_found - v_item.quantity_written_off;
        v_qty := COALESCE(round(NULLIF(v_el->>'quantity', '')::NUMERIC, 3), v_open);
        CONTINUE WHEN v_qty = 0;
        IF v_qty < 0 OR v_qty > v_open THEN
            RAISE EXCEPTION 'Only % % of % is still short.', public.fn_qty(v_open), v_item.unit, v_item.product_name;
        END IF;

        IF v_action = 'late' THEN
            PERFORM public.assert_business_member(v_t.to_business_id);
            PERFORM public.assert_permission(v_t.to_business_id, 'inventory.receive_stock', 'inventory.transfer_stock');
            v_me := public.fn_my_display_name(v_t.to_business_id);
            SELECT * INTO v_prod FROM public.products WHERE id = v_item.to_product_id AND deleted_at IS NULL FOR UPDATE;
            IF NOT FOUND THEN RAISE EXCEPTION '% is not in this branch any more.', v_item.product_name; END IF;
            v_cost := CASE WHEN v_prod.stock <= 0 THEN v_item.unit_cost
                           ELSE ROUND((v_prod.stock * v_prod.cost + v_qty * v_item.unit_cost) / (v_prod.stock + v_qty), 2) END;
            UPDATE public.products SET stock = stock + v_qty, cost = v_cost, updated_at = NOW() WHERE id = v_prod.id;
            INSERT INTO public.inventory_adjustments (business_id, product_id, product_name, type, quantity_adjusted,
                previous_stock, new_stock, reason, staff_name, reference_number, notes)
            VALUES (v_t.to_business_id, v_prod.id, v_prod.name, 'Transfer In', v_qty, v_prod.stock, v_prod.stock + v_qty,
                'Arrived late from ' || v_from, v_me, v_t.reference, v_note);
            UPDATE public.stock_transfer_items SET quantity_late = quantity_late + v_qty, short_note = COALESCE(v_note, short_note) WHERE id = v_item.id;
        ELSIF v_action = 'found' THEN
            PERFORM public.assert_business_member(v_t.from_business_id);
            PERFORM public.assert_permission(v_t.from_business_id, 'inventory.transfer_stock');
            v_me := public.fn_my_display_name(v_t.from_business_id);
            SELECT * INTO v_prod FROM public.products WHERE id = v_item.from_product_id AND deleted_at IS NULL FOR UPDATE;
            IF NOT FOUND THEN RAISE EXCEPTION '% is not in this branch any more.', v_item.product_name; END IF;
            UPDATE public.products SET stock = stock + v_qty, updated_at = NOW() WHERE id = v_prod.id;
            INSERT INTO public.inventory_adjustments (business_id, product_id, product_name, type, quantity_adjusted,
                previous_stock, new_stock, reason, staff_name, reference_number, notes)
            VALUES (v_t.from_business_id, v_prod.id, v_prod.name, 'Transfer Return', v_qty, v_prod.stock, v_prod.stock + v_qty,
                'Short on transfer to ' || v_to || ', found here', v_me, v_t.reference, v_note);
            UPDATE public.stock_transfer_items SET quantity_found = quantity_found + v_qty, short_note = COALESCE(v_note, short_note) WHERE id = v_item.id;
        ELSIF v_action = 'written_off' THEN
            PERFORM public.assert_business_member(v_t.from_business_id);
            PERFORM public.assert_permission(v_t.from_business_id, 'inventory.transfer_stock');
            PERFORM public.assert_permission(v_t.from_business_id, 'inventory.wastage', 'inventory.adjust_stock');
            UPDATE public.stock_transfer_items SET quantity_written_off = quantity_written_off + v_qty, short_note = COALESCE(v_note, short_note) WHERE id = v_item.id;
        ELSE
            RAISE EXCEPTION 'Choose: arrived late, found, or written off.';
        END IF;
        v_n := v_n + 1;
    END LOOP;
    IF v_n = 0 THEN
        RAISE EXCEPTION 'Nothing to settle.';
    END IF;
    UPDATE public.stock_transfers SET settled_at = NOW(), updated_at = NOW() WHERE id = v_t.id;
    RETURN jsonb_build_object('id', v_t.id, 'settled', v_n);
END;
$$;


ALTER FUNCTION "public"."settle_transfer_shortage"("p_transfer_id" "uuid", "p_lines" "jsonb", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spend_points_at_till"("p_customer_id" "uuid", "p_points" integer, "p_recorded_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_customer public.customers%ROWTYPE;
    v_value_per NUMERIC(10,4);
    v_min INTEGER;
    v_value NUMERIC(14,2);
    v_id UUID;
BEGIN
    SELECT * INTO v_customer FROM public.customers WHERE id = p_customer_id AND deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Customer not found.';
    END IF;
    PERFORM public.assert_permission(v_customer.business_id, 'customers.loyalty');

    v_value_per := public.fn_point_value(v_customer.business_id, v_customer.tier);
    SELECT min_redeem_points INTO v_min
    FROM public.loyalty_settings WHERE business_id = v_customer.business_id;
    v_min := COALESCE(v_min, 100);

    IF p_points IS NULL OR p_points < v_min THEN
        RAISE EXCEPTION 'You can use points from % points.', v_min;
    END IF;
    IF p_points > v_customer.loyalty_points THEN
        RAISE EXCEPTION 'This customer only has % points.', v_customer.loyalty_points;
    END IF;

    v_value := round(p_points * v_value_per, 2);
    UPDATE public.customers SET loyalty_points = loyalty_points - p_points WHERE id = p_customer_id;
    INSERT INTO public.loyalty_redemptions (business_id, customer_id, points, value, recorded_by, kind)
    VALUES (v_customer.business_id, p_customer_id, p_points, v_value, COALESCE(NULLIF(trim(p_recorded_by), ''), 'Staff'), 'till')
    RETURNING id INTO v_id;

    RETURN jsonb_build_object('redemptionId', v_id, 'value', v_value);
END;
$$;


ALTER FUNCTION "public"."spend_points_at_till"("p_customer_id" "uuid", "p_points" integer, "p_recorded_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_assign_rider"("p_order_id" "uuid", "p_rider_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_order    public.online_orders%ROWTYPE;
    v_user_id  UUID;
    v_employee UUID;
BEGIN
    SELECT * INTO v_order FROM public.online_orders WHERE id = p_order_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order not found.';
    END IF;
    PERFORM public.assert_permission(v_order.business_id, 'orders.assign_rider');

    IF v_order.fulfilment <> 'delivery' OR v_order.status NOT IN ('paid', 'preparing', 'out_for_delivery') THEN
        RAISE EXCEPTION 'Only paid delivery orders can be given to a rider.';
    END IF;

    IF p_rider_id IS NULL THEN
        UPDATE public.online_orders SET rider_id = NULL, rider_assigned_at = NULL WHERE id = p_order_id;
        RETURN;
    END IF;

    SELECT m.user_id INTO v_user_id
    FROM public.business_memberships m
    WHERE m.business_id = v_order.business_id AND m.status = 'Active' AND m.role = 'Rider'
      AND m.user_id IN (
          SELECT p_rider_id
          UNION ALL
          SELECT e.user_id FROM public.employees e WHERE e.id = p_rider_id AND e.business_id = v_order.business_id
      )
    LIMIT 1;
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'That rider was not found.';
    END IF;
    v_employee := public.fn_sync_employee(v_order.business_id, v_user_id);

    UPDATE public.online_orders SET rider_id = v_employee, rider_assigned_at = NOW() WHERE id = p_order_id;
    INSERT INTO public.notifications (business_id, user_id, title, message, type, payload, created_by)
    VALUES (v_order.business_id, v_user_id, 'New delivery',
            'Order #' || v_order.order_number || ' for ' || v_order.customer_name || ' is assigned to you.',
            'Online Store', jsonb_build_object('orderId', p_order_id), 'system');
END;
$$;


ALTER FUNCTION "public"."staff_assign_rider"("p_order_id" "uuid", "p_rider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_clear_order_attention"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    PERFORM public.assert_permission((SELECT business_id FROM public.online_orders WHERE id = p_order_id), 'online_store.view');
    UPDATE public.online_orders
    SET needs_attention = FALSE
    WHERE id = p_order_id AND business_id = ANY(public.get_user_business_ids());
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order not found.';
    END IF;
END;
$$;


ALTER FUNCTION "public"."staff_clear_order_attention"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_mark_customer_messages_read"("p_account_id" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT public.assert_permission((SELECT business_id FROM public.customer_accounts WHERE id = p_account_id), 'online_store.view');
    UPDATE public.customer_messages
    SET read_at = NOW()
    WHERE account_id = p_account_id
      AND sender = 'customer'
      AND read_at IS NULL
      AND business_id = ANY(public.get_user_business_ids());
$$;


ALTER FUNCTION "public"."staff_mark_customer_messages_read"("p_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_send_customer_message"("p_account_id" "uuid", "p_body" "text", "p_staff_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_business_id UUID;
    v_body TEXT := trim(COALESCE(p_body, ''));
BEGIN
    PERFORM public.assert_permission((SELECT business_id FROM public.customer_accounts WHERE id = p_account_id), 'online_store.view');
    SELECT business_id INTO v_business_id FROM public.customer_accounts WHERE id = p_account_id;
    IF v_business_id IS NULL OR NOT v_business_id = ANY(public.get_user_business_ids()) THEN
        RAISE EXCEPTION 'Customer not found.';
    END IF;
    IF length(v_body) NOT BETWEEN 1 AND 1000 THEN
        RAISE EXCEPTION 'Please write a message of up to 1000 characters.';
    END IF;

    INSERT INTO public.customer_messages (business_id, account_id, sender, staff_name, body)
    VALUES (v_business_id, p_account_id, 'staff', left(p_staff_name, 100), v_body);

    UPDATE public.customer_messages
    SET read_at = NOW()
    WHERE account_id = p_account_id AND sender = 'customer' AND read_at IS NULL;
END;
$$;


ALTER FUNCTION "public"."staff_send_customer_message"("p_account_id" "uuid", "p_body" "text", "p_staff_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_update_online_order"("p_order_id" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_order public.online_orders%ROWTYPE;
    v_allowed TEXT[];
    v_message TEXT;
BEGIN
    PERFORM public.assert_permission((SELECT business_id FROM public.online_orders WHERE id = p_order_id), 'online_store.view');
    SELECT * INTO v_order FROM public.online_orders WHERE id = p_order_id FOR UPDATE;
    IF NOT FOUND OR NOT v_order.business_id = ANY(public.get_user_business_ids()) THEN
        RAISE EXCEPTION 'Order not found.';
    END IF;

    v_allowed := CASE v_order.status
        WHEN 'pending_payment' THEN ARRAY['cancelled']
        WHEN 'payment_failed' THEN ARRAY['cancelled']
        WHEN 'paid' THEN ARRAY['preparing']
        WHEN 'preparing' THEN
            CASE v_order.fulfilment WHEN 'delivery' THEN ARRAY['out_for_delivery'] ELSE ARRAY['ready_for_pickup'] END
        WHEN 'out_for_delivery' THEN ARRAY['completed']
        WHEN 'ready_for_pickup' THEN ARRAY['completed']
        ELSE ARRAY[]::TEXT[]
    END;
    IF NOT p_status = ANY(v_allowed) THEN
        RAISE EXCEPTION 'That status change is not allowed.';
    END IF;

    UPDATE public.online_orders SET status = p_status WHERE id = p_order_id;

    v_message := 'Order #' || v_order.order_number || CASE p_status
        WHEN 'preparing' THEN ' is being prepared.'
        WHEN 'out_for_delivery' THEN ' is on its way.'
        WHEN 'ready_for_pickup' THEN ' is ready for pickup.'
        WHEN 'completed' THEN ' is complete. Thank you!'
        ELSE ' was cancelled.'
    END;
    PERFORM public.fn_customer_message(v_order.account_id, v_order.id, v_message);
END;
$$;


ALTER FUNCTION "public"."staff_update_online_order"("p_order_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_my_review"("p_product_id" "uuid", "p_rating" integer, "p_title" "text", "p_body" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_account  public.customer_accounts%ROWTYPE;
    v_verified BOOLEAN;
    v_id       UUID;
    v_title    TEXT := NULLIF(left(trim(COALESCE(p_title, '')), 120), '');
    v_body     TEXT := trim(COALESCE(p_body, ''));
BEGIN
    SELECT * INTO v_account FROM public.customer_accounts WHERE id = auth.uid();
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Please sign in to write a review.';
    END IF;
    IF p_rating IS NULL OR p_rating NOT BETWEEN 1 AND 5 THEN
        RAISE EXCEPTION 'Please choose a star rating.';
    END IF;
    IF length(v_body) < 3 THEN
        RAISE EXCEPTION 'Please write a few words about your experience.';
    END IF;
    IF length(v_body) > 2000 THEN
        RAISE EXCEPTION 'Please keep your review under 2000 characters.';
    END IF;
    IF p_product_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.products
        WHERE id = p_product_id AND business_id = v_account.business_id AND deleted_at IS NULL AND show_on_website
    ) THEN
        RAISE EXCEPTION 'That product is no longer available.';
    END IF;
    -- A few reviews an hour is plenty for a real customer.
    IF (SELECT count(*) FROM public.website_reviews
        WHERE account_id = v_account.id AND updated_at > NOW() - INTERVAL '1 hour') >= 5 THEN
        RAISE EXCEPTION 'You have sent several reviews just now. Please try again later.';
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM public.online_orders o
        WHERE o.account_id = v_account.id
          AND o.status IN ('paid', 'preparing', 'out_for_delivery', 'ready_for_pickup', 'completed')
          AND (p_product_id IS NULL OR EXISTS (
              SELECT 1 FROM public.online_order_items i WHERE i.order_id = o.id AND i.product_id = p_product_id))
    ) INTO v_verified;

    INSERT INTO public.website_reviews
        (business_id, account_id, product_id, rating, title, body, display_name, verified)
    VALUES
        (v_account.business_id, v_account.id, p_product_id, p_rating, v_title, v_body,
         public.fn_review_display_name(v_account.name), v_verified)
    ON CONFLICT (account_id, COALESCE(product_id, '00000000-0000-0000-0000-000000000000'::uuid))
    DO UPDATE SET rating = EXCLUDED.rating, title = EXCLUDED.title, body = EXCLUDED.body,
                  display_name = EXCLUDED.display_name, verified = EXCLUDED.verified,
                  status = 'pending', featured = FALSE, updated_at = NOW()
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."submit_my_review"("p_product_id" "uuid", "p_rating" integer, "p_title" "text", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_website_feedback"("p_slug" "text", "p_name" "text", "p_contact" "text", "p_rating" integer, "p_comment" "text", "p_type" "text" DEFAULT 'feedback'::"text", "p_product_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_business_id UUID;
    v_name TEXT := trim(COALESCE(p_name, ''));
    v_contact TEXT := trim(COALESCE(p_contact, ''));
    v_comment TEXT := trim(COALESCE(p_comment, ''));
    v_rating INTEGER := CASE WHEN p_type = 'suggestion' THEN 3 ELSE p_rating END;
    v_product TEXT;
    v_account UUID;
BEGIN
    IF length(v_name) NOT BETWEEN 1 AND 100
       OR length(v_contact) > 120
       OR length(v_comment) NOT BETWEEN 1 AND 2000
       OR p_type NOT IN ('feedback', 'suggestion', 'complaint')
       OR v_rating IS NULL
       OR v_rating NOT BETWEEN 1 AND 5 THEN
        RAISE EXCEPTION 'Invalid feedback' USING ERRCODE = '22023';
    END IF;

    SELECT id INTO v_business_id
    FROM public.businesses
    WHERE website_slug = p_slug AND deleted_at IS NULL;

    IF v_business_id IS NULL THEN
        RAISE EXCEPTION 'Unknown website' USING ERRCODE = 'P0002';
    END IF;

    IF (
        SELECT count(*) FROM public.complaints
        WHERE business_id = v_business_id
          AND last_modified_by = 'website'
          AND created_at > NOW() - INTERVAL '1 hour'
    ) >= 30 THEN
        RAISE EXCEPTION 'Too many submissions' USING ERRCODE = '53400';
    END IF;

    SELECT name INTO v_product FROM public.products
    WHERE id = p_product_id AND business_id = v_business_id AND deleted_at IS NULL;

    SELECT id INTO v_account FROM public.customer_accounts
    WHERE id = auth.uid() AND business_id = v_business_id;

    INSERT INTO public.complaints
        (business_id, customer_name, rating, comment, sentiment, branch, last_modified_by,
         feedback_type, product_id, account_id)
    VALUES (
        v_business_id,
        v_name,
        v_rating,
        CASE WHEN v_product IS NULL THEN '' ELSE 'About ' || v_product || E':\n' END
            || v_comment
            || CASE WHEN v_contact = '' THEN '' ELSE E'\n\nContact: ' || v_contact END,
        (CASE WHEN v_rating >= 4 THEN 'positive'
              WHEN v_rating = 3 THEN 'neutral'
              ELSE 'negative' END)::public.sentiment,
        'Website',
        'website',
        p_type,
        CASE WHEN v_product IS NULL THEN NULL ELSE p_product_id END,
        v_account
    );

    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."submit_website_feedback"("p_slug" "text", "p_name" "text", "p_contact" "text", "p_rating" integer, "p_comment" "text", "p_type" "text", "p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."suggest_product_idea"("p_title" "text", "p_description" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_account public.customer_accounts%ROWTYPE;
    v_title   TEXT := regexp_replace(trim(COALESCE(p_title, '')), '\s+', ' ', 'g');
    v_desc    TEXT := NULLIF(trim(COALESCE(p_description, '')), '');
    v_same    public.website_product_ideas%ROWTYPE;
    v_id      UUID;
BEGIN
    SELECT * INTO v_account FROM public.customer_accounts WHERE id = auth.uid();
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Please sign in to suggest a product.';
    END IF;
    IF length(v_title) < 3 THEN
        RAISE EXCEPTION 'Please name the product you would like, in at least 3 letters.';
    END IF;
    IF length(v_title) > 80 THEN
        RAISE EXCEPTION 'Please keep the product name under 80 characters. Put the details in the description.';
    END IF;
    IF length(v_desc) > 500 THEN
        RAISE EXCEPTION 'Please keep the description under 500 characters.';
    END IF;

    SELECT * INTO v_same FROM public.website_product_ideas
    WHERE business_id = v_account.business_id AND lower(title) = lower(v_title) AND status <> 'hidden'
    LIMIT 1;
    IF FOUND THEN
        IF v_same.status IN ('open', 'planned') THEN
            RAISE EXCEPTION '"%" is already on the list. Vote for it there instead.', v_same.title;
        ELSIF v_same.status = 'available' THEN
            RAISE EXCEPTION 'Good news: "%" is already in our shop.', v_same.title;
        ELSE
            RAISE EXCEPTION 'Someone has already suggested "%". We will add it to the list once we have looked at it.', v_same.title;
        END IF;
    END IF;

    IF (SELECT count(*) FROM public.website_product_ideas
        WHERE suggested_by = v_account.id AND created_at > NOW() - INTERVAL '1 day') >= 3 THEN
        RAISE EXCEPTION 'You can suggest up to 3 products a day. Please try again tomorrow.';
    END IF;

    INSERT INTO public.website_product_ideas
        (business_id, kind, title, description, status, suggested_by, suggested_name, created_by)
    VALUES
        (v_account.business_id, 'suggestion', v_title, v_desc, 'pending', v_account.id,
         public.fn_review_display_name(v_account.name), 'Website')
    RETURNING id INTO v_id;

    PERFORM set_config('app.idea_votes', 'on', TRUE);
    INSERT INTO public.website_product_idea_votes (idea_id, account_id) VALUES (v_id, v_account.id);
    UPDATE public.website_product_ideas SET vote_count = 1 WHERE id = v_id;
    PERFORM set_config('app.idea_votes', 'off', TRUE);

    PERFORM public.fn_notify_staff(v_account.business_id, 'New product suggestion',
        format('%s suggested "%s" on the website. Approve it in Online Store → Product ideas.',
               public.fn_review_display_name(v_account.name), v_title),
        jsonb_build_object('ideaId', v_id));
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."suggest_product_idea"("p_title" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supplier_access_list"("p_supplier_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_b UUID;
BEGIN
    SELECT business_id INTO v_b FROM public.suppliers WHERE id = p_supplier_id;
    IF v_b IS NULL THEN RETURN '{}'::JSONB; END IF;
    PERFORM public.assert_business_member(v_b);
    PERFORM public.assert_permission(v_b, 'suppliers.view');
    RETURN jsonb_build_object(
        'accounts', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', a.id, 'name', u.name, 'email', u.email, 'since', a.created_at,
                                                                 'lastSeen', a.last_seen_at) ORDER BY a.created_at)
                              FROM public.supplier_accounts a JOIN public.users u ON u.id = a.user_id
                              WHERE a.supplier_id = p_supplier_id AND a.status = 'active'), '[]'::JSONB),
        'invitations', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', i.id, 'name', i.name, 'email', i.email, 'code', i.invitation_token,
                                                                    'expiresAt', i.expires_at) ORDER BY i.created_at)
                                 FROM public.invitations i
                                 WHERE i.supplier_id = p_supplier_id AND i.status = 'Pending' AND i.expires_at > NOW()), '[]'::JSONB));
END;
$$;


ALTER FUNCTION "public"."supplier_access_list"("p_supplier_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supplier_can"("p_business_id" "uuid", "p_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT COALESCE(
        (SELECT rp.granted FROM public.role_permissions rp
         WHERE rp.business_id = p_business_id AND rp.role::TEXT = 'Supplier' AND rp.permission = p_code),
        p_code = ANY(COALESCE((SELECT d.permissions FROM public.role_default_permissions d WHERE d.role = 'Supplier'), '{}'))
    );
$$;


ALTER FUNCTION "public"."supplier_can"("p_business_id" "uuid", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supplier_portal_accounts"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_me UUID := public.fn_my_user_id();
BEGIN
    IF v_me IS NULL THEN RETURN '[]'::JSONB; END IF;
    UPDATE public.supplier_accounts SET last_seen_at = NOW()
    WHERE user_id = v_me AND status = 'active' AND (last_seen_at IS NULL OR last_seen_at < NOW() - INTERVAL '5 minutes');
    RETURN COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
            'accountId', a.id,
            'businessId', b.id,
            'businessName', b.name,
            'businessLogo', b.logo_url,
            'businessPhone', b.contact_phone,
            'supplierId', s.id,
            'supplierName', COALESCE(NULLIF(s.company, ''), s.name),
            'can', jsonb_build_object(
                'orders', public.supplier_can(b.id, 'supplier_portal.orders'),
                'priceRequests', public.supplier_can(b.id, 'supplier_portal.price_requests'),
                'deliveries', public.supplier_can(b.id, 'supplier_portal.deliveries'),
                'statement', public.supplier_can(b.id, 'supplier_portal.statement'),
                'updateDetails', public.supplier_can(b.id, 'supplier_portal.update_details'),
                'stock', public.supplier_can(b.id, 'supplier_portal.stock'))
        ) ORDER BY b.name)
        FROM public.supplier_accounts a
        JOIN public.businesses b ON b.id = a.business_id AND b.deleted_at IS NULL
        JOIN public.suppliers s ON s.id = a.supplier_id AND s.deleted_at IS NULL
        WHERE a.user_id = v_me AND a.status = 'active'
    ), '[]'::JSONB);
END;
$$;


ALTER FUNCTION "public"."supplier_portal_accounts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supplier_portal_confirm"("p_purchase_id" "uuid", "p_expected_date" "date", "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_p public.purchases%ROWTYPE;
BEGIN
    SELECT * INTO v_p FROM public.purchases WHERE id = p_purchase_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That order was not found.'; END IF;
    IF public.assert_supplier(v_p.business_id, 'supplier_portal.orders') IS DISTINCT FROM v_p.supplier_id THEN
        RAISE EXCEPTION 'That order was not found.';
    END IF;
    IF v_p.status NOT IN ('Ordered', 'Part received') THEN
        RAISE EXCEPTION 'Only an open order can be confirmed.';
    END IF;
    IF p_expected_date IS NULL OR p_expected_date < (NOW() AT TIME ZONE 'Africa/Nairobi')::DATE THEN
        RAISE EXCEPTION 'Choose the day you will deliver (today or later).';
    END IF;
    -- Only these three fields: the purchase rules in fn_purchase_guard stay as they are.
    UPDATE public.purchases
    SET supplier_confirmed_at = NOW(), supplier_expected_date = p_expected_date,
        supplier_note = left(NULLIF(btrim(COALESCE(p_note, '')), ''), 500), updated_at = NOW()
    WHERE id = v_p.id;
    PERFORM public.fn_buying_notify(v_p.business_id, NULL, 'Purchase', 'Supplier confirmed an order',
        COALESCE(v_p.supplier_name, 'The supplier') || ' confirmed ' || public.fn_purchase_ref(v_p) || ' for '
            || to_char(p_expected_date, 'Dy DD Mon') || COALESCE(': ' || NULLIF(btrim(COALESCE(p_note, '')), ''), '') || '.',
        'buying', jsonb_build_object('purchaseId', v_p.id));
END;
$$;


ALTER FUNCTION "public"."supplier_portal_confirm"("p_purchase_id" "uuid", "p_expected_date" "date", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supplier_portal_data"("p_business_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_s      UUID := public.assert_supplier(p_business_id, NULL);
    v_sup    public.suppliers%ROWTYPE;
    v_orders JSONB := '[]'::JSONB;
    v_quotes JSONB := '[]'::JSONB;
    v_grns   JSONB := '[]'::JSONB;
    v_bills  JSONB := '[]'::JSONB;
    v_pays   JSONB := '[]'::JSONB;
    v_rets   JSONB := '[]'::JSONB;
    v_stock  JSONB := '[]'::JSONB;
    v_owed   NUMERIC := 0;
BEGIN
    SELECT * INTO v_sup FROM public.suppliers WHERE id = v_s;

    IF public.supplier_can(p_business_id, 'supplier_portal.orders') THEN
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'id', p.id, 'number', public.fn_purchase_ref(p), 'theirRef', p.reference_number,
            'status', p.status, 'orderedAt', COALESCE(p.ordered_at, p.date), 'total', p.total_amount,
            'confirmedAt', p.supplier_confirmed_at, 'expectedDate', p.supplier_expected_date, 'supplierNote', p.supplier_note,
            'notes', p.notes,
            'lines', (SELECT COALESCE(jsonb_agg(jsonb_build_object('name', i.name, 'quantity', i.quantity, 'unit', i.unit, 'price', i.price,
                                                                  'received', COALESCE(i.qty_received, 0), 'damaged', COALESCE(i.qty_damaged, 0))
                                                ORDER BY i.created_at), '[]'::JSONB)
                      FROM public.purchase_items i WHERE i.purchase_id = p.id)
        ) ORDER BY COALESCE(p.ordered_at, p.date) DESC), '[]'::JSONB)
        INTO v_orders
        FROM public.purchases p
        WHERE p.business_id = p_business_id AND p.supplier_id = v_s
          AND (p.status IN ('Ordered', 'Part received', 'Received') OR (p.status = 'Cancelled' AND p.ordered_at IS NOT NULL));
    END IF;

    IF public.supplier_can(p_business_id, 'supplier_portal.price_requests') THEN
        -- Only their own quote: never another supplier's prices, nor the price paid before.
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'id', q.id, 'status', q.status, 'askedAt', q.asked_at, 'pricedAt', q.priced_at, 'total', q.total,
            'deliveryDays', q.delivery_days, 'note', q.note, 'open', q.status IN ('asked', 'priced') AND p.status = 'RFQ',
            'purchaseNotes', p.notes,
            'lines', (SELECT COALESCE(jsonb_agg(jsonb_build_object('itemId', i.id, 'name', i.name, 'quantity', i.quantity, 'unit', i.unit,
                                                                  'price', ql.unit_price, 'available', COALESCE(ql.available, TRUE))
                                                ORDER BY i.created_at), '[]'::JSONB)
                      FROM public.purchase_items i
                      LEFT JOIN public.purchase_quote_lines ql ON ql.quote_id = q.id AND ql.purchase_item_id = i.id
                      WHERE i.purchase_id = p.id)
        ) ORDER BY q.asked_at DESC), '[]'::JSONB)
        INTO v_quotes
        FROM public.purchase_quotes q
        JOIN public.purchases p ON p.id = q.purchase_id
        WHERE q.business_id = p_business_id AND q.supplier_id = v_s;
    END IF;

    IF public.supplier_can(p_business_id, 'supplier_portal.deliveries') THEN
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'id', r.id, 'number', r.number, 'receivedAt', r.received_at, 'receivedBy', r.received_by, 'note', r.note,
            'orderNumber', public.fn_purchase_ref(p), 'value', r.total_value, 'damagedValue', r.damaged_value,
            'lines', (SELECT COALESCE(jsonb_agg(jsonb_build_object('name', l.name, 'unit', l.unit, 'received', l.qty_received, 'damaged', l.qty_damaged)), '[]'::JSONB)
                      FROM public.purchase_receipt_lines l WHERE l.receipt_id = r.id)
        ) ORDER BY r.received_at DESC), '[]'::JSONB)
        INTO v_grns
        FROM public.purchase_receipts r
        JOIN public.purchases p ON p.id = r.purchase_id
        WHERE r.business_id = p_business_id AND p.supplier_id = v_s;
    END IF;

    IF public.supplier_can(p_business_id, 'supplier_portal.statement') THEN
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'id', b.id, 'number', b.number, 'theirInvoice', b.supplier_invoice_no, 'date', b.bill_date, 'dueDate', b.due_date,
            'total', b.total, 'vat', b.vat_total, 'paid', b.paid, 'balance', b.balance, 'status', b.status
        ) ORDER BY b.bill_date DESC), '[]'::JSONB),
        COALESCE(SUM(b.balance) FILTER (WHERE b.status IN ('open', 'needs_check')), 0)
        INTO v_bills, v_owed
        FROM public.supplier_bills b
        WHERE b.business_id = p_business_id AND b.supplier_id = v_s AND b.status <> 'void';

        SELECT COALESCE(jsonb_agg(jsonb_build_object('id', sp.id, 'amount', sp.amount, 'method', sp.method, 'paidAt', sp.paid_at,
                                                     'reference', sp.reference, 'bill', b.number) ORDER BY sp.paid_at DESC), '[]'::JSONB)
        INTO v_pays
        FROM public.supplier_payments sp
        LEFT JOIN public.supplier_bills b ON b.id = sp.bill_id
        WHERE sp.business_id = p_business_id AND sp.supplier_id = v_s AND sp.voided_at IS NULL;

        SELECT COALESCE(jsonb_agg(jsonb_build_object('id', r.id, 'number', r.number, 'date', r.created_at, 'reason', r.reason, 'total', r.total,
                                                     'lines', (SELECT COALESCE(jsonb_agg(jsonb_build_object('name', l.name, 'unit', l.unit, 'quantity', l.quantity)), '[]'::JSONB)
                                                               FROM public.supplier_return_lines l WHERE l.return_id = r.id))
                                  ORDER BY r.created_at DESC), '[]'::JSONB)
        INTO v_rets
        FROM public.supplier_returns r
        WHERE r.business_id = p_business_id AND r.supplier_id = v_s;
    END IF;

    IF public.supplier_can(p_business_id, 'supplier_portal.stock') THEN
        SELECT COALESCE(jsonb_agg(jsonb_build_object('name', pr.name, 'unit', pr.unit, 'stock', pr.stock,
                                                     'reorderLevel', COALESCE(pr.reorder_level, pr.min_stock)) ORDER BY pr.name), '[]'::JSONB)
        INTO v_stock
        FROM public.products pr
        WHERE pr.business_id = p_business_id AND pr.preferred_supplier_id = v_s AND pr.deleted_at IS NULL;
    END IF;

    RETURN jsonb_build_object(
        'supplier', jsonb_build_object('id', v_sup.id, 'name', v_sup.name, 'company', v_sup.company, 'phone', v_sup.phone, 'email', v_sup.email,
                                       'kraPin', v_sup.kra_pin, 'mpesaPaybill', v_sup.mpesa_paybill, 'mpesaAccount', v_sup.mpesa_account,
                                       'mpesaTill', v_sup.mpesa_till, 'bankName', v_sup.bank_name, 'bankAccount', v_sup.bank_account),
        'orders', v_orders, 'priceRequests', v_quotes, 'deliveries', v_grns,
        'bills', v_bills, 'payments', v_pays, 'returns', v_rets, 'owed', v_owed, 'stock', v_stock);
END;
$$;


ALTER FUNCTION "public"."supplier_portal_data"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supplier_portal_price"("p_quote_id" "uuid", "p_lines" "jsonb", "p_delivery_days" integer DEFAULT NULL::integer, "p_note" "text" DEFAULT NULL::"text") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_q     public.purchase_quotes%ROWTYPE;
    v_p     public.purchases%ROWTYPE;
    v_el    JSONB;
    v_total NUMERIC;
BEGIN
    SELECT * INTO v_q FROM public.purchase_quotes WHERE id = p_quote_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That price request was not found.'; END IF;
    IF public.assert_supplier(v_q.business_id, 'supplier_portal.price_requests') IS DISTINCT FROM v_q.supplier_id THEN
        RAISE EXCEPTION 'That price request was not found.';
    END IF;
    SELECT * INTO v_p FROM public.purchases WHERE id = v_q.purchase_id;
    IF v_q.status IN ('won', 'lost') OR v_p.status <> 'RFQ' THEN
        RAISE EXCEPTION 'This price request is closed: the business has already chosen.';
    END IF;
    IF p_delivery_days IS NOT NULL AND (p_delivery_days < 0 OR p_delivery_days > 365) THEN
        RAISE EXCEPTION 'Days to deliver must be between 0 and 365.';
    END IF;
    FOR v_el IN SELECT * FROM jsonb_array_elements(COALESCE(p_lines, '[]'::JSONB)) LOOP
        IF NOT EXISTS (SELECT 1 FROM public.purchase_items WHERE id = (v_el->>'itemId')::UUID AND purchase_id = v_q.purchase_id) THEN
            RAISE EXCEPTION 'One of the items is not on this request. Refresh and try again.';
        END IF;
        IF COALESCE(NULLIF(v_el->>'price', '')::NUMERIC, 0) < 0 THEN
            RAISE EXCEPTION 'A price can''t be below zero.';
        END IF;
        INSERT INTO public.purchase_quote_lines (business_id, quote_id, purchase_item_id, unit_price, available)
        VALUES (v_q.business_id, v_q.id, (v_el->>'itemId')::UUID, round(COALESCE(NULLIF(v_el->>'price', '')::NUMERIC, 0), 2),
                COALESCE((v_el->>'available')::BOOLEAN, TRUE))
        ON CONFLICT (quote_id, purchase_item_id) DO UPDATE SET unit_price = EXCLUDED.unit_price, available = EXCLUDED.available;
    END LOOP;
    SELECT COALESCE(SUM(round(pi.quantity * ql.unit_price, 2)), 0) INTO v_total
    FROM public.purchase_quote_lines ql JOIN public.purchase_items pi ON pi.id = ql.purchase_item_id
    WHERE ql.quote_id = v_q.id AND ql.available;
    UPDATE public.purchase_quotes
    SET status = 'priced', priced_at = NOW(), total = v_total, delivery_days = p_delivery_days,
        note = NULLIF(trim(COALESCE(p_note, '')), ''), priced_by_supplier = TRUE
    WHERE id = v_q.id;
    PERFORM public.fn_buying_notify(v_q.business_id, NULL, 'Purchase', 'Supplier sent prices',
        v_q.supplier_name || ' priced ' || public.fn_purchase_ref(v_p) || ': KSh ' || to_char(v_total, 'FM999,999,990.00')
            || COALESCE(', delivery in ' || p_delivery_days || ' days', '') || '. Compare and choose in Buying.',
        'buying', jsonb_build_object('purchaseId', v_p.id));
    RETURN v_total;
END;
$$;


ALTER FUNCTION "public"."supplier_portal_price"("p_quote_id" "uuid", "p_lines" "jsonb", "p_delivery_days" integer, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supplier_portal_update_details"("p_business_id" "uuid", "p_details" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_s UUID := public.assert_supplier(p_business_id, 'supplier_portal.update_details');
    f   TEXT;
BEGIN
    FOREACH f IN ARRAY ARRAY['phone', 'email', 'kraPin', 'mpesaPaybill', 'mpesaAccount', 'mpesaTill', 'bankName', 'bankAccount'] LOOP
        IF length(COALESCE(p_details->>f, '')) > 80 THEN
            RAISE EXCEPTION 'That is too long.';
        END IF;
    END LOOP;
    IF NULLIF(btrim(COALESCE(p_details->>'phone', '')), '') IS NULL THEN
        RAISE EXCEPTION 'Keep a phone number the business can reach you on.';
    END IF;
    UPDATE public.suppliers SET
        phone         = btrim(p_details->>'phone'),
        email         = NULLIF(btrim(COALESCE(p_details->>'email', '')), ''),
        kra_pin       = NULLIF(upper(btrim(COALESCE(p_details->>'kraPin', ''))), ''),
        mpesa_paybill = NULLIF(btrim(COALESCE(p_details->>'mpesaPaybill', '')), ''),
        mpesa_account = NULLIF(btrim(COALESCE(p_details->>'mpesaAccount', '')), ''),
        mpesa_till    = NULLIF(btrim(COALESCE(p_details->>'mpesaTill', '')), ''),
        bank_name     = NULLIF(btrim(COALESCE(p_details->>'bankName', '')), ''),
        bank_account  = NULLIF(btrim(COALESCE(p_details->>'bankAccount', '')), ''),
        details_updated_by_supplier_at = NOW(),
        last_modified_by = 'supplier:' || COALESCE(public.fn_my_user_id()::TEXT, ''),
        updated_at = NOW()
    WHERE id = v_s;
    PERFORM public.fn_buying_notify(p_business_id, NULL, 'Purchase', 'Supplier changed their details',
        (SELECT COALESCE(NULLIF(company, ''), name) FROM public.suppliers WHERE id = v_s)
            || ' changed their contacts or how they get paid. Check them before the next payment.',
        'buying', jsonb_build_object('supplierId', v_s));
END;
$$;


ALTER FUNCTION "public"."supplier_portal_update_details"("p_business_id" "uuid", "p_details" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."switch_my_store"("p_slug" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_account  public.customer_accounts%ROWTYPE;
    v_target   UUID;
    v_store    public.customer_account_stores%ROWTYPE;
    v_customer UUID;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Please sign in first.';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::TEXT, 0));

    SELECT * INTO v_account FROM public.customer_accounts WHERE id = auth.uid() FOR UPDATE;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    SELECT id INTO v_target FROM public.businesses
    WHERE website_slug = p_slug AND deleted_at IS NULL;
    IF v_target IS NULL THEN
        RAISE EXCEPTION 'This shop is not available.';
    END IF;
    IF v_target = v_account.business_id THEN
        RETURN p_slug;
    END IF;
    IF NOT public.fn_branches_share_owner(v_account.business_id, v_target) THEN
        RAISE EXCEPTION 'You can only switch between branches of the same shop.';
    END IF;

    -- Keep the store being left, so its points and delivery area are there on the way back.
    INSERT INTO public.customer_account_stores (account_id, business_id, customer_id, delivery_zone_id)
    VALUES (v_account.id, v_account.business_id, v_account.customer_id, v_account.delivery_zone_id)
    ON CONFLICT (account_id, business_id) DO UPDATE
    SET customer_id = EXCLUDED.customer_id,
        delivery_zone_id = EXCLUDED.delivery_zone_id,
        updated_at = NOW();

    SELECT * INTO v_store FROM public.customer_account_stores
    WHERE account_id = v_account.id AND business_id = v_target;
    v_customer := v_store.customer_id;

    -- First visit to this store (or its customer was removed): a new customer there. Never
    -- matched to an existing customer by phone, because the phone number is unverified.
    IF v_customer IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.customers WHERE id = v_customer AND deleted_at IS NULL
    ) THEN
        INSERT INTO public.customers (business_id, name, phone, email, description, last_modified_by)
        VALUES (v_target, v_account.name, v_account.phone, v_account.email, 'Website account', 'website')
        RETURNING id INTO v_customer;
        INSERT INTO public.customer_account_stores (account_id, business_id, customer_id)
        VALUES (v_account.id, v_target, v_customer)
        ON CONFLICT (account_id, business_id) DO UPDATE SET customer_id = EXCLUDED.customer_id, updated_at = NOW();
    END IF;

    UPDATE public.customer_accounts
    SET business_id = v_target,
        customer_id = v_customer,
        delivery_zone_id = v_store.delivery_zone_id
    WHERE id = v_account.id;

    RETURN p_slug;
END;
$$;


ALTER FUNCTION "public"."switch_my_store"("p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transfer_request_catalog"("p_to_business_id" "uuid", "p_from_business_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    PERFORM public.assert_business_member(p_to_business_id);
    PERFORM public.assert_permission(p_to_business_id, 'inventory.request_transfer', 'inventory.transfer_stock');
    IF p_from_business_id IS NULL OR p_from_business_id = p_to_business_id
       OR NOT public.fn_branches_share_owner(p_from_business_id, p_to_business_id) THEN
        RAISE EXCEPTION 'You can only ask another branch of this business.';
    END IF;
    RETURN COALESCE((
        SELECT jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'sku', p.sku, 'unit', p.unit, 'category', p.category,
                                            'price', p.price, 'stock', p.stock) ORDER BY p.name)
        FROM public.products p
        WHERE p.business_id = p_from_business_id AND p.deleted_at IS NULL
          AND NOT EXISTS (
              SELECT 1 FROM public.products x
              WHERE x.business_id = p_to_business_id AND x.deleted_at IS NULL
                AND ((NULLIF(p.sku, '') IS NOT NULL AND x.sku = p.sku) OR lower(btrim(x.name)) = lower(btrim(p.name))))
    ), '[]'::JSONB);
END;
$$;


ALTER FUNCTION "public"."transfer_request_catalog"("p_to_business_id" "uuid", "p_from_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unmatched_payments"("p_business_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v JSONB;
BEGIN
    PERFORM public.assert_business_member(p_business_id);
    PERFORM public.assert_permission(p_business_id, 'invoices.manage');
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', p.id, 'reference', p.reference_code, 'amount', p.amount, 'free', p.amount - COALESCE(u.used, 0),
        'method', p.method, 'name', COALESCE(p.customer_name, p.sender_name), 'phone', p.sender_phone, 'date', p.date)
        ORDER BY p.date DESC), '[]'::JSONB) INTO v
    FROM public.payments p
    LEFT JOIN (SELECT payment_id, SUM(amount) AS used FROM public.invoice_payments WHERE voided_at IS NULL GROUP BY payment_id) u
        ON u.payment_id = p.id
    WHERE p.business_id = p_business_id AND p.status = 'Success'
      AND COALESCE(p.debt_applied, 0) = 0 AND COALESCE(p.wallet_applied, 0) = 0
      AND p.amount - COALESCE(u.used, 0) > 0
      AND p.date > NOW() - INTERVAL '120 days'
      AND NOT EXISTS (SELECT 1 FROM public.transactions t WHERE t.business_id = p.business_id AND t.reference_id = p.reference_code)
    LIMIT 200;
    RETURN v;
END;
$$;


ALTER FUNCTION "public"."unmatched_payments"("p_business_id" "uuid") OWNER TO "postgres";


