CREATE OR REPLACE FUNCTION "public"."update_team_member"("p_business_id" "uuid", "p_user_id" "uuid", "p_name" "text", "p_phone" "text", "p_avatar" "text" DEFAULT NULL::"text", "p_role" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_me     UUID := (SELECT id FROM public.users WHERE auth_user_id = auth.uid());
    v_target public.business_memberships%ROWTYPE;
    v_name   TEXT := NULLIF(TRIM(COALESCE(p_name, '')), '');
BEGIN
    IF v_me IS NULL THEN
        RAISE EXCEPTION 'Please sign in first.' USING ERRCODE = '42501';
    END IF;

    SELECT * INTO v_target FROM public.business_memberships
    WHERE business_id = p_business_id AND user_id = p_user_id AND status = 'Active';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'That team member was not found.';
    END IF;

    IF p_user_id <> v_me THEN
        PERFORM public.assert_permission(p_business_id, 'staff.update');
    ELSE
        PERFORM public.assert_business_member(p_business_id);
    END IF;

    IF v_name IS NULL THEN
        RAISE EXCEPTION 'Please enter a name.';
    END IF;

    UPDATE public.users
    SET name = v_name,
        phone = NULLIF(TRIM(COALESCE(p_phone, '')), ''),
        avatar = COALESCE(NULLIF(p_avatar, ''), avatar)
    WHERE id = p_user_id;

    IF p_role IS NOT NULL AND p_role <> v_target.role::TEXT THEN
        IF p_user_id = v_me THEN
            RAISE EXCEPTION 'You can''t change your own role.';
        END IF;
        IF v_target.role = 'Owner' OR p_role = 'Owner' THEN
            RAISE EXCEPTION 'The owner''s role can''t be changed here.';
        END IF;
        PERFORM public.assert_permission(p_business_id, 'staff.roles');
        UPDATE public.business_memberships
        SET role = p_role::public.employee_role
        WHERE id = v_target.id;
    END IF;

    PERFORM public.fn_sync_employee(p_business_id, p_user_id);
EXCEPTION
    WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'That role is not valid.';
END;
$$;


ALTER FUNCTION "public"."update_team_member"("p_business_id" "uuid", "p_user_id" "uuid", "p_name" "text", "p_phone" "text", "p_avatar" "text", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_user_password_by_email"("p_email" "text", "p_new_password" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'auth'
    AS $$
DECLARE
    v_clean_email TEXT;
BEGIN
    v_clean_email := LOWER(TRIM(p_email));

    -- Update encrypted password in auth.users using extensions.crypt and extensions.gen_salt
    UPDATE auth.users
    SET encrypted_password = extensions.crypt(p_new_password, extensions.gen_salt('bf')),
        updated_at = NOW()
    WHERE LOWER(TRIM(email)) = v_clean_email;

    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."update_user_password_by_email"("p_email" "text", "p_new_password" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_password_reset_otp"("p_email" "text", "p_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_success BOOLEAN := FALSE;
    v_clean_email TEXT;
    v_clean_code TEXT;
BEGIN
    v_clean_email := LOWER(TRIM(p_email));
    v_clean_code  := TRIM(p_code);

    IF EXISTS (
        SELECT 1 FROM public.otps
        WHERE LOWER(TRIM(email)) = v_clean_email
          AND TRIM(code) = v_clean_code
          AND type = 'password_reset'
          AND expires_at > NOW()
    ) THEN
        DELETE FROM public.otps
        WHERE LOWER(TRIM(email)) = v_clean_email
          AND type = 'password_reset';

        v_success := TRUE;
    END IF;

    RETURN v_success;
END;
$$;


ALTER FUNCTION "public"."verify_password_reset_otp"("p_email" "text", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_signup_otp"("p_email" "text", "p_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_success BOOLEAN := FALSE;
BEGIN
    IF EXISTS (
        SELECT 1 FROM public.otps
        WHERE email = p_email
          AND code = p_code
          AND type = 'signup'
          AND expires_at > NOW()
    ) THEN
        DELETE FROM public.otps WHERE email = p_email AND type = 'signup';

        UPDATE public.users
        SET is_verified = TRUE
        WHERE email = p_email;

        UPDATE auth.users
        SET
            email_confirmed_at = NOW(),
            raw_app_meta_data  = COALESCE(raw_app_meta_data, '{}') ||
                                 jsonb_build_object('provider', 'email', 'providers', ARRAY['email'])
        WHERE email = p_email;

        v_success := TRUE;
    END IF;

    RETURN v_success;
END;
$$;


ALTER FUNCTION "public"."verify_signup_otp"("p_email" "text", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_business_payment"("p_payment_id" "uuid", "p_reason" "text", "p_voided_by" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_pay        public.payments%ROWTYPE;
    v_wallet     NUMERIC(14,2);
    v_debt       NUMERIC(14,2);
    v_offset     NUMERIC(14,2);
    v_remaining  NUMERIC(14,2);
    v_take       NUMERIC(14,2);
    v_rec        RECORD;
    v_by         TEXT := COALESCE(NULLIF(trim(p_voided_by), ''), 'System');
    v_note       TEXT;
BEGIN
    SELECT * INTO v_pay FROM public.payments WHERE id = p_payment_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Payment not found.';
    END IF;

    PERFORM public.assert_business_member(v_pay.business_id);
    PERFORM public.assert_permission(v_pay.business_id, 'payments.manage');

    IF v_pay.status = 'Voided' THEN
        RETURN;
    END IF;
    IF COALESCE(trim(p_reason), '') = '' THEN
        RAISE EXCEPTION 'Give a reason for voiding this payment.';
    END IF;

    v_note := 'Voided payment ' || v_pay.reference_code || ': ' || trim(p_reason);

    IF v_pay.status = 'Success' THEN
        PERFORM public.fn_post_money_asset(
            v_pay.business_id, v_pay.method, -v_pay.amount, v_note, v_pay.id, NULL, v_by
        );

        IF v_pay.customer_id IS NOT NULL AND (v_pay.debt_applied > 0 OR v_pay.wallet_applied > 0) THEN
            SELECT wallet_balance, debt_balance INTO v_wallet, v_debt
            FROM public.customers WHERE id = v_pay.customer_id FOR UPDATE;

            IF v_wallet < v_pay.wallet_applied THEN
                RAISE EXCEPTION 'This customer has already spent Ksh % of the wallet credit from this payment, so it can''t be voided here. Adjust their balance from the customer screen.',
                    v_pay.wallet_applied - v_wallet;
            END IF;

            v_wallet := v_wallet - v_pay.wallet_applied;
            v_debt   := v_debt + v_pay.debt_applied;
            -- A customer can't hold credit and owe at the same time, so the two net off.
            v_offset := LEAST(v_wallet, v_debt);
            v_wallet := v_wallet - v_offset;
            v_debt   := v_debt - v_offset;

            UPDATE public.customers
            SET wallet_balance = v_wallet, debt_balance = v_debt
            WHERE id = v_pay.customer_id;

            IF v_pay.debt_applied > 0 THEN
                INSERT INTO public.customer_ledger (
                    business_id, customer_id, type, amount, wallet_balance, debt_balance,
                    recorded_by, note, reference_id
                )
                VALUES (
                    v_pay.business_id, v_pay.customer_id, 'debt_adjustment', v_pay.debt_applied,
                    v_wallet, v_debt, v_by, v_note, 'void-' || v_pay.id || '-debt'
                )
                ON CONFLICT (business_id, reference_id) WHERE reference_id IS NOT NULL DO NOTHING;

                -- Reopen credit, most recently paid first.
                v_remaining := v_pay.debt_applied - v_offset;
                FOR v_rec IN
                    SELECT id, amount_paid FROM public.credit_payments
                    WHERE customer_id = v_pay.customer_id AND business_id = v_pay.business_id
                      AND amount_paid > 0
                    ORDER BY updated_at DESC, created_at DESC
                    FOR UPDATE
                LOOP
                    EXIT WHEN v_remaining <= 0;
                    v_take := LEAST(v_remaining, v_rec.amount_paid);
                    v_remaining := v_remaining - v_take;
                    UPDATE public.credit_payments
                    SET amount_paid = amount_paid - v_take,
                        status = CASE WHEN amount_paid - v_take <= 0
                                      THEN 'Open'::public.credit_status
                                      ELSE 'Partial'::public.credit_status END,
                        settled_at = NULL,
                        updated_at = NOW()
                    WHERE id = v_rec.id;
                END LOOP;
            END IF;

            IF v_pay.wallet_applied > 0 THEN
                INSERT INTO public.customer_ledger (
                    business_id, customer_id, type, amount, wallet_balance, debt_balance,
                    recorded_by, note, reference_id
                )
                VALUES (
                    v_pay.business_id, v_pay.customer_id, 'wallet_usage', v_pay.wallet_applied,
                    v_wallet, v_debt, v_by, v_note, 'void-' || v_pay.id || '-wallet'
                )
                ON CONFLICT (business_id, reference_id) WHERE reference_id IS NOT NULL DO NOTHING;
            END IF;
        END IF;
    END IF;

    -- The reference is freed so the same receipt can be recorded correctly again.
    -- reference_id still holds the original.
    UPDATE public.payments
    SET status = 'Voided', voided_at = NOW(), voided_by = v_by, void_reason = trim(p_reason),
        reference_id = COALESCE(reference_id, reference_code),
        reference_code = reference_code || '-VOID-' || to_char(NOW(), 'YYMMDDHH24MISS')
    WHERE id = v_pay.id;

    -- A till payment that was assigned goes back to the queue.
    UPDATE public.mpesa_till_payments
    SET status = 'unclaimed', payment_id = NULL, customer_id = NULL, handled_by = NULL, handled_at = NULL
    WHERE payment_id = v_pay.id;
END;
$$;


ALTER FUNCTION "public"."void_business_payment"("p_payment_id" "uuid", "p_reason" "text", "p_voided_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_invoice_payment"("p_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_p public.invoice_payments%ROWTYPE;
BEGIN
    SELECT * INTO v_p FROM public.invoice_payments WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'That payment was not found.';
    END IF;
    PERFORM public.assert_business_member(v_p.business_id);
    PERFORM public.assert_permission(v_p.business_id, 'invoices.manage');
    IF v_p.voided_at IS NOT NULL THEN
        RETURN;
    END IF;
    PERFORM 1 FROM public.sales_invoices WHERE id = v_p.invoice_id FOR UPDATE;
    UPDATE public.invoice_payments
    SET voided_at = NOW(), voided_by = public.acc_who(), void_reason = left(NULLIF(trim(p_reason), ''), 300)
    WHERE id = p_id;
    PERFORM public.sd_invoice_refresh(v_p.invoice_id);
END;
$$;


ALTER FUNCTION "public"."void_invoice_payment"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_sales_invoice"("p_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_i public.sales_invoices%ROWTYPE;
    v_l RECORD;
BEGIN
    SELECT * INTO v_i FROM public.sales_invoices WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'That invoice was not found.';
    END IF;
    PERFORM public.assert_business_member(v_i.business_id);
    PERFORM public.assert_permission(v_i.business_id, 'invoices.manage');
    IF v_i.status = 'void' THEN
        RETURN;
    END IF;
    IF NULLIF(trim(COALESCE(p_reason, '')), '') IS NULL THEN
        RAISE EXCEPTION 'Say why the invoice is void.';
    END IF;
    IF EXISTS (SELECT 1 FROM public.invoice_payments WHERE invoice_id = p_id AND voided_at IS NULL) THEN
        RAISE EXCEPTION 'This invoice has payments. Remove them first, or give a credit note instead.';
    END IF;
    IF EXISTS (SELECT 1 FROM public.credit_notes WHERE invoice_id = p_id) THEN
        RAISE EXCEPTION 'This invoice has a credit note, so it can''t be voided. Credit what is left instead.';
    END IF;
    IF v_i.order_id IS NOT NULL THEN
        PERFORM 1 FROM public.sales_orders WHERE id = v_i.order_id FOR UPDATE;
    END IF;
    FOR v_l IN SELECT * FROM public.sales_invoice_lines WHERE invoice_id = p_id AND order_line_id IS NOT NULL LOOP
        UPDATE public.sales_order_lines SET qty_invoiced = GREATEST(qty_invoiced - v_l.quantity, 0) WHERE id = v_l.order_line_id;
    END LOOP;
    UPDATE public.sales_invoices
    SET status = 'void', voided_at = NOW(), voided_by = public.acc_who(), void_reason = left(trim(p_reason), 300), updated_at = NOW()
    WHERE id = p_id;
    IF v_i.order_id IS NOT NULL THEN
        PERFORM public.sd_order_refresh(v_i.order_id);
    END IF;
END;
$$;


ALTER FUNCTION "public"."void_sales_invoice"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_supplier_bill"("p_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_b public.supplier_bills%ROWTYPE;
BEGIN
    SELECT * INTO v_b FROM public.supplier_bills WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That bill was not found.'; END IF;
    PERFORM public.assert_business_member(v_b.business_id);
    PERFORM public.assert_permission(v_b.business_id, 'supplier_bills.manage');
    IF v_b.status = 'void' THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM public.supplier_payments WHERE bill_id = p_id AND voided_at IS NULL) THEN
        RAISE EXCEPTION 'This bill has payments. Void them first.';
    END IF;
    IF NULLIF(trim(COALESCE(p_reason, '')), '') IS NULL THEN
        RAISE EXCEPTION 'Say why this bill is void.';
    END IF;
    UPDATE public.supplier_bills
    SET status = 'void', voided_at = NOW(), voided_by = public.fn_my_display_name(v_b.business_id), void_reason = trim(p_reason), balance = 0
    WHERE id = p_id;
    UPDATE public.purchase_receipts SET bill_id = NULL WHERE bill_id = p_id;
END;
$$;


ALTER FUNCTION "public"."void_supplier_bill"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_supplier_payment"("p_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_p  public.supplier_payments%ROWTYPE;
    v_by TEXT := public.acc_who();
BEGIN
    SELECT * INTO v_p FROM public.supplier_payments WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'That payment was not found.'; END IF;
    PERFORM public.assert_business_member(v_p.business_id);
    PERFORM public.assert_permission(v_p.business_id, 'accounting.manage', 'purchases.approve');
    IF v_p.voided_at IS NOT NULL THEN RETURN; END IF;
    IF COALESCE(trim(p_reason), '') = '' THEN RAISE EXCEPTION 'Give a reason.'; END IF;
    UPDATE public.supplier_payments SET voided_at = NOW(), voided_by = v_by, void_reason = trim(p_reason) WHERE id = p_id;
    PERFORM public.fn_post_money_asset(v_p.business_id, v_p.method, v_p.amount, 'Voided supplier payment to ' || v_p.supplier_name, NULL, NULL, v_by);
END;
$$;


ALTER FUNCTION "public"."void_supplier_payment"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vote_product_idea"("p_idea_id" "uuid", "p_vote" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_account public.customer_accounts%ROWTYPE;
    v_idea    public.website_product_ideas%ROWTYPE;
    v_changed INTEGER;
    v_count   INTEGER;
BEGIN
    SELECT * INTO v_account FROM public.customer_accounts WHERE id = auth.uid();
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Please sign in to vote.';
    END IF;
    SELECT * INTO v_idea FROM public.website_product_ideas
    WHERE id = p_idea_id AND business_id = v_account.business_id
    FOR UPDATE;
    IF NOT FOUND OR v_idea.status IN ('hidden', 'pending') THEN
        RAISE EXCEPTION 'That idea is no longer on the list.';
    END IF;
    IF v_idea.status = 'available' THEN
        RAISE EXCEPTION 'Voting has closed: "%" is already in our shop.', v_idea.title;
    END IF;

    IF COALESCE(p_vote, TRUE) THEN
        INSERT INTO public.website_product_idea_votes (idea_id, account_id)
        VALUES (v_idea.id, v_account.id)
        ON CONFLICT DO NOTHING;
    ELSE
        DELETE FROM public.website_product_idea_votes WHERE idea_id = v_idea.id AND account_id = v_account.id;
    END IF;
    GET DIAGNOSTICS v_changed = ROW_COUNT;

    SELECT count(*) INTO v_count FROM public.website_product_idea_votes WHERE idea_id = v_idea.id;
    IF v_changed > 0 THEN
        PERFORM set_config('app.idea_votes', 'on', TRUE);
        UPDATE public.website_product_ideas SET vote_count = v_count WHERE id = v_idea.id;
        PERFORM set_config('app.idea_votes', 'off', TRUE);
    END IF;

    RETURN jsonb_build_object('votes', v_count, 'voted', COALESCE(p_vote, TRUE));
END;
$$;


ALTER FUNCTION "public"."vote_product_idea"("p_idea_id" "uuid", "p_vote" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_accepts_airtel"("p_slug" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.businesses b
        JOIN public.airtel_payment_settings s ON s.business_id = b.id AND s.status = 'connected'
        JOIN public.airtel_payment_secrets k ON k.business_id = b.id
        WHERE b.website_slug = p_slug AND b.deleted_at IS NULL
          AND 'Airtel Money' = ANY(b.default_payment_methods)
    );
$$;


ALTER FUNCTION "public"."website_accepts_airtel"("p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_accepts_cards"("p_slug" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.businesses b
        JOIN public.card_payment_settings c ON c.business_id = b.id AND c.online_enabled
        JOIN public.card_payment_secrets k ON k.business_id = b.id
        WHERE b.website_slug = p_slug AND b.deleted_at IS NULL
          AND 'Card' = ANY(b.default_payment_methods)
    );
$$;


