    "country" "text" DEFAULT 'Kenya'::"text" NOT NULL,
    "currency" "text" DEFAULT 'Ksh'::"text" NOT NULL,
    "timezone" "text" DEFAULT 'Africa/Nairobi'::"text" NOT NULL,
    "default_payment_methods" "text"[] DEFAULT ARRAY['Cash'::"text", 'M-Pesa'::"text", 'Card'::"text", 'Bank'::"text"] NOT NULL,
    "description" "text",
    "address" "text",
    "logo_url" "text",
    "cover_image_url" "text",
    "contact_email" "text",
    "contact_phone" "text",
    "primary_color" "text",
    "secondary_color" "text",
    "version" integer DEFAULT 1 NOT NULL,
