    CONSTRAINT "businesses_contact_phone_check" CHECK ((("contact_phone" IS NULL) OR ("contact_phone" = ''::"text") OR ("contact_phone" ~* '^\+[1-9]\d{1,14}$'::"text"))),
    CONSTRAINT "businesses_name_check" CHECK (("length"(TRIM(BOTH FROM "name")) > 0)),
    CONSTRAINT "businesses_payment_methods_check" CHECK ((("cardinality"("default_payment_methods") >= 1) AND ("default_payment_methods" <@ ARRAY['Cash'::"text", 'M-Pesa'::"text", 'Airtel Money'::"text", 'Card'::"text", 'Bank'::"text"]))),
    CONSTRAINT "businesses_website_slug_check" CHECK ((("website_slug" IS NULL) OR ("website_slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::"text")))
);


