CREATE OR REPLACE VIEW "public"."v_active_customers" WITH ("security_invoker"='true') AS
 SELECT "c"."id",
    "c"."business_id",
    "b"."name" AS "business_name",
    "c"."name",
    "c"."phone",
    "c"."email",
    "c"."loyalty_points",
    "c"."tier",
    "c"."purchases_count",
    "c"."debt_balance",
    "c"."wallet_balance",
    "c"."join_date",
    "c"."created_at",
    "c"."description"
   FROM ("public"."customers" "c"
     JOIN "public"."businesses" "b" ON (("c"."business_id" = "b"."id")))
  WHERE ("c"."deleted_at" IS NULL);


ALTER VIEW "public"."v_active_customers" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_active_products" WITH ("security_invoker"='true') AS
 SELECT "id",
    "business_id",
    "name",
    "category",
    "price",
    "cost",
    "image",
    "stock",
    "min_stock",
    "unit",
    "sku",
    "description",
    "perishable",
    "expiry_days",
        CASE
            WHEN ("stock" = (0)::numeric) THEN 'out_of_stock'::"text"
            WHEN ("stock" <= "min_stock") THEN 'low_stock'::"text"
            ELSE 'ok'::"text"
        END AS "stock_status",
    "created_at",
    "updated_at"
   FROM "public"."products" "p"
  WHERE ("deleted_at" IS NULL);


ALTER VIEW "public"."v_active_products" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_active_shifts" WITH ("security_invoker"='true') AS
 SELECT "s"."id",
    "s"."business_id",
    "b"."name" AS "business_name",
    "s"."employee_id",
    "e"."name" AS "employee_name",
    "e"."role" AS "employee_role",
    "s"."start_time",
    "s"."end_time",
    "s"."sales_count",
    "s"."sales_total",
    "s"."status",
    "s"."created_at"
   FROM (("public"."shifts" "s"
     JOIN "public"."businesses" "b" ON (("s"."business_id" = "b"."id")))
     JOIN "public"."employees" "e" ON (("s"."employee_id" = "e"."id")))
  WHERE (("s"."status" = 'Active'::"public"."shift_status") AND ("s"."deleted_at" IS NULL));


ALTER VIEW "public"."v_active_shifts" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_customer_ledger_detail" WITH ("security_invoker"='true') AS
 SELECT "cl"."id",
    "cl"."business_id",
    "cl"."customer_id",
    "c"."name" AS "customer_name",
    "cl"."type",
    "cl"."amount",
    "cl"."wallet_balance",
    "cl"."debt_balance",
    "cl"."recorded_by",
    "cl"."note",
    "cl"."transaction_id",
    "t"."final_total" AS "transaction_total",
    "t"."payment_method",
    "cl"."created_at"
   FROM (("public"."customer_ledger" "cl"
     JOIN "public"."customers" "c" ON (("cl"."customer_id" = "c"."id")))
     LEFT JOIN "public"."transactions" "t" ON (("cl"."transaction_id" = "t"."id")));


ALTER VIEW "public"."v_customer_ledger_detail" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_daily_sales_summary" WITH ("security_invoker"='true') AS
 SELECT "business_id",
    ("date_trunc"('day'::"text", "timestamp"))::"date" AS "sale_date",
    "count"(*) AS "order_count",
    "sum"("final_total") AS "total_revenue",
    "sum"("discount") AS "total_discount",
    "sum"(
        CASE
            WHEN "is_delivery" THEN 1
            ELSE 0
        END) AS "delivery_count"
   FROM "public"."transactions" "t"
  WHERE ("deleted_at" IS NULL)
  GROUP BY "business_id", (("date_trunc"('day'::"text", "timestamp"))::"date");


ALTER VIEW "public"."v_daily_sales_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_expense_summary" WITH ("security_invoker"='true') AS
 SELECT "business_id",
    "category",
    "date_trunc"('month'::"text", "date") AS "month",
    "sum"("amount") AS "total_amount",
    "count"(*) AS "count"
   FROM "public"."expenses" "e"
  WHERE ("deleted_at" IS NULL)
  GROUP BY "business_id", "category", ("date_trunc"('month'::"text", "date"));


ALTER VIEW "public"."v_expense_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_low_stock_products" WITH ("security_invoker"='true') AS
 SELECT "id",
    "business_id",
    "name",
    "category",
    "stock",
    "min_stock",
    "unit",
    "price",
        CASE
            WHEN ("stock" = (0)::numeric) THEN 'out_of_stock'::"text"
            ELSE 'low_stock'::"text"
        END AS "alert_level"
   FROM "public"."products" "p"
  WHERE (("deleted_at" IS NULL) AND ("stock" <= "min_stock"));


ALTER VIEW "public"."v_low_stock_products" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_open_debts" WITH ("security_invoker"='true') AS
 SELECT "cp"."id",
    "cp"."business_id",
    "cp"."customer_id",
    "cp"."customer_name",
    "cp"."amount_owed",
    "cp"."amount_paid",
    "cp"."balance",
    "cp"."status",
    "cp"."due_date",
    "cp"."created_at",
    "c"."phone" AS "customer_phone",
    "c"."tier" AS "customer_tier"
   FROM ("public"."credit_payments" "cp"
     LEFT JOIN "public"."customers" "c" ON (("cp"."customer_id" = "c"."id")))
  WHERE ("cp"."status" = ANY (ARRAY['Open'::"public"."credit_status", 'Partial'::"public"."credit_status"]));


ALTER VIEW "public"."v_open_debts" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_pending_invitations" WITH ("security_invoker"='true') AS
 SELECT "i"."id",
    "i"."business_id",
    "b"."name" AS "business_name",
    "i"."name",
    "i"."email",
    "i"."phone",
    "i"."role",
    "i"."expires_at",
    "i"."created_at",
    "i"."status"
   FROM ("public"."invitations" "i"
     JOIN "public"."businesses" "b" ON (("i"."business_id" = "b"."id")))
  WHERE (("i"."status" = 'Pending'::"public"."invitation_status") AND ("i"."expires_at" > "now"()));


ALTER VIEW "public"."v_pending_invitations" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_product_sales_rank" WITH ("security_invoker"='true') AS
 SELECT "t"."business_id",
    "ti"."product_id",
    "ti"."product_name",
    "sum"("ti"."quantity") AS "total_qty_sold",
    "sum"("ti"."line_total") AS "total_revenue",
    "count"(DISTINCT "ti"."transaction_id") AS "order_count",
    "rank"() OVER (PARTITION BY "t"."business_id" ORDER BY ("sum"("ti"."quantity")) DESC) AS "rank"
   FROM ("public"."transaction_items" "ti"
     JOIN "public"."transactions" "t" ON (("ti"."transaction_id" = "t"."id")))
  WHERE ("t"."deleted_at" IS NULL)
  GROUP BY "t"."business_id", "ti"."product_id", "ti"."product_name";


ALTER VIEW "public"."v_product_sales_rank" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_team_members" WITH ("security_invoker"='true') AS
 SELECT "bm"."id" AS "membership_id",
    "bm"."business_id",
    "bm"."role",
    "bm"."status",
    "bm"."joined_at",
    "u"."id" AS "user_id",
    "u"."name",
    "u"."email",
    "u"."phone",
    "u"."avatar",
    "u"."is_verified",
    "e"."active_shift_id",
    "e"."tasks",
    "e"."assigned_branches"
   FROM (("public"."business_memberships" "bm"
     JOIN "public"."users" "u" ON (("bm"."user_id" = "u"."id")))
     LEFT JOIN "public"."employees" "e" ON ((("e"."user_id" = "u"."id") AND ("e"."business_id" = "bm"."business_id"))))
  WHERE ("bm"."status" = 'Active'::"public"."membership_status");


ALTER VIEW "public"."v_team_members" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_transaction_summary" WITH ("security_invoker"='true') AS
 SELECT "t"."id",
    "t"."business_id",
    "t"."final_total",
    "t"."discount",
    "t"."tax",
    "t"."amount_paid",
    "t"."wallet_applied",
    "t"."payment_method",
    "t"."customer_id",
    COALESCE("c"."name", "t"."customer_name") AS "customer_name",
    "t"."staff_id",
    "t"."staff_name",
    "t"."status",
    "t"."timestamp",
    "t"."note",
    "t"."is_delivery",
    "t"."delivery_fee",
    "t"."rider_name",
    "t"."created_at"
   FROM ("public"."transactions" "t"
     LEFT JOIN "public"."customers" "c" ON (("t"."customer_id" = "c"."id")))
  WHERE ("t"."deleted_at" IS NULL);


ALTER VIEW "public"."v_transaction_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_unread_notifications" WITH ("security_invoker"='true') AS
 SELECT "id",
    "business_id",
    "user_id",
    "role",
    "title",
    "message",
    "type",
    "priority",
    "action_type",
    "action_target",
    "payload",
    "created_at",
    "expires_at",
    "status"
   FROM "public"."notifications" "n"
  WHERE (("read_at" IS NULL) AND ("archived_at" IS NULL) AND ("deleted_at" IS NULL) AND (("expires_at" IS NULL) OR ("expires_at" > "now"())));


ALTER VIEW "public"."v_unread_notifications" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_upcoming_schedules" WITH ("security_invoker"='true') AS
 SELECT "sc"."id",
    "sc"."business_id",
    "sc"."employee_id",
    "e"."name" AS "employee_name",
    "e"."role" AS "employee_role",
    "e"."avatar" AS "employee_avatar",
    "sc"."title",
    "sc"."notes",
    "sc"."date",
    "sc"."start_time",
    "sc"."end_time",
    "sc"."repeat",
    "sc"."color",
    "sc"."reminder_sent",
    "sc"."created_at"
   FROM ("public"."schedules" "sc"
     JOIN "public"."employees" "e" ON (("sc"."employee_id" = "e"."id")))
  WHERE (("sc"."deleted_at" IS NULL) AND ("sc"."date" >= CURRENT_DATE) AND ("sc"."date" <= (CURRENT_DATE + '14 days'::interval)));


ALTER VIEW "public"."v_upcoming_schedules" OWNER TO "postgres";


