CREATE TABLE IF NOT EXISTS "public"."website_product_ideas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "business_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "image_url" "text",
    "staff_note" "text",
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "product_id" "uuid",
    "suggested_by" "uuid",
    "suggested_name" "text",
    "vote_count" integer DEFAULT 0 NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "website_product_ideas_description_check" CHECK ((("description" IS NULL) OR ("length"("description") <= 500))),
    CONSTRAINT "website_product_ideas_image_url_check" CHECK ((("image_url" IS NULL) OR (("image_url" ~ '^https://'::"text") AND ("length"("image_url") <= 1000)))),
    CONSTRAINT "website_product_ideas_kind_check" CHECK (("kind" = ANY (ARRAY['upcoming'::"text", 'suggestion'::"text"]))),
    CONSTRAINT "website_product_ideas_staff_note_check" CHECK ((("staff_note" IS NULL) OR ("length"("staff_note") <= 300))),
    CONSTRAINT "website_product_ideas_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'open'::"text", 'planned'::"text", 'available'::"text", 'hidden'::"text"]))),
    CONSTRAINT "website_product_ideas_suggested_name_check" CHECK ((("suggested_name" IS NULL) OR ("length"("suggested_name") <= 60))),
    CONSTRAINT "website_product_ideas_title_check" CHECK ((("length"(TRIM(BOTH FROM "title")) >= 3) AND ("length"(TRIM(BOTH FROM "title")) <= 80))),
    CONSTRAINT "website_product_ideas_vote_count_check" CHECK (("vote_count" >= 0))
);


ALTER TABLE "public"."website_product_ideas" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."website_reviews" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "business_id" "uuid" NOT NULL,
    "account_id" "uuid",
    "product_id" "uuid",
    "rating" integer NOT NULL,
    "title" "text",
    "body" "text" NOT NULL,
    "display_name" "text" NOT NULL,
    "verified" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "featured" boolean DEFAULT false NOT NULL,
    "staff_reply" "text",
    "replied_by" "text",
    "replied_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "website_reviews_body_check" CHECK ((("length"(TRIM(BOTH FROM "body")) >= 3) AND ("length"(TRIM(BOTH FROM "body")) <= 2000))),
    CONSTRAINT "website_reviews_display_name_check" CHECK (("length"("display_name") <= 60)),
    CONSTRAINT "website_reviews_rating_check" CHECK ((("rating" >= 1) AND ("rating" <= 5))),
    CONSTRAINT "website_reviews_staff_reply_check" CHECK ((("staff_reply" IS NULL) OR ("length"("staff_reply") <= 1000))),
    CONSTRAINT "website_reviews_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'hidden'::"text"]))),
    CONSTRAINT "website_reviews_title_check" CHECK ((("title" IS NULL) OR ("length"("title") <= 120)))
);


ALTER TABLE "public"."website_reviews" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."website_settings" (
    "business_id" "uuid" NOT NULL,
    "delivery_enabled" boolean DEFAULT true NOT NULL,
    "delivery_fee" numeric(14,2) DEFAULT 0.00 NOT NULL,
    "min_order" numeric(14,2) DEFAULT 0.00 NOT NULL,
    "assistant_enabled" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
