    "ad_cards" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    CONSTRAINT "website_settings_ad_cards_check" CHECK (("public"."fn_valid_ad_cards"("ad_cards") AND ("pg_column_size"("ad_cards") < 20000))),
    CONSTRAINT "website_settings_delivery_fee_check" CHECK (("delivery_fee" >= (0)::numeric)),
    CONSTRAINT "website_settings_hero_slides_check" CHECK (("public"."fn_valid_hero_slides"("hero_slides") AND ("pg_column_size"("hero_slides") < 20000))),
    CONSTRAINT "website_settings_hours_check" CHECK (((("opening_hours" IS NULL) OR ("length"("opening_hours") <= 500)) AND (("whatsapp" IS NULL) OR ("whatsapp" ~ '^\+?[0-9 ]{7,20}$'::"text")))),
    CONSTRAINT "website_settings_min_order_check" CHECK (("min_order" >= (0)::numeric)),
    CONSTRAINT "website_settings_pages_check" CHECK ((("jsonb_typeof"("pages") = 'object'::"text") AND ("pg_column_size"("pages") < 200000)))
);


ALTER TABLE "public"."website_settings" OWNER TO "postgres";


